insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2021.11.09. 화요일] 경기연구원 — 기획재정위원회 2021년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2021년도 행정사무감사(2021. 11. 05. ~ 2021. 11. 18.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=13486" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2021년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 경기연구원
</p>
<p><hr /></p>
<p>일  시: 2021년 11월 9일(화)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(15시31분 감사개시)
</p>
<p><b>○ 위원장 심규순 </b> 의석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조와 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2021년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  허성관 경기연구원 이사장을 비롯한 관계자 여러분! 안녕하십니까? 기획재정위원장 심규순입니다. 지금부터 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 여러분들께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무 전반에 관한 실태를 정확히 파악하는 한편 나아가 2022년도 예산안 심사에 반영하고 도정 실태를 파악하여 도민의 삶과 질 향상에 기여하고자 함이 그 목적인 만큼 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사에 임하는 관계자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기를 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 허성관 경기연구원 이사장과 각 본부장, 실장 등은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기 전에 선서를 하여야 합니다.
</p>
<p style="padding-left:1.2em">  선서를 하는 이유는 경기도의회가 2021년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언 거부 또는 제149조 업무상비밀과 증언 거부에 해당되는 때에는 선서와 증언 그리고 서류제출을 거부할 수 있음을 함께 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  허성관 경기연구원 이사장 나오셨습니까?   
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 송미영 연구부원장 나오셨습니까?   
</p>
<p><b>○ 연구부원장 송미영 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 장형철 경영부원장 나오셨습니까?  
</p>
<p><b>○ 경영부원장 장형철 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 봉인식 연구기획본부장 나오셨습니까?  
</p>
<p><b>○ 연구기획본부장 봉인식 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 김동성 균형발전본부장 나오셨습니까?   
</p>
<p><b>○ 균형발전본부장 김동성 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 김동영 감사실장 나오셨습니까?   
</p>
<p><b>○ 감사실장 김동영 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 이정훈 북부연구센터장 나오셨습니까?   
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 류시균 시군연구센터장 나오셨습니까?   
</p>
<p><b>○ 시군연구센터장 류시균 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 이성룡 도시주택연구실장 나오셨습니까?   
</p>
<p><b>○ 도시주택연구실장 이성룡 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 성영조 경제사회연구실장 나오셨습니까?   
</p>
<p><b>○ 경제사회연구실장 성영조 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 빈미영 교통물류연구실장 나오셨습니까?  
</p>
<p><b>○ 교통물류연구실장 빈미영 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 이기영 생태환경연구실장 나오셨습니까?  
</p>
<p><b>○ 생태환경연구실장 이기영 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 이수진 연구기획부장 나오셨습니까?  
</p>
<p><b>○ 연구기획부장 이수진 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 김정훈 전략기획정책부장 나오셨습니까?  
</p>
<p><b>○ 전략정책부장 김정훈 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 손호철 행정지원부장 나오셨습니까?   
</p>
<p><b>○ 행정지원부장 손호철 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 박인숙 재정지원부장 나오셨습니까?   
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 배미성 성과관리부장 나오셨습니까?   
</p>
<p><b>○ 성과관리부장 배미성 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 강승현 홍보정보부장 나오셨습니까?   
</p>
<p><b>○ 홍보정보부장 강승현 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 이덕환 대외협력부장 나오셨습니까?  
</p>
<p><b>○ 대외협력부장 이덕환 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 김도일 경기도공공투자관리센터 소장 나오셨습니까?  
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 김병석 경기도공공투자관리센터 총괄기획부장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터총괄기획부장 김병석 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 김대중 경기도공공투자관리센터 투자분석평가1부장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터투자분석평가1부장 김대중 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 이상미 경기도공공투자관리센터 투자분석평가2부장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터투자분석평가2부장 이상미 </b> 네. 
</p>
<p><b>○ 위원장 심규순 </b> 다음은 선서의 요령을 말씀드리겠습니다. 선서는 증인들을 대표해서 허성관 이사장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인들께서는 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2021년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2021년 11월 9일 경기연구원 원장 직무대행 이사장 허성관.  
</p>
<p><b>○ 위원장 심규순 </b> 모두 자리에 앉아 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  계속해서 간부인사와 업무보고를 받도록 하겠습니다. 허성관 이사장 나오셔서 간부 소개와 업무보고를 간략히 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 지난 9월 7일 자로 이한주 경기연구원 원장이 임기 만료돼서 퇴임을 하셨고 그래서 연구원 정관에 의해서 이사장인 제가 원장 직무대행을 하고 있습니다. 제 이름은 허성관입니다.
</p>
<p style="padding-left:1.2em">  평소 저희 경기연구원 발전을 위해 관심을 가져 주시고 항상 염려해 주시고 성원해 주시는 심규순 위원장님을 비롯한 기획재정위원회 위원님 여러분! 충심으로 감사드립니다. 참고로 신임 원장 선임을 위해서 현재 공개 모집을 진행 중에 있고 11월 2일까지 공개 공모한 결과 2명이 응시하여 현재는 전형 절차를 진행 중에 있습니다. 오늘 기획재정위원회 심규순 위원장님을 비롯하여 위원님들을 모시고 2021년도 경기연구원 행정사무감사 업무보고를 드리게 되어 아주 뜻깊게 생각합니다. 아시다시피 우리 연구원은 대내외 여건 변화와 민선7기의 효율적인 정책 대응을 위해 연구원의 비전을 새로운 경기, 정책 플랫폼 GRI로 설정하고 경기도민의 삶의 질 향상을 위해 전 직원이 합심하여 열심히 노력하고 있습니다. 향후에도 연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 주요 간부를 소개해 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 송미영 연구부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 장형철 경영부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  봉인식 연구기획본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 균형발전본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사) 
</p>
<p style="padding-left:1.2em">  김도일 경기도공공투자관리센터 소장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동영 감사실장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정훈 북부연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  류시균 시군연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이성룡 도시주택연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사) 
</p>
<p style="padding-left:1.2em">  성영조 경제사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  빈미영 교통물류연구실장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이기영 생태환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사) 
</p>
<p style="padding-left:1.2em">  이수진 연구기획부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김정훈 전략정책부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  손호철 행정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박인숙 재정지원부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  배미성 성과관리부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  강승현 홍보정보부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이덕환 대외협력부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김병석 공공투자관리센터 총괄기획부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김대중 공공투자관리센터 투자분석1부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상미 공공투자관리센터 투자분석평가2부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  참고로 이현우 자치분권연구실장은 병원 치료로 인해서 오늘 불참하신 것 양해 부탁드립니다.
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 저희 연구원의 주요업무를 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  보고드릴 순서는 기본현황 그리고 금년도 경영목표 및 연구사업 방향 그리고 2021년도 지금까지 주요 연구사업 성과 그리고 2021년도 주요 경영성과의 순으로 말씀을 드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 1쪽 기본현황입니다. 저희 연구원은 1995년에 개원해서 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 연구원의 조직은 본원이 2부원장 1실 2본부 5연구실 2센터 7부로 구성되어 있고 부설기관인 경기도공공투자관리센터가 3부로 구성되어 있습니다. 현재 우리 연구원의 인력은 정규직이 정원 187명인데 현재 인원은 167명입니다. 비정규직인 기간제근로자 28명을 포함하면 총 195명이 근무하고 있습니다. 본원에 178명, 경기도공공투자관리센터에 17명이 근무하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 2쪽 본 연구원의 주요기능입니다. 원장 직속으로 감사실이 편재돼 있고 또 연구부원장 산하에 연구기획본부와 균형발전본부 그리고 각 연구실이 있습니다. 경영부원장 산하에는 5개의 행정부서가 편재돼 있습니다. 아울러 본원의 부설기관으로 경기도공공투자관리센터를 두고 있습니다. 부서별 주요업무 및 상세한 내용 및 기능에 관해서는 2쪽을 참조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 3쪽 예산현황에 대해서 말씀을 드리겠습니다. 올해 총예산 규모는 286억 원입니다. 일반회계 264억 원, 본원 예산입니다. 공공투자관리센터 특별회계 22억 원을 보탠 것입니다. 일반회계 수입ㆍ지출내역의 주요내용을 말씀드리겠습니다. 수입항목은 일반회계, 일반회계도 일반계정과 수탁계정 두 가지가 있는데 일반계정은 234억 중에서 경기도 출연금이 185억 원으로 일반회계 전체 예산의 79.1%가 출연금입니다. 수탁회계에 들어올 전입금은 15.5억 원이고 전기이월금은 30.5억 원 그다음에 운영비 이자수입은 3억 원입니다.
</p>
<p style="padding-left:1.2em">  주요 지출항목으로는 인건비가 146억 원으로 일반회계 예산의 62.3%를 차지하고 있으며 연구사업비는 60억 원으로 25.6% 비중입니다. 이외에 경상경비 25억 원이 예산으로 편성되어 있습니다. 일반회계 수탁계정과 공공투자관리센터 특별회계는 자료를 참조해 주시면 되겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 4쪽입니다. 2021년 경영목표, 금년도 경영목표 및 연구사업 방향에 대해서 말씀드리겠습니다. 연구원은 원내 공모를 통해서 설립목적에 근거한 GRI 경기연구원 미션을 경기도민의 삶의 질 향상과 도정 선도를 위한 정책연구로 정했습니다. 그래서 그 밑에 4대 경영목표를 1. 도민 삶의 질 향상에 기여하는 연구를 선도하고 2. 현장과 소통하는 연구체계를 수립하며 3. 환경변화에 대응한 새로운 사업을 확대하고 4. 공정하고 투명한 경영관리체계 수립으로 설정하여 현재 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  2021년 주요 연구사업 성과입니다. 6쪽입니다. 2021년 첫 번째 성과는 4대 연구사업 방향에 맞추어 총 206건의 연구과제를 적극 수행한 것입니다. 내용은 포스트 코로나 시대의 지역 회복력 강화 전략, 공정사회를 위한 새로운 사회복지체계 연구, 지속가능 발전을 위한 인프라 구축방안 연구, 강력하고 효율적인 지방정부 실현을 위한 연구 등이 주요 연구주제가 되었습니다.
</p>
<p style="padding-left:1.2em">  다음은 7쪽입니다. 두 번째 성과로는 지속가능한 공정 경기도를 위한 여러 담론 연구를 추진하였습니다. 먼저 포스트 코로나, 뉴노멀 시대를 사람중심의 번영 기회로 삼고 경기도의 미래상과 정책방향을 재정립하기 위해 시대적 사회가치인 공정성과 지속가능성에 관한 담론 연구를 추진하였습니다. 여기에 관련한 주요 연구내용은 공정성, 공정경제, 공정사회, 기본소득, 공정토지, 공정개발, 한반도 공동체 담론 관련 외부 전문가 및 관련 학회 등과의 협력을 통하여 전략연구과제를 추진하였고 연구 성과물의 적극적인 사회적 공유를 위하여 일반 대중서적 6권을 출간 완료하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 8쪽입니다. 세 번째 연구성과로는 기본소득 관련 연구를 추진하였습니다. 저희 연구원은 경기도에서 추진 중이거나 논의 중인 인간으로서 누려야 할 보편적인 기본서비스 정책을 평가하고 보다 확장된 경기도형 기본서비스 모델과 정책방안 연구를 추진하였습니다. 주요내용은 경제, 재정, 법률, 복지 등 다양한 전문가의 융합연구를 실시하고 2021년 4월 28일부터 29일까지 기본소득 국제컨퍼런스를 추진하였습니다.
</p>
<p style="padding-left:1.2em">  네 번째 성과는 포스트 코로나, 뉴노멀 시대 선도연구를 추진하였습니다. 연구원에서는 코로나19로 급변하는 환경에 대비하여 선제적으로 코로나19 이후 뉴노멀 시대를 준비하는 경기도의 미래를 위한 대응전략을 종합적으로 마련하는 연구를 추진하였습니다. 그 주요내용으로는 포스트 코로나 시대의 지역 회복력 강화 전략, 코로나19의 영향과 정부 지원의 효과분석, 코로나19 감염재난이 국민 정신건강에 미치는 연구 등입니다.
</p>
<p style="padding-left:1.2em">  다음은 9쪽을 봐주시기 바랍니다. 다섯 번째 성과로는 국내외 연구기관과 협력을 통한 공동연구 추진입니다. 먼저 공공 정책연구기관의 특성을 반영하여 국책연구기관 및 타 연구기관 등과의 협력을 통한 여러 공동연구를 추진하였습니다. 융합연구 추진 및 연구 네트워크 강화를 통해 코로나19 충격과 긴급재난소득 효과 평가, 지방자치단체 간 갈등조정 방안 연구 등을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음 10쪽입니다. 여섯 번째 성과로는 비무장지대 DMZ 포럼 등 국제행사의 성공적 개최입니다. 먼저 배경으로는 DMZ의 국제적 상징성을 바탕으로 한반도와 국제시민사회의 평화협력ㆍ공동번영을 구현하기 위한 논의의 장을 마련하고 네트워크 거점 역할을 수행하였습니다. 특히 21년에는 “새로운 평화의 지평을 열다”를 주제로 총 20개 세션을 구성하여 DMZ 포럼을 진행하였습니다.
</p>
<p style="padding-left:1.2em">  일곱 번째 성과로는 도민이 참여하는 도민을 위한 소위 ‘도도한’ 연구 공모를 추진하였습니다. 경기도민을 대상으로 도민의 눈높이에서 연구 아이디어를 공모하고 현장의 필요성과 문제점을 연구과제로 발전ㆍ추진함으로써 도민의 체감형 정책 발굴과 현장 밀착형 연구를 수행하였습니다. 2021년도에는 연구 아이디어 부문의 자유주제와 위탁 연구과제 부문은 “코로나19 시대 경기도민은 어떻게 살고 있을까?”라는 기획주제 2개로 구분하여 진행을 하였습니다.
</p>
<p style="padding-left:1.2em">  다음 11쪽을 봐주시기 바랍니다. 여덟 번째 성과는 민선7기 현안에 대한 적시 적절한 시기 대응을 하였습니다. 주요 대응사항은 비대면 시대의 그림자, 소위 디지털 소외 문제, 지역 탄소중립, 목표선언 넘어 실행이 중요하다, 사람들은 기본소득을 어떻게 생각한다 등입니다. 또한 경제동향 통계분석을 통해 국내외 산업, 고용, 부동산 동향 통계분석을 실시하였습니다.
</p>
<p style="padding-left:1.2em">  아홉 번째 성과로는 공공투자관리센터 운영을 통해서 경기도 재정건전성을 확보하는 데 기여하였습니다. 투자심사 사전검토 217건을 수행하였고 또 사업비 5,000만 원 이상 867건의 사업평가를 실시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽입니다. 열 번째 성과로는 의정연구교류 사업을 추진하였습니다. 경기도의회와 정책교류 및 상호협력을 통한 생산적인 의정지원을 위해 2021년 올 한 해 총 4회 의정포럼을 실시하였습니다. 또한 도내 지역현안에 대한 관계자 및 전문가 토론을 통한 대응방안 수립 지원을 위한 토론회를 안양 열병합발전소 개선방안 등 총 6회 개최하였고 향후 원도봉산 상권 활성화 및 환경 개선을 주제로 토론회 등 5건을 추가로 계획 중에 있습니다. 도내 지역현안 문제 해결을 위해 위원님들과 함께 고민하는 자리를 더 많이 만들도록 노력을 하겠습니다.
</p>
<p style="padding-left:1.2em">  13쪽을 봐주시기 바랍니다. 2021년도 주요 경영성과입니다. 첫 번째 성과는 대폭 연구과제 만족도가 향상된 점입니다. 최근 3년 동안 연구과제 만족도 점수가 꾸준히 증가했고 특히 2021년도 3분기는 전년 대비 3점이 상승하였습니다. 그래서 90.4점에서 금년 3분기에는 95.1점으로 상승했다고 말씀드리겠습니다. 특히 연구진에 대한 신뢰도 부문에서 97.5점을 받아서 조사분야 중 가장 높은 점수를 획득하였으며 향후 연구수요자 중심의 고객 맞춤형 연구를 앞으로도 지속적으로 수행하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 14쪽입니다. 두 번째 성과는 연구자료 및 데이터 관리ㆍ홍보 확산을 강화한 점입니다. 연구정보 블로그, 생활밀착형 연구제공 페이스북 운영 등 성과를 인정받아서 제11회 2021년 대한민국 SNS 대상 연구소 부문 최우수상을 수상하였음을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  향후 경기연구원 및 경기도정에 대한 관심과 공감을 유도하기 위해서 경기연구원의 연구성과 동영상 제작, 유튜브 홍보를 더욱 강화하도록 하겠습니다. 또한 경기도 온라인 정책도서관 운영을 통해 정책연구자료 확산에 기여하였으며 이를 통해 연구수행 중복 예산 방지에도 기여하였습니다. 
</p>
<p style="padding-left:1.2em">  15쪽입니다. 세 번째 성과는 주니어보드 운영 확대를 통한 연구원 내부만족도를 제고한 점입니다. 내부 연구원 간 협업과정에서 발생하는 갈등해결을 위해서 2018년 시작한 주니어보드에 대하여 각 직군별 신입 직원들의 참신한 의견을 반영할 수 있도록 참여대상을 확대 운영하였습니다. 네이밍 공모전을 통해 소위 ‘GRI人 그리인’인데 GRI人을 선정하였는데 그 의미는 경기연구원이 나아가야 할 방향을 그리는 사람들입니다. 논의결과에 대하여 개선과제 수립, 즉각적 피드백을 통한 내부만족도 향상을 위해서 내년에도 열심히 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  마지막으로 16쪽부터는 2020년도 행정사무감사 조치결과로 자료로 갈음하고자 합니다. 기억하시겠지만 2020년도 행정사무감사에서 시정요구 2건, 처리요구사항 1건, 건의사항 41건 등이 있었습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요업무보고를 모두 마치겠습니다. 경청해 주신 위원님들 진심으로 감사드립니다. 고맙습니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 심규순 </b> 허성관 이사장 수고하셨습니다. 다음은 감사 질의 답변 순서입니다. 앉아주세요.
</p>
<p style="padding-left:1.2em">  질의 답변에 앞서 위원님들께 양해 말씀을 드립니다. 위원님들과 사전에 상의한 대로 간부소개와 업무보고는 허성관 이사장님이 하고 위원님들의 질의에 대한 답변은 송미영 연구부장이 하는 것으로 진행하겠습니다. 그럼 질의는 감사의 효율적인 진행을 위하여 본질의는 10분 이내, 보충질의는 5분 이내로 제한하여 일문일답 형식으로 하겠습니다. 추가질의는 별도의 신청을 받아 진행하겠으니 위원님들의 많은 협조 부탁드립니다.
</p>
<p style="padding-left:1.2em">  만약 시간적 제약으로 인해 준비하신 질의를 다 하지 못하신 위원님들께서는 추후 서면으로 질의가 가능하오니 이를 활용해 주시기 바랍니다. 또한 위원님들의 질의사항 중 구체적이고 실무적인 내용에 대해서는 경영부원장 및 담당부서장이 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직ㆍ성명을 분명히 밝히고 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  이덕환 대외협력부장님, 저 뒤에 계시죠? 경기도연구원이 생기고 의회와 소통을 가장 잘하는 부장입니다. 그래서 앞으로 위원님들의 많은 질타가 있겠습니다만 먼저 칭찬을 드리고요. 그래도 우리 위원회와 토론을 굉장히, 지역현안 토론을 많이 잡아주셨습니다. 진짜 감사드립니다. 지금 혼자, 우리 위원들께서 고민할 문제를 경기연구원과 함께 지역을 찾아가서 토론을 해서 많은 성과를 본 걸로 알고 있습니다. 향후에도 이런 토론회를 많이 준비해 주시기 바랍니다. 감사드립니다.
</p>
<p style="padding-left:2.4em">    (「너무 편애하시는 거 아니에요.」하는 위원 있음)
</p>
<p style="padding-left:2.4em">    (웃   음)
</p>
<p style="padding-left:1.2em">  질의에 앞서 자료요청하실 위원님 계십니까? 원미정 위원님.
</p>
<p><b>○ 원미정 위원 </b> 공공투자관리센터에서 2021년도 경기도 재정사업 평가한 거 있죠, 결과? 일몰ㆍ감액 사업한 결과보고서 하나만 주세요. 제가 미리 요청하기는 했는데 아직 안 왔어요. 
</p>
<p><b>○ 위원장 심규순 </b> 원미정 위원님 수고하셨습니다. 김강식 위원님 자료요청해 주시기 바랍니다.
</p>
<p><b>○ 김강식 위원 </b> 경기연구원 내부 직원들이, 내부 직원 말고 외부활동들을 했던 내역을 한 3년간 주셨으면 좋겠고 경기연구원에서 수행한 공기관 대행사업들이 있다면 그 공기관 대행사업 리스트를 좀 제출해 주셨으면 좋겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 준비하겠습니다.
</p>
<p><b>○ 위원장 심규순 </b> 김강식 위원님 수고하셨습니다. 자료요청하실 위원님, 김재균 위원님 자료요청해 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (책자를 들어 보이며)
</p>
<p><b>○ 김재균 위원 </b> 지금 베이직 인컴이라고 그래서 이거 경기연구원에서 만들어낸 거 맞나요?
</p>
<p><b>○ 연구부원장 송미영 </b> 영문 보고서의 하나입니다. 국문 보고서도 있습니다.
</p>
<p><b>○ 김재균 위원 </b> 그러면 여기에 대한 예산 및 자료, 자세한 세부적인 자료를 좀 내주십시오.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 심규순 </b> 김재균 위원님 수고하셨습니다. 또 자료요청하실 위원님 안 계십니까? 염종현 위원님 자료요청해 주시기 바랍니다.
</p>
<p><b>○ 염종현 위원 </b> 전체적인 연구과제 실적은 나와 있는데요. 저희가 5개 실이 있는데 실별로 나와 있으면 실별로 분리해서 주시고요. 그다음에 업무보고서 8쪽에 포스트 코로나, 뉴노멀 시대 선도 연구 추진이라고 나와 있는데 거기에 6개 과제가 있는데 이게 다인가요, 아니면 추가로 있나요?
</p>
<p><b>○ 연구부원장 송미영 </b> 그 해당 것에 대해서……. 
</p>
<p><b>○ 염종현 위원 </b> “포스트 코로나, 뉴노멀 시대 선도 연구 추진”했는데 이 항에 포함되어 있는 게 6개인지 아니면 추가로 좀 있는지?
</p>
<p><b>○ 연구부원장 송미영 </b> 대표과제들을 적어 놓은 것입니다. 추가로 하고 있는 것들도 있습니다. 
</p>
<p><b>○ 염종현 위원 </b> 여기에 관련된 게 있으면 전체적으로 한번 주시기 바랍니다. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 염종현 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 심규순 </b> 염종현 위원님 수고하셨습니다. 이영봉 위원님 자료요청해 주시기 바랍니다.
</p>
<p><b>○ 이영봉 위원 </b> 경기연구원 의정포럼 있죠?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 거기 위원회 명단과 예산집행 현황 그리고 우리 기획재정위원회에 보고한 부분에 대해서 자료제출해 주시기 바랍니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 위원장 심규순 </b> 이영봉 위원님 수고하셨습니다. 자료요청하실 위원님 더 이상 안 계십니까?
</p>
<p style="padding-left:1.2em">  자료요청이 좀 방대한 것 같은데 시간 내에 다 제출할 수 있습니까? 위원님들께서 자료를 보시고 아마 질의하실 위원님이 계십니다. 될 수 있는 한 빨리 자료를 제출해 주시기 바랍니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 준비하겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 제출 가능해요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 일부 자료는 미리 말씀해 주신 게 있어서 준비해 놓은 것을 드리고 지금 오늘 이 자리에서 말씀하신 것은 준비해 주시면 보고드리겠습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 네. 질의를 시작하겠습니다. 질의하실 위원님 거수해 주시기 바랍니다. 오지혜 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 오지혜 위원 </b> 안녕하세요? 오지혜입니다. 먼저 경기도와 31개 시군의 경쟁력 강화와 경기도민의 삶의 질 향상을 위해 다양하고 전문적인 조사와 연구를 함께 진행해 주셔서 진심으로 감사합니다.
</p>
<p style="padding-left:1.2em">  먼저 작년 행정사무감사 때 말씀드렸던 내용으로 시작을 하려고 하는데요. 무기계약직 연구원, 행정원의 처우개선 문제입니다. 작년 4월에 무기직 처우개선을 위한 연구용역 결과가 마무리됐고 작년 행정사무감사에서 무기직 처우개선을 위해서 다수의 회의와 협의를 진행하셨다고 말씀을 해 주셨습니다. 그 당시 서로의 의견 차이로 인해서 협의할 내용을 확정하지 못했다고 답변을 주셨었는데요. 그래서 올해는 어느 정도, 1년이 지났으니까 어느 정도 개선이 됐는지 확인하고자 임금 테이블, 수당, 복지 등을 자료로 받아보았습니다. 그런데 일단 작년 행정사무감사 때와 동일한 금액, 동일한 등급표의 임금 테이블을 적용하고 있었고 물론 수당 등의 복지는 작년과는 다르게 기관 성과급이 추가가 된 걸 확인할 수가 있었습니다. 그래서 그거를 제외하고는 가장 많이 문제가 됐던 당시 12등급제의 임금체계가 아직까지도 적용되고 있다는 게 믿겨지지가 않는데요. 먼저 12등급제의 적용받는 인원이 총 57명으로 나와 있는데요, 이 중에 12등급 이상을 적용받아야 하는데 12등급만으로 구성돼 있어서 딱 그 경계에, 상한선에 맞춰져 있는 인원이 정확히 몇 명입니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 위원님이 양해해 주신다면 이 건은 경영부원장님이 대신 답변하도록 하겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 네.
</p>
<p><b>○ 경영부원장 장형철 </b> 경영부원장 장형철입니다. 지금 위원님께서 질의하신 부분은 총 20명이 그 대상으로 되어 있습니다.
</p>
<p><b>○ 오지혜 위원 </b> 그래서 57명 중에 20명이면 35%죠? 
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 그렇습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 35%가 원래는 12등급 이상의 등급을 받아 적용받아야 하지만 임금체계가 12등급까지밖에 없기 때문에 그 이상을 받지 못하고 계속 동일한 임금으로 적용되고 있는 거죠?  
</p>
<p><b>○ 경영부원장 장형철 </b> 네. 위원님 혹시 양해해 주신다면 지금 확정되지는 않았지만 진행된 사항들이 있기 때문에 간략하게 노사 간에 논의된 사항들을 잠깐 좀 설명을 드렸으면 하는데 괜찮으시다면 먼저 말씀을 드리겠습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 향후 적용될 내용에 대해서 말씀해 주시면 감사하겠습니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 그간 의회에서 지적해 주신 사항들을 무겁게 받아들여서 무기계약직분들의 처우개선을 위해서 네 차례 이상의 노사 간담회를 진행했고 지난 10월 28일 최종적인 노사 합의안을 만들기 위한 노사 협의회를 진행했습니다. 지금 존경하는 오지혜 위원님께서 지적하셨던 12등급으로 멈춰 있던 그것을 32등급으로 확대하는 부분에 대해서는 합의를 봤고요. 그리고 합의를 보면서 그 위에 상향 등급에 나와 있는 임금액도 부족하지만 어느 정도 노조 입장을 반영해서 상향 조정하는 것으로도 합의를 봤습니다.
</p>
<p style="padding-left:1.2em">  그리고 그동안 연구원 가ㆍ나등급만으로 단선적으로 되어 있던 직급체계를 연구원 가ㆍ나 그다음에 전문연구원 가ㆍ나 이렇게 해서 좀 중층적으로 만들어서 승진과 처우를 개선할 수 있는 기회들을 좀 더 확대하는 것으로 정리를 했고 법적으로 저희가 확인해 본 결과 문제가 없었기 때문에 이 내용들이 확정되면 소급해서 올해 적용할 수 있는 그 부분까지도 노사 양측이 협의를 했습니다. 다행히 아직까지는 최종 확정을, 도와 규정이나 여러 가지를 확정지어야 하는 단계가 남아 있지만 노사 간에는 다행히 좋은 결론을 얻어서 양측 다 지금 만족하고 있는 상황이고 도에서도 조금 적극적으로 검토를 하고 있는 상황이어서 저희가 사실은 행감 전에 결정을 짓고 좋은 보고를 드리고 싶었었는데 조금 늦어진 부분들에 대해서는 위원님들께서 양해를 해 주셨으면 감사하겠습니다. 이상입니다.
</p>
<p><b>○ 오지혜 위원 </b> 상세한 설명 감사합니다. 혹시 소급해서 적용을 하는 데 있어서 예산 수반은 언제 반영이 되는 건가요?  
</p>
<p><b>○ 경영부원장 장형철 </b> 저희가 이미 확보해 놓은 예산 내에서 그게 가능하기 때문에 그 부분도 노측과 저희 사측과 금액 전체적으로 두고 다 협의를 보고 제가 감히 말씀드릴 수는 없겠지만 양측 다 지금 만족한 차원에서 진행을 하고 있습니다.
</p>
<p><b>○ 오지혜 위원 </b> 그러면 혹시 이 문제 확정하는 것에 대해서 지금 원장님께서 공석이신데 크게 문제는 없는 건가요?  
</p>
<p><b>○ 경영부원장 장형철 </b> 지금 보시는 것처럼 권한대행이신 이사장님께서 적극적으로 업무에 책임감을 갖고 해 주시고 계시고 그래서 도하고 세부 문건들이나 확정 짓는 부분들은 필요하지만 아직까지는 별문제가 없을 것 같은데 혹시 필요한 부분이 있다면 의회의 의원님들께도 저희가 도움을 부탁드리도록 하겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 네, 감사합니다. 지금 이사장님, 원장님께서도 꼭 신경 써 주시길 부탁드립니다. 
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 보고를 받아 나누고 있습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 네. 사실 이 부분에 대해서 작년 행정사무감사에 따르면 경기연구원의 무기직 기본급이 서울연구원의 70%, 인천연구원의 80% 정도밖에 되지 않는다고 말씀을 주셨어요. 그래서 이거에 대해서 좀 많이 확대가 돼야 되지 않나라는 생각이 있었고 이번에 소급이 된다면 조금 더 나은 환경에서 연구를 잘 진행할 수 있지 않을까 하는 생각이었습니다. 그 부분에 대해서…….
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 잘 진행되도록 노력하겠습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 전국 최대 광역단체에 있는 브레인 연구원이잖아요. 그렇기 때문에 그에 맞는 처우를 해 주시기 부탁드리겠습니다. 
</p>
<p><b>○ 경영부원장 장형철 </b> 감사합니다. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 감사합니다. 다음은 기획 출판 관련된 내용입니다. 혹시 경영부원장님께서 가능하실까요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 질문을 일단 주시면 저희가 답변할 분을 정해 보겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 기획 출판 관련해서 제가 자료를 요청했었는데요. 2021년도에 기획 출판한 내용에 대해서 자료를 달라고 요청했었습니다. 보내주신 기획 출판은 총 6건인데 사실 전자도서관에는 다할미디어에서 출판한 2권의 책이 더 있습니다, 기획 출판으로. ‘답이 있는 소득’ 그리고 ‘뉴 머니, 지역화폐의 현재와 미래’라는 책이 2권 더 있는데 이거는 왜 안 주셨는지 궁금합니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 그것보다는 저희가 기본소득과 관련된 연구는 도하고 협의과정에서 대외비로 처리가 되고 있는 것들이 있어서 그 부분은 사실 행정사무감사 자료에 공식적으로는 넣지 못한 자료들이 있습니다. 그래서 혹시 그 자료를 저희가 따로 준비해서 보고드리면 안 될까요?  
</p>
<p><b>○ 오지혜 위원 </b> 이게 대외비라고요? 전자도서관에 나와 있고 판매를 하는 책인데 대외비예요?   
</p>
<p><b>○ 연구부원장 송미영 </b> 아니, 그렇기는 한데 저희가 협의하는 과정에서 기본소득이나 기본소득단과 관련된 자료는 사실 별도로 관리하고 있어서 아마 그게 누락된 모양입니다. 따로 보고를 이따 드리면 될까요?  
</p>
<p><b>○ 오지혜 위원 </b> 저는 일단 전자도서관을 참고해서 이미 판매되고 있는 책에 대한 내용을 말씀드린 거기 때문에 공개되어 있는 건데 대외비라고 말씀하신 것에 대해서 동의를 할 수가 없고요. 그리고 제가 일단 판매 부수 그리고 판매 수익금, 판매 출판 예산, 그 예산은 어느 부분에서 나가는지도 질문을 했었는데 자료가 구체적으로 오진 않았습니다. 일단 출판 예산은 어느 사업비에서 지출이 되고 있는 건가요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 출판 예산이라고 해서 별도로 되는 게 아니고 과제를 성립할 때 과제 예산 중에 출판을 저희가 내부에서 그냥 인쇄할지 아니면 조금 더 상업적인 목적으로 기획하는 상업적 출판사하고 할지를 결정하는 과정을 하게 되고요. 그걸 성과보고회를 통해서 하게 됩니다. 그래서 그때 결정되는 거에 따라서 어떤 출판물은 그냥 내부에서 인쇄해서 하는 형식을 취하게 되고 보편적인 독자들을 대상으로 해서 조금 더 연구결과를 확산할 필요가 있을 경우에는 기획 출판물을 저희가 다시 또 결정하게 되고 그렇게 해서 별도 인쇄를 하게 됩니다.
</p>
<p><b>○ 오지혜 위원 </b> 그러면 처음부터 이거는 기획 출판으로 가자라고 결정을 하고 나서 출판사를 정해서 시행을 하게 되는 거죠?  
</p>
<p><b>○ 연구부원장 송미영 </b> 그렇게 해서 정해지는 과제들도 있고 그렇지 않은 과제들도 있고 아까 제가 말씀드린 대로 어떤 특정한 사안마다 다르게 결정이 되는데 아까 말씀하신 온라인 도서관에 있는 과제들은 과제를 정하고 나서 기획 성과물을 인쇄할 것을 저희가 결정한 것들이 아마 대부분일 것이고 아까 저희가 별도로 드린 6권의 책은 사실은 전임 원장님하고 처음부터 상업적인 목적을 가지고 조금 더 연구결과를 다양한 독자층을 대상으로 해서 기획된 출판물입니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그래서 사실 이 부분에 대해서 또 궁금했던 건 판매 부수, 그러니까 상업적인 목적이고 다양한 독자들을, 다수의 독자들을 위해서 만든 책이기 때문에 판매 부수라든가 그 책의 저자들에 대한 수익금의 분배는 어떻게 되는지도 궁금했는데 해당 내용은 출판사 경영 관련 사항으로 제공이 어렵고 발행된 지 얼마 안 돼서 판매 수익금의 분배는 없다고 말씀을 주셨습니다.
</p>
<p style="padding-left:1.2em">  그래서 제가 이런 자료를 찾아보다가 서울연구원 홈페이지라든가, 서울연구원의 경우에는 아예 그냥 단행본을 독자적으로 출판하고 있더라고요. 그러니까 다른 출판사와 하는 게 아니라 서울연구원 자체에 출판팀이 있어서 그 부분에서 단행본을 굉장히 주기적으로, 한 달에 한 번 정도로 출판을 지속적으로 하고 있는데 굳이 그렇게 다른 출판사를 하지 않아도, 다른 출판사라는 게 좀 어렵잖아요. 그런 운영 같은 게, 경영이라든가 수익금 분배라든가 어려운데 독자적으로 출판을 할 수 있는 능력이 있고 그리고 할 수 있다면 경기연구원 자체에서 출판을 하는 것도 나쁘지 않다는 생각을 했습니다. 그래서 이 부분에 대해서도 좀 반영해 주시면 감사하겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 저희도 그런 점을 고려해서 홍보정보부에 출판 인력이라든가 전문적인 편집 인력들을 계속 보강은 하고 있으나 서울연구원에 비해서는 아직 충분한 인력을 확보하지 못한 상태라 저희 자체적으로 그런 기획물을 출판할 여력은 아직 안 됐습니다. 그런데 앞으로 위원님 지적해 주시는 대로 저희 자체역량을 조금 더 강화해서 노력하도록 하겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 감사합니다. 이상입니다.
</p>
<p><b>○ 위원장 심규순 </b> 오지혜 위원님 수고하셨습니다. 그쪽 발언 답변석에서 여기 시간 남는 거 보이나요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 보입니다. 
</p>
<p><b>○ 위원장 심규순 </b> 여기 보여요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 여기 이 시간이 보입니다.
</p>
<p><b>○ 위원장 심규순 </b> 아, 그쪽도 보이나요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 네.  
</p>
<p><b>○ 위원장 심규순 </b> 그거 감안해서 좀 답변해 주시기 바랍니다. 위원님들이 제한된 시간이 있기 때문에. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 계속해서 질의하실 위원님 계십니까? 김재균 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 김재균 위원 </b> 평택 출신의 김재균 위원입니다. 항상 이거 감사를 볼 때마다 그리고 업무보고 받을 때마다 참 희한한 게 있는 게 지금 1페이지에 보면 인력현황이 195명으로 돼 있죠?  
</p>
<p><b>○ 연구부원장 송미영 </b> 네.  
</p>
<p><b>○ 김재균 위원 </b> 그러면 정원은 187명인데 현원은 195명, 그 밑에 비정규직은 연구과제 수행을 위한 기간제 인력인데 최소한 정원이라는 그 숫자 안에 맞춰주는 게 정상적인 행정 아닌가요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 답변을 드려도 될까요?  
</p>
<p><b>○ 김재균 위원 </b> 네.  
</p>
<p><b>○ 연구부원장 송미영 </b> 원래 정원 안에서 저희가 운영을 하는데 저희가 수탁이라든가 외부과제를 수행한다는 것을 아마 아실 겁니다. 근데 수탁과제를 운영할 때 저희 내부인력만으로 하기가 힘들어서 외부에서 인력을 초빙해서 기간제로 쓰고 있는데 그분들을 28명 저희가 쓰고 있습니다. 올해는 특히 그게 기술적인 과제에서 실태조사라든가 분석을 하는 과제들이 저희가 많아서 이분들이 많이 지금 현재 고용된 상태입니다.
</p>
<p><b>○ 김재균 위원 </b> 물론 계시고 있는 연구원들이나 그런 분들을 해 가지고 연구를 하는 게 가장 하지만 특별한 경우는 기간제 인원이 들어온다고 그랬지만 어떤 부분의, 여기 지금 경기연구원 같은 경우는 특수한 경우니까 약간의 이해는 가지만 정원을 맞춰주는 건 조직에서 하나의 기본적이라고 봐집니다. 보통 조직에서 정원을 몇 %를 갖고 있느냐 하면 90%에서 92%로 해서 100% 풀로 채우는 데가 별로 없어요. 공직에서도 그렇고 사조직에서도 그렇고 사회적인 기업에서도 그렇고 그렇게 가는데 어디 가서 봐 가지고 인력현황이라는 거 가장 평범한 것이 가장 좋은 거라고 생각을 하는데 정원을 넘어서서 매번 지금 이런 현상이 나와요. 그러면 보이지 않게 지금 경기연구원은 정원에 의미가 없다는 얘기예요. 아니면 정원이 더 필요하면, 이런 경우가 계속 지금 반복적으로 생기니까 정원을 늘려 가지고 예비 정원을 갖고 있다가 현원으로 만들어야죠. 그걸 매년 인정해 달라고 그러는 거는 좀 미안하지 않아요?
</p>
<p><b>○ 연구부원장 송미영 </b> 저희도 죄송하게 생각은 하는데 이제 저희가 하는 일이 연구이다 보니 어떤 특정 회의에 특정한 연구수요가 갑자기 발생할 때가 있습니다. 그런데 그런 전문인력이 저희 연구원에 있지 않은 때가 있고 그 인력을 갑자기 저희가 충당하지 못해서 그분들을 기간제 비정규직으로 운영하다가 그 업무가 저희 업무의 어떤 면에서 정규적인 업무가 되고 일상적인 업무가 되면 그분들은 또 공개채용을 통해서 정규직으로 뽑기도 합니다마는 어떤 해에는 저희가 이렇게밖에 운영할 수 없다는 점을 좀 양해해 주시기 바랍니다. 
</p>
<p><b>○ 김재균 위원 </b> 올해 같은 경우는 지금 인천광역시에서 21년도 수도권 여객 기종점 통행량 조사 및 현행화 공동사업 이것 때문에 인원이 좀 늘었다고 저는 봐집니다, 본 위원은. 
</p>
<p><b>○ 연구부원장 송미영 </b> 그것도 있고요, 다른 연구들도 있습니다.
</p>
<p><b>○ 김재균 위원 </b> 그러면 거기에 맞춰서 갈 수 있는 여분을 갖고 가서 그때그때마다 상위기관의 인정을 받고 임기제도 하는 게 좋지 자체적으로 했을 때, 솔직히 지금 저희는 감사기관입니다. 감사기관에 이게 매년 이런 식으로 정원보다 현원이 많다고 그러는 거를 이해해 달라고 그러면 그게 이해가 됩니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 근데 아시다시피 저희가 기간제근로자가 1년 미만을 근무하는 분들이 대부분이고 저희가 하는 수탁과제에서 임용되는 분들이 지금 현재 시점에서 이렇게 있는 거지 내년이 되면 또 그 과제나 그 과제의 성격상 그분들을 저희가 계속해서 고용할 수 없는 상황이 있습니다. 왜냐하면 위원님들도 아시다시피 저희가 정원에 거의 육박하게…….
</p>
<p><b>○ 김재균 위원 </b> 시간이 되게 없거든요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 말씀하세요. 
</p>
<p><b>○ 김재균 위원 </b> 계속 그런 식으로 해서 변명식으로 나가려면 예스와 노로 대답하라고 그럴 거예요.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 알겠습니다.
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 위원님, 제가 한 말씀만 드려도 되겠습니까?  
</p>
<p><b>○ 김재균 위원 </b> 네.  
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 그런데 경기연구원은 제가 잠깐 보니까 다른 연구원하고 차이가 있어요. 다른 연구원들은 연구분야가 한정이 돼서 있는데 경기연구원은 분야가 한정돼 있는 거하고 제한이 없습니다. 그래서 다양한 연구들이 수시로 나오는 거예요. 이게 경기연구원 운영하는 데, 인력운영하는 데 가장 큰 애로점입니다. 그래서 이 사람이 1년도 근무를 못 하는데 이 인원을 정원 속에 포함시켜도 되느냐 안 되느냐 이런 고민들을 경영 일선현장에서는 하지 않을 수가 없다 이런 말씀을 제가 첨언을 합니다.
</p>
<p><b>○ 김재균 위원 </b> 제가 2년째 경기연구원의 업무보고를 받고 지금 감사를 하고 있지만 여기 3페이지의 예산현황을 보면 특별하게 들어가는 돈 자체가 거의 출연 쪽으로 오는데 그래서 자체, 관외사업으로 어떤 사업에서 좀 예산의 증대를 가져올 수 있는 방법을 하라고 그래서 쭉 보고 있는데 그런 부분이 아직까지도 굉장히 미진해요. 물론 공적인 연구를 하다 보니까 그런 부분 미흡할 수도 있다고 약간은 들지만 앞으로 자구책으로, 경기연구원이 경기도가 있는 동안은 계속 존재를 하겠지만 자기 자생력을 키우려면 최소한, 연구원이라고 하지만 본 위원의 생각으로는 30% 정도는 자급자족을 해야 되지 안 그러면 솔직히 정원을 줄이든지 할 수밖에 없지 않겠느냐는 게 언젠가는 과제로, 난제로 나올 것 같아요. 근데 그거를 계속 요구를 하는데도 지금 그게 안 들어가, 지금 실행이 안 되고 있어요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 그거는…….
</p>
<p><b>○ 김재균 위원 </b> 어떤 회사가 됐든, 사조직이 됐든 공조직이 됐든 자급자족의 힘이 강할수록 자기가 갈 수 있는 길이 있고 그 목적한 바대로 갈 수가 있는데 그렇지 못하면 외압에 의해서 휘둘릴 수밖에 없거든요. 이따가 보충질의 때 하겠지만 지금 3년 동안에 밖에하고 한 거, 우리 경기도하고 시군에서 주는 계약금액 없으면 지금 여기 같은 경우는 굉장히 힘들다고밖에 판단이 안 돼요. 자생력이 그렇게 세지가 않다고 보여지는 거예요. 어느 조직이든지 살아가려면 자생력이 있어야 되는 거 아니에요. 지금 2019년도 보면 42건의 저기를 하셨어요.
</p>
<p><b>○ 연구부원장 송미영 </b> 수탁과제 말씀하시는 겁니까?  
</p>
<p><b>○ 김재균 위원 </b> 네, 수탁과제요. 42건을 했는데 지금 22건이 경기도하고 연관된 거예요. 아니면 경기도 31개 시군하고 연관된 거. 그래서 36억 4,600만 원 정도를 지금 했는데 관에서, 여기서 22건이 지금 얼마 정도 되나 보니까 23억 6,000만 원이에요. 그러면 관에서 한 거는 3분의 1밖에 안 된다는 거예요. 3분의 2 이상이 지금 경기도 또는 경기도와 관계된 시군에서 들어온 거예요.
</p>
<p style="padding-left:1.2em">  2020년도에 보면 47건을 해 가지고 지금 57억 9,600만 원 정도의 수탁을 했는데 32건이 경기도하고 경기도와 연관된 데서 해 가지고 외주로 밖에서 순수하게, 본 위원이 지금 판단하는 거는 57억 중에서 32건, 50억 정도는 경기도와 연관된 거 그리고 7억 8,000 정도만 경기연구원에서 어떤 노력을 했다고 봐지는 거예요. 21년도에는 37건을 했는데 경기도에서 지금 저기 한 게 24건, 37건이……. 13건 중에서 지금 보면 1,000만 원짜리 단위고 경기도 내외에서 했던 게 31억 정도가 되는데 47억 중에서 31억이고 외부에서 수탁이 좀 많아졌다고 생각해서 봤는데 인천광역시에서 21년도 수도권 여객 기종점 조사를 해서 10억짜리가 하나 들어온 게 있더라고요. 그거 빼고 나면 결국은 자체용역으로 한 건 4억 8,000밖에 안 된다는 얘기예요. 그렇게 분석을 할 수밖에 없어요, 지금. 과연 자생력이 있느냐? 거기에 대해서 잠깐만 답변을 해 주실래요? 시간은 끝났지만.
</p>
<p><b>○ 연구부원장 송미영 </b> 만약에 저희 연구원의 자생력에 대해서 답변을 요구하시면 제가 참 드리기가 어려운 게 저희 연구원은 원래 설립목적이 경기도하고 시군에 정책적인 지원과 연구개발을 하는 것을 목적으로 설립이 되었기 때문에 지금까지는 사실 저희 정책연구, 출연금에 기반한 정책연구를 주로 하고 있고요. 수탁을 만약에 어느 정도 요구하신다면 거기에 맞춰서, 목표에 맞춰서 점점 늘려가고 있는 상황입니다. 그 부분이 조금 부족하다고 생각되신다면 행정부하고 다시 또 의논을 하고 도의회 의견을 반영해서 저희가 더 조정하는 그런 역할은 필요하겠으나 지금 현재 하고 있는 수탁도 저희가 그냥 경기도나 시에서 받는 게 아니고 대부분 다 입찰을 통해서 수주를 하고 있는 상황이라 저희도 나름대로 노력은 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그런데 그 비중이 얼마나 되어야 하고 그런 역할을 얼마나 저희 연구원에 원하시는지에 대해서는 사실 도의회하고 행정부서하고의 협의가 필요한 부분이라고 저는 생각이 듭니다.
</p>
<p><b>○ 김재균 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 심규순 </b> 김재균 위원님 수고하셨습니다. 계속 이어서 이제영 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 이제영 위원 </b> 안녕하세요? 성남 출신 이제영 위원입니다. 전쟁을 오래하면서 승리할 수 있는 요건이 뭐라고 생각하세요?
</p>
<p><b>○ 연구부원장 송미영 </b> 어떤 의미에서 말씀하시는지?
</p>
<p><b>○ 이제영 위원 </b> 보급이라고 얘기 많이 하더라고요. 보급이 제대로 안 되면 어떤 전쟁도 장기간에서 이길 수 있는 전쟁은 없다 이런 얘기를 하거든요. 연구원의 역할이 저는 경기도에 그런 보급 역할을 하고 있다라고 생각하거든요. 공감하십니까?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 얼마 전 지방지에 보도된 걸 보면 “이름값 못하는 ‘경기硏’ 도내 시군 수탁연구 저조”, “서울연구 절반 불과 연구실적” 이런 게 보도된 게 있어요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 있습니다.
</p>
<p><b>○ 이제영 위원 </b> 그렇다라고 하면 제가 말씀드린 경기도의 정책방향이나 어떤 정책기조를 이끌어가는 데 역할이 미흡하지 않았나 이런 판단이 들거든요. 언론 비판 없이 그냥 칭찬만 받고 기관을 운영하기란 쉽지 않을 겁니다. 그렇지만 이런 것도 뼈아프게 받아들여서 향후에는 정책방향으로 삼아줬으면 좋겠다는 말씀을 드리겠습니다.
</p>
<p style="padding-left:1.2em">  경기연구원에서 운영하는 공식 블로그가 있더라고요. 그래서 검색을 쭉 해 보니까 2020년도에는 1월부터 12월까지 운영이 잘됐어요. 필요한 내용이 계속 블로그에 올라와 있고. 그런데 2021년도 1월 22일 날 경기도 음식점업 2020년 폐업 분석 이렇게 해서 올라오고 난 이후에는 이게 10월 달까지 계속 블로그에 올라온 게 없더라고요. 아마 모 언론사 모 기자분께서도 이거에 대해서 두 부서에, 홍보정보부하고 전략정책부에 왜 이걸 올리지 않고 있느냐 이런 거를 그쪽으로 문의한 것 같은데 두 군데 부서의 답이 틀린 것 같아요. 그렇게 한 9개월 이상을 공식 블로그에 게재 안 한 이유가 뭔지에 대해서 좀 간략하게 답변해 주시기 바랍니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 이거는 경영부원장님이 답변드려도 되겠습니까?
</p>
<p><b>○ 이제영 위원 </b> 네.
</p>
<p><b>○ 경영부원장 장형철 </b> 경영부원장입니다. 존경하는 이제영 위원님 지적해 주신 것처럼 저희 온라인 쪽 운영하는 부분에 업데이트가 안 돼 있던 부분에 대해서 언론 쪽에서 지적을 받았고 저희도 내부적으로 살폈는데 아마 변명에 불과하겠지만 저희 내부 인원 중에 이직이 좀 있었고 업무를 관리하고 또 홈페이지나 이런 디자인 등을 전환하는 과정에서 저희가 실무적으로 그 부분은 좀 부족했던 부분입니다. 그래서 언론 그 지적사항을 보고 나서 내용을 빨리 조치하기 위해서 한 8월 달 것까지의 관련된 내용들은 지금 새로 올려뒀고 추가적으로 더 필요한 부분들은 빨리 보완조치를 하도록 그렇게 노력하도록 하겠습니다.
</p>
<p><b>○ 이제영 위원 </b> 그러니까 이게 블로그에 올리는 거기 관련 자료는 다 필요한 때가 있지 않습니까?
</p>
<p><b>○ 경영부원장 장형철 </b> 그렇습니다.
</p>
<p><b>○ 이제영 위원 </b> 수출입 동향도 그 시점 걸 올려야지 다 지나서 소급해서 올려놓으면 그거 뭐로 확인이 돼, 조회 수가 낮지 않습니까, 그게.
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 맞습니다.
</p>
<p><b>○ 이제영 위원 </b> 그 자료 봐서 도움도 안 되는데 누가 조회를 하겠습니까?
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 저희가 부족했던 부분입니다.
</p>
<p><b>○ 이제영 위원 </b> 지금 말씀하신 것은 제가 볼 때 2~3개월 정도라고 하면 직원이 결원되거나 이런 이유로 해서 가능하다라고 저도 이해가 될 수 있거든요. 그런데 이거는 지금 1월 달에 등재가 되고 나서 10월 그 이후에 등재된 게, 10월 6일 날 한 번에 6건, 13일 날 5건, 14일 날 3건 이렇게 올린다고 하면 연구원 본연의 역할하고는 이게 너무 동떨어진 게 아닌가. 물론 이게 큰 부분이 아닐 수도 있어요. 그러면 이건 가장 기본적으로 해야 될 부분인데 이게 지켜지지 않았다라고 하면 이 자료를 참고로 해서 했던 분들은 연구원에 대한 어떤 신뢰를 갖겠습니까. 우리 부원장님께서 좀 전에 지적하신 그런 내용으로 공감할 사람이 누가 있겠습니까?
</p>
<p><b>○ 경영부원장 장형철 </b> 위원님 지적이 마땅하고요. 이 업무 자체를 책임지는 부원장으로서 대단히 죄송하다는 말씀드립니다.
</p>
<p><b>○ 이제영 위원 </b> 그래서 이것은 원인이 뭔지에 대한 분석을 지금 포괄적으로 답변하셨는데 제가 볼 때는 그 이유는 아닐 것 같고요. 다른 이유가 있지 않을까? 아까 존경하는 김재균 위원님께서도 여러 가지 지적 말씀을 하셨어요. 아까 연구원의 이사장님께서도 경기연구원의 특징이 연구범위가 제한돼 있는 게 아니라 굉장히 펼쳐져 있기 때문에 인력운영이나 이런 게 어렵다라고 얘기를 하셨는데 좋게 얘기하면 이것저것 다 관심 있게 연구활동이 이루어진다라고 볼 수 있고 또 다르게 보면 본연의 연구목적 외에 다른 데에 관심을 갖는 게 아닌가 이런 오해를 받을 수도 있어요. 한 예로 여기 아까 보고한 것 중에 지속가능한 공정 경기도를 위한 담론 연구 추진 해서 여기 대중서적 출간 6개 이렇게 돼 있습니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 이걸 연구원이라는 걸 빼놓고 이 제목만 가지고 “이거 어디서 발행했을 것 같습니까?” 물어보면 아마 99%는 국가연구원에서 이걸 했을 거라고 답변하지 경기연구원에서 했을 거라고 답변 안 할 거 같아요. 그러면 이 시점에 공정한 부동산 지속가능한 도시부터 공정한 국제질서와 한반도의 지속가능한 평화, 그럼 경기도하고 어떤 연계가 있느냐라고 하면 뭐 연계가 될 수도 있겠죠. 그런데 이렇게 봤을 때 과연 이거는 국가연구기관에서 해야 될 건데 왜 이 시점에 경기연구원에서, 이거 외부 원고를 줬거나 내부 연구진이 작성했거나 이렇게 됐을 거 아닙니까? 
</p>
<p><b>○ 경영부원장 장형철 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 그럼 왜 했을까에 대해서는 뭐 이건 조크입니다. 그럼 여기 전임 지사께서 어떤 대권 가는 데 있어서 공약이라든가 기타 이런 거에 연계될 수도 있지 않을까 이런 오해를 받을 수도 있는 겁니다, 이게. 그렇다라고 하면 이게 발행되는 게 긍정적인 측면을 제가 무시하는 건 아닙니다. 그렇지만 그것도 오비이락이라고 해야 될 때가 있고 이런 건데 지금 제가 지적한 것대로 블로그에 주요지표 올리는 것도 9개월 동안 하지를 못하면서 이런 것을 만들어 한다는 것을 긍정적인 시각으로만 볼 수 있겠느냐, 저는 합리적인 의심을 해 보는 겁니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 답변드려도 되겠습니까?
</p>
<p><b>○ 이제영 위원 </b> 답변 짧게 해 주세요.
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 홍보 부분에 있어서의 역량이 부족했고 챙기지 못했던 부분들과 연구사업의 성과 부분들은 물론 저희 연구원 전체의 역량에 대한 평가이시겠지만 조금 분리해서 봐 주셨으면 좋겠습니다. 아까 말씀드렸던 것처럼 홍보 파트 부분에서 좀 부족했던 부분은 완전히 인정을 하고 개선을 위해 노력하겠습니다. 그런데 지금 말씀드렸던 것처럼 경기도의 연구역량이라는 것이 경기도 내의 구체적인 의제에 대한 부분이기도 하고 전국적인 혹은 전 세계적인 경향성에 대한 연구도 경기연구원에서 마땅히 맡을 수 있는 연구의 분야라고 생각을 합니다. 그러니까 그런 취지로 경기연구원에서 선택한 연구영역이었다라는 생각을 해 주셨으면 좋겠고 말씀하신 대로 그렇게 좀 다르게 판단하신다면 그건 저희의 취지와 맞지 않게 오해의 여지들이 훨씬 좀 많은 부분이라고 말씀드리고 싶습니다.
</p>
<p><b>○ 이제영 위원 </b> 답변 됐고요. 제가 합리적 의심이 든다라고 했지 뭐 그렇게 잘못했다고 지적한 건 아니니까 그렇게 길게 설명 안 하셔도 될 것 같고요. 
</p>
<p style="padding-left:1.2em">  그다음에 경기연구원 비상근 임원을 6월 달에 공개모집을 해서 선정이 됐어요. 
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 그렇습니다.
</p>
<p><b>○ 이제영 위원 </b> 여기에 보면 한 분이 비상근 이사로 되셨는데 서울시의회 의장실 비서실장 현직이지요?
</p>
<p><b>○ 경영부원장 장형철 </b> 그렇습니다.
</p>
<p><b>○ 이제영 위원 </b> 이분이 선임됐어요. 그러면 타 자치단체에 현직으로 있는 분을 이렇게 해야 되는 어떤 당위성이 있습니까? 이런 예가 있었어요, 그동안에?
</p>
<p><b>○ 경영부원장 장형철 </b> 저희 절차에 따라서 심사위원들이 여러 가지 방향과 목적, 자질에 대한 평가를 통해서 결정을 하신 거라고 생각을 합니다.
</p>
<p><b>○ 이제영 위원 </b> 여기 탈락되신 분 현황을 보면 박사가 네 분이나 계세요, 이분은 석사고. 그러면 박사가 네 분이나 오셨는데, 한 분도 아니고. 뭐 박사라고 해서 다 유능하고 꼭 필요한 분은 아니라고 생각이 들 수 있겠지만 이분은 석사고 또 현직에 서울시에 근무하고 계신 분을 여기 박사분을 네 분씩이나 탈락시키면서 해야 될 이유가 뭘까?
</p>
<p><b>○ 경영부원장 장형철 </b> 네 분이 탈락하고 서울시의회 비서실장님만 된 게 아니고 그때 다른 분야의 세 분 또 다른 박사급의 좋으신 분들도 함께 이사로 결정이 되셨습니다.
</p>
<p><b>○ 이제영 위원 </b> 아니, 그러니까 그렇게 얘기하는 것을……. 
</p>
<p><b>○ 경영부원장 장형철 </b> 그래서 전체적으로 총량을 맞추어서 분야……. 
</p>
<p><b>○ 이제영 위원 </b> 저를 이해시키려고 하지 마시고 도민들한테 이 사람이 이렇게 필요하고 이런 역량이 있어서, 대부분 이렇게 할 때는 어느 자치단체 현직인 분은 통상적으로 임명하지 않는 걸로 알고 있거든요. 왜냐하면 현직 근무하고 있으면 하다못해 회의를 소집하거나 뭘 하더라도 여러 가지 제약이 될 수 있고……. 
</p>
<p><b>○ 경영부원장 장형철 </b> 겸임에 대해서 그쪽에서 충분히……. 
</p>
<p><b>○ 이제영 위원 </b> 그렇다라고 하면 장점이 아닐 수도 있는데 굳이 역량 있는 다른 분들이 많이 응모를 했음에도 불구하고 그분을 해야 되는 당위성에 대해서 저를 이해시키려고 하지 마시고 도민들한테 이래서 이 사람을 뽑았습니다 하는 얘기를 짧게 답변 듣고 제가 질의 마치도록 하겠습니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 아까 말씀드렸던 것처럼 공정한 과정을 통해서 해당 분야의 전문성을 가지고 계신 이사님이 선정됐다고 생각을 하고요. 오히려 역으로 보면 현직 서울시의회에 계신 분이기 때문에 수도권의 교류와 지방자치에 대한 협력 부분에 있어서 보다 큰 장점이 있기 때문에 선정이 되셨을 거라고 생각합니다. 도민 여러분께서 혹시 의문을 제기하신다면 그 부분에 대해서 어디에서든지 찾아뵙고 설명을 드리도록 이렇게 하겠습니다.
</p>
<p><b>○ 이제영 위원 </b> 그럼 결과보고서 제출해 주실 수 있나요? 지금 말씀하신 거라고 하면 공개 못 할 이유 없을 것 같은데, 그렇다라고 하면.
</p>
<p><b>○ 경영부원장 장형철 </b> 결과보고서라는 게 어떤 걸 말씀하시는 건가요?
</p>
<p><b>○ 이제영 위원 </b> 여기 이분을 채택하게 된. 심사하면서 그런 과정을 제출해 주실 수 있어요, 그러면?
</p>
<p><b>○ 경영부원장 장형철 </b> 그거는 아까도 말씀드린 것처럼 연구원에서 저희가 자체로 했던 게 아니고 외부 심사위원 등등이 참여했던 그 과정을 통해서 됐기 때문에……. 
</p>
<p><b>○ 이제영 위원 </b> 아니, 공정하게 했다고 지금 말씀을 하시니까. 그렇다라고 하면 제가 어디 공개하지 않고 하는 조건하에서 저만 아니면 여기 위원님들 같이 볼 수 있게끔 제출해 주실 수 있습니까?
</p>
<p><b>○ 경영부원장 장형철 </b> 그런데 위원님, 모든 심사과정에 관련된 결과보고서를 여러 방향으로 판단할 수 있는데 하나의 방향 때문에 저희가 공개할 수는 없는 것 아니겠습니까? 심사위원님들의 고유한……. 
</p>
<p><b>○ 이제영 위원 </b> 아니, 그러니까 어디 공개 안 하는 조건하에서, 지금 공정한 것을 강조하셨으니까 제가 말씀을 드리는 거예요. 그런 얘기를 안 하셨으면……. 
</p>
<p><b>○ 경영부원장 장형철 </b> 그러면 위원님, 죄송하지만 이게 저희가 공정하지 않았다는 근거가 어떤 게 있으신지 사실은 좀 납득이 되지 않는 부분이 있습니다.
</p>
<p><b>○ 이제영 위원 </b> 아니, 그걸 저희가 확인하고 싶어서 제출해 줄 수 있느냐를 제가 여쭤보는 겁니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 그 부분에 대해서는 아까 말씀드렸던 것처럼 심사위원분들의 고유한 권한이고 절차상으로 이루어졌고 법적인 문제가 없기 때문에 지금 말씀드렸던 것처럼 저희가 짐작하는 그 취지로서만 말씀을 드리고 나중에 그 이사분의 활동이나 이런 걸 가지고 또 결과적으로 한번 말씀을 드리는 걸로 이해를 해 주셨으면 좋겠습니다, 위원님.
</p>
<p><b>○ 이제영 위원 </b> 알겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 심규순 </b> 이제영 위원님 수고하셨습니다. 지금 이제영 위원님이 말씀하셨던 블로그 문제나 SNS 문제, 요즘 블로그 잘 안 하죠. 5명, 6명 들어가 있고요. 한꺼번에 8개월 치 올린다는 것은 블로그를 폐쇄해야 돼요. 이제영 위원님이 정확한 거 얘기하셨어요. 한꺼번에 몰아서, 이 중에 전부 다 박사님들이신데 SNS 관리팀이 있잖아요.
</p>
<p><b>○ 경영부원장 장형철 </b> 네.
</p>
<p><b>○ 위원장 심규순 </b> 그 관리팀이 왜 있습니까? 과감히 폐쇄하시고 페이스북 하세요. 페이스북도 들어가니까 지금 11월 15일 날 올렸는데 그게 페이스북 연동이 잘 안 되네요. 기본적으로 경기도의원들은 팔로우 신청을 해야죠. 서로 공감해야죠.
</p>
<p><b>○ 경영부원장 장형철 </b> 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 위원장 심규순 </b> 그것도 관리를 누가 합니까? 정확한 지적을 해 주셨기 때문에. 그리고 아까 그 인사 문제는 공개되는 범위에서는 줄 수 있지만 비공개되는 정보나 개인정보에서는 줄 수가 없잖아요.
</p>
<p><b>○ 경영부원장 장형철 </b> 네.
</p>
<p><b>○ 위원장 심규순 </b> 공개되는 범위에서 줄 수 있다고 생각을 합니다. 그거 한번 따져보시고 검토해 보시기 바랍니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 위원장 심규순 </b> 계속해서 염종현 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 염종현 위원 </b> 부천 출신 염종현 위원입니다. 조금 아까 우리 허성관 이사장님이 경기연구원의 정책연구개발 분야가 대단히 넓다고 그랬는데 그래서 제가 경기연구원이랑 서울연구원의 설립목적을 잠깐 찾아봤는데 서울연구원은 “서울시정 발전에 기여하는 데 있음.” 이렇게 돼 있고 경기도는 “국가와 경기도 발전을 위한 정책개발에 기여함.” 경기도가 대단히 넓네요, 사실. 이거대로 하는지 모르지만.
</p>
<p style="padding-left:1.2em">  하여튼 이 정관 얘기가 나왔으니까 정관에 관련돼서 하나 먼저 질문을 드리면 직무대행님 관련인데요. 저희가 경기연구원의 정관에 따르면 대표가, 원장이 궐위가 되면 이사장님이 권한대행으로 되는 게 돼 있어요. 그래서 제가 오늘 경기도 공공기관, 대표적으로 경기관광공사, 경기아트센터, 경기문화재단 쪽의 정관을 한번 살펴봤는데 모든 곳이 다 경영본부장이 대행을 하게끔 이렇게 돼 있습니다. 그래서 이렇게 된 이유가 뭔지 보니까 18년 12월인가요, 정관 개정을 했는데 이유가 뭐가 특별한 게 있는지?
</p>
<p><b>○ 연구부원장 송미영 </b> 이 부분도 경영부원장님이 답변하시도록 하겠습니다.
</p>
<p><b>○ 염종현 위원 </b> 네.
</p>
<p><b>○ 경영부원장 장형철 </b> 경영부원장입니다. 지금 말씀하셨던 부분들은 이전에 존경하는 위원장님께서도 한번 말씀을 하셨던 부분이었는데 2018년 당시 상황을 정확하게는 알 수 없겠지만 해당되었던 연구부원장 직책에 계신 분과 그리고 또 연구원의 운영에 있어서 가장 밀접한 영향을 가지고 있는 도 등등의 의논 결과 대외적인 대표성의 문제들이나 이런 역할들이 있고 또 연구를 담당하는, 저희는 지금 직제상으로 보면, 지금 존경하는 염종현 위원님 말씀대로면 연구부원장님께서 그 역할들을 해야 되는 그렇게 직제의 순서들이 되어 있습니다. 그러니까 연구 파트 쪽에 대한 집중력들을 좀 더 높이고 다른 대외적인 전체적인 총괄 역할들은 다른 파트에서 했으면 좋겠다라는 취지가 저희는 있었다고 생각합니다.
</p>
<p><b>○ 염종현 위원 </b> 그 과정은 이해를 하는데 지금 이사장님이 비상임이잖아요.
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 그렇습니다.
</p>
<p><b>○ 염종현 위원 </b> 그리고 지금 서울연구원도 권한대행으로 있어요. 서울연구원장도 권한대행으로 있습니다. 
</p>
<p><b>○ 경영부원장 장형철 </b> 그렇습니다.
</p>
<p><b>○ 염종현 위원 </b> 그런데 거기는 기획본부장이 하고 있습니다. 똑같은 연구원이죠. 그래서 서울연구원이 꼭 맞다는 건 아니지만 서울연구원이나 경기도 대표적인 공공기관들의 권한대행 체제가 다 경영과 관련된 본부장들이 맡는다 하니까 이 부분은, 왜냐하면 대표 권한대행으로 오면 여기에 대해서 전체적으로 업무가 숙지돼야 됩니다. 아까 말씀드린 대로 이사장님의 대외적인, 우리 허성관 대행님 같은 경우에는 뭐 대단하신 이력을 갖고 계시죠. 해양수산부장관도 하시고 행자부장관도 하시고 그러나 권한대행 체제에 있어서 실무적인 문제는 또 다릅니다. 이 부분은 재검토 요청을 한번 제안드리는 바입니다. 
</p>
<p><b>○ 경영부원장 장형철 </b> 알겠습니다. 한 가지만 더 말씀드리면 대표권을 행사하기 위해서는 법률적으로 이사의 직을 가지고 있어야 하는데 현재는 부원장들이 그 이사직을 가지고 있는 규정도 미비되어 있기 때문에 지금 말씀하셨던 모든 부분들을 좀 감안해서, 그런데 특히나 이번에 원장님 부재 상황에서 맞닥뜨린 상황에서 정관을 다르게 고치면서 나가는 게 또 다른 오해를 일으킬 수 있기 때문에…….
</p>
<p><b>○ 염종현 위원 </b> 아니, 지금 상황은 이해를 한단 말이죠. 하는데……. 
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 그래서 적극적으로……. 
</p>
<p><b>○ 염종현 위원 </b> 전체적인 거를 봤을 때 좀 다시 한번 고민이 필요하지 않을까 제안드리는 겁니다.
</p>
<p><b>○ 경영부원장 장형철 </b> 내부적으로 다시 한번 그 부분은 주신 말씀 가지고 상의해 보도록 하겠습니다.
</p>
<p><b>○ 염종현 위원 </b> 네, 고맙습니다. 그렇게 하시고요. 아까 우리 존경하는 김재균 위원도 말씀하시고 했는데 우리 연구원 부원장님, 질책을 좀 받으셨죠. 그래서 질책을 받으실 건 받으셔야 되는데 제가 작년에 업무보고 때인가요, 이제 기억이 나는데 저희가 흔히 서울연구원을 많이 비교합니다. 우리 오지혜 위원님께서도 서울연구원에 비교한 바가 있는데 그래서 저희가 예를 들면 예산 같은 경우에도 서울시 서울연구원은 417억입니다. 저희는 286억 정도 되죠. 인력도 보니까 정원이 233명 대 187명, 46명이 좀 적어요. 근데 이 부분이 좀 이해가 안 갑니다. 살펴봐야 되는데 그 인력 중에서 서울연구원은 연구직이 154명이에요. 그런데 저희는 84명입니다. 그런데 전체적인 정원은 한 46명 차이뿐이 나지가 않는데 연구직은 70명가량 차이가 납니다. 이해가 좀 안 가는데 그래서 연구과제에 있어서도 보면 저희는 19년, 20년, 21년 3개년 자료를 제가 봤지만 기본부터 정책위탁, 수탁, 연구과제까지 토털해서 2020년 기준으로 하면, 2021년이 지금 9월 30일까지뿐이 안 나와 있으니. 172건인데 동일한 서울시 서울연구원의 2020년 토털이 352건입니다. 2배죠, 2배. 한번 살펴보십시오. 제가 확인한 자료는 그렇습니다.
</p>
<p style="padding-left:1.2em">  그래서 이런 것들을 봤을 때 저희가 3개년에서 한 5개년 정도 계획을 중장기적으로 인력이라든지 예산이라든지 이런 준비가 좀 필요하다. 그래서 거기에 대해서 보고를 해 달라, 그런데 보고가 되질 않았어요. 그러니까 행정사무감사 조치결과에는 완료 비슷하게 나왔는데 전혀 주문한 거에 대해서 조치결과가 온 게 없습니다. 그러니까 이런 겁니다. 우리가 예산이나 인력이나 등등이 우리 경기도 설립목적에, 정관에 국가까지 들어가 있는 상황에서 그것을 수행해 내기 위해서는 그만한 예산과 인력이 뒷받침이 돼야 돼요. 그리고 서울시 인구가 지금 오늘 현재 955만 명입니다. 경기도가 1,090만이라고 얘기를 해요. 그러니까 경기연구원에 인력과 예산을 주자고 제가 얘기하는 게 아닙니다. 그런데 인구로 보나 지방분권, 자치분권 시대에서 우리가 봤을 때 경기도가 점점 비중이 높아지고 지리적으로나 한반도의 중심 아닙니까. 그렇게 봤을 때는 약진이 필요한데 너무 예산과 인력에 대한 고민이 좀 없었다.
</p>
<p style="padding-left:1.2em">  그래서 전임 연구원장님한테도 제가 각별히 얘기를 드렸었는데 그러기 위해서는 단숨에 이게 해결되는 게 아니잖아요. 그래서 적어도 3년에서 5년 정도의 인력과 예산에 대한 고민을 담은 중장기 계획을 만들어서 의회에 제출해 달라라고 당부를 드렸어요. 그런데 여태까지 그 피드백이 없어요.
</p>
<p style="padding-left:1.2em">  그래서 그런 면에서 시급하다 이런 말씀을 드리고 그때도 기억나지만 공공투자센터 같은 경우에도 그렇습니다. 공공투자센터도 오늘 제가 확인해 보니까 서울이 4팀에 25명이에요. 근데 우리 공투가 그래도 많이 인원이 좀 늘어났습니다, 초반에 비해서는. 그런데 우리는 3부에 16명, 9명 차이거든요. 그래서 이러한 것을 좀, 그러니까 우리가 인력이, 예산이 이만큼뿐이 안 되는데 서울연구원을 어떻게 쫓아갑니까. 당연히 못 쫓아가죠. 근데 못 쫓아가는 이 자체가 저는 문제가 있다는 얘기입니다. 심각한 문제가 있어요. 경기연구원에서 집행부와 왜 그런 고민을 안 합니까. 그래서 국가와 경기도의 발전을 위한 설립목적에 맞게 우리가 해 나가야죠. 그러려면 거기에 대한 그림이 나와야 될 거 아닙니까. 그래서 집행부와도 의논하고 의회랑도 의논하고, 의회에서는 당장, 아니 경기도에서 연구과제도 이렇게 하고 예산을 보면 서울시 같은 경우에 수탁 예산이 95억이에요, 95억. 우리가 15억 5,000입니다. 어마어마한 차이죠. 자체수입입니다. 그러니까 경기연구원의 이런 필요, 이런 준비 부족하다. 그래서 다시 한번 말씀드리지만 빠른 시간 내에 중장기 계획을 짜서 의회에 제출해 달라. 기재위원님들과 함께 머리를 맞대고 고민해 볼 필요가 있다. 그러고 나서 현 상태에서 잘잘못은 우리가 행감을 통해서 지적을 하겠지만 그런 계획서를 일단 제출해 주시기 바랍니다. 답변 한번 듣고 마무리하도록 하겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 여러 가지 질책을 해 주신 거는 저희도 다 수용을 하는 입장이고요. 저희가 올해 조금 부진하거나 부족했던 부분이 있었고 앞에 말씀하신 중장기 계획은 저희가 계속 논의를 하고 있었는데 저희가 연구원 이전이며 여러 가지 문제가 불거지면서 그 내용을 좀 정리하는 과정에서 의사결정이 늦어졌습니다. 말씀하신 대로 저희가 빨리 준비를 해서 도하고도 협의를 마치고 위원님들한테도 보고하는 자리를 갖도록 하겠습니다. 죄송합니다.
</p>
<p><b>○ 위원장 심규순 </b> 염종현 위원님 수고하셨습니다. 계속해서 원미정 위원님 자료요청해 주시기 바랍니다.
</p>
<p><b>○ 원미정 위원 </b> 제가 시작 전에 자료요청을 좀 했는데요, 안 오네요. 그런데 2021년 6월에 이미 보고서가 발간돼서 이걸 토대로 해서 예산실에서 예산 참고로 해서 편성을 하잖아요. 그래서 그냥 출력해 주시면 될 거라고 생각하고 있는데 왜 안 주실까? 혹시 뭐 편집을 하시나요? 그대로, 제가 여기 전체 다 보고서를 볼 수 있는 상황은 아니고 몇 가지만 확인하려고 하는 건데 이게 늦어지는 이유를 모르겠어요. 6월 달에 이미 보고서는 정리가 된 걸로 알고 있는데. 
</p>
<p style="padding-left:2.4em">    (「그거 준비해서 바로 드리도록 하겠습니다, 제가.」하는 관계직원 있음) 
</p>
<p><b>○ 연구부원장 송미영 </b> 죄송합니다. 준비 중이라고 합니다.
</p>
