<p><b>○ 연구부원장 송미영 </b> 연구의 필요성은 저도 공감을 하고요. 그 연구를 수행할 수 있는 여건이 될 수 있도록 의회에서 조금 더 적극적으로 말씀을 해 주셔야지만 아마 저희가 수행할 수 있을 겁니다.
