<p><b>○ 이영봉 위원 </b> 알겠습니다. 계속해서 현안사업을 좀 보겠습니다. 경기연구원 내 도내 시군 수탁연구와 경기북부 연구실적에 관련하여 질의를 좀 드릴 수 있도록 하겠습니다. 최근 3년간 공개된 경기연구원의 연구보고서를 토대로 확인한 결과 시군에서 위탁받아 진행하는 연구가 계속적으로 줄어들고 있고 경기북부 관련 연구도 소극적인 것으로 나타나고 있어요. 여기 자료를 살펴보니까 시군 수탁연구 실적이 2018년도 10건, 2019년도 5건, 2020년도는 조금 많습니다, 16건. 올해는 이제 끝난 것은 아니지만 현재 11건 이렇게 진행됐습니다. 이게 맞습니까?  
