<p><b>○ 연구부원장 송미영 </b> 저희가 사실 시군 수탁은 조금 줄어들었지만 시군 간에 협의를 해서 도 행정부를 통해서 오는 과제들이 있습니다, 시군 정책과제라고. 시군 정책과제가 1년에 최소한 13개 이상을 저희가 하고 있고 그것들도 수행하기가 좀 저희가 버거워서 어떤 의미에서는 연구 숫자는 늘지 않고 있습니다. 그런데 시군에서 이제 도를 통해서 시군 수탁과제 대신에 시군 전략과제를 저희한테 요구하시기 때문에 그 과제의 성격이 거의 수탁과제 같은 성격을 저희가 하고 있습니다. 그래서 그 부분들로 지금 수행하는 걸로 하고 있어서 그런 격차가 통계에서는 나타나고 있음을 양해해 주셨으면 합니다.
