<p><b>○ 연구부원장 송미영 </b> 아까도 답변을 드렸지만 저희가 수탁에 정말 주력을 해야 되는지가 우선 결정이 되어야 하고요. 그다음에 수탁에 주력을 하는 걸로 결정이 되면 저희가 예산을 받는 구조, 출연금의 구조라든가 지금까지 연구원에서 하고 있는 연구과제의 선정 구조도 조금 더 개선이 돼야지만 저희가 그쪽으로 주력을 할 수가 있습니다. 그런데 그거는 아직까지는 사실 도의 행정부서에서는 제안된 바가 없고 오히려 행정 쪽에서는 저희의 다양한 전략적인 정책과제라든가 일반 정책과제 같은 것들을 더 많이 요구하시는 상황입니다.
