<p><b>○ 위원장 심규순 </b> 이영봉 위원님 수고하셨습니다. 지금 자료요청을 했는데 자료요청이 안 오고 있고요. 자료요청이 늦어지면 말씀해 주시기 바랍니다. 계속 이어서 정희시 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 정희시 위원 </b> 수고 많습니다. 정희시 위원입니다. 아주 디테일한 질문들은 위원님들께서 다 많이 하셨기 때문에 조금 포괄적인 질의를 하겠습니다.
</p>
<p style="padding-left:1.2em">  민선7기 경기도 정부에서 가장 핵심적으로 진행했던 것이 기본소득 그리고 지역화폐에 관련된 이런 연구성과를 이룬 것 같아요. 그동안에 고생을 하셨는데 혹시 소회나 이런 거 있습니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 그 부분은 기본소득 단장님이 좀 답변하시도록 해도 되겠습니까?
</p>
<p><b>○ 정희시 위원 </b> 아니요, 간단하게. 시간……. 
</p>
<p><b>○ 연구부원장 송미영 </b> 간단하게 하자면 사실 저희가 연구를 수행하고 연구결과를 확산하고 이런 여러 가지 것들에서는 보람이 있었으나 반대로 아까 말씀드린 것처럼 정무적인 판단에 의해서는 다양한 어려움이 있었습니다. 그건 위원님들이 더 잘 아실 거라고 생각합니다.
</p>
<p><b>○ 정희시 위원 </b> 역사적으로 학자들 또는 책사분들이 가지는 여러 가지 고민들은 있을 것 같아요. 본인이 주도해 가지고 했을 때와 또는 수명업무로서 했을 때 여러 가지 생각들이 있을 것 같은데 어찌 됐든 큰 성과는 이루셨는데 저는 경기연구원에서 진행하는 지역현안 토론회를 보면서 개선을 좀 해야 되겠다는 생각을 해 봤습니다. 이번에 먼저 현실을 가지고 잠깐 질문을 하자면 지역현안 토론회가 좀 부진했어요. 횟수라든지 그리고 또 내용 준비도 좀 부진하신 것 같은데 그 이유가 뭘까요?
</p>
<p><b>○ 연구부원장 송미영 </b> 어떤 의미에서는 저희가 현안에 급급하다 보니 좀 부진했었던 것으로 저는 생각합니다.
</p>
<p><b>○ 정희시 위원 </b> 저는 경기연구원이 존재하는 것은 크게 두 가지로 볼 수 있겠죠. 하나는 정책 최종결정자의 정책을 뒷받침하는 그것도 중요하죠, 경기연구원이 존재하는 데. 또 한편으로는 경기연구원이 스스로 어떤 정책을 만들어내는 엔진으로 역할을 할 때 더 아마 에너제틱해지고 또 조직이 활성화될 것이라고 보는 거고 그것은 그만큼 본 연구원 자체가 고민을 해야 되는 이런 사안이라 생각합니다. 우리 위원회에서 지역현안에 대한 토론을 하자 이렇게 제안을 했는데 사실은 지역현안이라기보다는 관심, 꼭 지역과 관계없이 현안들에 대한 토론회를 현장감을 가지고 있는 위원님들하고 같이 하자 이런 개념이거든요. 그래서 그런 부분에서는 적극적으로 동참하지 않은 데 대해서 좀 유감을 표현하고 내년부터는 이것을 위원들하고 그냥 한다 이런 개념이 아니고 정말 같이 고민하고 같이 설계를 해서 내년에는 좀 더 심도 깊고 꼭 지역현안을 넘어서 대한민국 또는 세계적인 이슈에 대해서도 한번 토론회를 하는 게 좋겠다. 
</p>
<p style="padding-left:1.2em">  왜냐하면 연구원은 연구를 할 수 있는 능력은 있지만 예산편성권이나 예산을 세우는 것은, 입법권은, 예산심의권은 없습니다. 그래서 우리가 제안하는 이유는 예산심의권을 가지고 있는 의회와 또 예산편성을 가지고 있는 우리 집행부랑 같이 토론회를 열고 그래서 실제로 정책과제가 예산으로 수립되고 정책으로 수립될 수 있도록 하자는 그런 취지거든요. 그런 면에서 올해 진행됐던 것은 시작은 좋았으나 상당히 유감이다 이렇게 생각하고 있어요.
</p>
<p><b>○ 연구부원장 송미영 </b> 답변을 드릴까요?
</p>
<p><b>○ 정희시 위원 </b> 네, 그러시죠.
</p>
<p><b>○ 연구부원장 송미영 </b> 사실 저희 연구원이 연구만 하는 곳이라고 생각하시겠지만 그 외에 여러 가지 것들을 많이 수행해야 되고 연구를 준비하는 과정에서 사실 저희가 이렇게 경영부원장하고 연구부원장으로 나눠져 있다 보니 두 원장 체계가 원활하게 작동하지 않은 점도 있습니다. 그다음에 여러 측면에서 저희가 대외협력부가 아직은 완전히 본인의 역량의 최고조에 도달하지를 못하고 있어서 그런 문제가 발생했던 것으로 저는 판단합니다.
</p>
<p><b>○ 정희시 위원 </b> 그렇게 보완을 좀 해 주시고요. 저는 근간에 대선 국면이라든지 또 그동안의 연구를 쭉 보면 너무 이슈 중심의 파이팅, 그런 정책 이게 좀 매몰돼 있는 부분이……. 
</p>
<p><b>○ 연구부원장 송미영 </b> 그쪽에 너무 치우쳤다고 생각하시는 거죠?
</p>
<p><b>○ 정희시 위원 </b> 있었다는 것은 사실인 것 같고. 그래서 제가 생각할 때는 좀 놓치고 있는 부분이 또는 놓치고 싶은, 너무 까다로운 문제니까. 부분이 인구문제예요. 2021년 주요 이슈 중의 하나로 연구원 스스로 인구구조 변화, 저성장 이런 부분에 대해서 인지를 하고 계시고 그걸 중요과제로 삼고 있었어요. 그런데 여기에 대한 연구라든지 SIB 연구를 아마 한 것 같은데 그 부분에 대한 설명을 나중에 해 주시기 바라고 어떤 생각을 가지고 있는지, 어떤 정책을 또 생산했는지.
</p>
<p style="padding-left:1.2em">  그리고 또 하나는 기후변화, 이번에 문재인 대통령도 유엔에서 연설을 하시고 또 영국에도 다녀오시고 했는데 기후변화와 기후위기 또는 그것을 담보하기 위한 탄소중립 이것은 세계적인 흐름이거든요. 이것은 정략적인 문제하고 전혀 관계없는 앞으로의 흐름이라고요. 그것이 미국의 정치적인 어떤 에너지원을 바꾸겠다는 이런 부분이 있을지라도 어찌 됐든 결국은 전체적인 흐름인데 이런 부분에 대해 우리 경기연구원에서 진짜 고민을 하고 있는지. 그래서 최소한 이 고민을 다음 도지사한테 한번 이렇게 했으면 좋겠다라는 이야기를 할 수 있는 그런 준비를 하고 있는지를 묻고 싶어요. 만약에 지난 우리 도지사님한테는 못 했다면.
</p>
<p><b>○ 연구부원장 송미영 </b> 인구문제 관련해서는 인구 관련한 통계나 이런 일을 하시는 분들을 저희가 추가로 인력을 구성하기도 했고 복지나 사회문제 쪽 박사님들도 계속 채용을 하면서 이 부분을 저희가 조금 더 체계적으로 그다음에 구조적으로 접근하려고 노력 중에 있습니다. 아직 성과가 충분하지 않은 점은 유감, 죄송스럽게 생각을 하고. 어쨌든 저희가 저희 현안 중에 하나로 채택을 했고 내년이나 앞으로 향후 연구방향에는 특히 이 문제에 더 집중해서 의회 의원님들하고 현안도 발굴하도록 하겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 이 문제는 우리 위원장님도 관심이 많은 부분이고 하니까……. 
</p>
<p><b>○ 연구부원장 송미영 </b> 의논을 더 드리도록 하겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 위원님들하고 같이 하는 것이 얼마나 소중하고 또 시간을 단축할 수 있고 공감대를 형성할 수 있고 실제로 집행을 할 수 있는 데 근접할 수 있는가를 생각해 보면 대단히 중요하다.
</p>
<p><b>○ 연구부원장 송미영 </b> 조금 더 의논을 자주 드리도록 하겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 네, 그렇게 좀 부탁을 드립니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 그다음에 말씀하신 기후변화와 관련된 부분도 탄소중립 관련해서 앞으로 조금 더 연구를 많이 하도록 할 텐데 저희가 탄소인지 예산이라든가 탄소중립화 전략이라든가 이런 것들은 이미 지금 진행 중에 있습니다.
</p>
<p><b>○ 정희시 위원 </b> 지금 에너지 2030, 더 나아가서는 4030까지 가고 있는데 에너지 2030에 대해서 경기도 정책이 저는 안 보여요. 그러면서 뒷받침할 수 있는 경기연구원에서의 자료도 또 안 보이고 그리고 인구정책이라고 하는 것 중에 하나 조금 해 보겠다 했던 SIB도 안 하고 있어요. 그래서 도대체 무슨 생각을 하고 계시는 건지 아쉽습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 말씀하신 부분은 좀 부족한 부분을 보완해서 내년 연구에 더 반영해서 하고 그다음에 위원님들하고도 의논하는 자리를 좀 더 마련하겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 그래서 사전 설계를 우리 위원장님 중심으로 좀 해 주시고 설계를 하고 또 실질적으로 토론회가 되든 정책발표회가 되든 그런 거 하는 시점을 후반기로 잡지 말고 내년 선거가 있어도……. 
</p>
<p><b>○ 연구부원장 송미영 </b> 상반기에 잡도록 하겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 선거 관계없이 세상은 또 중요해요, 돌아가야 되니까. 전반기부터 일찍 하나하나 좀 준비를 해 나갔으면 좋겠다는 말씀드립니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네. 그리고 에너지 관련해서는 경기도 에너지 비전을 저희 연구원에서 이미 했었고요. 그 내용에 따라서 추진을 하려고 하는데 사실 생각보다 집행부 쪽에서 에너지 정책을 추진하는 데 굉장히 부담스러워하는 측면이 있어서 그 부분이 좀 어렵다는 것은 이해하실 거라고 생각이 듭니다.
</p>
<p><b>○ 정희시 위원 </b> 어려우니까 안 하는 거예요. 어려운 걸 해야죠. 그게 정치죠. 쉬운 것만 하면 정치인 필요 없죠.
</p>
<p><b>○ 연구부원장 송미영 </b> 위원님들이 조금 더 도와주시면 더 열심히 해 보겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 참고로 이건 제 개인의 이야기입니다만 19일 날 쓰레기에 관련된 토론회를 해요. 경기도에서 사실 쓰레기 문제가, 가장 배출을 많이 하고 있는데 대책이 없어요. 그동안 매립 중심으로 해 왔는데 매립지 다 없어지고. 그래서 이런 부분에 대해서도 연구원 분 중에 누가 한 분 참여하는데 과연 그렇게 사명감을 가지고 적극적으로 참여하는 것인가? 그래도 참석을 해야지 이렇게 생각하면서 같이 하고는 있는데 그러나 그 진행과정을 지켜보면서 좀 아쉬운 부분이 있고요. 하여간 이런 인구문제라든지 탄소중립 또는 에너지원의, 새로운 에너지원에 대한 대안 이런 거에 대해서 좀 관심을 가지고 내년에 위원님들하고 한번 좀 더 연구를 해 나갔으면 좋겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 지역현안 토론회를 그런 주제를 중심으로 저희가 기획해서 의논드리겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 이상입니다.
</p>
<p style="padding-left:2.4em">    (심규순 위원장, 이필근 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 정희시 위원님 수고하셨습니다. 원미정 위원님 질의하시기 바랍니다.
</p>
<p><b>○ 원미정 위원 </b> 안산 출신 원미정 위원입니다. 자료요청한 거를 이렇게 편집을 해서 주셨네요. 그래서 주고 싶은 것만 주나 봐요. 제가 보고 싶은 게 안 오고.
</p>
<p><b>○ 연구부원장 송미영 </b> 다시 말씀해 주시면 정리해서 드리겠습니다.
</p>
<p><b>○ 원미정 위원 </b> 아니에요. 전체적으로 일몰 사업이나 감액 사업이나 이런 것들을 평가할 때 기준이 뭘까도 좀 보고 싶었고요. 그러니까 리스트만 지금 주셨네요. 그냥 쭉 리스트 정리하셔서 주시느라고 좀 늦게 주셨는데 그거 외에 일몰 사업에 대한 이유들, 평가들 다 정리했잖아요. 그리고 의견수렴을 한 번씩 했고. 그 내용을 보려고 그랬던 건데 그냥 리스트를 쭉 정리해서 일몰 사업, 감액 사업만 정리해서 주셨고요. 나중에 추가적으로 한번 전체, 그냥 전체 자료 한번 주시고.
</p>
<p style="padding-left:1.2em">  우리 경기도공공투자관리센터가 조례에 의해서 18년도 설립이 돼서 경기도의 재정건전화에 기여하고 공공투자 사업의 내실화, 효율성 제고를 위해서 운영을 하고 있는데요. 얼마나 효과적으로 업무를 진행하고 있는지에 대한 여러 가지 검토가 필요한 듯합니다. 앞서서 우리 염종현 위원님께서도 간단하게 짚기는 하셨는데 서울공공투자센터와 경기도 센터의 규모나 실적이나 이런 성과들이 아직 출발이 다르기 때문에 단순 비교하기는 좀 어렵기는 하지만 어쨌거나 공공투자센터에서 하는 여러 가지 일들의 신뢰가 사실은 높아져야 그 목적하는 바가 효율성도 제고되고 재정건전성도 높아질 거라고 보여지거든요. 그렇게 하기 위해서는 굉장히 정보의 공개나 투명성이 되게 중요한 것 같은데 제가 홈페이지를 한번 들어가 봤는데요. 기본적으로 올라와 있는 정보의 수나 이런 것들도 굉장히 부족하고요. 실적으로 말씀해 주신 이 자료에는, 경기연구원 전체 자료에는 여러 가지 실적 건수들은 많기는 하지만 실질적으로 홈페이지에 올라와 있는 정보공개는 그렇게 많지 않다라는 말씀드리고요. 
</p>
<p style="padding-left:1.2em">  그리고 그냥 이거는 사이드이기는 하지만 저희가 핸드폰으로 보는 데 최적화돼 있지는 않아요. 제가 KDI도 들어가 보고 다른 데 들어가 보면 이게 우리가 컴퓨터로 볼 수만은 없잖아요. 그러니까 급하게 계속 자료들을 할 때 깨져요. 핸드폰으로 보면 거기서 보여줄 수 있는 것들이 전체적으로 한 화면에 보이지 않고 정보도 많지는 않지만. 그러니까 이게 작은 것 같지만 굉장히 신뢰의 문제일 것 같아요. 이 기관에 대해 일반 도민들이 볼 때 굉장히 성의가 덜해 보이기도 하고 정보의 내용도 좀 부실하다는 느낌이 굉장히 많이 듭니다. KDI와 비교할 수는 없지만 그것들을 참고해서 경기도의 공공투자관리센터로서의 위상과 또 신뢰도를 좀 높여주셨으면 좋겠다라는 말씀드리고요. 
</p>
<p style="padding-left:1.2em">  일몰 사업은 제가 개별 사업으로 여러 의견들을 좀 듣기는 합니다, 저희 소관은 아니어도. 그래서 제가 평가기준이나 이런 것들을 좀 더 객관적으로 어떻게 보고 있을까에 대한 것들을 한번 찾아보고 싶기는 해서 그 기준들이 있다면 별도로 저한테 좀 설명을 해 주시고 기준을 제시해 주셨으면 좋겠는데 대체적으로 기계적으로 평가할 수 있는 게 있고 예를 들어서 어떤 마을 만들기나 주민 의식을 높이는 그런 어떤 운동적 개념의 사업들은 사실 굉장히 객관적 수치로 성과를 표현하기가 되게 어렵습니다. 저도 그런 활동을 하다가 의회로 들어왔지만 이게 주민들의 의식이 변화되는 것들이 눈으로 바로 보이거나 아니면 숫자로 표현하기가 참 어렵고 그리고 공동체 사업이라는 것이 진짜 이렇게 숫자로 아무튼 표현하기는 참 어려운 사업들이라 제대로 평가받지 못하는 경우가 굉장히 많습니다. 그래서 그런 것들을 어떻게 기준을 가지고 평가해서 일몰 내지는 감액 사업으로 제시를 하는가에 대한 검토가 한번 저는 필요하다는 생각을 했고요. 
</p>
<p style="padding-left:1.2em">  왜냐하면 이거에 근거해서 예산편성이 되고 있습니다, 경기도 예산과에서. 그래서 그냥 일몰 사업으로 여기서 평가를 해 줘버리면 그 사업은 그냥 날아가는 사업이 돼버려요. 그래서 그 부분에 대해서 저한테 의뢰가 와서 한번 검토를 했는데 조금 제가 받아들이기가 어려운 결과들이 있어서 별도로 이건 한번 세부자료를 주시면 좋겠다라는 말씀을 드리고요. 
</p>
<p style="padding-left:1.2em">  그리고 정보공개에 대한 것들도 좀 더 추가적으로 노력을 해 주셨으면 좋겠다라는 말씀드리겠습니다. 간단하게 답변해 주시고요.
</p>
<p><b>○ 연구부원장 송미영 </b> 그 부분은 공투 소장님이 답변드리도록 하고 정보공개 측면은 저희가 그룹웨어나 이런 거를 계속 업데이트는 하고 있는데 속도가 좀 느려서 그렇습니다.
</p>
<p><b>○ 원미정 위원 </b> 길게 설명하지 마시고요. 속도가 아니라 내용 자체가 부실합니다. 양이 적고요. 전체적으로 하신 실적에 비해서 올라와 있는 것은 굉장히 적습니다.
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 공공투자관리센터 소장 김도일입니다. 답변드리겠습니다. 우선 평가 관련해서, 재정사업 평가와 관련해서 평가기준에 대해서 말씀드렸는데요. 제가 간략하게 먼저 말씀드리고 세부적인 것은 지침이나 이런 게 있기 때문에 그 자료를 추후로 제출하도록 하겠습니다. 
</p>
<p><b>○ 원미정 위원 </b> 조금 간단하게 설명해 주세요.
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 일단 크게 보면 평가는 그 사업부서가 자체적으로 평가하는 게 50% 그다음에 전문기관에서 평가하는 게 50% 이렇게 합쳐서 평가를 하게 되고요. 그다음에 평가기준에 대해서 아까 말씀하실 때 객관적인 수치로 분석하기 어려운 거 그건 역시 저희도 마찬가지로 어렵고요.
</p>
<p><b>○ 원미정 위원 </b> 그래서 제가 한 예로는 아무튼 사업부서는 적극적인 평가를 하고 있는데 투자센터에서의 의견서는 굉장히 일몰 사업으로 평가가 되어지는 사업들이 있어요. 제가 이게 정답이다 이렇게 말씀드리는 건 아닌데 그래서 그런 사업들 평가할 때 굉장히 쉽지 않다. 그래서 그런 기준들을 조금 더 객관화하고 사업부서의 의견들을 충분히 반영하는 것이 필요하다라는 생각이 들어서 한 번 더 점검해 주시기를 요청드리고 그 기준은 제가 좀 한번 봤으면 좋겠다라는 말씀드리고요.
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 한 가지만 더 말씀드리면 저희가 평가를 마치면 그거를 그 사업부서하고 인터뷰를 합니다. 이렇게 평가결과가 나왔는데 동의하는지 그걸 다 의견수렴을 해서 최종적으로 나온 것이 그거고요. 그다음에 저희가 지금 현재 완벽하게 모든 보고서가 다 나오지는 않았습니다. 아직도 편집 중에 있는데……. 
</p>
<p><b>○ 원미정 위원 </b> 제가 그 과정에 사실은 좀 개입해서 많이 들어, 양쪽을 다 들었던 사안이 있어서 말씀을 드리는 거고요. 아무튼 좀 더 점검해 주고 도민들이, 그걸 위탁받아서 하는 사업들이기 때문에 사실은 또 어떻게 보면 도민들의 의견수렴도 굉장히 중요하다. 그러니까 사업의 특성상 그렇다는 거예요. 그런 것들을 좀 보내주시길 기대하겠습니다. 
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 네, 알겠습니다.
</p>
<p><b>○ 원미정 위원 </b> 제가 다음 질문이 있어서. 우리 지방연구원과의 공동연구 추진 관련해서는 누가 답변을 해 주실까요?
</p>
<p><b>○ 연구부원장 송미영 </b> 질의를 해 주시면 일단……. 
</p>
<p><b>○ 원미정 위원 </b> 아니, 지방연구원 관련한 공동연구 관련해서 어디서 담당하십니까?
</p>
<p><b>○ 연구부원장 송미영 </b> 저희 연구부서에서 하는 일입니다.
</p>
<p><b>○ 원미정 위원 </b> 네. 이거는 현재 100만 이상의 시도에서 연구원들이 다 설립되어 있는 연구원들과 공동연구를 한 거죠? 울산연구원이나 경남연구원, 광주전남연구원, 대전세종연구원하고 공동협약을 해서 추진하겠다라고 진행한 바 있잖아요?
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 있습니다.
</p>
<p><b>○ 원미정 위원 </b> 그거 관련해서 혹시 연구결과에 대해서 나온 게 있나요? 추진 아니면 연구를 하고 있는 게 있거나.
</p>
<p><b>○ 연구부원장 송미영 </b> 올해 추진한 것들은 아직 진행 중인 것들이라서요. 아직 결과가 나오지 않았습니다. 나오는 대로 보고드리도록 하겠습니다.
</p>
<p><b>○ 원미정 위원 </b> 기사에 의하면 간단한 한 가지 연구사례를 좀 말씀하시기는 하는데 지방자치단체 간 갈등조정 방안 연구, 경기도 및 경남 사례를 중심으로 공동연구 중, 그러니까 어떤 연구를 하고 있는지는 제가 리스트를 보지 않아서 그냥 어떤 협약을 위한 협약이거나 보여주기식 협약이 아니라 정말 지방 간의 공동연구가 필요한 과제가 뭔지에 대한 고민들이 조금 더 필요하지 않을까라는 생각이 좀 들었습니다.
</p>
<p style="padding-left:1.2em">  그리고 이거하고 조금 다르기는 한데요. 지금 지방자치단체출연 연구원의 설립 및 운영에 관한 법률에 의해서 지방연구원이 설립되잖아요, 그 기준에 의해서. 그런데 현재 법에는 100만 이상으로 되어 있어요. 근데 지금 50만 이상인 시군들에서는 지역 실정에 맞는 정책연구 개발이 필요하다고 그래서 지방연구원 설립기준 완화, 그러니까 50만 이상으로 좀 개정해 달라는 요구를 계속하고 있습니다. 알고 계십니까?
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 알고 있습니다.
</p>
<p><b>○ 원미정 위원 </b> 그리고 지금 박완주 국회의원께서 개정안도 발의한 것으로 알고 있어요. 그 내용도 좀 한번 검토하셨나요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 저희가 검토하지는 않았습니다. 
</p>
<p><b>○ 원미정 위원 </b> 왜 그러냐 하면 어쨌거나 경기연구원도 시군의 수탁사업들, 연구사업들 좀 받아서 진행을 하고 있잖아요. 하고 있죠?   
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 원미정 위원 </b> 결과 보니까 10건 정도, 지금 2021년도에는 5건, 2018년도 10건, 16건, 11건, 5건 이러네요. 어쨌거나 이제 추세는 저는 그렇게 가야 된다고 보거든요. 50만 이상은 자체적인 지역현안에 맞춰서 연구과제들을 선정해서 적극적으로 연구를 하는 것이 저는 필요하다고 생각을 하고 또 지역현안에 대해서 신속 대응을 하기 위해서도 적극적으로 필요해요. 그래서 이런 어떤 법적 개정의 흐름에 맞춰서 경기연구원의 대응도 저는 필요하다고 생각을 해서 이 질문을 드리는 겁니다. 그래서 전체적인 기존에 시군의 수탁사업들을 받아서 많이 연구과제들을 했고 또 그 예산을 봐도 그렇게 적지 않은 예산이란 말이에요. 이런 부분들이 법 개정이 되고 자체적인 연구원들이 설립이 되면 분리돼서 연구를 하게 될 것 같고 이후에는 공동연구의 개념으로 가지 않을까라는 생각이 들어서 어떤 법적 개정의 흐름을 잘 인지하시고 그거에 대해서 대응을 좀 해야 되지 않을까라고 해서 질의를 드립니다. 답변 듣고 마치겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 원래 저희 연구원이 처음에 생길 때도 사실 국책연구원이 하던 역할 중에 지방연구원이 역할을 맡아가면서 하면서 자리를 잡아왔고 저희 연구원이 사실 국책연구원하고 하는 여러 가지 협력사업들이 지금도 있고 그다음에 광역시하고 하는 여러 가지 협력사업들도 다 있습니다. 그건 상호 공감대가 있는 연구주제를 가지고 협약을 토대로 해서 하는 거고요. 앞으로 아까 말씀하신 것처럼 시군에서 연구원이 생겨나면 그런 방향으로 당연히 갈 수밖에 없고 저희도 그런 방향에 맞춰서 연구체제를 조금씩 전환할 예정입니다.
</p>
<p><b>○ 원미정 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 원미정 위원님 수고하셨습니다. 또 본질의할 위원, 질의하실 위원님 계신지요? 김강식 위원님 질의하시기 바랍니다.
</p>
<p><b>○ 김강식 위원 </b> 제가 자료요청한 게 있는데 사실은 그렇게 양이 많아 보이진 않는데 자료가 오지 않고 있어요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 다시 한번만 말씀해 주시면 점검해 보겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 연구원에 있는 내부 직원분들의 외부활동에 대한 부분들을 다 승인받고 지금 하고 있지 않습니까? 그래서……. 
</p>
<p><b>○ 연구부원장 송미영 </b> 아까 말씀하신 그 자료가 아직 준비가 안 됐습니까? 대외협력부장…….
</p>
<p><b>○ 김강식 위원 </b> 그 리스트를 좀 달라고 했고 공기관 대행사업들 3년간 했던 내역을 좀 부탁을 드렸는데…….
</p>
<p style="padding-left:2.4em">    (대외협력부장, 김강식 위원에게 자료 전달)
</p>
<p style="padding-left:1.2em">  아니, 제가 궁금한 건 이런 겁니다. 어쨌든, 이제 왔네요. 지금 어쨌든 연구, 제가 재작년에 기조실에서 공기관들 평가하는 경영평가 말고 다른 평가했던 지표들을 보면 경기연구원의 지표가 구성원 1인당 창출하는 부가가치에 대한 부분들이 서울연구원하고 비교했을 때 상당히 높다라는 데이터가 있었어요, 지표가. 그거는 어떻게 보면 두 가지로 볼 수 있는데 1인당 하는 일이 되게 많거나 아니면 인력에 대한 부분들이 서울연구원보다 부족하거나 이 두 가지로 볼 수 있거든요. 사실 지금 어쨌든 경기연구원이 갖고 있는 조직적인 부분들 속에서 지금 인력에 대한 부분들이나 아니면 이런 부분들 속에서 충분히 이 부분들이 다 충원되고 아니면 활동할 수 있는 부분들까지 되고 있나요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 답변드릴까요?  
</p>
<p><b>○ 김강식 위원 </b> 네.  
</p>
<p><b>○ 연구부원장 송미영 </b> 저희가 사실 지금 한 최근 2년 동안 인력을 상당히 부족한 부분을 많이 충원했습니다. 그래서 조금 더 역동적이고 다양한 분야의 연구 대응을 하려고 노력은 하고 있으나 아시다시피 저희 연구원이 한 사람당 거의 4건의 연구 정도를 수행하고 있고 저희 연구원은 서울연구원에 비해서 현업이나 현안이 굉장히 많습니다. 그다음에 전임 원장님의 연구 방향이 연구의 양보다는 질 쪽으로 조금 더 집중했으면 좋겠다는 말씀도 하시고 해서 조금 양적으로는 저희가 부족한 부분이 있음을 말씀드리겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 그래서 어쨌든 지금 활동하면서 부족한 부분들이 있고 충분히 어쨌든 그분들의 인력이나 여러 가지 지금 채워가고는 있는데 제가 연구원 분들의 대외활동에 대한 것들을 좀 요청을 드렸던 건, 이것보다 좀 더 디테일한 거는 18년도 행감 조치에도 보면 대외활동을 할 때 거기에 윤리 이런 거에 따라서 신청하고 금액들이나 강의료나 부대 행사를 했던 부분들을 충분히 앞으로 반영해서 하겠다라는 답변이 있으셨어요, 조치결과에. 그래서 그 결과를 보고 싶었던 부분들이 있고요. 왜냐하면 지금 횟수만 갖고 보면 대외활동 횟수가 1년에 평균 33회, 19년도에. 20년도에 35회, 한 30회 정도 외부에 대한 활동들을 하고 계시거든요. 이 내용들이 과연 어떤 내용인지는 잘 모르겠지만 대외적인, 제가 비슷한, 우리 경기연구원 말고 경기도 내의 다른 연구원들에 대한 부분들을 봤을 때 어쨌든 지금 경기연구원에서 연구활동들을 하기에도 턱없이 좀 힘들고 어려운 조건인데 대외활동을 통해서 어쨌든 그 연구에 충실히 할 수 있는 시간들 동안에 대외활동들을 좀 하고 있는 것들은 아닌가라는 부분들의 우려를 하고 있어서 그 부분들이 데이터를 가지고서 좀 봤으면 좋겠다라는 부분들 때문에 그래서 이 자료보다는 어쨌든 지금 1인당 전체 수로 보면 2,800건, 20년도에 2,900건 이 정도 되거든요. 구성원들이 그 정도로 대외활동들에 대해, 그러니까 이 내용들을 제가 전체를 모르겠으니까 좀 더 자세하게 내용을 좀 주시면 다음번 종합감사 때 이 부분들에 대한 얘기를 할 수 있었으면 좋겠다라는 생각을 하고요. 
</p>
<p style="padding-left:1.2em">  경기연구원의 정관사항에서 보면 제가 아까 공기관 대행사업들에 대한 부분들을 말씀을 드렸는데 보니까 정해져 있는 게 6가지 항이 있더라고요. 대부분이 조사ㆍ연구사업들하고 연구와 관련된 수탁사업들을 할 수 있도록 되어 있습니다. 그래서 이 대행사업들을 봐도 대부분이 기반 연구 이런 부분들인데 사실은 제가 좀 말씀을 드리고 싶은 건 DMZ 포럼과 관련된 사업들이 있어요. 그 부분들의 사업들이 지금 정관사항에서 어떤 사업에 포함되는지가 좀 궁금해요. 연구사업도 아니고 조사사업도 아닌데 이 부분들에 지금 행사에 대한 대행들을 하고 계신단 말이죠, 포럼에 대한. 그런 목적성, 그러니까 경기연구원의 목적과 사업하는 내용의 사업과 다른 사업들을 하고 있다라고 보여지는데 이 부분에 대한 답변을 부탁드리겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> DMZ 포럼을 저희가 운영하기는 했으나 그 내용 중에 저희가 하는 역할은 주로 어떤 것이냐 하면 DMZ 포럼 중에 연구나 협력 그다음에 교류와 관련된 기획을 하고 거기에 주요 발제자들의 역할 그다음에 저희 연구원이 할 수 있는 연구협력 분야의 역할을 중심으로 저희가 하는 겁니다. 
</p>
<p><b>○ 김강식 위원 </b> 그래서……. 
</p>
<p><b>○ 연구부원장 송미영 </b> 그 내용은 킨텍스에서 한다는 거는 위원님도 아시지 않습니까?  
</p>
<p><b>○ 김강식 위원 </b> 그럼요, 행사에 대한 부분들이 다 포함돼 있는 거죠, 사실 기획 부분들에. 
</p>
<p><b>○ 연구부원장 송미영 </b> 근데 행사는 전부 다 킨텍스에서 하고 저희는 연구기획 쪽만 하는 겁니다. 
</p>
<p><b>○ 김강식 위원 </b> 아니, 지금 하려고 하는, 여기에 써져 있는 게 정확하게 읽어보면 1번이 정책에 대한 조사ㆍ연구를 하게 돼 있고 두 번째 것도 보면 경기도의회와 경기도 그 시군에 대한 현안사항에 대한 조사ㆍ연구를 하게 돼 있고 그다음에 세 번째가 경기도, 경기도의회 그다음에 다른 기관으로부터 각종 연구사업에 수탁을 하게 돼 있고. 그렇죠? 국내외 연구기관에 대한 교류협력을 하게 돼 있고 도정발전에 관한 국내 주요현안에 대한 조사ㆍ연구를 하게 돼 있고 나머지는 1번부터 5번까지 관련된 부대 사업들을 하게 돼 있는데. 그러니까 제가 말씀드리는 건 지금 DMZ 포럼을 준비하는 것 속에서, 섹션을 준비하거나 여러 가지 하는 부분들은 어떻게 보면 DMZ 포럼에 대한, 행사에 대한 일부거든요, 사실은. 그 부분들이 기획에 대한 참여를 하는 부분들이거든요. 그렇죠? 조사ㆍ연구에 대한 부분들의 사업들을, 저는 경기연구원이 연구 업무에 대한 부분들을 하기에도 아니면 이 부분들에 대해 하나의 섹션들을 연구용역으로 받아서 아니면 그 부분들을 용역을 받아서 진행을 해야 되는 부분들인데 공기관 대행하고 이건 좀 다른 문제거든요, 사실은. 공기관 대행사업의 성격하고 지금 여기서 하는 사업을 받아서 할 수 있는 사업의 성격이 좀 다른 건 아니냐라는 말씀을 드리는 겁니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 그렇게 말씀을 하시면 또 그런 측면도 있겠죠. 근데 제가 이런 말씀을 다시 여쭙고 싶습니다. 저희가 경기도에 있는 연구원으로서 DMZ나 평화 관련된 업무를 연구하거나 그 업무와 관련된 연구기관과의 교류협력, 국내외 기관과의 연구 기획 같은 거는 당연한 업무로 저희도 해야 되지 않겠습니까? 그래서 그 업무를 하기 위해서 그 부분만을 대행한다고 생각하시면 어떨지요?   
</p>
<p><b>○ 김강식 위원 </b> 아니, 제가 그걸 하지 말고 그걸 할 필요가 없다라는 말씀을 드리는 건 아니고요.
</p>
<p><b>○ 연구부원장 송미영 </b> 그런 업무를 하는 겁니다, DMZ 포럼에서. 
</p>
<p><b>○ 김강식 위원 </b> 그런 업무들은, 사실은 이제 우리가 용역이라고, 그러니까 저는 경기연구원에 뭐라고 하는 것이 아니라 그 사업의 성격들이 공기관 대행의 사업이 있고 이건 기조실이나 다른 쪽에 좀 논의를 해야 되는데 위탁사무를 할 수도 있고 대행사무를 할 수도 있고 용역사무를 할 수도 있는 거 아니겠습니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 그렇습니다. 그거는 발주기관에서 선택하는 겁니다. 
</p>
<p><b>○ 김강식 위원 </b> 그렇죠. 그러니까 그 부분들이 사실은 연구용역에 대한, 근데 집행하는 것들, 사업비의 성격들이나 집행한 내역들을 좀 구체적으로 살펴보시면 이게 사실은 거기에 들어가는 비용들이나 모든 것들이 용역사업하듯이 용역, 이게 대행사업이 아니라 연구용역에 준하는 내용으로 집행들이 되고 있다는 거예요. 그러면 이 사업은 연구용역사업으로 받아서 이 부분들을 하면 경기연구원이 충분히 수행할 수도 있고 그 부분들에 대해서 마땅히 거기 절차대로 진행돼야 되는 것이 아닌가. 그런데 이 부분들을 공기관 대행사업이라는 것들로 가져가 버리면 그러면 집행에 대한 부분들이 사실 맞지 않게 집행이 되는 부분들이 있거든요. 왜냐하면 다른 데보다 훨씬 고비용에 대한 부분들이 들어가는 부분들이 있다라는 부분이 보여져요.
</p>
<p style="padding-left:1.2em">  그래서 저는 그 부분들에 대한 것들이 원래 경기연구원의 목적에 맞게 그 부분들이 연구용역사업으로, 용역사업으로 받아야 되는 것이 아닌가. 그게 경기연구원에서 수익들을 가지고서도, 재원 조달할 때도 분명히 거기에서도 포함되는 부분들이라고 생각되는데 자칫 잘못하면 DMZ 포럼이라는 행사의 기획에 대한 핵심적인 부분들이 있거든요. 근데 행사 진행은 별도로 하고 옆에 맨 위에 기획 단위만 우리가 해 줄게라는 이원적인 걸로 가다 보면, 사실은 요즘에는 기획ㆍ마케팅이 항상 같이 따라가는 것들이거든요. DMZ 포럼을 성공적으로 운영하기 위해서는 행사 대행도 필요하지만 이 부분들을 기획하는 사람들이 어떻게 행사를 진행했으면 좋겠다라는 생각까지도 같이 해서 진행하는 게 훨씬 효율적이고 그 부분들이 원활하게 진행될 수 있다고 생각하고 그 목적을 달성할 수 있다고 봅니다.
</p>
<p style="padding-left:1.2em">  그런데 우리는 그냥 핵심, 알맹이, 총알만 만들어줄 테니 그 부분들에 대한 것들은 총은 너네들이 쏴라라는 부분들 갖고는 안 될 것이라고 보여지고 오히려 그 한 주제에 대한 부분이 되게 중요하고 내용이 충실해야 된다고 한다면 사실 그 부분들을 협의해서 일부분들에 대한 부분들은 평화통일 그다음에 DMZ에 관련된 부분들은 연구용역해서 그 부분들을 경기연구원이 감당해야 되는 부분들이 아닌가라는 부분들이고 그 예산의 집행현황도 한번 꼼꼼히 살펴보시면 그 부분들은 사실은 연구용역의 단가로 그 부분들이 적용되면 사실은 연구용역사업으로 집행부도 집행을 했어야 되는 부분들, 그러니까 연구원이 아니고 그 부분들이 있다 보니까 그게 어느 것이 타당한가라는 생각들을 좀 여쭤보는 겁니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 이제 답변드려도 되겠습니까?  
</p>
<p><b>○ 김강식 위원 </b> 네.  
</p>
<p><b>○ 연구부원장 송미영 </b> 저희가 하는 여러 가지 일 중에 특히 이런 뭐라고 해야 될까요, 행사성 업무가 포함된 기획업무들은 위원님 말씀하신 대로 조금 더 연구용역의 성격에 맞게 저희도 받고 싶을 때가 있는데 사실 기획을 한다는 것 자체에 굉장히 실무진 그다음에 집행부들이 부담을 느낄 때가 많습니다. 그럴 경우 저희 연구원의 연구역량을 토대로 해서 그 기획업무를 하면서 행사업무도 같이 진행해 줄 것을 요구하는 경우가 많이 있습니다. 그래서 이 업무 외에도 저희가 이때까지 수행했던 공기관 대행사업에 보시면 꼭 연구목적에 딱딱 맞게, 대행사업 형태로만 오는 게 아니고 연구사업하고 융합된 형태로 오는 것들이 꽤 있습니다. 그래서 그런 것들은 앞으로 저희도 조금 더 정리가 됐으면 하는 바람은 있으나 지금 현재 경기도나 시군의 역량 그다음에 여러 가지 제반여건이 그게 좀 어려운 점이 있어서…….
</p>
<p><b>○ 김강식 위원 </b> 짧게 좀 더 말씀을 드리자면…….
</p>
<p><b>○ 연구부원장 송미영 </b> 이게 중간과정이라고 저는 생각을 합니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러니까 저는 이런 거예요. 우리 경기연구원의 조직도를 보면 공기관 대행들, 특히나 이제 DMZ 포럼 같은 경우에는 좀 규모도 있고 하는 부분들을 하기 위해서 여러 인력들이 TF를 구성해서 오랜 시간 동안 이 부분들을 자문하고 또 찾고 발굴하지 않습니까. 그러니까 사실은 그런 부분들의 활동들 때문에 이 부분들이 그냥 일정 부분 자문을 받거나 아니면 연구용역하는 부분들로 가져갈 수도 있는 부분들임에도 불구하고 이런 걸 준비하는 과정들 속에서 박사님들부터 시작해서 여러 인력들이 여기에 집중하고 하는 부분들이 과연 제가 앞서 말씀드린 개인적인 연구활동들을 하기도 벅찬 상황에서 이런 대행사업들을 하는 부분들에 대한 TF를 꾸려서, 제가 보니까 거기 구성되는, 참여하는 인력들이 상당히 많은 것 같이 보이더라고요. 그 부분들이 과연 바람직한 것이냐. 연구원에서 아까 말씀드린 1인당 부가가치 창출이 가장, 서울연구원보다 훨씬 높다는 지표가 나올 정도로 어쨌든 조직에 대한 그런 부분들의 문제점들이 있는 부분처럼 보이는데 이런 부분들의 사업들을 좀 성격에 맞도록 하고, 거기에 있는 팀 조직조차도 없는 상황 아니겠습니까? 대행사 업무를 하는 조직도 없이 그냥 그때그때 맞춰서 하는 건 조금 맞지 않지 않냐. 앞으로 그런 부분들에 대해서는 조금 개선의 여지가 있지 않나라는 부분들 때문에 말씀드리는 겁니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 그런 점이 잘 정리되고 저희도 그렇게 적응해 나갈 수 있도록 위원님들이 조금 더 도와주시기 바랍니다.
</p>
<p><b>○ 김강식 위원 </b> 이상입니다.
</p>
<p style="padding-left:2.4em">    (이필근 부위원장, 이종인 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 이종인 </b> 김강식 위원님 수고하셨습니다. 다음은 이필근 위원님 질의해 주십시오. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 수원 권선의 이필근 위원입니다. 아까 존경하는 우리 원미정 위원님이 광역 지방연구원과 공동연구한 것에 대해서 제가 또 추가로 질문 좀 하겠습니다. 올해만 네 군데를 했어요. 5월 달에 울산, 6월 달에 경남, 7월 달에 광주전남 그다음에 8월 달에 대전세종연구원하고 공동 MOU를 했는데 이거 말고 그 이전에도 공동연구를 추진한 적이 있나요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 있습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 몇 년도에 어디 어디서 했죠?  
</p>
<p><b>○ 연구부원장 송미영 </b> 연구원 간의 협력연구는 늘상 있는 일이고요. 그전에 20년부터 보시면 경제과학진흥원이나 이렇게 같이 공공기관들끼리도 하게 돼 있고요. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 광역단체하고는. 
</p>
<p><b>○ 연구부원장 송미영 </b> 그다음에 국책연구원들과도 많이 하고 있고 광역단체하고도 합니다. 5개 시도라고 그래서 한강수계에 있는 데끼리도 같이 많이 하고 충남이나 인천하고도 자주 연구를 같이 합니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 그러니까 MOU를 치른 적이 있냐고. 올해처럼 울산연구원 거기 가서 이렇게 했잖아요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 지사님, 연구원장 같이 했는데 그렇게 한 적이 있냐고. 
</p>
<p><b>○ 연구부원장 송미영 </b> 때에 따라서는 한 적도 있었고요, 이번에는 조금 더 많이 한 것뿐입니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 그러니까 예를 들어서 서울연구원하고 시장하고 도지사하고 거기 서울연구원 원장하고 우리 경기연구원장하고 넷이 모여서 MOU 체결하고 사진 찍고 그런 적이 있냐고. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 필요에 따라서는 그렇게 한 적이 있습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 한 번 하면 그만이지 이게 사업마다 하는 게 아니잖아요.
</p>
<p><b>○ 연구부원장 송미영 </b> 그렇기는 한데요. 저희가 예전에도 충남, 남 지사님 계실 때도 그랬고 그 전에도 시도연구원이 광역적인 차원에서 어떤 협력연구를 할 때 정무적인 판단에 의해서 협약이 필요하시다고 하면 또 협약도 한 적이 있습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 제가, 잘 이해를 못 하시는데 한 번 이걸, 예를 들어서 광주전남연구원하고 협약을 했어요. 하면 큰 틀에서 협약을 하고 그 밑에 세부적인 사항 같은 거, 사업 같은 거는 그냥 연구원끼리 협의해 가지고 하는 거지. 한 번만 하는 거 아닙니까, 협약은? 그게 사업할 때마다 협약을 하는 건 아니잖아요.
</p>
<p><b>○ 연구부원장 송미영 </b> 어떤 질문을 하시는지는 알겠으나 제가 거기에 정무적인 답변까지 드리기는 어려울 것 같습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 그러니까 제가 그거를 좀 말씀드리고 싶은 것은 이거 다 우리가 내려갔죠? 경기도에서 한 게 아니잖아요. 우리가 울산 가고 우리가 대전 가고 우리가 광주전남 가고 경남 간 거 아닙니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그렇게 하셨죠. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 울산 같은 데는 인구가 104만 명입니다. 우리 경기연구원, 경기도의 인구에 비하면 10분의 1도 안 돼요. 물론 이게 왜 내려갔는지도 알지만 우리가 애걸복걸해서 내려간 그런 이미지가 보인다 이거지. 우리가 훨씬 연구원도 많을 것 같아. 그렇죠? 울산연구원보다 우리가 많지 않아요? 훨씬 크죠, 연구원의 규모나 조직이나 예산 같은 게?  
</p>
<p><b>○ 연구부원장 송미영 </b> 저희가 더 큽니다. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 제가 보기에 서울 빼고는 경기도가 제일 많다고 생각이 되는데 제가 그런 거를 질문하는 취지를 알고 그러시는데 그래서 저는 이런 것이 보여주는 게 아니라 정말 그쪽 시도하고 긴밀한 관계에서 지방연구 또 광역단체끼리 공동연구할 게 상당히 많다고 생각이 되는데 실질적 연구를 해라 이거지. 그냥 사진 찍고 MOU 찍고 끝나는 게 아니라 정말 이런 데하고 같이, 대전세종연구원하고 같이 그런, 거기가 경기도에다 요구하는 사항도 있고 우리가 거기다 요구하는 사항이 있어서 실질적인 공동연구가 돼야지 사진만 찍고 그냥 보여주기식으로 하는 것은 의미가 없다는 걸 지금 지적하고 싶어서 얘기하는 겁니다. 
</p>
<p style="padding-left:1.2em">  그리고 서울하고도 공동연구했어요? 협약했어요?
</p>
<p><b>○ 연구부원장 송미영 </b> 서울연구원하고도 한 게 하나 있습니다, 21년도에.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 하나 한 게 아니라 전체를 포괄적으로 했냐고.
</p>
<p><b>○ 연구부원장 송미영 </b> 그것은 필요에 따라서 할 때도 있고 안 할 때도 있습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 인천하고는 했어요, 안 했어요?
</p>
<p><b>○ 연구부원장 송미영 </b> 인천하고도 서해안권 초광역 대기질 개선 프로젝트 관련해서는 협약을 했습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 제가 얘기하는 거는 이런, 경남연구원하고 할 때는 하나의 건으로 한 게 아니라 포괄적으로 했을 거 아닙니까? 도지사하고 할 때.
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 그렇게 포괄적으로 했냐 이거지, 세부적으로 그런 게 아니라.
</p>
<p><b>○ 연구부원장 송미영 </b> 그러니까 그런 부분은 위원님 계속 질의하셔도 제가 답변하기 어려울 거라는 건 아실 거라고 생각합니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 아니, 그걸 했냐 안 했냐만 제가 물어보는 거예요.
</p>
<p><b>○ 연구부원장 송미영 </b> 그런데 제가 이런 말씀은 드릴 수 있습니다. 사진을 찍고 여러 가지 정무적인 판단에 의해서 협약식을 했을망정 연구를 소홀히 하거나 아무 연구나 하지는 않았습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 그러시겠죠. 제가 그걸 요구하는 거고. 우리 경기도하고 밀접한 데가 서울하고 인천입니다. 그렇죠?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 서울하고 수도권에 공동연구할 게 얼마나 많습니까? 환경 그다음에 교통 그런 것은 잘 안 하고 우리가 과연 저기 경남연구원하고 공동연구할 게 뭐가 있을까? 과연. 물론 있겠죠, 그것도. 내가 보기에. 그렇지만 가장 우리 수도권에 한 2,000몇만 명이 사는 거기가 제일 중요하고 그런 데하고 공동연구할 게 많지 않냐 그런 차원에서 제가 말씀을 드리니까 이 공동연구를 그냥 형식적이 아니라 끊임없이 하시고, 내년이고 뭐 제주도도 할 수도 있죠. 그래서 정말 어떤 공동연구했던 실효성이 있게끔 부탁을 드리고.
</p>
<p style="padding-left:1.2em">  그다음에 100만 도시인 수원, 용인, 고양은 시정연구원이 있죠?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 거기하고는 했습니까?
</p>
<p><b>○ 연구부원장 송미영 </b> 그쪽하고는 연구를 협약해서 하지는 않았지만 연구교류는 굉장히 빈번하게 일어나고 있습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 그러니까 여기도, 물론 수원, 용인, 고양의 시정연구원이 경기연구원보다는 규모도 작고 예산도 열악하고 연구원도 열악하지만 경기도에 있는 저기 아닙니까. 그러면 같이 협약을 해 가지고 큰 집이 작은 집 도와줄 수도 있는 거고 또 도움을 줄 수 있는 그런 차원에서 수원하고 용인, 고양 그런 데하고 하는 것도 큰 의미가 있다고 저는 생각이 됩니다. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 저희가 수원시정연구원하고 고양시정연구원하고는 상호 연구교류협력 체결을 했는데 앞으로 조금 더 긴밀하게 협력하도록 노력하겠습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 또 하나는 경기연구원도 이제 경기도의 정체성을 한번 생각할 필요가 있다고 저는 생각이 됩니다. 경기도는 옛날도 그렇고 지금도 그렇지만 정말 전국에 있는 팔도 또 16개 시도의 주민들이 다 사는 데가 경기도입니다. 그리고 상당히 사상이 실용적이고 그런 데 좀 강해요. 그러니까 뭐라고 그럴까, 어떤 좌나 우에 쏠리지 않고 이념ㆍ진영에 쏠리지 않고 좀 그런 실학적인 게 있는데 경기도에 다산연구소도 있고 박물관도 있고, 성호 이익 선생 박물관도 있고. 실학의 3대 거두가 반계 유형원 씨, 성호 이익 선생님, 다산 정약용 선생님 다 경기도 사람입니다. 조선 중기부터 경기도가 이런 대한민국 실학의 어떤 흐름을 이끌고 갔어요. 그럼 경기연구원도 이런 거에 대한 어떤 관심을 가져야 돼.
</p>
<p style="padding-left:1.2em">  이한주 전 경기연구원장님이 다산연구소가 서울에 있었는데 3년 전에 수원으로 오라고 하신 분이 그분입니다. 와서 홀대한 거예요, 홀대를. 그분이 홀대한 게 아니라 경기도가 홀대한 겁니다. 조그만 경기문화재단에 한 20평짜리 주고 한 달에 660만 원씩 임대료 받아가고. 그분들이 돈이 어디 있어요, 그분들이. 경기도의 사상을 이끌고 가는 그런 다산연구소의 박석무 이사장님을 비롯한 다산연구소의 실무자들이 혀를 차요, 혀를 차. 중앙일보에 있는, 16년 동안 중앙일보에서 잘 있다가 내려오라고 해서 내려왔는데 경기도가 우리를 이렇게 할 수가 있느냐. 저는 문화재단하고도 할 얘기지만 경기연구원의 부설 연구소로 다산연구소가 들어가야 된다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  그런 차원에서 경기도도 정말 경기도의 실학, 정말 실천적인 학문인 실학을 또 아니면 이 세 분의 어떤 사상을 이끌 수 있는 하나의 연구성과 같은 것도 있어야 된다고 생각이 됩니다. 물론 맨날 조금조금씩 하는 것도 중요하지만 경기도의 이념이고 이게 정체성입니다. 우리 사상이에요, 그게. 그런 차원에서 그분들하고 협력도 하고 그분들의 사상, 경기도의 사상을 받아들여서 좀 이끌어 가야 되지 않을까 그렇게 생각하는데 부원장님 의견은 어떠세요?
</p>
<p><b>○ 연구부원장 송미영 </b> 저희가 사실 저희 연구원 안에 있는 여러 조직이나 새로운 인원을 충원하는 거에도 지금 충분한 여력이 안 되다 보니 문화나 인문학 쪽에서는 사실 저희가 역량 발휘를 못 하고 있습니다. 그리고 그 분야의 박사님도 저희가 한 분밖에 안 계십니다. 그래서 앞으로 저희 연구원이 새로운 기능을 갖추게 될 때 충분히 도하고 협의해서 고려하도록 하겠습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 시간이 다 돼서 그러는데 그분들하고도 어떤 교류를 통해서 경기도의 어떤 정체성, 경기도의 어떤 주인의식을 잘 정립해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 이필근 위원님 수고하셨습니다. 지금 본질의가 다 끝났습니다. 장시간 회의를 했고요. 그러면 본질의를 마치고 보충질의를 바로 시작하도록 하겠습니다. 그리고 시간을 좀 우리 위원님들께서는 엄수해 주시고요. 답변하시는 분도 답변을 좀 짧게 해 주세요. 왜냐하면 답변이 기니까 결국은 시간이 다 오버가 되는 부분이 있으니까 좀 요약해서 답변을 짧게 해 주시고요.
</p>
<p><b>○ 연구부원장 송미영 </b> 알겠습니다.
</p>
<p><b>○ 부위원장 이종인 </b> 먼저 질의하실 위원님, 그럼 오지혜 위원님부터 하도록 하겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 안녕하세요? 오지혜입니다. 저는 정책연구도서관 홈페이지에 관련해서 질문을 드리겠습니다. 경기도의 정책연구를 한곳에 모아놓은 곳이죠. 경기도민의 알권리를 제공하는 정책연구정보의 허브라는 자료가 써 있었는데요. 일단 관리를 경기연구원에서 하는 게 맞나요?
</p>
<p><b>○ 연구부원장 송미영 </b> 저희가 하도록 맡아진 역할이기 때문에 저희가 하는 게 맞다고 저는 생각합니다.
</p>
<p><b>○ 오지혜 위원 </b> 보고서의 업로드는 각 기관이 담당하나요? 그러니까 시군에서 올리거나 각 공공기관들에서 업로드를 하고 있는 건가요?
</p>
<p><b>○ 연구부원장 송미영 </b> 시군 것은 시군에서도 올리고 저희 거는 또 저희도 올리고 이렇게 하고 있습니다.
</p>
<p><b>○ 오지혜 위원 </b> 그러면 경기도는 그나마 꾸준히 업로드가 되고 있는데, 학술연구한 내용들에 대해서. 그런데 경기연구원은 2021년 4월 7일, 9일, 10월 25일에 한 번에 올라오게 자료가 있었고요. 경기도가족여성연구원은 2021년 4월 22일 이후 한 번에 또 자료가 올라온 이후 자료 등록이 없었고 일자리재단은 2021년 10월 7일에 1년 치를 쭉 올렸어요. 그런데 예를 들면 2021년 1월 전국 및 경기도 고용동향 분석을 10월 7일에 업로드를 했거든요. 그러니까 아예 1년 치를 그날 다 업로드를 한 건데 연구 같은 경우에는 지금 온라인 정책연구도서관이 그런 아카이브의 역할도 하겠지만 실제로는 도민들에게 정보제공을 위한 목적도 있잖아요. 그런데 1월의 고용동향이 10월에 필요한 건지 약간 의문이 되는 거지요, 이런 경우에는.
</p>
<p style="padding-left:1.2em">  그러니까 연구라는 것 자체가 딱 연구를 마치고 바로 발간이 되었을 때, 자료가 나왔을 때 가장 사용하기에 좋은 자료가 되는 거잖아요. 그게 오래되면 어떻게 보면 자료로서의 효과가 조금은 떨어질 수도 있는 그런 문제가 있기 때문에 가능하면 바로바로 업로드를 할 수 있게 각 시군과 연구기관들에 요청을 해 주셨으면 좋겠고요.
</p>
<p style="padding-left:1.2em">  그리고 연구를 하고 있는데도 불구하고 경제과학진흥원은 2020년 3월 31일 이후에 아무런 업로드가 없었고요. 수원시정연구원 같은 경우는 2018년 12월 31일 이후에는 자료 등록이 아예 없었습니다. 이러한 형태로 지금 정책연구도서관이 운영되고는 있지만 실제로 여기에 참여하는 그런 시군이라든가 연구기관들이 많지 않은 것 같이 느껴집니다. 그래서 이 부분에 대해서도 조금 많이 독려를 해 주셔서 가능하면 가급적 바로바로 연구가 끝난 뒤에 연구정보들을 업로드할 수 있도록 해 주시면 감사할 것 같습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 저희가 좀 부족한 부분이 있었는데 그 부분은 조금 더 체계적이고 일관성 있게 자료를 업로드하거나 아니면 공개하는 절차를 점검해 보고 말씀하신 사항을 보완하도록 하겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 사실 이게 바로바로 업로드한다는 게 좀 어려우면 월에 한 번 정도라도 일괄적으로 업로드를 할 수 있게 해 주시면 감사하겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그렇게 조치하도록 하겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 오지혜 위원님 수고하셨습니다. 다음은 이제영 위원님 질의해 주십시오.
</p>
<p><b>○ 이제영 위원 </b> 질의 전에 제가 감사관 때 질의를 길게 하다 보니까, 아침에 일찍 오셨죠, 경기연구원도?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 너무 많은 분들을 장시간 기다리게 해서 제가 죄송하다는 말씀을 먼저 드리겠습니다.
</p>
<p style="padding-left:1.2em">  지금 최근 대선 정국이잖아요. 어느 후보께서 기본소득 이렇게 하시는 것의 여론조사 결과를 보니까 국민의 60%가 지금 반대하고 있다 이런 걸 본 적이 있습니다. 제가 이 말씀을 드리는 것은 기본소득을 비판하려고 하는 게 아니고 코로나 시대에 지금 수요자와 공급자의 관계에 있어서 과연 그게 수요자의 의견을 충분하게 수렴해서 했느냐 이 부분에 대해서 저는 굉장한 의구심을 갖고 있거든요. 왜냐하면 어제도 시장에 가서 물건을 구매하고 그분들하고 30분 이상 얘기를 하다 보니까 우리가 생각하지 않은 많은 문제점을 제기하고 있어요. 그런데 매우 심각한 얘기들을 많이 하고 있거든요. 
</p>
<p style="padding-left:1.2em">  그래서 경기연구원에서 기본소득 관련해서 연구한 것도 있고 그런데 그것을 연구자의 입장이 아닌 현장의 목소리를 한번 방문해서 과연 어떤 연구주제를 갖고 하는 게 소상공인과 자영업자에게 정말 필요한 연구가 되는지를 그냥 이렇게 책상에 앉아서 판단하는 것보다는 시장 몇 군데 가서 현업에 있는 분들하고 대화를 해 보면 뭔가 어떤 연구가 필요한지를 거기서 연구과제를 얻을 수가 있을 것 같아요. 
</p>
<p style="padding-left:1.2em">  그래서 그러한 부분도 가서 실질적인, 그분들이 원하는 게 무엇인지에 대한 연구가 이루어지고 이게 정책으로 만들어져야 60%가 반대하는 게 아니라 70~80%가 찬성을 해서 국가 정책으로도 받아들여질 수가 있는데 지금 결과가 결국에는 만족스럽지 못한 게 아닌가 이런 생각을 해 보거든요. 그래서 앞으로 그런 부분에 대해서 코로나뿐이 아니라 다른 부분에 있어서도 현장의 목소리를 가서 연구과제로 이렇게 좀 듣고 주제로 채택을 해 주십사 하는 말씀을 드리고요.  
</p>
<p style="padding-left:1.2em">  또 하나 요즘에 뉴스를 틀면 요소수 문제가 매일 나옵니다. 정부에서 2만 ℓ를 수입했다 이렇게 했는데 2만 ℓ가 어느 정도 쓸 수 있는 거냐? 화물차 333대 하루 사용량밖에 안 된다. 한 달 뒤에는 화물차가 다 멈춘다. 이런 심각한 사태가 지금 연일 보도가 되는데 시원한 해결책은 제시가 안 되고 있습니다. 저희가 얼마 전에도 일본하고 관계에 있어서 반도체 불화수소 소재 문제로 인해서 일본에서 수출을 안 하니까 굉장히 심각한 위기를 겪고 지금 문 대통령께서도 그럼 우리가 자급자족할 수 있는 방안을 좀 만들어야 될 거 아니냐라는 강력한 주문을 했어요. 근데 이건 한 가지로 되는 게 아니라, 아까 제가 여러 가지 지표에 대해서 블로그에 올리는 것도 지적을 했었는데 그렇다라고 하면 이것은 이런 통계자료를 가지고, 우리가 사실은 수출도 많이 하지만 수입을 많이 하잖아요, 원자재를. 그럼 이런 걸 다 분석해서 지금 외교적으로도 미국과 중국 간에 굉장한 군사적 대립 그다음에 경제적인 대립 이런 걸로 인해서 피해를 볼 수 있는 여건이 대한민국이 심하다라는 것은 어떤 언론을 보더라도 굉장히 많이 예측하고 있거든요.
</p>
<p style="padding-left:1.2em">  그럼 이런 것도 반도체 불화수소나 요소수는 현재 닥친 문제지만 나머지 원자재 수입도 이게 어느 한 나라에 치중돼 있는데 그 나라와 우리나라의 외교적 관계에 문제가 될 수 있는 여지가 있는 거에 대해서는 경기연구원에서 한번 이런 것도 연구를 좀 해서 제시가 되면 “야, 이건 뭐 국가연구원도 못 하는 이런 걸 어떻게 경기연구원에서 제시를 하느냐?”라고 해서 제가 볼 때 한순간에 대한민국 최고의 연구기관이 되지 않을까 이런 생각도 해 봅니다. 공감하실지 안 하실지는 모르겠지만.
</p>
<p><b>○ 연구부원장 송미영 </b> 공감합니다.
</p>
<p><b>○ 이제영 위원 </b> 그래서 이런 게 많은 시간이 필요한 게 아니고 정말 연구원 몇 분이 그런 자료만 수집해서 제시가 된다고 하더라도 제가 볼 때, 아까 언론의 비판 언론을 제가 제시했는데 그러면 경기연구원에 대해서 언론 홍보 몇십억 하는 것보다 그런 거 한 건만 제대로 보도가 되면 경기연구원의 위상은 지금하고 엄청나게 변화될 게 아니냐. 이런 것이 연구원의 역할이 아닌가, 본연의 역할이. 이런 부분에 있어서 저는 굉장히 지금까지 업적도 있지만 미흡한 부분도 많이 있다. 
</p>
<p style="padding-left:1.2em">  왜 그러냐는 저의 주관적인 판단이 될 수 있기 때문에 제가 그것은 말씀을 드리지 않겠습니다. 적어도 이 자리에 계신 우리 이사장님이나 부원장님, 간부들께서는 제가 무슨 얘기를 하는지 아마 가슴속으로 느껴지는 게 있을 겁니다. 그래서 그런 것을 충실하게 해야 연구원도 규모가 더 커질 수 있고 여러분들도 여기서 더 발전이 될 수 있는 것이지 그런 게 이루어지지 않는다라고 하면 경기연구원의 발전은 기대하기 어렵다. 그래서 향후에 이런 부분에 대해서는 연구원에서 뭔가 새로운 각오를 해 주시기를 꼭 좀 제가 당부드리면서 질문을 마치겠습니다.
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 이거는 이사장 이름이 나와서 제가 한두 마디만 답변을 드리고자 합니다. 위원님께서 해 주신 말씀은 경기연구원에 대한 큰 격려의 말씀으로 듣겠습니다. 그리고 틀림없이 많은 수고가 들지만 그런 방향에서 연구과제를 개발하고 접근을 하면 성과는 반드시 좋습니다. 다만 몇 가지 한계는 있을 수가 있죠. 도하고, 도 행정부하고 그런 한계는 있을 수가 있는데 그 한계는 연구원이 스스로 노력해서 극복해 나가면서 위원님이 주신 조언의 말씀 또 방향 그것은 저희들이 가슴에 새기도록 그렇게 직원들하고 같이 공유를 하겠습니다. 감사합니다.
</p>
