<p><b>○ 경영부원장 장형철 </b> 경영부원장입니다. 명칭 때문에 존경하는 이영봉 위원님께서 조금 오해를 하실 수 있을 것 같습니다. 여기 통합이전추진단이라는 명칭을 썼지만 이건 아까도 말씀하셨던 것처럼 전적으로 저희 내부에, 연구원이 이전이라는 과제를 앞두고 내부에 어떤 준비가 필요한지를 준비하는 단이기 때문에 외부의 의회나 의정부시 쪽의 인사를 저희가 생각하지 못했던 부분이고요. 아까 말씀드렸던 것처럼 지금 이전이 의정부 쪽에 대충 지역만 결정이 된 것이지 사실은 시기나 아무것도 결정이 안 된 상황이기 때문에 아직까지 뭔가 명쾌하게 준비할 수 있는 시기와 계기가 되지를 않고 있습니다. 그럼에도 불구하고 아까 존경하는 염종현 위원님께서 말씀하셨던 것처럼 장기적인 연구원의 발전계획을 이전과 맞물려서 내부적으로 준비해야 될 필요성들 때문에 그랬던 겁니다. 
