<p><b>○ 경기연구원장직무대행 허성관 </b> 과거의 기금들의 경우에는 금리 수준이 높고 그래서 기금이 들어오면 큰 힘이 됐습니다. 그런데 지금은 금리 수준이 굉장히 낮고 또 그 기금 자체는 위험이 높은 자산에 절대로 투자를 할 수가 없습니다. 예를 들어서 주식에 투자를 할 수도 없고. 그래서 어느 기관이든지 기본자산, 즉 기금이 있는 데에는 특별히 기본자산을 많이 쌓아야 된다는 그런 필요성을 별로 못 느끼고 있습니다. 예를 들어서 기금이 1년에 1,000억이라도 1년에 사업할 수 있는 규모가 10억이 안 됩니다. 그렇기 때문에 전반적인 분위기가 그렇다는 말씀을 하나 첨가해서 드리겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 네, 알겠습니다, 무슨 말씀인지. 그리고 경기연구원에서 교육재능 기부사업을 하고 있었어요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네.  
</p>
<p><b>○ 정희시 위원 </b> 그런데 거기 주로 운영현황, 강의 주제, 강연 주제 이런 것을 보니까 아주 내용들이 톡톡 좀 튀고 우리 학생들한테 좀 호감이 갈 만한, 흥미가 갈 만한 그런 주제들이 많은 것 같아요. 주로 반응이 어떻습니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 학교에서는 어쨌든 선생님들이 저희같이 전문가를 초빙해서 할 수 있는 기회가 적기 때문에 굉장히 환영하시는 입장이고 학생들도 새로운 진로탐험이나 체험 측면에서 좋아하고 있습니다.
</p>
<p><b>○ 정희시 위원 </b> 그 내용은 좋은데 실질적으로 굉장히 바쁘셔서 그렇겠지만 혜택받는 학교나 학생 숫자는 굉장히 제한적이에요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그걸 교육청하고 협의를 해야 되기 때문에 일정 협의가 어려워서 더 그렇습니다.
</p>
<p><b>○ 정희시 위원 </b> 쭉 내용을 보면 학생들뿐만 아니라 평생교육 개념으로 일반 시민들도 좀 받았으면 좋겠다는 이런 내용들이 많은데 여기에 이제 대상이 경기도 내 중ㆍ고등학생 그리고 시민단체 이렇게 되어 있는데 이것을 교육을 신청하려면 어떤 단계를, 어떤 절차를 밟아야 됩니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 지금 현재로는 교육청하고 협약을 해서 그 내용을 받고 있는데 일반적인 시민한테 하려면 아마 저희가 평생교육진흥원 같은 데서 하는 시민대학이나 일반 교육기관과의 협약이나 절차를 아마 고려를 해 봐야 될 것 같습니다. 그런데 저희가 필요하시다면 그런 절차를 만들도록 하겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 제 생각에는 좀 필요하지 않을까. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네.  
</p>
<p><b>○ 정희시 위원 </b> 여기에 형식적으로 시민단체 이렇게 써 놨는데 실제로 학생들뿐만 아니라 평생교육 차원에서 또 시대가 많이 바뀌는데 그런 아주 시대상황, 변화상황을 담은 그런 내용들이 많기 때문에 좀 확대를 할 수 있는 방안을 찾으면 어떨까 생각이 듭니다. 
</p>
<p><b>○ 연구부원장 송미영 </b> 요즘 추세에 따라서 유튜브나 이런 걸 저희가 마련해서 그런 교재를 이렇게 온라인에 같이 공유할 수 있는 그런 체계도 생각해 보겠습니다.
</p>
<p><b>○ 정희시 위원 </b> 제일 좋은 것은 민방위교육도 이렇게 좀 넣었으면 좋겠다는 생각이 듭니다, 가능할지 모르겠습니다만. 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 정희시 위원님 수고하셨습니다. 다음은 김강식 위원님 추가질의해 주십시오.
</p>
<p><b>○ 김강식 위원 </b> 앞서 말씀하신, 우선 좀 제가 요청한 자료를 정리해서 다시 한번 말씀드리자면 이런 겁니다. 18년도에 보면 외부특강 및 출강 시 복무관리를 철저히 해 주기 바란다. 거기에 처리결과가 임직원 행동강령 시행규칙 및 대외활동 규칙에 따라서 외부강의, 출강에 대해서 사전 결재하고 거기에 대한 신고서를 쓰고 하는 부분들이 있습니다. 그러니까 그거에 따라서 지금 2,892건, 19년도에 관련해서 그렇죠? 그다음에 2020년도에는 2,939건 이렇게, 21년도에는 2,754건이 있는데 이 부분들에 대한 개인, 이름은 없어도 상관없지만 어쨌든 개인별로 어떤 활동들을 했고 그 부분들에 대한 강의료나 이런 부분들의 썸이 좀 나타나서 볼 수 있도록 자료를 그렇게 만들어 주시면 좋을 것 같아요. 가능하시겠죠?  
</p>
<p><b>○ 연구부원장 송미영 </b> 이름 빼고 요구하신 자료 만들어 보겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 네. 그래서 이분이 박사님이신지 그다음에 이런 분, 직급 정도만 좀 써 주시면 좋을 것 같습니다. 
</p>
<p><b>○ 연구부원장 송미영 </b> 대외활동은 박사급 연구원만 나가고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그렇죠? 오케이. 그럼 그렇게 좀 부탁드릴게요.
</p>
<p style="padding-left:1.2em">  그리고 아까 말씀드린 것들, 공기관 대행사업들 관련해서 보니까 주신 자료만 보면, 사실은 주신 자료를 보면 지금 정관에 나와 있는 사업들을 다 다른 것들은 하셨어요. 보니까 조사사업이고 연구인 거고 이런 사업입니다. 그런데 DMZ 포럼과 관련된 부분들만 그런 부분에 우려가 있다는 말씀을 드리는 거고 우리 기본소득박람회나 이런 부분들은 주최로, 주최는 아니지만 주관에는 포함되어 있던데 거기에는 역할들이 좀 없으셨나요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 그 부분은 그 연구를 수행한 균형발전본부장님, 기본소득연구단에서 답변드리도록 해도 되겠습니까?  
</p>
<p><b>○ 김강식 위원 </b> 아니, 저는 궁금한 게 그거예요. 기본소득박람회를 우리가 기조실에서 했었잖아요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 네. 
</p>
<p><b>○ 김강식 위원 </b> 거기는 보니까 대행사업은 없이 어떤 식으로든, 거기 주관으로 되어 있던데 이 부분들에 주관으로 참여한 거는 다른 어떤 수탁이나 이런 부분들 없이 그냥 경기연구원에서 참여만 해 주신 건지를 궁금해서 여쭤보는 겁니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 그러니까 그 업무를 담당하는 분이 답변드려도 되겠습니까?  
</p>
<p><b>○ 김강식 위원 </b> 네, 그러시죠.
</p>
<p><b>○ 경제사회연구실선임연구위원 유영성 </b> 기본소득연구단장직을 맡고 있는 유영성이라고 합니다. 저희 경기도에서 추진한 기본소득박람회에서 경기연구원이 맡고 있는 부분은 기본소득 국제컨퍼런스 부분만 맡고 있습니다. 전체 예산이 아마 한 12억 정도 되는 걸로 아는데요. 컨퍼런스는 한 2억에서 2억 몇천 정도 그 부분만 맡아서 저희가 주로 기획하고 프로그램 짜고 해외인사ㆍ연사들 선정하고 섭외하고 이런 정도의 일을 주 업무로 맡고 해 왔습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그럼 여기에 지금 자료 주신 거에는 공기관 대행이나 대행사업으로 표시가 안 돼 있어서 여쭤보는 거예요.
</p>
<p><b>○ 경제사회연구실선임연구위원 유영성 </b> 저희는 그것까지는 해당사항이 없고 그냥 컨퍼런스만 주로 맡고 있기 때문에…….
</p>
<p><b>○ 김강식 위원 </b> 그럼 그 2억에 대한 부분들은 경기연구원에서 수탁받으신 거 아니시고. 어떻게 하신 거예요?  
</p>
<p><b>○ 경제사회연구실선임연구위원 유영성 </b> 우리 안에 아마 예산으로 받은 부분을 집행하는 걸로 알고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 출연사업으로 하셨던 거예요?  
</p>
<p><b>○ 경제사회연구실선임연구위원 유영성 </b> 네. 
</p>
<p><b>○ 김강식 위원 </b> 그럼 DMZ 포럼도 똑같은 방식으로 하셔도 되는 거 아니에요?  
</p>
<p><b>○ 경제사회연구실선임연구위원 유영성 </b> 그것까지는 잘 모르겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 거기 답변하실 건 아니신 것 같고. 
</p>
<p><b>○ 연구부원장 송미영 </b> 그러니까 그런, 아까도 제가 말씀드렸지만 위원님이 원하시는 답은 집행부하고 발주 부서에서 결정하는 대로 사실 저희가 협의를 해야 되기 때문에 그런 문제가 있음을 아실 거라고 생각합니다.
</p>
<p><b>○ 김강식 위원 </b> 네, 알겠습니다. 아니, 여기에는 수탁, 거기 행사에는 주관이라고 돼 있는데 여기에는 대행사업비를 받은 리스트가 없어서 제가 한번 말씀드린 거고요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 기본소득단의 대부분의 사업은 저희 출연금 안에서 소득단 운영 예산으로 운영했습니다. 
</p>
<p><b>○ 김강식 위원 </b> 일단 알겠습니다. 이상입니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 위원님, 아까 대외활동에 대해서 잠깐 제가 답변드려도 되겠습니까? 
</p>
<p><b>○ 김강식 위원 </b> 네.
</p>
<p><b>○ 연구부원장 송미영 </b> 횟수를 보시면 해마다 횟수가 굉장히 많은 것처럼 생각이 되시겠지만 저희 연구원당 대개 한 30회 정도 된다고 생각하실 때 저희 연구원들이 대부분 경기도하고 시군의 위원회에 참여를 하고 있습니다. 그러니까 이 중에 한 절반 정도는 그런 위원회 업무를 해야만 하는 일들이 있습니다. 그래서 이 중에 한 절반은 그런 업무고 나머지 절반 업무 중에 한 또 반 정도는 국가하고 연동된 국가위원회 아니면 국가하고 연동된 협력과제 등을 저희가 자문을 하거나 같이 협력하는 동안에 일어나는 대외활동입니다. 그리고 개인의 역량을 키우기 위해서 아마 그 절반 정도가 저는 소요된다고 생각을 하는데 그게 금액적인 면이나 활동 면에서 너무 과다하다고 생각하실 수도 있지만 저희 같은 연구직에서는 어쨌든 이런 일을 해야지만 교류협력이 일어나고 다양한 또 정책지원 활동을 할 수 있다는 점을 양해해 주셨으면 합니다. 
</p>
<p><b>○ 김강식 위원 </b> 제가 횟수가 많고, 뭐 어떤 지금 내용을 제가 모르니까 횟수가 많고에 대한 내용이 아니라…….
</p>
<p><b>○ 연구부원장 송미영 </b> 그래서 일단 제가 설명을 먼저 드린 겁니다. 자료는 나중에…….
</p>
<p><b>○ 김강식 위원 </b> 그러니까 그거는 자료를 좀 주셔야 저도 판단할 수가 있는데 자료는 안 주시고 설명을 그렇게 해 버리시면 제가 무슨 그걸 지적하려고 했던 것도 아닌데, 그렇지 않습니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 일단 설명을 먼저 드렸습니다, 자료가 아직 준비가 안 됐기 때문에. 
</p>
<p><b>○ 김강식 위원 </b> 그 자료를 먼저 주시고, 주셔서 제가 판단해서 그 부분들이 이해가 가는 부분이면 그냥 마무리 되는 부분들인데…….
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그렇게 자료준비하겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 그렇지 않은 거를 먼저 이렇게 이야기를 하셔서 마치, 제가 자료요청한 의도가 뭔 줄 아시고 그렇게 얘기하시는 거예요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 아니, 이 자료를 설명드리기 위해서 그런 겁니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러니까요. 
</p>
<p><b>○ 부위원장 이종인 </b> 정리해 주시고요. 우리 김강식 위원님 수고하셨습니다. 그리고…….
</p>
<p><b>○ 김강식 위원 </b> 일단은 충분히 이해는 했고요. 어쨌든 그 내용을 보려고 했던 부분들보다도, 개인적인 활동들이 좋죠. 그런데 하도 연구에 대한 부분들에 대한 부분이 부족하다 하는 부분들이 충실히 하고 있는 정도의 시간이 할애되고 있는지 아니면 대외활동들의 어떤 시간들을 좀 거기에 하시는 부분들이 있으신 건 아닌지. 그 부분들은…….
</p>
<p><b>○ 연구부원장 송미영 </b> 파악하실 수 있도록 자료준비하겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 자료를 보면 파악할 수 있겠죠. 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 김강식 위원님 수고하셨습니다. 제가 아까 사전에도 답변을 좀 짧게 요약해서, 부족한 부분은 자료로 주셔야죠. 우리 송미영 부원장님은 지금 뭐 경기연구원 홍보하시는 거예요? 위원님이 됐다라는데 왜 추가, 계속 완벽하게 이해도 안 되는 거를, 지금 경기연구원 홍보하시는 겁니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 아닙니다. 죄송합니다.
</p>
<p><b>○ 부위원장 이종인 </b> 짧게 해 주시기 바라겠습니다. 다음은 김재균 위원님 추가질의해 주십시오.
</p>
<p><b>○ 김재균 위원 </b> 평택 출신의 김재균 위원입니다. 지금 보면 홍보정보부가 있고 대외협력부가 있는데 홍보정보부에 지금 몇 분이 근무하십니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 그 부분은……. 
</p>
<p><b>○ 경영부원장 장형철 </b> 제가 말씀드리겠습니다.
</p>
<p><b>○ 김재균 위원 </b> 몇 분이 근무하시는 숫자만 말씀해 주세요. 직원 숫자요. 
</p>
<p><b>○ 경영부원장 장형철 </b> 네, 9명입니다.
</p>
<p><b>○ 김재균 위원 </b> 9명이고. 대외협력부에서는?  
</p>
<p><b>○ 경영부원장 장형철 </b> 대외협력부는 3명이 있습니다.
</p>
<p><b>○ 김재균 위원 </b> 네, 됐습니다. 지금 보면 우리가 연구과제가 4개가 있어요. 기본연구하고 정책연구는 집행부나 어떤 연초에 결정을 하는 거고 정책연구는 좀 그런데 위탁연구 부분에 대해서는 지금 쭉 위탁연구를 19년도서부터 낸 걸 자료를 보면 어느 한 시에, 공통적인 게 아니라 31개 시군 중에 하나에 해당하는 게 있으면 이런 거는 위탁연구로 갈 게 아니라 수탁연구로 보내야죠. 집행부하고 그런 거를 정확히 상의해서, 아까서부터 본 위원 같은 경우 계속 자생력을 키워야 되고 하라 그러는 부분에서도 그런 부분에서 집행부에서 준다고 그래서 그냥 받는 게 아니라 아닌 건 아니라고 하면서 집행부와 협의할 수 있는 경기연구원이 돼야지 앞으로도 발전이 있을 거라고 저는 봐집니다.
</p>
<p style="padding-left:1.2em">  그리고 여기서 이제 수탁용역을 한 거 보니까 작년에 4건, 올해 2건이 도시생태 현황지도라는 걸 해서 상당히 수탁연구에서는 예산이 많이 들어왔어요. 수입이 됐는데 경기도 31개 시군에 보면 기본적으로 5년에 한 번씩 하는 그런 연구가 되게 많아요. 그러면 그 금액이 적지가 않거든요. 그러면 31개 시군, 경기도에서 원하는 연구과제가 있다면 경기연구원도 그런 쪽의 방향을 좀 잡아서 같이 갔을 때는 훨씬 더 발전적이고 도움도 줄 수 있고 그런 두 가지 방법이 있는데 그런 거를 지금, 제가 왜 지금 대외협력부나 홍보정보부의 숫자를 물어봤냐면 대외협력부의 분들이 그런 정보를 갖고 그런 데 가서 협의를 해 주고 경기연구원에서 갖다 줬을 때 그 협력이 가능하다고 저는 봐집니다. 근데 세 분이 이거 갖고 31개 시군 돌아다니기에는 너무, 물론 경기연구원이니까 연구 쪽에 많이 하지만 앞으로 경기연구원이 좀 더 강해지고 좀 더 발전되려면 이런 부분을 좀 극대화, 좀 더 활성화시키지 않으면 안 된다고 본 위원은 판단을 하는 겁니다, 지금. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네. 
</p>
<p><b>○ 김재균 위원 </b> 그러니까 어차피 중장기, 아까 우리 염종현 위원님이 말씀하셨던 중장기 계획을 세우고 내년에 계획을 세울 때는 이런 부분을 좀 더 활성화될 수 있는 방법을 고민해 주시기 바랍니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 알겠습니다.
</p>
<p><b>○ 김재균 위원 </b> 그리고 제가 아까 이 책에 대한 자료를 좀 달라고 그랬는데.
</p>
<p style="padding-left:2.4em">    (책자를 들어 보이며)
</p>
<p style="padding-left:1.2em">  이게 무슨 책인지 아시죠?  
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 압니다. 
</p>
<p><b>○ 김재균 위원 </b> 이 책을 왜 만들었습니까? 그 이유가, 저도 이 책을 택배로 받았는데 이 책을 왜 저한테 보냈을까, 저는 솔직히 궁금하더라고요. 이거 몇 권이나 만들었어요?  
</p>
<p><b>○ 연구부원장 송미영 </b> 영문 보고서 말씀하시는 거죠?  
</p>
<p><b>○ 김재균 위원 </b> 네. 이 책이요, 이 책. 그리고 이거 몇 권 만들었는지 나왔을 거 아니에요.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그거는 자료를 뽑아서 말씀드리겠습니다.
</p>
<p><b>○ 김재균 위원 </b> 이게 계약금액이 1,940만 원으로 돼 있는데 이게 지금 이 편집자하고의 계약금액입니까, 아니면 이 책을 만드는 데 계약금액입니까?  
</p>
<p><b>○ 연구부원장 송미영 </b> 보고서는 원래 국문 보고서가 있고요, 영문 보고서로 만드는 비용을 포함한 금액일 겁니다.
</p>
<p><b>○ 김재균 위원 </b> 영문 보고서를 만든 금액이 1,940만 원?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 김재균 위원 </b> 그러면 이거 하나 가지고 연구과제로 잡아서 또 하고 그랬으면 여기에 들어간 총체적인 예산은 얼마 정도인지 다시 보조 추가자료 좀 내주시고요. 그렇다고 그러면 지금 1불이 환율로 보니까 한 1,180원 정도 돼요. 책 가격이 여기 뒤에 보니까 40불 정도로 돼 있어. 39불 99전으로 돼 있더라고. 그러면 4만 7,000원으로 계산해 가지고 한 400권 정도를 만들었을 거라고 예상을 해요. 배부처를 지금 준 데 이거 자료 있습니까?
</p>
<p><b>○ 연구부원장 송미영 </b> 있습니다.
</p>
<p><b>○ 김재균 위원 </b> 이것도 추가자료로 좀 내주십시오.
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 김재균 위원 </b> 그리고 이걸 일반수용비로 만들었죠?
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 일반수용비가 인쇄비를 포함하는 거라서 그렇습니다.
</p>
<p><b>○ 김재균 위원 </b> 그런데 이거를 만든 자체 그리고 이게 정말 필요해서 영문으로 만들었다면 이것이 필요한 부분의 분들한테 가야 되는데 솔직히 광고용으로밖에, 거짓말 하나도 안 시키고 제가 이거 받자마자 옆에다 놔뒀다가 3일 후에 아마 고물상으로 갔을 거예요, 폐지로. 근데 우리는 이거를 4만 7,000원이라는 돈을 들여서 쓸 데도 없는 저 같은 사람들한테 보내줬어요. 우리 사무실에도 이거 몇 개 지금 왔다 갔다 하는 걸 봤는데 정말 필요한 분들한테 가야지 자료도 귀중한 거지. 그리고 지금 영문 이렇게 해 가지고 이거 해독할 사람 몇 분 안 계실 거예요. 일반수용비의 한 단면을 지금 보고 있는 것 같아서 굉장히 씁쓸합니다. 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 김재균 위원님 수고하셨습니다. 다음은 이필근 위원님 질의해 주십시오.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 수원 권선의 이필근 위원입니다. 제가 감사담당관실, 감사관실에서 자료를 받고 지금 질문을 하는 건데요. 2020년도 경기도 공직유관단체 청렴도 평가 결과입니다. 그러니까 쉽게 말해서 경기도 공공단체 청렴도 평가인데 경기연구원이 3등급입니다. 그러니까 평균이 8.90인데 경기연구원은 8.74입니다. 그러니까 평균보다 좀 낮았죠? 좋은 편은 아닙니다. 그러나 이거 분석을 해 보니까 외부청렴도는 9.7이에요, 제일 높아요. 아주 외부에서는 경기연구원이 가장 청렴도가 높다고 평가를 받는데 내부청렴도를 보면 꼴찌에서 두 번째입니다. 경기연구원이 6.94 그다음에 평균이 7.79입니다. 
</p>
<p style="padding-left:1.2em">  이건 무슨 뭘 뜻할까? 외부에서는 청렴도가 제일 좋다고 평가했는데 내부청렴도는 내부 구성원, 조직 구성원들이 어떤 청렴도를 평가할 때는 제일 낮은 거예요. 이거는 그 안에 그만큼 화합도 안 되고, 조직 간의 구성원들이. 그다음에 보이지 않는 위기, 불화가 있는 거고. 제가 듣기로는 예를 들어서 박사, 석사, 여러 가지 학사 또 있는데 그 안에 그런 보이지 않는 것이 있지 않냐? 우리 공무원들한테 내부청렴도가 가장 나쁜 것은 갑질문화라고 얘기합니다. 그러니까 갑질이 있는 거예요. 자기들은 아니라고 그러지만 밑에서 보기는 박사가 갑질하는 거지. 그러니까 내부청렴도가 6.94, 거의 꼴찌입니다. 이거 어떤 연구를 같이 할 때 무슨 그런 거 주도하는 사람도 있고 보조하는 사람도 있지만 같이 화합을 해야지 내부청렴도가 이렇게 낮아서 무슨 좋은 작품이 나오겠습니까? 외부에서만 그냥 폼 잡고 우리 박사들이 열심히 한다고 얘기를 하지만 실제로 거기 구성원들은 제일 불만이 많은 겁니다. 그거 어떻게 생각하세요, 부원장님?
</p>
<p><b>○ 연구부원장 송미영 </b> 저희도 이게 계속 점수가 나빠서 분석을 해 봤는데 저희가 무기직군을 새로 만들지 않았습니까? 그분들이 이제 어쨌든 이런 내부만족도 평가를 처음 하게 되는 과정에 있어서 그분들을 수용하는 저희 내부 조직문화도 아직 적응을 못 했고 그분들도 이런 정규직 직군으로 이렇게 수용되는 것에 서로 생각이 달라서 그 부분을 저희가 조정하는 노력을 하고 있습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 그것은 여기 공직기관에 그런 공무직이라고 할 수 있는 무기계약직이 다 있어요. 거기만 있는 게 아니에요. 일자리재단, 관광공사. 근데 그런 데는 내부청렴도가 왜 높으냐고. 보이지 않는, 그거는 제가 알기로는 학벌에 관한 여러 가지 보이지 않는 계층 그런 거에 대한 어떤 불만 또 배운 사람이 못 배운 사람에 대한 어떤 무시나 그런 것이 있으니까 이렇게 내부청렴도가 제일 낮지. 외부청렴도는 제일 높은데 내부청렴도가 제일 낮은 것은 저는 화합도 안 되고, 이게 뭐가 되겠어요? 서로 그냥, 그런 문화를 부원장이나 여기 계신 분들이, 부장님들이 적극적으로 해소하는 데 좀 앞장섰으면 좋겠습니다. 
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 이상입니다.
</p>
<p><b>○ 경기연구원장직무대행 허성관 </b> 위원님, 제가 한마디만 답변을 드리겠습니다. 제가 지금 대행을 하고 있기 때문에 잠깐이면 끝날 텐데요. 방금 해 주신 말씀은 굉장히 중요한 말씀이라고 저는 개인적으로 생각을 합니다. 그래서 그 문제는 후임 원장이 선임되면 위원님께서 하신 문제, 지적하신 말씀 그 말씀을 후임 원장에게 제가 꼭 명확하게 전달하도록 하겠습니다. 그래서 내년에는 이런 청렴도 조사가 나왔을 때 다시는 그런 문제가 거론되지 않도록 각별히 조심하라고 제가 전달하도록 하겠습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 부위원장 이종인 </b> 이필근 위원님 수고하셨습니다. 다음은 염종현 위원님 질의해 주십시오.
</p>
<p><b>○ 염종현 위원 </b> 저는 자료가 좀 천천히 온다고 그래서 종합감사 때 질의를 하고요. 아까 기금 문제 우리 정희시 위원님도 얘기하시고 해서, 저희가 기금은 지금 만들 수가 없고, 여러 가지 상황상. 이사장님이 말씀하신 부분도 일리가 있는 말씀이고. 그런데 저희가 3년에서 한 5년 중장기 계획을 세워라라고 하는 입장에서 아마 집행부가 거기에 대해서 예산과 인력이 들어가는 건 쉽게 동의가 잘 안 될 겁니다, 부원장님. 그랬을 때 의회에서 이렇게 저와 같이 주장하는 사람들의 얘기를 담아서 하기 위해서는 중장기 계획을 잡아서 예산과 인력을 늘려야 돼요.
</p>
<p style="padding-left:1.2em">  그런데 경기연구원은 집행부와 예산 협의를 할 때 얘기할 수 있는 명분이 하나 있어요. 그건 뭐냐 하면 지금 우리가 한 30개 공공기관이 있는데 그동안에 출연금을 받는 대다수의 공공기관들은 집행잔액이나 자체수익 등등으로 이월금이 생기면, 이월금이죠. 출연금 받는 기관은 반납을 하지 않지 않습니까? 근데 경기연구원은 반납하는 거랑 똑같이 지금 하고 있어요. 너무 그, 이게 맞는 건지 싶을 정도로. 그런데 다른 공공기관은 그동안 어떻게 했냐 하면 30억의 이월금이 남았다 그러면 반납을 안 하죠. 그러면 다음에 이듬해 2~3월에 자체 추경을 해 버립니다. 그러니까 자체 추경하는 것은 의회의 심의를 받지 않아요. 그러니까 하고 싶은 거를 그냥 30억 가지고, 자기들이 그냥 하고 싶은 거를 자체적으로 이사회를 열어서 자체 추경으로 해서 그냥 써버리는 겁니다. 의회에 보고도 안 해요. 그렇게 현재도 할 겁니다, 아마. 제가 8ㆍ9대 경험을 할 때는 다 그렇게 했으니까. 그런데 경기연구원은 그걸 또박또박 이월금, 그러니까 출연금 그다음 이듬해 예산에 반영을 해 버린단 말이죠. 그래서 그런 것들을 좀 얘기를 드릴 필요가 있다라는 말씀을 하나 드리고.
</p>
<p style="padding-left:1.2em">  마지막으로 우리 공공투자센터가 언론에 큼지막하게 보도자료를 내서 “지난 3년간 도 재정사업 2,797건을 평가해 이 중 984건의 예산을 일몰ㆍ감액 방식으로 절감했다.” 이렇게 했는데 절감했어요? 아니, 거기서 하세요. 나올 정도는…….
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 했습니다.
</p>
<p><b>○ 염종현 위원 </b> 했어요? 그러면 이 자료를 줄 수가 있어요? 그러니까 내가 왜 자료요구를, 왜 그 말씀을 드리냐 하면 공공투자센터는 경기연구원으로부터 독립돼 있잖아요, 독립성. 그렇죠?
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 네, 맞습니다.
</p>
<p><b>○ 염종현 위원 </b> 그런데 이게 일몰 예산을, 그러니까 이게 상당수의 행사성이 많이 포함됐을 텐데 이 사업 예산이 일몰됐다고 했을 때 그 일몰된 명단이 나오면 상당히 좀 곤혹스러울 것 같아서 제가 얘기를 드리는 거예요. 자료를 줄 수가 있어요?
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 그 자료는 다 있는데요. 사실 이것의 주관은 예산실이기 때문에 좀 협의가 필요할 것 같습니다. 저희가……. 
</p>
<p><b>○ 염종현 위원 </b> 자료를 줬을 때 공공투자센터가 공격받을 수가 있다?
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 드리더라도 예산실에서 드리는 게 적정할 것 같습니다.
</p>
<p><b>○ 염종현 위원 </b> 협의해서. 강요하는 건 아니고 협의해서 줄 수 있으면 주시고 정 어렵다라고 판단되면 별도로 얘기를 주세요.
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 네, 알겠습니다. 
</p>
<p><b>○ 염종현 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 염종현 위원님 수고하셨습니다. 지금 현재 추가질의는 다 끝났고요. 경기연구원이 의정부로 이전 계획이 있지 않습니까. 그래서 위원장 재량으로 2분만 우리 의정부 출신의 이영봉 위원님에게 보충질의를 드리도록 하겠습니다.
</p>
<p><b>○ 이영봉 위원 </b> 위원장님 고맙습니다. 올 6월 18일 원장님하고 의정부시장님 면담이 있었어요?
</p>
<p><b>○ 연구부원장 송미영 </b> 있었습니다.
</p>
<p><b>○ 이영봉 위원 </b> 그런데 해당 위원회 위원도 모르는 면담을 하시나요? 실무협의라고 그래서, 자체적인 추진단 협의라고 그래서 그렇게 생각을 했었는데 여기 자료에 의하면 그 면담을 하셨어요. 그리고 6월 29일 날 3차 공공기관 이전에 대한 협약식을 했었던 거죠. 이런 부분들을 해당 지역의 의원님한테도 안 알려주고 이렇게 면담을 하시나요?
</p>
<p><b>○ 연구부원장 송미영 </b> 그것은 의정부시에서 시장님이 요청을 하셔서 저희 원장님이 가셔서……. 
</p>
<p><b>○ 이영봉 위원 </b> 그렇다 하더라도요.
</p>
<p><b>○ 연구부원장 송미영 </b> 서로 협의를 하는 걸로 됐었고요. 그다음에 사실 이전에 관련해서 저희가 의사결정을 하지 못하지 않습니까? 그래서 대부분 비전을 포함해 집행부에서 모든 구조나 협의체 의사결정을 하면 저희는 따르는 상황입니다.
</p>
<p><b>○ 이영봉 위원 </b> 지금 1, 2차 실무협의를 하셨어요?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 이 내용은 뭔가요?
</p>
<p><b>○ 연구부원장 송미영 </b> 1차 때는 저희가 지금 담고 있는 내용을 어떤 식으로 서로 협의할 건지, 구조는 어떻게 만들 건지를 얘기한 거였고요. 2차 때는 그 내용 중에 어떤 진전사항이 있는 부분을 서로 어떤 식으로 협의해 갈지를 의논하는 그냥 아주 초보적인 단계의 의논이었습니다.
</p>
<p><b>○ 이영봉 위원 </b> 앞으로 이제 해야 될 부분들이 지금 많죠?
</p>
<p><b>○ 연구부원장 송미영 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 그렇죠? 예산을 어떻게 확보할 것인가. 그리고 직원들에 대한 이를테면 설문이라면 설문이고, 이전에 관련해서. 이 부분들도 하셔야 될 것 같고.
</p>
<p><b>○ 연구부원장 송미영 </b> 앞으로 해야 됩니다.
</p>
<p><b>○ 이영봉 위원 </b> 그리고 여기 경기북부로 이전하게 되면 주거환경이 바뀌는 거 아니겠습니까? 학교 문제라든가 주거환경 문제라든가 이런 부분들, 앞으로 해야 될 부분들이 많은 것 같아요. 그렇게 하기 위해서는 좀 광범위하게 준비위원회를 꾸리는 게 합당하지 않을까라는 그런 말씀을 드리겠습니다. 그렇게 하시겠습니까?
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 저희도 노력해 보고 도에 건의도 드리겠습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 그렇게 하셔서 위원회에도 보고를 좀 해 주십시오.
</p>
<p><b>○ 연구부원장 송미영 </b> 네, 그렇게 말씀드리겠습니다.
</p>
<p><b>○ 이영봉 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 이영봉 위원님 수고하셨습니다. 3시간에 걸쳐서 본질의와 추가질의를 모두 마쳤습니다. 더 질의하실 위원님 안 계시죠?
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시므로 경기연구원 소관에 대한 질의와 답변을 모두 마치겠습니다.
</p>
<p><b>○ 연구부원장 송미영 </b> 감사합니다.
</p>
<p><b>○ 부위원장 이종인 </b> 위원 여러분 그리고 허성관 이사장을 비롯한 경기연구원 관계 여러…….  
</p>
<p style="padding-left:1.2em">  아니, 아직 안 끝났습니다. 
</p>
<p><b>○ 연구부원장 송미영 </b> 아니, 이사장님이 일어나시려고 해서 자리를 바꿔 드리려고.
</p>
<p><b>○ 부위원장 이종인 </b> 위원 여러분 그리고 허성관 이사장을 비롯한 경기연구원 관계 여러분! 행정사무감사를 위해 자료준비와 위원님들의 질의에 성의를 다해 답변해 주신 관계자 여러분께 감사드립니다. 허성관 이사장님을 비롯한 관계자 여러분께서는 오늘 여러 위원님들께서 지적해 주신 사항을 도민의 소중한 의견인 만큼 도정에 적극 반영하여 주시기 바라겠습니다. 또한 오늘 감사 중에 위원님들께서 개선을 요구한 사항에 대해서도 조속히 시정될 수 있도록 노력해 주시기 바라겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기연구원 관계 여러분! 수고하셨습니다. 이상으로 경기연구원 소관 사항에 대한 2021년도 행정사무감사를 종료하고 11월 12일에는 전체적인 정리 감사를 실시하겠습니다. 오늘의 행정사무감사를 모두 마치겠습니다. 산회를 선포합니다.
</p>
<p class=''ar''>(18시36분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(13명)
</b></p>
<p class=''aMan''>심규순이필근(수원3)이종인김강식김달수김재균김중식염종현오지혜원미정</p>
<p class=''aMan''>이영봉이제영정희시</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 이태헌
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p class=''em15''>경기연구원장 직무대행 허성관연구부원장 송미영</p>
<p class=''em15''>경영부원장 장형철연구기획본부장 봉인식</p>
<p class=''em15''>균형발전본부장 김동성감사실장 김동영</p>
<p class=''em15''>북부연구센터장 이정훈시군연구센터장 류시균</p>
<p class=''em15''>도시주택연구실장 이성룡경제사회연구실장 성영조</p>
<p class=''em15''>교통물류연구실장 빈미영생태환경연구실장 이기영</p>
<p class=''em15''>연구기획부장 이수진전략정책부장 김정훈</p>
<p class=''em15''>행정지원부장 손호철재정지원부장 박인숙</p>
<p class=''em15''>성과관리부장 배미성홍보정보부장 강승현</p>
