<p class=''em15''>경기도공공투자관리센터 소장 김도일</p>
<p class=''em15''>경기도공공투자관리센터 총괄기획부장 김병석</p>
<p class=''em15''>경기도공공투자관리센터 투자분석평가1부장 김대중</p>
<p class=''em15''>경기도공공투자관리센터 투자분석평가2부장 이상미</p>
