</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 경기연구원 
</p>
<p><hr /></p>
<p>일  시: 2020년 11월 9일(월)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(16시26분 감사개시)
</p>
<p><b>○ 심규순 위원장 </b> 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조와 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 따라 경기연구원에 대한 2020년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  이한주 경기연구원장을 비롯한 임직원 여러분! 안녕하십니까? 기획재정위원회 감사위원장 심규순 위원입니다. 지금부터 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 연구원 임직원 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 나아가 2021년도 예산안 심사자료 및 정보를 획득하여 도민의 삶의 질 향상에 기여하고자 함이 그 목적인 만큼 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사에 임하는 집행부 공직자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기를 당부드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기연구원장과 각 본부장, 실장 등은 증인의 자격으로 업무소관을 보고하고 질의에 답변하기에 앞서 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 경기도의회가 2020년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과됨을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인들께서는 자리에서 모두 일어나 주시기 바랍니다.
</p>
