</p>
<p><b>○ 경기도공공투자관리센터투자분석평가2부장 이상미 </b> 네, 나왔습니다. 
</p>
<p><b>○ 심규순 위원장 </b> 다음은 선서요령을 설명드리겠습니다. 선서는 증인들을 대표해 원장이 발언대로 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인께서는 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2020년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2020년 11월 9일 원장 이한주. 
</p>
<p><b>○ 심규순 위원장 </b> 모두 자리에 앉아주시기 바랍니다. 계속해서 간부인사와 업무보고를 받도록 하겠습니다. 경기연구원 원장 나오셔서 간부소개와 업무보고를 간략히 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 안녕하십니까? 경기연구원장 이한주입니다. 오늘 존경하는 기획재정위원회 심규순 위원장님을 비롯하여 여러 존경하는 위원님들을 모시고 2020년 경기연구원 행정사무감사 업무보고를 드리게 되어 감사하게 생각합니다. 우리 연구원은 대내외 여건 변화와 민선7기의 효율적인 정책대응을 위하여 연구원의 비전을 ‘새로운 경기 정책플랫폼 GRI’로 설정하고 경기도민의 삶의 질 향상을 위해 전 직원이 합심하여 노력하고 있습니다. 향후에도 경기연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  보고에 앞서 아까 위원장님께서 말씀하셨습니다만 다시 한번 연구원의 주요 간부를 소개해 드리겠습니다. 간부들께서는 호명하실 때 자리에서 일어나서 인사하고 착석하십시오. 
</p>
