</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치겠습니다. 지금부터 연구원의 주요업무보고를 드리겠습니다. 보고 순서는 기본현황, 20년 경영목표 및 연구사업 방향, 20년 주요사업 성과, 21년 주요사업 방향 순으로 말씀드리겠습니다. 배포해 드린 주요업무보고의 내용으로 요약되어 있습니다. 
</p>
<p style="padding-left:1.2em">  먼저 1쪽 기본현황입니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 연구원의 조직은 본원이 2부원장 1실 2본부 5연구실 2센터 5실 7부로 구성되어 있고 부설기관인 경기도공공투자관리센터가 3부로 구성되어 있습니다. 우리 원의 인력은 본원에 원장 1명, 부원장 1명, 연구직 63명, 관리ㆍ정보ㆍ기능직 26명 등 91명이 근무하고 있으며 부설 조직인 경기도 공투센터에는 소장 1명, 투자분석직 10명과 관리직 2명 등 13명이 근무하고 있어서 본원과 경기도 공투센터를 합하면 총 104명의 정규직원이 근무하고 있습니다. 아울러 연구원ㆍ행정원 등 무기계약직 62명, 초빙연구원 등 계약직원이 26명 근무하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 2쪽 주요기능입니다. 원장 직속으로 감사실이 편제되어 있으며 연구부원장 산하에 연구기획본부, 균형발전본부와 각 연구실이 위치하고 있습니다. 경영부원장 산하에는 5개의 행정부서가 편제되어 있습니다. 아울러 부설기관으로 경기도공공투자관리센터를 두고 있습니다. 상세한 내용은 부서별 주요업무 등 자료를 참조하여 주시기 바라겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 3쪽 예산현황에 대하여 말씀드리겠습니다. 올해의 총 예산 규모는 286억 원으로 일반회계 232억 원, 수탁용역사업 등 특별회계 30억 원, 공공투자관리센터 24억 원입니다. 일반회계의 수입ㆍ지출 내역을 보다 세부적으로 말씀드리겠습니다. 수입항목은 경기도 출연금이 174억으로 일반회계 예산의 75%를 차지하고 있으며 수탁회계전입금은 15.5억 원이고 전기이월금은 39억 원입니다. 지출항목으로는 인건비가 136억 원으로 일반회계 예산의 58.6%를 차지하고 있으며 연구사업비는 66억 원으로 28.4%의 비중입니다. 이외에 경상경비 23억 원이 편성되어 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 4쪽 2020년 경영목표 및 연구사업 방향입니다. 연구원은 새로운 경기, 정책 플랫폼 GRI를 비전으로 도민의 삶의 질 향상에 기여하는 연구를 선도하고 현장과 소통하는 연구체계를 수립하며 환경변화에 대응한 새로운 사업을 확대하고 공정하고 투명한 경영관리체계 수립을 4대 경영목표로 수립하였습니다. 또한 새롭고 공정한 세상을 위한 5대 연구사업 방향을 설정하였습니다. 5대 연구사업 방향은 첫째 공정경제와 노동권 등 기본권 보장 연구 추진, 둘째 미래산업 육성과 제조업 혁신 연구 추진, 셋째 한반도 공동의 번영과 교류ㆍ협력을 위한 연구 추진, 넷째 지속가능한 경기도 실현을 위한 연구 추진, 다섯째 안정된 도시 주거환경 조성을 위한 연구 추진으로 정하였습니다. 공정 가치를 위한 도민의 인권과 노동권 연구가 2020년 핵심연구였으며 기업의 SCALE UP, 미래 신성장 산업 연구 등 지역경제 활성화에 중점을 두었습니다. 
</p>
<p style="padding-left:1.2em">  2020년 주요사업 성과를 5쪽에서 보고드리겠습니다. 첫 번째 성과는 코로나19를 대응하고 공정경제와 노동권 등 총 203건의 핵심정책 연구과제를 수행하였으며 주요 연구주제로는 코로나19 대응 및 포스트 코로나19 관련 연구, 공정경제와 노동권 등 기본권 보장 연구, 미래산업 육성과 제조업 혁신 연구, 한반도 공동의 번영과 교류 협력을 위한 연구, 지속가능한 경기도 실현을 위한 연구, 안정된 도시 주거환경 조성을 위한 연구 등을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 6쪽입니다. 두 번째 성과로는 기본소득 연구를 통한 글로벌 이슈를 선도했다는 점입니다. 경제, 재정, 법률 등 다양한 전문가가 참여하는 기본소득연구단을 운영하였습니다. 기본소득운영단에서는 기본소득 재원, 기본소득 법제화, 기본소득의 경제적 영향, 지역화폐 등 다양한 연구와 글로벌 선도를 위한 영문 보고서를 지속적으로 출간하고 있습니다. 또한 2020년 9월 11일 기본소득 국제콘퍼런스를 개최하여 유튜브와 홈페이지를 통해 전 세계로 중계하였습니다. 주요 세션으로는 기본소득으로 가는 디딤돌 기본소득 재원 조달 전략, 현대자본주의에서 삶의 질과 기본소득, 기본소득과 지역화폐, 복지국가의 위기와 기본소득이었습니다. 그리고 2020년 9월 17일과 18일에는 도도한 기본소득 연구 공모제를 개최한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 7쪽입니다. 세 번째 성과로는 코로나19 및 경제위기에 관련하여 현안에 대한 적시 지원입니다. 코로나19로 인한 경제재난, 재난기본소득이 해법이다, 코로나19, 언택트 사회를 가속화하다 등 코로나19 관련 이슈&진단 시리즈를 추진하였습니다. 또한 코로나19발 경기도 소비지출 감소 등 코로나19와 경제위기 관련 현안에 대하여 적시 대응하였습니다. 네 번째 성과로는 DMZ포럼 등 국제행사를 성공적으로 개최하여 DMZ의 국내외적 상징성을 바탕으로 한반도와 국제 시민사회의 평화협력 공동번영을 구현하기 위한 논의의 장을 마련하였고 네트워크 거점 역할을 수행하였습니다. 다섯 번째 성과로는 공공투자관리센터 운영을 통한 경기도 재정건전성을 확보하였습니다. 사업비 5,000만 원 이상 1,015건의 사업평가를 통해 3,253억 원을 감액하는 데 기여하였으며 투자심사 사전검토 208건을 수행 완료했습니다. 
</p>
<p style="padding-left:1.2em">  다음은 8쪽 2021년도 주요 이슈 및 연구사업 방향입니다. 2021년 주요 이슈로는 국제정세 불안정성, 코로나19의 팬데믹, 인구구조의 변화와 저성장, 지역의 양극화, 기후변화, 4차 산업혁명 등을 선정하였습니다. 연구사업 방향 및 핵심 어젠다는 포스트 코로나ㆍ뉴노멀 시대를 선도, 공정한 경기도ㆍ인권보장과 보편적 복지의 강화, 지속가능발전을 위한 인프라 구축, 강력하고 효율적인 지방정부의 실현 등입니다. 자세한 내용은 자료를 참조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 9쪽 세부 연구사업 방향을 보고드리겠습니다. 먼저 기본소득, 기본서비스 연구를 지속적으로 추진하고자 합니다. 경기도 기본소득 5개년 종합계획 수립을 연구하고 경기도 청년기본소득 정책의 효과를 분석하는 등 기본소득과 관련한 연구를 추진하겠습니다. 그리고 기본서비스 관련 연구를 수행하겠습니다. 경기도에서 시행하거나 준비 중인 인간으로서 누려야할 보편적 기본서비스 정책, 예를 들면 기본주택, 무상교복, 공공산후조리원 지원 등을 평가하고 보다 확정된 경기도형 기본서비스 모델과 정책방향을 연구할 계획입니다. 다음은 공정성 기반 정책개발을 위한 전략연구과제를 추진하겠습니다. 주요내용으로 공정경제, 공정사회, 기본소득, 공정토지개발 등에 대한 연구를 통하여 코로나19 이후 뉴노멀 시대에 공정한 경기도를 실현하기 위한 사람중심 정책방향을 구체적으로 정립하고자 합니다. 
</p>
<p style="padding-left:1.2em">  다음은 10쪽입니다. 포스트 코로나, 뉴노멀 시대 선도 연구를 추진하겠습니다. 주요내용으로 재난으로부터 안전한 지역과 사회를 조성하고 새로운 경제 산업 패러다임 구축하며 포스트 코로나 시대 삶의 변화와 대응입니다. 민선7기 도정 현안에 대하여도 적시 대응하도록 하겠습니다. 또한 현안이슈에 대한 분석과 대안 제공으로 도민의 삶의 질을 개선하고 도정과제를 추진하고 지원하며 주요 사회이슈에 적극 대응하겠습니다. 또한 경제동향 통계분석 연구와 연구지원을 하겠으며 마지막으로 경기도의회의 관심사항을 적극적으로 연구하겠습니다.
</p>
<p style="padding-left:1.2em">  이어서 11쪽입니다. 언택트 시대에 맞는 유관기관과의 대외협력사업을 추진하겠습니다. 정책세미나 및 포럼운영, 의정연구 및 대외협력 교류사업을 코로나19로 인한 언택트 생활의 일상화에 따라 비대면ㆍ원격 플랫폼 등을 활용한 대외협력사업으로 추진하겠습니다. 다음은 연구자료 및 데이터 관리ㆍ홍보 강화입니다. 경기도 온라인 정책연구 도서관 운영, GRI 연구성과 동영상 제작 및 홍보 강화를 통한 도민의 접점 극대화, GIS 사업, 홈페이지 개선사업을 통해 정보접근성을 강화하고 사용자 업무의 효율 증대를 위하여 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽입니다. 공공투자관리센터를 통한 도 재정의 효율화를 지원하겠습니다. 공투센터 비전 및 목표는 자료를 참조해 주시기 바라며 주요사업계획에 대하여 보고드리겠습니다. 먼저 경기도 제1ㆍ2투자심사위원회 심사대상사업에 대하여 사전분석 및 검토의견을 제공하겠습니다. 또한 행정안전부 투자심사 대상사업의 논리를 개발하고 데이터 등 필요한 자료를 지원하겠습니다. 경기도 재정건정성 확보 및 재원의 효율적 배분을 위한 재정사업평가를 추진하겠습니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 13쪽 2019년 행정사무감사 조치결과와 20쪽의 3년간 도의회 요청과제 현황은 자료로 갈음하겠습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요업무보고를 모두 마치겠습니다. 경청해 주셔서 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 심규순 </b> 경기연구원장 수고하셨습니다. 다음은 감사 질의 답변 순서입니다만 감사에 앞서 출석해 주신 참고인을 소개하겠습니다. 
</p>
<p style="padding-left:1.2em">  이분들은 경기연구원 노동조합위원장, 부위원장을 맡고 계십니다. 
</p>
<p style="padding-left:1.2em">  경기연구원 이은환 연구위원.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  또 경기연구원 강철구 선임연구위원.
</p>
<p style="padding-left:2.4em">    (인   사) 
</p>
<p style="padding-left:1.2em">  또 경기연구원 조희은 연구위원 나오셨습니까? 
</p>
<p><b>○ 참고인 조희은 </b> 네.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p><b>○ 위원장 심규순 </b> 앉아도 좋습니다. 바쁘신 와중에도 출석해 주신 참고인들께 감사위원장으로서 감사드리며 위원님들께서 참고인으로 질의하실 사항을 우선적으로 진행해 주시면 감사하겠습니다. 감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 우선 위원님 한 분당 10분씩 드리겠습니다. 시간을 지켜주시기 바랍니다. 본 질문이 끝나면 감사 진행상황과 시간 등 제반 여건을 감안해 추가질문을 진행하도록 하겠습니다. 만약 시간적 제약으로 인해 준비하신 질의를 미처 다 하지 못하신 위원님께서는 추후 서면질의를 활용해 주시기 바랍니다. 또 위원님들의 질의사항 중 경기연구원장을 비롯한 증인들이 답변이 어려울 경우 실무자가 답변을 해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직ㆍ성명을 분명히 밝히고 답변을 해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그럼 먼저 자료 요청하실 위원님 계십니까? 오지혜 위원님 자료 요청해 주시기 바랍니다. 
</p>
<p><b>○ 오지혜 위원 </b> 오지혜입니다. 업무추진비 유형 및 집행기준과 주말 및 공휴일의 기관운영업무추진비 집행내역을 2018년부터 현재까지 제출해 주시기 바랍니다. 또한 1년 이상 근속자의 퇴직 시에 퇴직금 지급 지연한 경우에 대해서 퇴직일과 퇴직금 지급일, 지연이자 지급일과 지연 사유 등에 대해서도 적어주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 2018년부터 2020년도까지 전년도 이월액 출연금 이월금으로 사용한 행정운영비와 청사관리비의 세부내역을 제출해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 위원장 심규순 </b> 오지혜 위원님 수고하셨습니다. 계속해서 자료 요청하실 위원님 계십니까? 김재균 위원님 자료 요청해 주시기 바랍니다. 
</p>
<p><b>○ 김재균 위원 </b> 경기연구원에 대해서 연봉을 좀 제출해 달라고 그랬더니 그게 개인적으로 저기가 민감하다고 그러니까 임금 책정하는 기준조건이 있을 거예요, 아마. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 김재균 위원 </b> 그 기준조건을 제출해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 김재균 위원님 수고하셨습니다. 계속해서 자료 요청하실 위원님 계십니까? 염종현 위원님.
</p>
<p><b>○ 염종현 위원 </b> 염종현입니다. 가능하면 주시고요. 그렇지 않을 수도 있을 것 같아서. 임금테이블에 관련돼서 타 광역시와 비교분석된 것이 있습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 임금테이블을……. 
</p>
<p><b>○ 염종현 위원 </b> 경기연구원의 임금현황과 대비된 타 광역의 연구기관과의 비교…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 작업할 때는 늘 보면서 작업하지만 표로 작성된 게 있는지는 현재 확인을 해 봐야 되겠습니다. 
</p>
<p><b>○ 염종현 위원 </b> 만약에 전체가 좀 어렵다면 서울ㆍ부산ㆍ인천 정도만 가능하면 비교해서 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다.
</p>
<p><b>○ 염종현 위원 </b> 거기에는 성과연봉 체계도 같이 좀 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 염종현 위원님 수고하셨습니다. 계속해서 원미정 위원님 자료 요청해 주시기 바랍니다. 
</p>
<p><b>○ 원미정 위원 </b> 원미정 위원입니다. 자료 요청하겠습니다. 연구과제 선정위원회가 있다라면 그 위원회 현황하고요. 그다음에 절차, 연구과제를 선정하는 절차 공식적으로 있는 규정이 있다라면 그 규정 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 알겠습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 원미정 위원님 수고하셨습니다. 계속해서 자료 요청하실 위원님 계십니까? 김중식 위원님 자료 요청해 주시기 바랍니다. 
</p>
<p><b>○ 김중식 위원 </b> 공공투자센터 관련해서요, 재정사업평가 5,000만 원 이상 산출내역을 2020년도 치 부탁을 드리고요. 그다음에 특정과제 연구 실행 시 연구진에 대한 사ㆍ보임 현황이 있으면 좀 주세요. 최초에 설계 시에 현황 및 변동내역에 대한 부분을 좀 부탁을 드리고요. 그리고 그거에 관련돼서 특정과제 연구자가 실시한 연구목록별 연구수행계획서 그거하고 근로계약서, 초빙연구원에 대한 근로계약서 내역을 제출해 주시기 바랍니다. 이상입니다. 
</p>
<p><b>○ 위원장 심규순 </b> 김중식 위원님 수고하셨습니다. 자료 요청하실 위원님 안 계십니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  자료 요청은 빠른 시간 내에 제출해 주시기 바랍니다. 자료가 와야 또 질의할 수 있는 부분이 있으니까 빨리 서둘러서 자료 제출해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그럼 먼저 질의하실 위원님, 이영봉 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이영봉 위원 </b> 의정부 출신 이영봉 위원입니다. 원장님, 이번 행정사무감사 준비하시느라 직원분들 고생하셨다는 말씀을 먼저 드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 감사합니다. 
</p>
<p><b>○ 이영봉 위원 </b> 원장님, 경기연구원 의정포럼에 대해서 질의드리겠습니다. 의정포럼은 경기도의회 역량강화 및 의정활동 활성화를 위해서 2007년도 11월 1일에 경기개발연구원 하부조직 및 사무분장규칙 제3조8항에 의정연구센터 분장사무 제2호 및 4호에 따라서 의정포럼을 운영하고 구성하고 있죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 원장님, 최근 2년간 의정포럼 개최 횟수와 주요내용에 대해서 간략하게 말씀을 주시겠습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 자료를 보고 말씀드리겠습니다.
</p>
<p><b>○ 이영봉 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 의정포럼 운영실적을 말씀드리겠습니다. 최근 2018년 6회 제1차 의정포럼, 제2차 의정포럼 등을 포함하여 워크숍, 간담회 등 여섯 번의 경기도의회와 그다음에 속초, 경기연구원 등에서 있었고 2019년에는 4회가 있었습니다. 1차 의정포럼, 2차 의정포럼 이건 루틴하게 하고 있는 거고요. 
</p>
<p style="padding-left:1.2em">  그다음에 행정학회세미나 그다음 의정포럼, 워크숍 등 4회가 있었습니다. 그다음에 올해는 제1차 의정포럼, 제2차 의정포럼, 제3차 의정포럼 등 3회의 포럼이 있었습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 3회 하셨는데 거기에 참석한 인원이 몇 분 정도 되시죠, 횟수마다, 차마다? 1차에 몇 분, 2차에 몇 분, 3차에 몇 분. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 자료를 확인하고 말씀드리겠습니다.
</p>
<p><b>○ 이영봉 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 총 인원이 한 이십여 분 되는데 그중에서 십오 분에서 20명 정도 사이에 참여를 하고 계신다 합니다. 
</p>
<p><b>○ 이영봉 위원 </b> 지금 정확하게 기록된 것은 없네요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 있을 텐데 제가 가지고 있지 않습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 지금 가지고 나오진 않으시고. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 추후에……. 
</p>
<p><b>○ 이영봉 위원 </b> 여기 보면 집행률이 상당히 저조합니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네?
</p>
<p><b>○ 이영봉 위원 </b> 예산의 집행률이 상당히 저조해요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 올해 특별히 좀 그렇습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 올해뿐만 아니라 2018년도도 마찬가지고요. 2019년도도 마찬가지예요. 45%, 56% 그래요. 제가 원장님, 주어진 시간이 그렇게 많지 않아서 몇 가지 좀 지적을 하겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 이영봉 위원 </b> 보면 우리 하부조직 및 사무분장규칙이 있죠, 이거?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 아시는가요, 원장님?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 여기 보면 본 위원이 먼저도 말씀을 드린 것처럼 하부조직 및 사무분장규칙 제3조8항 그리고 연구센터 분장사무 제2호 및 4호에 따라 의정포럼 운영하고 구성한다라고 이렇게 되어 있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 그런데 여기 보면 항이 틀려요. 
</p>
<p style="padding-left:2.4em">    (자료를 들어 보이며)
</p>
<p style="padding-left:1.2em">  제가 이걸 자료를 요구했어요. 원장님, 자료를 요구했는데 아무리 찾아봐도 없는 거예요, 이게. 그 조항이.
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 요청하신 자료 중에? 
</p>
<p><b>○ 이영봉 위원 </b> 네, 그 조항이 없는 거예요. 내용은 있어요. 내용은 어디에 있냐면 2장 조직 및 사무분장 제5조 안에 들어있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.  
</p>
<p><b>○ 이영봉 위원 </b> 이게 지금 52번 개정이 됐더라고요. 최초에 제정된 게 96년도에 제정이 됐고요. 그래서 그럴 수도 있습니다. 그럴 수도 있지만 이게 만약에 대외업무를 담당하는 직원이 바뀌었을 때 어떤 규정으로 적용해서 할 수 있겠습니까? 규정이 이렇게 돼 있으면. 바로잡으셔야 되겠죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그거 잠깐 말씀을 드리면 그거는 직원들이 집행하지 않고 저희 박사급 중에서 한 명이 해 오시고 있는 그런 사항이라서 직원들 선에서 체크가 점검이 좀 부족했었던 사항이 있었던 것 같습니다. 정정하겠습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 그다음에 우리 경기연구원 의정포럼 운영지침 매뉴얼이 있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 보셨습니까, 원장님? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 이영봉 위원 </b> 거기에 보면 경기도에 소재한 대학의 교수님을 선임하기로 돼 있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 이영봉 위원 </b> 2020년도에는 지방에 있는 조선대학교 교수님이 선임이 돼 있어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이영봉 위원 </b> 뭐 이유가 있나요, 특별한? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이게 사실은 보수 책정에 좀 어려움이 있어서 저희들이 경기도 내 교수님들로 하시는데 개중에는 경기도에 계시다가 다른 데로 가셨다든지 또는 경기도를 잘 알고 계시든지 이런 분 중에서 좀 폭넓게 위원으로 임용하였던 것이 사실입니다.
</p>
<p><b>○ 이영봉 위원 </b> 네, 알겠습니다. 그다음에요, 제8조에 소집과 개최가 있어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이영봉 위원 </b> “위원회 소집과 개최는 운영책임자의 건의와 위원장의 결정에 의한다. 다만 이전에 경기연구원 원장의 승인을 얻어야 된다.” 이렇게 돼 있습니다. 이거 좀 문제가 있지 않나요, 문구 자체가? 
