<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 이영봉 위원 </b> 그러면 충분하게 이런 위원회에 대해서 있다라는 보고를 좀 하시는 게 맞지 않을까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 그 점과 관련하여서는 우선 이번 2기 의정포럼과 관련하여 다소간에 말이 있는 것에 대해서 잘 듣고 있었습니다. 매끄럽게 진행되지 못한 점에 대해서 유감의 말씀을 좀 드리고 다만 이게 연구원 내부에만 국한된 건 아니고 여러 분들과 협의하는 과정에서 의사전달이 좀 늦어지고 지체되었던 점이 있어서…….
</p>
<p><b>○ 이영봉 위원 </b> 아니요, 아니요. 원장님, 제가 그 부분에 대한 말씀을 드리는 게 아니고 이 부분이 7월 달에, 7월 10일에 원 구성이 되었는데 새롭게 위원장이 바뀌시고, 그렇죠? 그리고 위원님들도 지금 바뀌는 부분인 9월 6일 날 공문을 보내셨지 않습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 이영봉 위원 </b> 그럼 충분한 그 기간 동안에 업무협의하고 보고를 할 수 있는 그런 시간적인 여유가 있었다는 거예요. 그럼에도 불구하고 그 부분들을 묵인하고 가신 거라고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 사전협의를 하는 과정에 좀 매끄럽지 못해서 기간이 좀 길어졌던 걸로 알고 있습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 그리고 여기에 전반기 위원장님과 부위원장님 하셨던 분이 그대로 후반기에 하시고 또 하나, 기획재정위원회 위원 두 분이 들어가게 돼 있어요, 위원회에. 그렇죠? 맞습니까? 
