<p><b>○ 경기연구원장 이한주 </b> 이거는 그래서 기재위원회에서는 또 한 분이 추가적으로 들어가는 걸로 제가 다시 지시해서 정정하였습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 저는 이 부분에서 잘잘못을 따지기 전에 우리가 기획재정위원회는 경기연구원 산하기관이 하나 있습니다, 그렇죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 그럼에도 불구하고 그런 부분에 대해서 보고 체계가 안 돼 있다는 그런 부분들에 대해서 제가 지적을 하는 거예요. 그리고 이 내용을 보면 운영에 대한 최종적인 부분에 책임을 지는 부분들은 경기연구원 원장님이시잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이영봉 위원 </b> 이 관련해서 향후에 어떻게 조치하겠다라는 부분들을 좀 말씀해 주십시오. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 이 부분 논의가 이미 내부적으로 좀 있었고요. 이 책임을 맡고 있는 담당박사님들하고 대안을 지금 준비 중에 있었고 또 1차 대안보고는 받았습니다. 그래서 다음부터는 의정포럼을 구성할 때 이거를 도의회에 일임해서 의장께서 이거를 구성하는 걸로 이렇게 원칙을 확고하게 잡아두라 이렇게 얘기를 했기 때문에 다음번부터는 좀…….
</p>
<p><b>○ 이영봉 위원 </b> 그리고 또 하나, 방금 자꾸 박사님들 말씀하시는데요. 여기 업무를 하는 건 대외협력부장이에요, 실무 일은. 
