<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 그럼에도 불구하고 박사님들이 가서 이렇게 말씀하시는 게 지금까지 관례였기 때문에 그 말씀을 드리는 겁니다. 
</p>
<p><b>○ 이영봉 위원 </b> 아무튼 원장님, 행정사무감사 조치라든가 개선안에 대해서 그 부분에 대해서 명확하게 정리를 좀 해 주시길 바랍니다. 
