</p>
<p><b>○ 위원장 심규순 </b> 이영봉 위원님 수고하셨습니다. 의정포럼에 대해서 우리 위원회에서도 많은 얘기가 있었고요. 그 대외협력부장이 하는 일이 뭔지 모르겠어요. 대외협력부장이 어떤 대외협력을 하는 건지 저희 위원회에 와서 차 한 잔 안 마셨습니다. 소통 아닙니까? 소통의 장을 연결하는 대외협력부장인데 어디하고 대외협력을 하는지를 모르겠어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원장님. 간단히 말씀…….
</p>
<p><b>○ 위원장 심규순 </b> 그래서 의정포럼까지 이렇게 우리 위원회도 모르고 이번 대에만이 아니고 전반기 때도 기재위 위원님들이 잘 모르고 있었답니다, 참고로. 이렇게 하면 안 됩니다. 이영봉 위원님 적절하게 지적해 주셨습니다. 답변, 저는 됐고요.
