<p><b>○ 위원장 심규순 </b> 계속해서 오지혜 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 오지혜 위원 </b> 오지혜입니다. 일단 참고인분들이 계셔서 관련된 내용을 먼저 질의하고자 합니다. 
