<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오.
</p>
<p><b>○ 오지혜 위원 </b> 무기계약직 처우개선을 위한 연구용역 결과가 지난 4월 중순 마무리된 걸로 알고 있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그래서 아직 자료에 대해서는 협의 중인 사항으로 제출할 수 없다고 자료에 되어 있네요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그거는 원래 용역계약을 맺을 때 내부적으로 이게 외부에 나가서는 곤란해서 위원님들이 요청하시면 열람은 가능한데 그러나 자료가 밖으로 나가는 건 많은 부수가 인쇄되기 때문에 자료에서는 생략하였습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그냥 파일로 주시면 인쇄랑은 상관이 없을 거라고 생각이 되는데요. 자료 이 부분에 대해서 현재 용역결과가 나온 뒤부터 지금까지 무기계약직 처우개선 관련해서 협의 중이라고 하셔서 혹시 몇 차례 협의를 진행했습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 굉장히 많이 했습니다. 무기계약직 보수체계, 그러니까 무기계약직은 2018년 제가 연구원에 왔을 때부터 정규직 전환이 대통령님의 공약이었기 때문에 이 전환을 위해서 3차에 걸쳐서 정규직 전환을 하였고요. 그다음에 3차에 걸칠 때까지도 한 10여 차례 이상의 회의가 있었습니다. 뿐만 아니라……. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 그래서 연구용역 결과가 나온 뒤부터 지금까지 협의에 대한 내용이요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 협의?  
</p>
<p><b>○ 오지혜 위원 </b> 네. 그러니까 연구용역 결과가 나온 뒤부터 자료를 보고 나서 그 자료에 대해서 무기계약직 처우개선을 하기 위해서 어떻게 하겠다라고 서로 협의를 하게 되잖아요. 그래서 그 연구용역 결과가 나온 이후부터 지금까지 협의를 몇 차례 했는지가 궁금합니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 내부적인 협의는 한 20차례 했던 것 같고요. 당사자들 협의, 그러니까 무기계약직과 당사자들과 직접적인 회의 이거는 두 번, 세 번 있었고요. 그다음에 노동조합과는 한……, 제 기억으로는 5차례 이상 협의가 꾸준히 있었던 걸로 기억하고 그동안에 일부 당사자 그다음에 노동조합과 소통은 기록하지 않은 횟수들은 굉장히 많이 있다고 생각합니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그런데 협의가 아직까지도 진행 중인 건가요?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 서로 견해차가 있어서 아직까지 확정하지 못하고 있습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그러면 내부 의견 조율이 전혀 되고 있지 않은 상황인 건가요?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니요. 의견이라는 건 완전히 조율돼서 끝나기 전에는 조율되지 않은 게 맞지 않습니까? 그런 점에서 지금 진행되고 있다 이렇게 말씀드릴 수 있겠습니다.
</p>
<p><b>○ 오지혜 위원 </b> 그러면 어떻게 다르길래 제가 그런가 되게 궁금했거든요. 그런데 실제로 노측의 자료 같은 경우에는 저희가 따로 받아볼 수 있는 상황인 거고요. 사측에서 제시한 자료도 사실상 여기에서는 제출할 수 없다고 써있는데요. 제가 따로 요구한 자료에 의하면 52번 경기연구원 근태 및 급여 관련 자료가 있고요. 그 중에 석사직군 및 행정직군, 무기계약직 향후 개선될 호봉표에 대한 내용이 있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 아마 제출했던 걸로 기억하는데요. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 여기에서는 제출했는데 여기에서는 일단 안 된다고 해서 아마 자료에 대해서 조금 오해가 있었던 것 같습니다. 그래서 그 향후 개선될 호봉표를 제가 받아서 봤는데요. 이 내용과 지금 노측이 제시한 내용과는 많은 차이가 있는 것 같은데요. 가장 큰 차이가 어떤 건지 혹시 원장님께서 말씀해 주실 수 있나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그전에 이 건과 관련해서는 전체적인 개요를 좀 파악하실 필요가 있습니다. 18년도에 무기계약직 정규직 전환을 시도하였고 당시에 아무것도 저희들한테 주어진 게 없었기 때문에 다른 기관의 사례 그다음에 경기도의 다른 사례를 참고해서 저희들이 19년으로 넘어오면서 무기계약직을 정규직으로 전환하였습니다. 당시 시험과 여러 가지 검정절차를 거쳤는데 여러 분이 떨어져서 결국 3차에 걸쳐서 전원을 구제하였습니다. 한 명도 빼지 않고 3차에 걸쳐서 구제하였고 그다음 저희들이 임금과 관련하여서는 무기계약직은 그동안에 매우 단기적으로 그러나 그 단기에서 연장, 연장, 연장해서 여러 해가 가는 그런 상황이었기 때문에 또 임명절차에 관해서도 워낙 단기를 전제로 하고 뽑는 상황이었기 때문에 보수 수준이 상당히 낮았습니다. 그래서 2019년과 2020년에 걸쳐서 다른 직군과는 달리 끊임없이 보수를 인상시켰습니다. 그럼에도 불구하고 워낙 낮은 단계에서 출발했기 때문에, 다소 낮기는 하였기 때문에 이번에 임금체계를 12등급 체계에서 32등급 체계로 바꾸는 데에는 저희들이 주장을 하였고요. 올해도 임금인상이 있었습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 확인했습니다, 2.8% 인상된 것.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 크게 보자면 무기계약직에서 요청하는 거는 본봉의 베이스를 많이 높여달라 이런 뜻입니다, 10% 이상. 그런데 올해 이미 2.8%를 올리고 시작했기 때문에 10% 이상을 올린다는 것은 당장 저희들 혼자만의 할 일은 아니고요. 도하고 협의해야 될 일이라고 생각합니다. 
</p>
<p><b>○ 오지혜 위원 </b> 도 어느 곳과 협의를 해야 되나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 도 저희를 담당하고 있는 비전전략팀하고. 
</p>
<p><b>○ 오지혜 위원 </b> 비전전략팀이요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 오지혜 위원 </b> 구체적으로 어떤 내용의 협의가 필요한 건가요? 그럼 예산을 증액해야 된다거나 아니면 공공기관의 그런 인건비 조정에 대한 문제를 해결해야 되는 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 공공기관의 무기직 전환 부분과 관련하여서는 도가 저희만 있는 게 아니라 27개 공공기관 전체가 다 있습니다, 지금. 그래서 그 부분들에 관한 일반적인 정책을 지금보다 조금 더 수립하여야 되고 그거에 따른 예산수립을 하여야 하며 저희하고 같이 보조를 맞춰서 해 나가게 될 겁니다.
</p>
<p><b>○ 오지혜 위원 </b> 네, 그럼 마지막으로 한 가지만 더 묻겠습니다. 노측에서 제시한 제안을 받아들이지 못하는 이유가 어떤 것일까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네?
</p>
<p><b>○ 오지혜 위원 </b> 노측에서 지금 경영진에 제시한 것 있잖아요? 그 제안 그거를 선뜻 받아들이지 못하는 이유가 궁금합니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 선뜻 받아들이지 못하는 건 아니고요. 선뜻 받아들이고 싶은 마음이 굴뚝같지만요. 그럼에도 불구하고 저희는 예산을 배정받아서 그리고 또 도의 지침을 동시에 배정받아서 사용하는 공공기관입니다. 저희 공공기관이 무조건 1년에 몇 번씩 올려가면서 이렇게 예산을 배정할 수는 없는 노릇이고요. 도하고 협의를 해야만 하는 사항이라고 생각합니다. 
</p>
<p style="padding-left:1.2em">  아울러 또 한 가지 근본적인 차이 중의 하나는 성과연봉과 관련된 얘기인데 이 무기계약직은 저희 기관에 일부 있습니다마는 전체적으로 호봉제로 실시하고 있습니다. 약간의, 매우 약간의 성과연봉제가 들어가 있음에도 불구하고 전체적으로 호봉제인데 우리나라의 추세는 호봉제가 없어지고 성과연봉제로 확대되어 나가는 게 추세입니다. 그 와중에서 이 부분을 거의 다 제 생각으로는 99%의 호봉제를 실시하고 있어서 이거를 완전히 없애자 이런 것들은 받아들이기 좀 어렵습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 지금 제가 다른 걸 질문드리게 됐는데요. 호봉제를 하는 곳 중에서 지금 경기연구원에서 성과연봉에 포함되어 있다고 말씀을 하셨어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 처음 들어가 있다고요? 
</p>
<p><b>○ 오지혜 위원 </b> 성과연봉이 포함되어 있다고 말씀을 하셨어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 있습니다. 그렇게 설계하고 있습니다.
</p>
<p><b>○ 오지혜 위원 </b> 호봉제 지금 하고 계신 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 호봉제. 
</p>
<p><b>○ 오지혜 위원 </b> 네. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이분들은 호봉제…….
</p>
<p><b>○ 오지혜 위원 </b> 진행을 하고 계신 건가요, 지금? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네? 
</p>
<p><b>○ 오지혜 위원 </b> 지금 진행을 하고 계신 건가요, 성과연봉제를 호봉제에다가? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 지금 현재. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 지금 저는 그렇게 이해를 했습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 현재는 12호봉제로만 되어 있어서 12호봉제로 되어 있는데…….
</p>
<p><b>○ 오지혜 위원 </b> 그러니까 지금은 12호봉제가 되어 있고 성과연봉제가 포함되어 있지 않은 상태인 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다. 그러나 그걸 32호봉제로 늘려주면서 여기에 성과요소를 좀 포함시키겠다 이런 뜻입니다.
</p>
<p><b>○ 오지혜 위원 </b> 그렇게 돼 있고요. 지금 실제로 행정직군이 있잖아요? 경기연구원 행정직군 32호봉표, 다른 32호봉표를 적용받는 그 직군은 성과연봉제가 없죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 어디요? 행정직군의……. 아, 행정직 무기계약직이요?
</p>
<p><b>○ 오지혜 위원 </b> 아니요, 그거는 이거 같은 걸로 포함될 것으로 알고 있고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 어떤 말씀이십니까?
</p>
<p><b>○ 오지혜 위원 </b> 그 말고 다른 행정직에 대해서 관리직이라고 표현을 하지요? 관리직이 지금 32호봉제를 적용받는 걸로 알고 있는데요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 32호봉제가 아니고요. 그거는 직급마다 조금씩 다릅니다, 관리직은.
</p>
<p><b>○ 오지혜 위원 </b> 네, 직급마다 다른데요. 관리직은 지금 이런 표 중에 다른 걸로 제가 적용받는 걸로 알고 있고 있거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 관리직 호봉테이블은 따로 있고요. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 호봉테이블이 따로 있고 그런데 그분들도…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 7급부터 시작해서 1급까지 호봉테이블이 다 따로 있습니다.
</p>
<p><b>○ 오지혜 위원 </b> 네, 등급별로 돼 있는 자료를 저도 받아봤습니다. 그분들은 지금 성과연봉을 하지 않고 있는 상태인 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 성과상여금 형태로 지급하고 있습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 네?
</p>
<p><b>○ 경기연구원장 이한주 </b> 성과상여금.
</p>
<p><b>○ 오지혜 위원 </b> 상여금 형태로 진행하고 있습니다. 그래서 제가 느꼈을 때 가장 큰 차이는 지금 여러 가지 수당들이 포함되어 있는 것, 수당이 지금 보수총액에 포함되어 있는 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 오지혜 위원 </b> 그렇지만 그 수당의 종류가 굉장히 많이 다르게 나타나고요. 연봉제랑도…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 어디 말씀하십니까? 관리, 무기계약직? 관리직…….
</p>
<p><b>○ 오지혜 위원 </b> 네, 관리직이랑 굉장히 많이 다르게 나타나고 있습니다. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  그래서 실질적으로 제가 원래 참고인께 질의를 조금 하려고 했었는데요. (위원장을 향하여) 다음 추가질의 때 진행을 해야 될까요?
</p>
<p><b>○ 위원장 심규순 </b> 한꺼번에 질의, 길어요? 
</p>
<p><b>○ 오지혜 위원 </b> 답변하시기에 따라 다른 것 같습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 그럼 추가 설명이 돼서 한 분 같으면 조금 더 드리는데 지금 세 분이라서 다음 추가질의 때…….
</p>
<p><b>○ 염종현 위원 </b> 한 분한테 먼저 하시죠. 
</p>
<p><b>○ 위원장 심규순 </b> 그러실래요? 
</p>
<p><b>○ 오지혜 위원 </b> 위원님들 양해해 주시면 감사하겠습니다.
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p><b>○ 위원장 심규순 </b> 네, 계속 질의해 주시기 바랍니다. 
</p>
<p><b>○ 오지혜 위원 </b> 감사합니다. 그럼 참고인분께 제가 질의를 하도록 하겠습니다. 자리에 앉으셔도 괜찮을까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니요, 위원님들 얼굴 보면서 하죠. 괜찮습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 자리 바꿔주세요. 지명을 해서 나오시라고. 
</p>
<p><b>○ 오지혜 위원 </b> 그럼 내용에 대해서 가장 잘 설명해 주실 분이 나오시는 게 가장 좋을 것 같습니다. 
</p>
<p><b>○ 참고인 이은환 </b> 안녕하세요? 경기연구원 노조위원장 이은환입니다. 
</p>
<p><b>○ 오지혜 위원 </b> 제가 이 내용들을 보고 일단 처우개선을 위한 용역결과가 공개되어 있지는 않아요, 그렇죠? 공개되어 있는 상황은 아니고 노동조합, 그러니까 무기직이 노측에서 제시한 임금테이블이 있고 사측에서 제시한 임금테이블이 있습니다. 가장 큰 차이가 어떤 건지 먼저 말씀해 주시겠어요? 
</p>
<p><b>○ 참고인 이은환 </b> 일단 가장 큰 차이는 둘 다 컨설팅 보고서의 결과에 근거해서 만들어지긴 했는데 컨설팅 보고서를 해석하는 데 있어서 가장 시각 차이가 큽니다. 뭐냐 그러면 첫 번째, 노조가 받아들일 때는 연구보고서의 결과에도 명시가 되어 있듯이 수당은 포함되지 않는 걸로 그렇게 했음에도 불구하고 사측은 모든 수당, 예를 들면 우리가 하지도 않은 초과근무수당 한 달에 15시간, 그러니까 1년으로 치면 180시간이죠. 그런 것까지 다 포함을 해서 그 연봉테이블이 만들어진 거고요. 그리고 저희는 그 컨설팅 보고서에서 얘기하는 대로 수당은 제외해서 만든 게 저희 노측의 테이블입니다.
</p>
<p><b>○ 오지혜 위원 </b> 그러면 노측의 테이블에는 가족수당, 기관성과급, 성과연봉이 포함되어 있나요?  
</p>
<p><b>○ 참고인 이은환 </b> 노측의 테이블에는 보수총액에는 포함이 되어 있고 기본급에는 기본급만 제시를 했습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 초과시간, 초과수당이 15시간씩 하면 약 1등급일 경우에 300만 원 가까이 되네요. 
</p>
<p><b>○ 참고인 이은환 </b> 네, 그 정도로 알고 있습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 추가수당을 안 하면 총액에서 300만 원은 빠지게 되는 거죠?  
</p>
<p><b>○ 참고인 이은환 </b> 네, 맞습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그러면 이 자료만 봤을 때는 굉장히 초과 추정되어 있다고 볼 수 있는 건가요?
</p>
<p><b>○ 참고인 이은환 </b> 네, 그렇게 판단하고 있습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그리고 지금 노측과 사측의 가장 큰 이견이 어떤 건가요? 협의를 하는 데 있어서 가장 어려운 점이 어떤 건가요?  
</p>
<p><b>○ 참고인 이은환 </b> 일단은 저희가 최종협상, 가장 최근에 했던 협상 중에서는 우리도 양보를 하겠다. 그러니 좀 한발 서로 양보를 해서 합의점을 찾아보자고 제안을 했고요. 그 이후로 사측에서 또 저희에게 보내온 자료가 있는데 일단 그게 월급이 한 1만 원에서 3만 원 정도 개선된 그런 자료를 보내왔는데 이게 저희가 생각하던 수준과는 너무나 동떨어져 있어서 지금 그런 부분의 접점을 찾지 못하는 게 가장 큰 힘든 점이고요. 그런데 저희가 1년 동안 사실은 정말 많은 협상을 해 왔습니다, 협의를 해 왔습니다. 그래서 결국 협의의 결론이 뭐냐 그러면 ‘아, 예산이 없구나, 우리가.’ 원장님도 아까 전에 그렇게 말씀을 해 주셔서 너무나 감사한 마음을 가지고 있는데 우리 무기직들의 처우가 너무 안 좋습니다. 우리 경기도 내 공공기관에서 다른 무기직들 시설, 경비, 미화 그런 분들보다 월급이 적고요. 우리가 1,300만 인구에 대한 삶의 질 연구를 하고 있는데 자긍심이 생길 정도의, 그 정도의 급여 수준이 안 됩니다. 예를 들면 서울연구원의 한 70% 정도 수준이고요. 인천연구원의 한 80% 정도 수준이고 그런 상황입니다. 그래서 말씀드렸듯이 우리가 처우개선이 필요하다는 거에 대해서 노사가 이견이 없거든요. 그런데 결국에는 스무 차례 가까이 해온 협상에서 결론은 예산이 없구나. 우리가 도에 가서 그리고 위원님들께 한번 부탁을 해 보자, 그런 지금 처한 상황입니다.
</p>
<p><b>○ 오지혜 위원 </b> 인천연구원, 서울연구원과 비교를 할 때는 항상 기본급인가요? 
</p>
<p><b>○ 참고인 이은환 </b> 기본급을 비교한 것입니다. 
</p>
<p><b>○ 오지혜 위원 </b> 기본급을 기준으로 비교를 하신 거죠, 지금? 
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 오지혜 위원 </b> 기본급을 비교로 해 주셨다고 꼭 말씀을 해 주셔야 될 것 같아요, 각종 수당들이 포함되어 있기 때문에, 비교자료에는. 그 자료들만 본다고 하면 실질적으로 어떤 상황에서는 높게 책정이 될 수도 있거든요. 그래서 그런 거에 대해서는 꼭 그렇게 명시를 해 주시기 부탁드립니다. 
</p>
<p><b>○ 참고인 이은환 </b> 네, 알겠습니다. 
</p>
<p><b>○ 오지혜 위원 </b> 그러면 일단 예산적인 문제가 가장 컸다고 말씀을 해 주시는 거죠?  
</p>
<p><b>○ 참고인 이은환 </b> 네. 
</p>
<p><b>○ 오지혜 위원 </b> 네, 알겠습니다. 그럼 혹시 다른 말씀하실 거 또 있으신가요? 굉장히 짧게 부탁드립니다. 
</p>
<p><b>○ 참고인 이은환 </b> 도와주십시오. 그러면 저희들 진짜 열심히 일하겠습니다. 감사합니다.
</p>
<p><b>○ 오지혜 위원 </b> 감사합니다. 위원님들 양해해 주셔서 감사합니다.
</p>
<p><b>○ 위원장 심규순 </b> 오지혜 위원님 수고하셨습니다. 잠깐만 계세요. 이은환 노조위원장 님, 간략하게 좀 답변, 잠깐만요. 지금 업무분장하고 근무시간이 몇 시간인지 간략하게대답해 줄 수 있어요? 업무분장…….
</p>
<p><b>○ 참고인 이은환 </b> 저희 업무분장이요?
</p>
<p><b>○ 위원장 심규순 </b> 네.
</p>
<p><b>○ 참고인 이은환 </b> 보건의료정책을 연구하고 있고요.
</p>
<p><b>○ 위원장 심규순 </b> 지금 현재 하고 있습니까? 
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 위원장 심규순 </b> 노조위원장님도 지금 연구를 하고 있습니까?
</p>
<p><b>○ 참고인 이은환 </b> 연구도 같이 하고 있습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 근무시간은요?
</p>
<p><b>○ 참고인 이은환 </b> 근무시간은 9시에 시작해서 6시에 끝납니다.
</p>
<p><b>○ 위원장 심규순 </b> 대부분이 거의 노동위원장님 같은 경우는 경기연구원이 아닌 대부분 일을 안 하거든요. 노조원들 관리를 하고. 
</p>
<p><b>○ 참고인 이은환 </b> 저희도 그래서 시간 면제를 일부 받고는 있습니다.
</p>
<p><b>○ 위원장 심규순 </b> 몇 시간 받고 있죠?  
</p>
<p><b>○ 참고인 이은환 </b> 총 전체 6명의 간부에 대해서 총 3,000시간을 받고 있는데요.  
</p>
<p><b>○ 위원장 심규순 </b> 아니, 위원장님만. 위원장님만 몇 시간 면제받고 있죠? 
</p>
<p><b>○ 참고인 이은환 </b> 저는 한 1,000시간 정도 아마 됐던 것 같습니다.
</p>
<p><b>○ 위원장 심규순 </b> 몇 년에, 1년에요?
</p>
<p><b>○ 참고인 이은환 </b> 네, 1년에요.
</p>
<p><b>○ 위원장 심규순 </b> 1년에 1,000시간이나 받고 있어요? 
</p>
<p><b>○ 참고인 이은환 </b> 네, 그 정도 받고 있습니다.
</p>
<p><b>○ 위원장 심규순 </b> 그럼 근무를 안 한다는 거잖아요.
</p>
<p><b>○ 참고인 이은환 </b> 자료 프린트해서…….
</p>
<p><b>○ 위원장 심규순 </b> 아니, 아니, 그거 알죠. 그거 나누면 알죠.
</p>
<p><b>○ 참고인 이은환 </b> 이게 저희가 출근시간, 퇴근시간으로 보면 9시에서 6시가 제 하루거든요. 그런데 실제로 출퇴근 시간으로 연구를 수행하러 가는데 출퇴근 시간으로 사실 나누기가 되게 애매하긴 하거든요. 
</p>
<p><b>○ 위원장 심규순 </b> 출퇴근 시간 말고 안에서 근무하는 시간을 보통 근무시간이라고 그러잖아요.
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 위원장 심규순 </b> 그렇죠? 출퇴근 시간 다 빼잖아요. 일반인들도, 공무원들도 다 그러잖아, 회사원도 그렇고요. 그래서 그 시간을 1,000시간을 면제를 받는다는 거죠?
</p>
<p><b>○ 참고인 이은환 </b> 공식적으로는 그렇게 받고 있습니다.
</p>
<p><b>○ 위원장 심규순 </b> 네, 알았습니다. 참고하겠습니다. 수고하셨습니다. 
</p>
<p><b>○ 염종현 위원 </b> 위원장님, 참고인께서 지금 계속 계시면 제가 나중에 질의를 하고 가실 거면…….   
</p>
<p><b>○ 위원장 심규순 </b> 염종현 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 염종현 위원 </b> 양해해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  이거 잠깐 질문하고 질의는 맨 후에 좀 하도록 하겠습니다. 참고인 나오셔서 관련해서 제가 몇 가지 여쭤볼 텐데요. 저희가 정규직 전환위원회를 통해서 지금 무기계약직으로 다 되신 거지 않습니까? 
</p>
<p><b>○ 참고인 이은환 </b> 네. 
</p>
<p><b>○ 염종현 위원 </b> 그런데 지금 우리 원장님께서 말씀하셨고 그 다음에 노조위원장께서 말씀하신 게 “예산의 문제다.” 이렇게 두 분이 공히 말씀을 하셨는데 저는 그렇게 생각하지 않습니다. 이것이 궁극적으로 노와 사의 어떤 협의의 문제이고 그것이 저희가 예산을 증액해서 그 부분을 보완할 수도 있는데 그러기 위해서는 이것이 대단히 합리적이다라는 것이 전제가 돼야 된다고 생각합니다. 그래서 관련해서 좀 여쭤볼게요. 
</p>
<p style="padding-left:1.2em">  지금 서울과 인천을 비교하셨는데 저희가 총, 그로스(Gross) 기본급과 연봉을 다 포함해서 경기도와 서울, 인천의 비교가 어떻게 됩니까? 기본급 플러스 수당 다 포함해서 비교된 게 좀 있지 않겠어요? 제가 자료는 요청했는데 아까 서울의 70여 %, 인천의 80 몇 %라 그랬는데 전체를 포함했을 때 비교가 좀 어떻게 되나요?  
</p>
<p><b>○ 참고인 이은환 </b> 저희가 노조에서 파악한 자료를 보면 서울연구원, 인천연구원, 충남연구원, 대구경북연구원, 울산연구원, 경기연구원……. 
</p>
<p><b>○ 염종현 위원 </b> 전체 말고 서울이랑 경기만 일단 한번 비교해 보시죠. 기본급 플러스 수당 다 포함한 총 연봉의 비교. 
</p>
<p><b>○ 참고인 이은환 </b> 거기까지는 저희가 자료취득이 안 됐고요. 저희가 이제…….
</p>
<p><b>○ 염종현 위원 </b> 그러면 저희가 지금 노조위원장님께서 말씀하시는 게 합리적으로 저희 위원들이 이해하기 위해서는 단순히 수당을 뺀, 기본급만을 비교한 걸로써는 그건 좀 이해하기 쉽지가 않고요. 전체 총 연봉을 대비해서 비교가 돼야지 저희가 이해하기가 쉽다. 그래서 연봉, 그러니까 수당을 빼고 기본급만으로 비교해서 서울이나 인천보다 현저히 적은 듯한 것은 그것은 다시 한번 살펴볼 필요가 있다 이렇게 생각이 들어서 제가 좀 말씀을 드린 거고요. 
</p>
<p style="padding-left:1.2em">  그 다음에 전환위원회를 했을 때 우리가 무기계약직으로 전환될 때 임금테이블에 대한 논의는 없었습니까? 저는 이 부분에 대해서 전혀 지금 백지상태에서, 모르는 상태에서 제가 여쭤보는 거예요. 들은 바도 없고. 
</p>
<p><b>○ 참고인 이은환 </b> 그 부분은…….  
</p>
<p><b>○ 염종현 위원 </b> 그러니까 계약직에서 무기계약직으로 전환될 때 임금체계에 대해서 논의를 한 게 없냐는 얘기죠. 
</p>
<p><b>○ 참고인 이은환 </b> 그 부분은 혹시 전환위원회에 계셨던 우리 부위원장님이 계시는데 요. 
</p>
<p><b>○ 염종현 위원 </b> 간단히 있었다, 없었다라고 얘기하시면 되죠. 
</p>
<p><b>○ 참고인 이은환 </b> 일단 32단계 확정에 대해서는 공공연하게 계속 얘기가 있었던 걸로 그렇게 알고 있습니다. 
</p>
<p><b>○ 염종현 위원 </b> 전환할 때?  
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 염종현 위원 </b> 그러니까 전환할 때 전환위원회에서 양자가 계약에서 무기계약직으로 전환하는 논의를 할 때 임금에 대한 논의가 있었다? 
</p>
<p><b>○ 참고인 이은환 </b> 네, 그렇게 알고 있습니다. 
</p>
<p><b>○ 염종현 위원 </b> 임금에 대한 논의가 있었다. 그럼 그때는 일단 무기계약직 전환이 더 중요했기 때문에 이것부터 정리를 하고 그 다음 2단계로 임금에 대한 논의를 하기로 양자가 합의를 한 건가요, 아니면 동시에 무기계약직으로 전환을 할 때 임금문제도 동시에 타결을 한 건가요?
</p>
<p><b>○ 참고인 이은환 </b> 그 당시에 우선순위는 전환에 우선순위가 있었던 것 같고요. 
</p>
<p><b>○ 염종현 위원 </b> 타결을 할 당시에 어떤 논의가 있었을 거 아니에요, 양자 노사가. 
</p>
<p><b>○ 참고인 이은환 </b> 네, 그래서 추후에 바로 또, 처우개선에 대해서는 추후에 논의한다라고……. 
</p>
<p><b>○ 염종현 위원 </b> 추후에 논의한다라고 돼 있었다?
</p>
<p><b>○ 참고인 이은환 </b> 그렇게 얘기가 됐던 걸로 알고 있습니다. 
</p>
<p><b>○ 염종현 위원 </b> 하여튼 그게 좀 궁금했었고요. 그 다음에 또 나오신 김에 성과연봉에 대해서, 노조에서 지금 성과연봉에 대해서 과하다 이렇게 주장하는 바가 있나요, 현재?  
</p>
<p><b>○ 참고인 이은환 </b> 네, 일단 성과연봉과 인센티브, 성과급은 굉장히 큰 차이가 있는데요. 
</p>
<p><b>○ 염종현 위원 </b> 그러니까 지금 제가 확인한 바로는 0%에서 200%였던 것을 50%에서 150%로 바꿨죠. 
</p>
<p><b>○ 참고인 이은환 </b> 2018년도에, 네.
</p>
<p><b>○ 염종현 위원 </b> 그 상태도 지금 그거보다 더 조정을 해야 된다, 이런 입장을 갖고 계신 건가요?  
</p>
<p><b>○ 참고인 이은환 </b> 네, 그렇게 생각하고 있습니다. 일단…….
</p>
<p><b>○ 염종현 위원 </b> 그러면 제가 참고로 2019년도에 서울연구원의 행감 사항을 제가 한번 좀 봤었습니다. 그래서 서울연구원 같은 경우가 제로에서 200%에 있다가 거기는 나눴더라고요. 박사급은 20 대 180 그다음에 석사급은 50 대 150. 그거 확인되신 건가요, 서울연구원? 
</p>
<p><b>○ 참고인 이은환 </b> 알고 있습니다. 
</p>
<p><b>○ 염종현 위원 </b> 알고 계신가요?
</p>
<p><b>○ 참고인 이은환 </b> 그런데 가장 큰 차이가 그래서 제가 초두에 말씀드린 게…….  
</p>
<p><b>○ 염종현 위원 </b> 이거까지만 제가 듣고 질의마치도록 하겠습니다. 그 얘기를 좀 해 주세요.
</p>
<p><b>○ 참고인 이은환 </b> 그래서 제가 초두에 말씀드린 게 성과급과 성과연봉의 차이를 사실 잘 모르시는 분들이 또 많이 계십니다. 성과연봉이라는 건 처음에 제 연봉이 1,000만 원이다. 그러면 거기서 몇 %를 떼서 그거 가지고 경쟁을 시켜서 나눠주는 게 성과연봉이라는 거고요. 서울연구원처럼 인센티브는 연봉이 있고 평가에 따라서 성과급을 더해 주는 거거든요. 그래서 그게 가장 큰 차이입니다, 저희랑.
</p>
<p><b>○ 염종현 위원 </b> 그런데 우리가 예산을 볼 때나 저는 확인차 얘기를 하는 거예요. 예산을 볼 때나 성과연봉, 그러니까 연봉을 계약을 할 때 그걸 보면 기본연봉에서 20%를 떼어서 성과연봉으로 나눠준다, 이런 거는 있지 않지 않습니까? 
</p>
<p><b>○ 참고인 이은환 </b> 그렇죠, 규정상에는. 
</p>
<p><b>○ 염종현 위원 </b> 그럼 그걸 그렇게 단언해서 총 연봉에서 20%를 떼어서 성과연봉을 준다 이렇게 단언해서 얘기하는 것도 괜찮은 건가요? 자, 저는 여기까지 일단 질의를 하겠습니다. 그 답변 나중에 주시기 바랍니다. 이상입니다. 확인차 좀 질의를 했습니다. 
</p>
<p><b>○ 위원장 심규순 </b> 염종현 위원님 수고하셨습니다. 우리 노동위원장님, 여러 가지 우리 위원회하고 소통하는 걸로 알고 있습니다. 여러 가지 애로점은 우리 예산 다룰 때 또 다시 다루기로 하겠습니다. 힘내십시오, 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  계속해서 이필근 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 수원 출신 이필근 위원입니다. 아까 연봉 얘기 나와서 제가 그냥 그것부터 먼저 시작을 하겠습니다. 제가 27개 공공기관에 대한 임직원 연봉과 직원 평균연봉을 집행부에서 자료를 받았어요, 2019년도. 임원들의 평균연봉이 제일 많은 데가 킨텍스입니다, 1억 6,500만 원. 그다음에 경기도의료원이 1억 5,500만 원. 세 번째가 경기연구원이 1억 4,200만 원입니다. 그다음에 직원 평균연봉이 제일 많은 데가 경기연구원이에요, 8,268만 원. 물론 박사들이 많고 직원구조상 박사들이 많기 때문에 연봉이 많다고 생각이 됩니다. 도시공사나 그다음에 킨텍스, 신용보증재단도 많아요. 그래서 왜 많냐고 그러니까 그런 데는 자기들이 경영을 해 가지고 수익 버는 게 많기 때문에 애당초 이렇게 많다고 그러더라고요. 공무원 들어오는데 100 대 1입니다. 그런데 산하단체 들어온 데는 100대는 안 되고 한 20~30대 되는 걸로 알고 있어요. 그런데 공무원 연봉이 얼만지 아세요, 연봉이? 최저임금보다 조금 많아요, 9급 초임이. 지금 산하단체보다는 훨씬 적습니다. 그 점을 이해를 좀 해 줬으면 좋겠어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저도 잘 알고 있습니다. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 100 대 1로 들어오면, 그러니까 물론 그런 사명감 그런 것도 있겠지만 너무 이런 연봉 갖고 따지면 우리 공무원들, 집행부에 있는 사람들이요, 정말 일할 기분 하나도 안 납니다. 그렇게 말씀드리고 다른 거 질문하겠습니다. 
</p>
<p style="padding-left:1.2em">  경기연구원이, 경기도가 1,000년이 된 거 아시죠?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 2018년 1월 4일 날 제9대 경기도의회에서 경기도민의 날 조례를 해 가지고 1,000년의 역사를 이뤘습니다. 고려와 조선시대를 거쳐서 경기도가 우리나라의 중추도시로 됐고 여기서 실학과 실사구시가 돼 가지고 이거의 대표적인 게 성호 이익선생이나 다산이 경기도 사람이라 실학이 경기도의 어떤 정체성이라고 생각이 됩니다. 우리 이재명 지사님 와 가지고 캐치프레이즈가 ‘공정한 세상, 새로운 경기도’라고 그랬는데 이게 경기연구원에서 혹시 제안을 해 가지고 내놓은 건가요?  
</p>
