<p><b>○ 이필근(수원3) 위원 </b> 다산의 정신을 두 가지로 얘기할 수 있는데 공렴입니다. 공정과 청렴을 말하는 건데 지사님의 어떤 정책슬로건하고 다산의 어떤 정신하고 딱 맞더라고요, 공정한 세상. 그러면 이 공정한 세상, 이 공렴. 이걸 위해서 경기연구원에서 체계적으로 실학이나 실사구시에 대해서 그런 분야별로 연구한 실적이 있는지 또 그럴 부서가 있는지 좀 묻고 싶습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 송구합니다. 위원님 말씀 다 맞으시고요. 실학자의 대부분이 경기도 출신이고 경기도지사도 실사구시, 청렴ㆍ공정 이런 거에 대해서 매우 강조하고 계신 분이라고 알고 있습니다. 그런 점에서 다산이나 실학연구가 경기도에서 집중적으로 이루어져야 된다는 거에 대해서 100% 동의하고 있습니다. 다만 다산연구를 저희 연구원에서는 그동안에 연구원 제가 왔을 때 57명 지금 현재 68명인데 너무나 많은 저희들이 과제를 담당해야 되기 때문에 지금도 광범위한 외부연구원과 초빙연구원을 사용하고 있는 상황 속에서 그 부분에 대한 연구는 문화재단한테 미뤄놓고 저희는 그 부분에 대한 연구는 좀 제외하고 있었습니다. 
</p>
<p><b>○ 이필근(수원3) 위원 </b> 다산연구소가 16년 동안 서울에 있다가 작년에 제가 듣기로는 경기도에서 이렇게 해 가지고 지금 문화재단 9층에 와 있죠?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 이필근(수원3) 위원 </b> 그러면 다산연구소는 인문학 사상을 연구하는 겁니다. 문화재단하고 뭐 관계있어요? 사실은 경기연구원하고 더 관계있는 거 아닙니까? 경기연구원이 경기도의 정체성을 연구하고 그런 데가 지사님의 싱크탱크로서 어떤 그런 걸 주는데 아니, 다산연구소가 문화, 그것도 문화가 될 수 있지만 제가 알기로는 만일 그게 부설연구소가 된다면 경기연구원의 부설연구소, 경기연구원에서 같이 가야 된다고 저는 생각되는데 원장님 의견은 어떠신지요? 
