<p><b>○ 이제영 위원 </b> 성남 출신 이제영 위원입니다. 노조위원장님께서 끝까지 안 계시고 먼저 자리 이석하는 것 때문에 그러신 거죠, 위원장님? 위원장님, 잠깐 앞으로 나와 주시겠습니까? 몇 가지 질의드리겠습니다. 경기연구원에서 효율적인 연구원 운영을 위한 경기연구원 보수체계 개편연구를 용역을 줘서 한 거에 대해서 알고 계시죠?
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 제가 그 내용을 쭉 보니까 근속연수를 보니까 5년 미만이 굉장히 비율이 높아요, 그런데 거기에 대해서 무기직의 비율이. 그 이유가 뭘까 생각해 보면 근무조건이 좋으면 굳이 이직할 이유가 없다라고 생각하거든요. 그래서 여기 설문조항에 보니까 현재 임금수준에 만족하고 있느냐 이렇게 질문했을 때 91.5%가 부정적으로 답변한 게 나와 있어요. 그렇다라고 하면 임금체계에 대해서 지금 많은 위원님들께서 임금이 높다, 낮다 여러 가지 의견을 제시하셨는데 실제 무기직 당사자들은 다 매우 여기에 대해서 불만이 있다라고 생각하는데 여기에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 참고인 이은환 </b> 거기 설문조사에도 당연히 객관적인 자료니까요. 보시듯이 일단은 저희 무기직들이 느끼기에도 다른 어디 유사 동종기관과 비교를 했을 때도 너무나 지금 열악하다. 이거는 뭐 여기 계신 원장님도 인정하시는 바이고요. 그래서 많이 열악하다라고 말씀드리고 싶습니다.
</p>
<p><b>○ 이제영 위원 </b> 또 하나는 연구직도 어떻게 보면 창의적인 업무라고 생각을 하는데 창의적으로 일할 수 있는 그런 근무조건이 되고 있는지, 자율성이라든가 물론 어떻게 보면 공무원은 아니죠, 거기가 경기연구원이. 일반 사기업에서처럼 어떤 창의성을 중시하고 개인을 존중하면서 어떤 연구성과에만 매진할 수 있도록 할 수는 없을 거예요, 공공기관이기 때문에. 그런 부분에서 창의성 있게 일할 수 있는 그런 근무 분위기는 되고 있다라고 생각하십니까? 
</p>
<p><b>○ 참고인 이은환 </b> 아까 전에도 일부 말씀드린 바가 있는데요. 진짜 자긍심을 가지고 일을 했으면 좋겠다라는 게 저의 바람입니다. 아까 좋은 지적하신 것 중에 하나가 무기직들의 이직률이 참 높……. 그전엔 더 높았고요. 지금도 사실은 이직에 대한 그리고 직무에 대한 만족도는 굉장히 낮은데 그게 다 처우하고 연결돼 있고 거고 곧 그게 양질의 연구결과 그리고 양질의 인력을 유지할 수 있는 것과 바로 직결되어 있는 문제라고 그렇게 생각합니다. 비용이 아니라 향후 더 먼 미래를 보는 투자라고 생각을 하셔야지 더 좋은 양질의 사람들이 더 들어올 거고요. 그리고 내가 진짜 이거 받고 다른 데서 일하면 더 좋은데 하고 그런 실력 있는 사람들이 나가지 않게 하기 위해서도 그건 투자라고 봐야 하지 않을까 저는 그렇게 생각을 하고 있습니다. 
</p>
<p><b>○ 이제영 위원 </b> 본 위원도 장기간 근무했다고 해서 전문성이나 숙련도가 높게 연구를 한다라고 생각진 않거든요. 기간이 짧은 분도 역량을 더 발휘할 수 있고 오래 근무한 분이 전문성이나 경험 가지고 잘하는 경우 있을 수 있는데 모두가 다 그렇지는 않다라고 생각합니다. 그런 면에 있어서 최소한 무기직 석사분들이 근무하면서 자부심 정도는 아니더라도 그래도 뭐 어느 정도 거기 내가 이 연구원에 정말 열심히 할 수 있는 그런 어떤 본인이 느끼는 만족도가 있어야 되는데 이 설문조사를 보면 굉장히 심각하게 나타나 있고. 
</p>
<p style="padding-left:1.2em">  또 하나는 무기계약직의 임금 및 직무 관련 제도에서 무기직 임금의 숙련도 차이, 업무능력 차이가 반영되느냐. 81.4%가 반영이 되지 않는다라고 얘기하고 있어요. 그럼 이것도 마찬가지로 거기에 근무하면서 이분들이 어떤 자긍심하고는 동떨어진 이런 여건이 아닌가 생각이 들고. 또 무기직 임금이 업무내용과 난이도 차이가 반영되어야 하느냐에 대해서는 긍정이 75.4%예요. 그럼 여기 기타 시간관계상 다 예시를 들 수가 없는데 이 용역결과를 보면 이게 드러나 있거든요. 물론 지금 그게 우리 원장님과 노조 측과의 조그만 차이가 있을 수 있어요. 그렇지만 대전제로 봤을 때 연구원들의 사기가 진작이 돼야 좋은 연구성과를 나타낼 수 있다라고 봅니다. 그렇다라고 하면 뭔가 이거를 빨리 해결하셔야지 이게 안 되고 지속적으로 원장님은 원장님 입장에서의 의견을 제시하시고 노조는 노조 측에서 의견을 제시하고 이렇게 평행선을 긋고 간다라고 하면 결국에는 연구성과가 좋게 나타날 수가 없다. 이건 아마 모두가 공감할 겁니다. 
</p>
<p style="padding-left:1.2em">  그래서 이걸 해를 넘기지 말고 올해 안에 빨리 이거를 우리 원장님하고 노조 측하고 타결을 해서 내년부터는, 아까 우리 원장님께서 여기 2021년도에는 어떻게 하겠다라는 아주 원대한 내용이 담겨져 있어요. 그럼 직원들의 사기가 진작이 돼야 가능한 것이지 결국에는 내부의 불만이 많고 임금이 적다, 여러 가지 또 어떤 처우에 관한 문제 이런 거에 대해 불만이 쌓이게 되면 결국 일은 피동적으로 할 수밖에 없다. 이런 면에서 우리 원장님과 노조 측에서 금년 안에 이걸 빨리 마무리했으면 좋겠다는 말씀을 제가 원장님한테 한번 드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저도 잠깐 말씀드려도 될까요? 
</p>
<p><b>○ 이제영 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 좋습니다. 아까 이필근 위원님께서 말씀하신 건 제가 19년 기준으로 말씀드렸고요. 20년 기준으로 해서는 무기계약직 평균급여가 4,000만 원이고요. 
</p>
<p><b>○ 이제영 위원 </b> (참고인을 향하여) 위원장님은 들어가셔도 되겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 4,000만 원이라서 그다음에 새로 저희들이 계산한, 호봉제를 새로 계산하면 4,125만 원 정도로서 총액급여로 봤을 때는 기본급으로는 서로 다 틀리니까, 수당이 뭐가 들어가서. 총액급여도 봤을 때는 4,000이 넘는다는 말씀을 드리고요. 그다음에 아까 이직률은 저희 무기계약직이 예전에는 단기직으로 들어왔었기 때문에 당연히 높고요. 지금은 무기직 전환이 돼서 이직률이 저희 연구원의 각 구성 직군 중에서 제일 적습니다. 그래서 3% 정도가 되어 있어서 이거는 평균 이직률보다 훨씬 낮은 그런 상황, 오히려 관리직이 15%로써 굉장히 높습니다. 
</p>
<p style="padding-left:1.2em">  그다음에 아까 말씀하신 대로 그럼에도 불구하고 우리 석사연구원들이 무기직 전환되면서 보수인상에 대한 욕구라든가 기대가 굉장히 높았던 거는 사실입니다. 그러나 생각해 보면 작년에 무기계약직이 정규직 전환이 되었습니다. 그다음에 최근 3년 사이에, 18년, 19년, 20년 사이에 무기계약직은 임금인상률이 18.3%입니다. 다른 직군들은 관리직이 7.8%고, 3년 동안에. 그다음에 연구직은 없습니다. 그래서 무기계약직의 절대액이 부족한 거는 위원님 말씀이 맞습니다. 또 기대가 큰 만큼 실망도 컸을 게 사실이고요. 그러나 차근차근해 나가는 과정에 있다는 말씀드리고 싶습니다. 저희들이 12단계 호봉체계를 32단계로 바꾸었고 또 직급도 4개의 승진 직군으로 다시 바꾸어서 처리하고 있습니다. 여기에서 지금 기본급을 다시 10% 정도 더 올려달라 하는 얘기는 총 한 30%에 가까운 3년 사이의 급여 인상을 얘기하는 겁니다. 물론 하면 좋겠습니다. 30% 이상으로 되고 많이 올렸으면 좋겠습니다마는 그러나 저희가 위원님 여러분들이 주시는 돈 내에서 또 여러 가지 성과, 그리고 이 연구직은 연구보조직입니다. 연구를 주관적으로 설계하고 하는 게 아니라 박사들이 연구를 할 때 연구를 보조하는 직이었는데, 지금까지는. 제가 이번에 하면서 연구를 일정하게 할 수 있는 길도 터놓고 있습니다, 본인이 원한다면. 또 오랜 연구직들의 바람이었고요. 자기들도 할 수 있기 때문에 하게 해 달라라고 했고요. 또 어떤 연구직은 자기들은 연구를 하는 것보다는 행정을 하고 싶다, 연구행정을. 그래서 그렇게 이원화도 했습니다. 
</p>
<p style="padding-left:1.2em">  해서 이 부분들은 차근차근해 나갈 일이지 한 번에 모든 거를 다 할 수 있다고는 생각하지 않습니다. 다만 위원님들께서 급여를 충분히 주시고 하시면 경기도하고 협의해서 할 수 있으면 저로서야 그보다 더 좋은 일이 어디 있겠습니까? 다만 하시는 김에 우리 관리직도 좀 챙겨주시고 그래서 퇴직하는 사람들 줄여주시고 그래서 전체적으로 급여 인상을 해 주시면 감사하겠습니다. 
</p>
<p><b>○ 이제영 위원 </b> 원장이 답변을 저의 질문보다 워낙에 길게 하셔서……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 죄송합니다.
</p>
<p><b>○ 이제영 위원 </b> 그러다 보면 이게 시간이 다 소비돼 가지고 그래서 제가 사실은 위원장님 간다 해서 질문드린 거고 다른 거 질문할 거는 그렇게 길게 답변 못 하시도록 제가 따로 한 게 있어요. 지금 말씀하신 것 중에 제가……. (위원장을 향하여) 조금만 더 쓰겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 죄송합니다.
</p>
<p><b>○ 이제영 위원 </b> 지금 관리직이 아까 이직률이 높다라고 말씀하셨는데 제가 용역결과를 보고 말씀드린 거예요. 연구원 같은 경우가 5년 미만이 71.7%이고 관리직 같은 경우가 40.0%예요, 여기 이게. 제 얘기가 아니라 용역 준 결과를 갖고 얘기한 거거든요. 
</p>
<p style="padding-left:1.2em">  자, 그러면 여기에서 아까 다른 위원님들도 얘기했지만 관리직 그러면 박사님들 연봉이 얼마냐 그러면 뭐 8,000 정도 된다. 그러면 그걸 가지고 많다 적다 얘기하신 분은 없었어요. 그런데 무기계약직의 지금 처우가 열악하고 이분들이 근무할 수 있는 어떤 자긍심이 없다. 이런 문제가 노조에서 제기되고 거기에 공감하는 위원님도 계시고 그렇지 않은 위원님도 있었거든요. 그리고 원장님께서도 그동안에 많은 노력을 해 왔다라고 얘기를 했잖습니까? 그리고 이 용역을 줘서 이 결과는 누구보다 잘 알고 계실 거 아닙니까? 용역 주는 이유가 결국에는 이것을 해결하기 위한 방안을 찾아내기 위한 하나의 방편인 거 아니겠습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 그럼 여기에 답이 있어서 제가 이거 위해서 원장님한테 말씀을 드리는 거지 제 개인의 강요에 의해서 하라고 얘기한 게 아닙니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 잘 알고 있고요. 
</p>
<p><b>○ 이제영 위원 </b> 그런데 이걸 꼭 참고하셔서, 그리고 의지만 있으시면…….  
</p>
<p><b>○ 경기연구원장 이한주 </b> 그리고 용역의 한 80% 정도는 저희가 했습니다. 
</p>
<p><b>○ 이제영 위원 </b> 그리고 아까 의회에서 의원들이 예산을 세워주면 한다라고 얘기했는데 그 말씀은, 제가 알기로 원장님께서는 이 지사님하고 성남에 계실 때부터 인연이 돼 있고 나름대로 또 지금 연구원에서 큰 역할을 하고 계시기 때문에 굉장히 신뢰받고 있다 저는 이렇게 인정하고 있거든요. 원장님 능력에 대해서도 저도 인정하고 있고. 그렇다라고 하면 의회 의원들이 예산 세워서 해 주면 못 할 사람이 누가 있습니까? 그건 누구나 다 할 수 있죠. 원장님의 뭔가 역량을 발휘해서 해 줘야 아마 노조원들도 ‘아, 우리 원장님이 정말 우리를 위해서 열심히 했다.’라고 하면 아마 일하지 말라 그래도 죽기 살기로 할 겁니다. 그런 모습을 보여주십사 하는 것을 제가 말씀드린 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 고맙습니다. 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 이제영 위원 </b> 네. 이상 여기 질문 마치고요. 나머지는, 제가 준비한 거는 보충질의 때 하도록 하겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 심규순 </b> 이제영 위원님 수고하셨습니다. 지금 이은환 연구위원, 강철구 선임연구위원, 조희은 연구위원은 퇴장하셔도 좋습니다. 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  그리고 또 아울러 지금 의회에서 원장님도 승인을 그때 부동의하셨나요? 기획재정위원회에서 임금 인상을 했었습니다. 했고 그래서 예결특위에서 삭감되는 이런 경우가 있었기 때문에 올해도 우리 위원님들께서 많은 설득이 된다라면 그런 과정을 거치도록 제가 한번 노력해 보겠습니다. 퇴장하셔도 좋습니다. 
</p>
<p style="padding-left:1.2em">  계속 이어서 이종인 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이종인 위원 </b> 양평 출신 이종인 위원입니다. 우선 경기도 발전을 위해서 연구하시고 행정사무감사를 준비해 주신 이한주 원장님과 공직자 여러분께 감사드립니다. 
</p>
<p style="padding-left:1.2em">  나간 다음에 하겠습니다. 자리가……. 빨리 나가주세요. 
</p>
<p style="padding-left:2.4em">    (장내정리)
</p>
<p style="padding-left:1.2em">  인사 안 하고 그냥 나가주세요. 
</p>
<p style="padding-left:1.2em">  본 위원이 18년 행감 때 주문드렸던 지역별 자연보전권역 피해지도 제작이 급 필요하다고 주문했는데 엊그저께 경기도 규제지도 이거 잘 받았습니다. 2020년도 경기도 규제지도를 만들어주셔서 감사하고요. 지도를 만듦으로써 끝나는 게 아니라 이것을 홍보하고 중복규제 해결을 위해서 또 연구도 필요하다는 말씀을 드립니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 저희 과제라고 생각합니다. 
</p>
<p><b>○ 이종인 위원 </b> 원장님께서는 더 많은 관심과 홍보에 열정을 주시기 바라겠습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 경기도 추진사업에 대한 성과분석을 경기연구원에서 내놨어요. 제가 읽어보도록 하겠습니다. 추진사업에 대한 평가결과 첫째, 사업명은 제가 말씀을 안 드리겠습니다. “공공사업들이 부가가치 창출, 일자리 창출 등의 측면에서 효과가 잘 나타나지 않았다. 당초 기획이나 선정단계에서 시장ㆍ군수의 공약이나 시군의 장기민원성 사업이 많았기 때문에 성과창출 부분에서 근본적 한계를 도출하였다. 앞으로 사업기획단에서 부가가치 창출, 일자리 창출 장치를 강화하고 이를 측정 및 모니터링할 수 있는 성과표를 잘 짜서 관리가 필요하다.” 이렇게 정의를 내렸고요. “둘째, 사업이 지연되고 있거나 사업목적 변경을 추진하는 경우가 많았다. 여건 변화에 따라 어쩔 수 없는 상황도 있겠지만 당초 사업계획이 부실하게 이루어져 계획이 변경되는 경우도 발생하고 있다. 앞으로 사업 변경 기준과 원칙” 그러면서 “유연하게 사업을 관리할 수 있도록 정책이 필요하다.” 이렇게 성과보고서를 냈습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 재정사업 평가보고서. 
</p>
<p><b>○ 이종인 위원 </b> 네. 그렇다고 보면 지금 제가 여기 경기연구원에서 주신 거를 금방 읽었으면 이 사업은 2차 연도 사업을 할 때 계속 동일한 방법으로 경기도가 지금 하고 있습니다. 연구원에서 입장은 어떤 입장이죠, 이런 거는?
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희는 5,000만 원 이상의 전체 정부 재정사업에 대해서 평가를 하고 저희들의 의견을 도에 제출을 하는 겁니다. 그 과정에서 약 3,000억 원 정도의 예산을 절감하였다고 저희들은 판단하고 있고요. 그럼에도 불구하고 도가 어떤 사업에 대해서 저희들이 판단하지 않는 정무적이거나 혹은 다른 효율적인 판단을 했을 경우에는 도의 재량대로 하는 그런 상황입니다.
</p>
<p><b>○ 이종인 위원 </b> 그러면 경기연구원에서는 그 사업에 대해서 분석만 하고 그냥 마시는 것……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 꼭 그런 것은 아니고요. 대부분 많은 경우에 경기연구원에서 분석된 대로 진행되는데 또 일부에 있어서는 협의과정을 따로 거치고 있습니다. 
</p>
<p><b>○ 이종인 위원 </b> 그러면 이 사업은 지금 제가 여기 보고서 주신 것대로 하면 2차 사업을 제가 봤을 때는 동일하게 하면 안 되는 데도 하고 있습니다. 이거는 그럼 추후 제가 담당자들하고 확인을 해 보도록 하겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이종인 위원 </b> 그리고 수도권 2,600만의, 대한민국 국민의 50% 이상이 먹는 팔당상수원에 대한 연구가, 오늘 제가 경기연구원 홈페이지 한번 들어가 봤습니다. 그런데 연구는 12년 이후에 거의 있지를 않더라고요. 팔당상수원에 대한 연구는 총 76개가 있었고 12년도에 마지막 연구보고서가 있고 없더라고요. 특별한 이유가 있으신가요, 그런 거에 대해서는? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 특별하게 안 해야 되는 건 아니고 수시로 토론회, 현안대응 이런 걸로 하고 있습니다. 최근에도 곧 팔당상수원 문제와 관련하여 저희들이 포럼을 열고 포럼에서 저희들이 토론을 하고 이럴 예정으로 있습니다. 
</p>
<p><b>○ 이종인 위원 </b> 그러니까 그 토론회는 실질적으로 정책을 하기 위한 기본적인 거고 토론회에서 끝나는 것 같고 연구보고서가 나와야지만 다른 데도 서로 소통을 한다고 비쳐져 보입니다. 그런데 연구보고서가 없더라고요, 12년도 이후로는. 혹시 있는 게 있으신가요? 제가 잘못 봤나요, 그러면? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 우리 담당자, 부원장이 마침 담당하고 계셔서요. 
</p>
<p><b>○ 이종인 위원 </b> 네. 
</p>
<p><b>○ 연구부원장 송미영 </b> 말씀하신 대로 예전에 비해서는 저희가 연구가 좀 부족하긴 하지만 2015년에도 수계기금 관련한 연구를 저희가 정책연구로도 했고요. 그다음에 한강유역환경청에서 발주한 연구를 5개 시도 연구원하고 한 것도 있습니다. 그리고 지금 현재는 국가의 물 관리 체계가 바뀌고 있어 가지고 국가의 물 관리 체계가 일원화되고 바뀌는 과정에서 필요한 여러 가지 종합계획 그리고 법정계획의 변화에 대한 연구를 계속해서 하고 있습니다. 그런데 그 연구들에는 팔당이라는 이름이 안 붙어 있어서 아마 이렇게 검색을 하시면 그 연구가 거기에 포함되지 않는 것으로 보여질 수는 있습니다. 
</p>
<p><b>○ 이종인 위원 </b> 제가 경기연구원에 들어가서 팔당상수원 해서 봤더니 그렇게 나오더라고요. 그거는 자료로 한번 연구보고서라도 있으면요. 
</p>
<p><b>○ 연구부원장 송미영 </b> 15년 이후 자료는 한꺼번에 같이 보내드리도록 하겠습니다. 
</p>
<p><b>○ 이종인 위원 </b> 네, 저한테 좀 보내주시면 좋겠습니다. 왜 그런 말씀을 드리냐면 제가 양평 출신이다 보니까 그런데 양평군 같은 경우에는 사실 규제 1등급입니다. 그리고 규제 법이 12개의 법과 72개의 시행령과 156개의 고시로 묶여져있어요. 그리고 거기에는 아시다시피 중첩규제로 돼 있어 갖고 사실 저희가 법을 잘 모르다 보니까 중첩규제를 알지를 못합니다. 그래서 그거를 경기연구원이나 이런 전문집단에서 해결을 해 주셔야 됩니다. 여기도 볼 것 같으면 지금 수도법도 사실은, 한강수계법도 2개가 있고요. 자연보전권역에 돼 있고 수변구역에도 돼 있고 뭐 이런 식으로 중첩규제가 되게 많음에도 불구하고 이게 집행부에서 노력을 아니 하면 일반인들은 사실 무슨 일을 하는 데에 있어서 안 되는 것만 있지 되는 것은 안 됩니다. 
</p>
<p style="padding-left:1.2em">  예를 들어서 제가 아까 말씀드린 12개의 법과 72개의 시행령과 156개의 고시라고 이미 뿌려놨기 때문에 시군에서는 무슨 사업을 하려고 하면 이 법 때문에 “안 됩니다.”만 얘기하지 그거를 풀지 않습니다. 그러면 경기도 차원에서 선도적으로 이거를 더 연구해서 사실 경기도민이 규제받지 않게끔 노력을 해야 된다는 말씀을 드리는 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 저희들 규제 관련된 것은 위원님, 규제지도가 있듯이 연구원이 각종 규제 해제와 관련해선 적극적으로 대응을 하고 있으나 조금 더 말씀하신 대로 분발해서 그 부분 더욱더 열심히 하겠습니다. 
</p>
<p><b>○ 이종인 위원 </b> 네, 감사합니다. 이상입니다.
</p>
<p style="padding-left:2.4em">    (심규순 위원장, 이필근 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 이종인 위원님 수고하셨습니다. 다음은 김중식 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김중식 위원 </b> 용인의 김중식 위원입니다. 이한주 연구원장님, 우리 싱크탱크 대부대를 이끌고 가시느라 고생이 많으십니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사합니다.
</p>
<p><b>○ 김중식 위원 </b> 우선 간단한 것부터 머리 좀 식힐 겸, 우리 경영부원장님이 지금 안 계시죠? 겸직을 하고 계시나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 경영부원장이요? 
</p>
<p><b>○ 김중식 위원 </b> 네, 경영부원장. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 경영부원장. 
</p>
<p><b>○ 김중식 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 계시다가 이직하시는 바람에. 
</p>
<p><b>○ 김중식 위원 </b> 언제부터 언제까지, 언제 충원계획이 있으신가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 도하고 협의 중에 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 막중한 조직인데 하루 빨리 이게 해소돼야 될 텐데요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 저희가 지금 감사인하고 두 직이 결원이라서 도하고 계속 협의 중에 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 처음부터 왜 이 부분을 짚고 가냐 하면 조직이라고 하는 것이 굉장히 체계적이고 시스템적으로 가야 되고 인원 충원계획이나 어떤 이런 것들이 빨리 이루어져야 되거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김중식 위원 </b> 그래서 그거와도 관련된 질의를 좀 드릴 텐데요. 우선 본 위원이 상임위원회 및 도민 대상 연구원 성과보고회 및 정책간담 추진에 관련된 사항과 특정과제 연구를 위한 선발위에서 선발된 초빙연구원이 타 연구에도 참여하는 사례 발생. 그래서 그거에 대한 문제점이나 현황에 대해서 질의를 드리겠습니다. 우선 먼저 연구원의 연간 과제 성과물 관련 상임위원회와 도민 대상 성과보고회 및 정책토론회 개최 추진에 관련해서 지난 번 행정사무감사 때 위원님들께서 제안하신 다양한 연구, 그 내용에는 저성장, 양극화, 청년실업, 저출산, 고령화, 중첩규제 해소방안 등에 대한 진행결과를 다음 행정사무감사 이전에 공유하고 전달을 하지 않으면 알 수가 없죠. 이러한 부분들이 피드백이 돼야 다음 계획이라든지 그런 부분도 의견을 수렴할 수 있고 그런 부분이 있고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김중식 위원 </b> 두 번째는 연구원의 플랫폼 역량강화를 위해서 1년간 연구자료나 성과를 관련 상임위원회나 시민과 공유해서 각종 사전계획이나 성과 공유 시 다양한 의견을 수렴해야 된다 하는 부분에서 착안하고 질문을 드리겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김중식 위원 </b> 그렇다면 지난번 행정사무감사에서 지적 또는 제안한 이런 연구과제들에 대해서 어떻게 진행됐는지 성과보고회나 이런 거를 어떻게 하고 있는지에 대해서 설명을 해 주시고요. 또 그거로 인해서 어떻게 의견수렴을 어떤 절차를 거쳐서 하고 있는지 말씀해 주실 수 있어요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀드리겠습니다. 지난번에…….
</p>
<p><b>○ 김중식 위원 </b> 담당자가 하셔도 돼요. 편하신 대로…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 아니요. 제가 드리도록 하겠습니다. 지난번에 우리 위원님들께서 말씀해 주신 저성장, 양극화, 청년 고용 그다음에 양극화 문제, 고령화 이런 문제들에 관해서는 연구원도 핵심과제로 설정을 하고 있는 바였고 다만 저희들이 가지고 있지 못한 인력, 예컨대 고령화라든가 저출산 관련 인력은 저희들이 상대적으로 부족했기 때문에 이 부분을 좀 줄였지만 저성장, 양극화, 청년 문제 이런 문제들에선 저희들이 적극적으로 연구를 하였습니다. 그래서 다양한 연구들을 하여서 한국경제 전망이라든지 청년정책 개선방안이라든지 이런 연구들을 하였습니다. 빈곤에 관한 연구나 하는 연구들은 기본소득 등에서도 대단히 광범위하게 연구된 그런 내용이라고 말씀드릴 수 있겠습니다.
</p>
<p style="padding-left:1.2em">  다만 아까 말씀하신 대로 플랫폼을 만들고 자료나 연구성과를 공유하자라는 말씀은 저희들이 그 부분에 대해서도 저희 연구원의 연구결과를 지속적으로 끊임없이 탑재하고 있고 위원님들께도 이슈&진단 등을 비롯하여 발송하고 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 원장님 말씀을 잘 들었고요. 결과는, 결론은 그렇습니다. 제가 간단하게 정리를 해 보면 두 가지 내용을 공히, 결국은 성과물이나 어떤 이런 부분 보고 또는 정책 토론이 결국 피드백을 하고 공유하고 이런 개념 아니겠습니까? 그래서 보고회도 할 수 있는 기회를 1년에 한 번이라도 가질 수 있도록 했으면 좋겠고 그래서 제안을 드리면 공동정책 연구성과 토론회 개최를 좀 해 주셨으면 하는 제안과 또 함께 경기연구원 주간을 신설해서 이거를 도민들에게도 알리고 그래서 또 관련된 의견을 수렴할 수 있는 기회를 제도적으로 만들었으면 좋겠다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님 말씀하신 대로 저희들이 더 노력하겠고요. 저희들이 자료를 공유하고 하는 것들은 저희들 홈페이지에 늘 있고 위원님들께는 대부분 전달을 하고 있어서 위원님들이 더더욱 필요한 게 있으면 언제든지 저희들이 따로 별도로 또 제공하도록 하겠고요. 
</p>
<p style="padding-left:1.2em">  그다음에 의회와 특히 기재위와 공동정책을 하는 데에는 조금 더 노력을 하겠지만 위원님들께 저도 또 하나 요청을 드리면 저희들이 1년에 한 번씩 무슨 연구를 할까라고 하는 거를 몽땅 연구원들이 다모여서 연구과제 토론회를 합니다. 이때 위원님들을 늘 초대를 하고 싶은데 저희들이 일정을 못 맞춰서 위원님들 초대를 제대로 잘 못 했었는데 앞으로는 위원님들하고 조금 더 잘해서 초대를 하도록 하겠습니다. 아울러 저희들도 의정포럼과는 별개로 저희 상임위인 기재위하고 특정한 주제들에 대해서 같이 공동토론회를 하고 하는 것들을 저희들도 기대하고 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 네. 시간이 꽤 흘렀는데요. 사실은 질문은 짧게 하고 대답을 많이 듣는 게 원칙인데 지금 시간이 짧다 보니까. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 죄송합니다. 
</p>
<p><b>○ 김중식 위원 </b> 아이로니컬하게 지금 진행이 되고 있어요. 그 부분은 그렇게 넘어가고요. 
</p>
<p style="padding-left:1.2em">  두 번째, 특정과제 연구를 위해 선발된 초빙연구원이 타 연구에 참여하는 어찌 보면 불합리한 이런 사례들이 발견이 되고 있습니다. 예를 들어서 권 모모 초빙연구원께서 도시계획지역분 야연구원으로 채용됐는데 4차 산업혁명기술 이쪽에 참여하신 예도 있고요. 김 모모 위원님께서는 2019년 6월 12일 임용이 되었는데 지역화폐 연구 이미 시작되고 있는, 그 전에 시작된 지역화폐 연구에 참여를 하셨어요. 또 김 모모 연구위원님도 미세먼지 관련 특정연구를 위해 채용됐는데 균형발전 연구에 참여하셨다. 이 외에도 이 모모 연구위원님이 3개 연구에 참여하셨어요. 그렇다면 특정연구를 위해서 임용된 연구원이 다른 연구에도 참여할 수 있는지가 궁금합니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님. 초빙연구위원을 말씀하시는 걸로 판단되는데요. 저희가 어떤 주제가 있으면 저희 연구위원들로만 가지고 부족할 경우에는 초빙연구원을 저희들이 모아서 투입을 합니다. 그런데 연구위원들이 하나의 주제만이 아니라 여러 주제에 동시에 투입돼서 여러 작업을 할 수 있는 것처럼 초빙연구원들도 하나의 과제뿐만이 아니라 유사한 과제들 여러 개에 투입돼서 보고 있습니다. 위원님께서 사람 이름으로 보기 때문에 여러 개로 보이는데 과제 명으로 다시 분류해서 보면 하나의 과제에 여러 명의 연구위원과 여러 명의 초빙연구위원이 투입돼 있는 것으로 확인할 수 있을 겁니다.
</p>
<p><b>○ 김중식 위원 </b> 그렇기는 합니다. 그렇기는 한데요. 그런 초빙연구원을 선발할 때 보면 어떤 어떤 분야를 해서 선발을 하셔요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 그런데 여기 계신 박사님들도 그렇지만 예컨대 노동시장을 주로 뽑는다고 했지만 뽑아놓고 나면 노사관계도 좀 해야 되는 게 저희 현실입니다. 그래서 인근 분야에 대해서는 주는 안 맡겨도 협력들을 다 같이 시키고 있는 그런 실정입니다.
</p>
<p><b>○ 김중식 위원 </b> 그런데 본 위원이 염려하는 부분은, 물론 다양한 곳에서 여러 가지로 쓰일 수 있으면 좋고요. 또 여력이 생기면 그 여력을 또 활용하는 것도 좋고 그런 부분도 있을 텐데…….
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  위원장님, 제가 보충질의 없이 조금만 더 하고 마치도록 양해해 주시면…….
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 네, 그러시죠. 
</p>
<p><b>○ 김중식 위원 </b> 고맙습니다. 
</p>
<p style="padding-left:1.2em">  그럴 텐데 그렇다 하더라도 그렇게 되면 기존에 여기서 예를 들면 직원으로 활동을 하시는 박사님들이나 연구하시는 분들에 초빙연구원이 서브역할을 해 주신다는 말씀이시잖아요, 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김중식 위원 </b> 그렇긴 한데 이 체계가 과연 올바른 것인지에 대한 거는 굉장히 임의적일 수 있다는 부분이…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 전문적일 수 있도록 더 노력하겠고요. 또 그러나 저희들이 이거를 할 때 일방적으로 배당하는 건 아니고 관련자들을 쭉 소집해서 누가 책임을 맡고 누가 어떤 부분을 도울 것인지에 대한…….
</p>
<p><b>○ 김중식 위원 </b> 그런 부분에 대한 사전 충분한 협의가 이루어지나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 충분히 논의하고 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 그런 기록은 안 남아있겠죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니요, 그거는…….
</p>
<p><b>○ 김중식 위원 </b> 속기록이나 기록도…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 기록도 있습니다. 회의록은 남아있지 않지만 언제 모여서 이런 주제를 연구해서 어떻게 결론 내렸다 하는 정도는 가지고 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 그래서 아까도 말씀을 드렸듯이 그런 전문성이라든지 아니면 원래의 취지, 이 분을 초빙연구원으로 초빙할 때 어떤 취지라든지 이런 것이 퇴색되지 않을까 하는 부분과 더 나아가서 좀 노파심인지 모르겠습니다마는 또 과도하게 일을 시키는 건 아닌가 하는 부분도 들여다볼 수 있어요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 좀 저희 연구원이 1인당 평균과제가 아까 위원님들께서는 자꾸 무기계약직 전환만 말씀하셨지만 그다음에 연구위원들도 저희가 급여가 그렇게 적지는 않습니다. 그러나 그럼에도 불구하고 굉장히 많은 과제들을 수행하고 있어서 저는 또 마음속에 그분들께도 늘 마음의 빚을 지고 있는 그런 상황입니다.
</p>
<p><b>○ 김중식 위원 </b> 그분들은 불만은 없나요? 충분히 양해나 어떤 동의를 구하고 하시는 건가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 동의는 구하고 있는데 연구원 사정을 알기 때문에 본인들도 자발적으로 응하고 있습니다. 
</p>
<p><b>○ 김중식 위원 </b> 네, 하여튼 좀 전에 같이 염려했던 대로 임용목적에 맞게 연구과제를 수행할 수 있도록 그렇게 해서 추진을 해 주시고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김중식 위원 </b> 박사급 연구원은 연구계획 당시 필요한 연구진을 사전에 확보해서 연구에 차질이 생기지 않도록 기본적인 체계 개선이 필요하다면 그런 것들이 보일 수 있는데 간과하고 넘어갈 수 있어요. 원장님께서는 그런 부분도 놓치지 마시고 주변의 의견을 잘 섭렵을 하셔 가지고 개선할 방향 있으면 개선해 주시기를 당부드리겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 격려 고맙습니다. 
</p>
<p><b>○ 김중식 위원 </b> 이상입니다. 
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 김중식 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  지금 위원님들이 요구한 자료가 아직 많이 받지를 못해 가지고 위원님들이 질의하는 데 많은 어려움이 있으니까, 연구원에서 지금 자료를 준비하고 있는 것 같은데 조속히 제출해 주시기 부탁을 드리겠습니다. 그리고 우리 원장 증인이 너무 상세히 설명하는 바람에 원장님이 위원 같아요, 내가 보기에. 거꾸로 된 것 같아. 여기 질문할 정도면 어느 정도 업무를 파악하고 하는 거니까 답변을 단답식으로 하셔도 돼요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 너무 시간이 많이 가는 것 같고 그만큼 위원들이 질문을 못 하니까 부탁드리고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 다음 원미정 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 원미정 위원 </b> 안산 출신 원미정 위원입니다. 우리 이한주 원장님 이하 경기연구원 구성원들, 행감 준비하시느라 고생하셨고요. 연구과제도 굉장히 많으신데 원장님 지금까지 얘기하신 것처럼 과도하게 많은 정책연구와 수탁연구들을 해 오고 있는 것으로 결과적으로도 보여집니다. 그런데 사실은 제가 자료 요청하고 이게 제가 처음 업무보고할 때 질의 겸 요청드렸던 사안이기도 해요. 이게 핵심은 어쨌거나 연구과제를 선정하고 연구를 진행하는 건데, 경기연구원이. 그 연구과제 선정과 추진에 있어서 공정한 절차들이나 적합한 절차들을 거쳐서 하는 것이 저는 중요하다라고 생각을 하고 있고 기타 제가 다른 상임위일 때 연구기관들도 그런 절차들을 거치고 요구했었고 또 그런 절차들을 통해서 연구과제를 선정하는 시스템들을 만들었습니다. 그래서 제가 업무보고 때도 질의를 좀 드렸었고 하고 있다라고 말씀을 하셨기에 제가 이 자료 요청하면 바로 왔어야 돼요. 연구과제 선정위원회 현황하고 절차 달라고 하는데 이게 지금 왔어요, 지금, 원장님. 지금 와서 보니까 아주 열심히 만들어 오신 것 같아요, 자료 자체 내용이. 기존에 시스템으로 딱 되어 있어서 그걸 주셨다기보다 제가 자료 요청을 한 후에 만드신 것 같은 그런 내용적 느낌이 있습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 선정위원회는 잘 운영되고 있습니다. 잘 운영되고 있는데 이게……. 
</p>
<p><b>○ 원미정 위원 </b> 그런데 기본적으로 이 자료가 지금 보시면 상시적으로, 아니, 상시적은 아니겠죠. 선정위원회가 매번 열리는 건 아닐 텐데 큰 틀의 일련의 정책연구를 어떻게 하고 어떤 과제를 하고 어떤 절차를 통해서 선정하고 추진을 하겠다라는 그런 아마 회의를 할 거고 단기적으로는 단기과제 들어오는 부분에 대해서는 어떤 회의나 어떤 과제를 통해서……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희는 굉장히 많이 열리는 게 연구위원회입니다.
</p>
<p><b>○ 원미정 위원 </b> 연구위원회가 아니라 연구과제 선정위원회를 얘기하는 거죠. 그래서 그 자료를 제가 요청했는데 지금 왔어요. 그런데 이 내용 자체가 그렇게 사전에 충분하게 자료가 일상적으로……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희는 연구위원회라는 이름으로. 
</p>
<p><b>○ 원미정 위원 </b> 연구위원회면 연구위원회 자료를 주시면 좋았을 텐데. 아무튼 지금 왔습니다, 원장님 어쨌거나. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구 선정위원회가 아마 저희가 그런 이름으로 없어서 그랬던 것 같습니다. 
</p>
<p><b>○ 원미정 위원 </b> 그거는 이해를 그 정도로 못 하시면 안 되죠. 연구과제 선정하는 걸 그럼 어떤 업무, 다른 이름으로 한다라면 그 이름으로 딱 얘기를 제안해 주시고 와서 자료 주시고 설명해 주시면 되죠. 
</p>
