<p><b>○ 경기연구원장 이한주 </b> 자료를 위탁하는 경우가 있고 저희가 직접 하는 경우가 있어서 그렇습니다.
</p>
<p><b>○ 원미정 위원 </b> 그러니까 경기도 비정규직 현황에 대한 자료 요청을 했고요. 그 자료를 토대로 이 연구를 했기 때문에 제가 도에다 요청할 수도 있어요, 이거는. 그런데 이 연구를 했기 때문에 당연히 그런 데이터를 가지고 연구를 분석해야 금액이 나오는 거 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇죠. 
</p>
<p><b>○ 원미정 위원 </b> 그래서 저는 오히려 그 연구한 기본데이터를 달라. 그럼 이거 제대로 분석해서 연구결과가 나왔는지에 대한 것들을 한번 검토해 보려고…….  
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 검증하시려고요. 
</p>
<p><b>○ 원미정 위원 </b> 요청을 했는데 일단 자료 제출 자체를 거의 거부하다시피 안 주셨고 연구보고서도 나중에 좀 주셔서 내용에 대한 분석을 하기가 어려운 부분도 있었고요. 아무튼 문제의식은 세분화된 비정규직의 여러 유형에 따라서 임금 산정하는 것이 그냥 단순하게 여론조사나 해외사례만 가지고 5%에서 10% 올리는 것으로 지금 제한을 했단 말이에요. 세분화돼서 그러면 이 결과로 보면 더 불공정한 사례들이 생길 거라고 저는 예상이 돼요. 직급별로, 여러 가지 유형별로. 그거 아주 설계할 때 세분화되지 않으면 사실은 굉장히 좀 그 안에서도 불공정 문제가 불거질 수 있다는 생각과 앞서 말씀드린 사실은 비정규직 정규직 전환을 하면 이 부분들이 굉장히 많이 소진되고 그다음에 오히려 업무에 대한 상시업무와 비정규직이 아닌 직접 집행할 수 있는 것들을 오히려 연구를 해서 조사해서 전환하고 나머지 정말로 비정규직으로 단기간에 필요한 업무나 이런 부분에 대해서 구분을 정한 다음에 이 금액을 산정하면 차츰 굉장히 줄어들 거라고 저는 생각이 들어요. 그래서 되게 급하게 추진하고 있고 근본적인 걸 놓치고 있다 이 생각이 저는 굉장히 많이 듭니다. 그래서 그 부분에 대해서 좀 같이 얘기를 하려고 사실은 자료도 요청하고 보고서도 요청했는데.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그러셨군요.
</p>
<p><b>○ 원미정 위원 </b> 그거에 대해서 충분히 협의하거나 소통하지 않은 것에 대해서는 굉장히 유감스럽다는 말씀드립니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님 식견이 좀 많으셔서……. 
</p>
<p><b>○ 원미정 위원 </b> 시간상 저는 질의 마치고 말씀 듣겠습니다. 
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 증인이 너무 자세히 설명하는 바람에 위원님들이 항상 질문시간에 쫓겨 가지고 추가하는데 나중에 추가질문하시고요. 
</p>
<p style="padding-left:1.2em">   2시간이 넘어서 우리 원장님도 증인도 많이 힘들 것 같은데 앉아서 답변하셔도 되니까. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니요, 위원님 보면서 얘기하는 것은 나쁘지 않습니다. 
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 아니, 불편, 너무 힘들지 않으세요? 괜찮아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 오늘은 컨디션이 좋아서.
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 위원님들이 앉아서 답변해도 좋다는 의견이 많이 와서 제가 말씀드리는 건데. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그럼 그렇게 하도록 하겠습니다. 사실 여기 앉으면 또 안 보여서요.
</p>
<p><b>○ 부위원장 이필근(수원3) </b> 그렇게 하세요. 아무리 1년에 한 번씩 하는 거라도 너무 힘든 것 같은데. 그럼 그렇게 하시고. 
</p>
<p style="padding-left:1.2em">  다음은 우리 김달수 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김달수 위원 </b> 김달수 위원입니다. 저는 복잡한 거 말고 좀 간단하게 제가 평소에 연구원을 보면서 느꼈던 내용에 대해서 한 가지만 말씀드리겠습니다. 현재 우리 연구원에서 연구원이나 연구위원에 대한 직급은 석박사 학위를 근거로 하죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 석사하고 박사는 구별하고 있습니다. 
</p>
<p><b>○ 김달수 위원 </b> 그러니까 학위를 폐쇄적으로 대입해서 직급을 운영하는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 학위를 기반으로 해서 채용을 합니다. 
</p>
<p><b>○ 김달수 위원 </b> 학위를 기반으로, 그렇죠. 연구소나 물론 정부 연구기관은 다를 수도 있겠지만 싱크탱크나 이런 연구기관에서 석박사 학위를 이렇게 우리나라처럼 폐쇄적으로 하는 나라도 드물죠? 학위만 가지고……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 일률적으로 말씀드리기는 좀 어렵고요. 하여튼 대체로 학위가 기준인 거는 맞습니다. 
</p>
<p><b>○ 김달수 위원 </b> 글쎄요. 하여튼 뭐 대체적으로 어떻든 그런 직급을 구분하려면 그럴 수도 있겠죠. 그런데 우리 연구원이 하는 게 학술연구도 물론 하지만 학술연구가 주는 아니잖아요, 우리가. 데이터나 사례연구 중심으로 하고…….  
</p>
<p><b>○ 경기연구원장 이한주 </b> 다양한, 저희는 보다 현장에 가까운 연구를 하고 있습니다. 
</p>
<p><b>○ 김달수 위원 </b> 그렇죠. 정책개발이나 대안 제시나 비전 수립 같은 일종의 실사구시형 연구프로젝트를 주로 하잖아요.  
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 김달수 위원 </b> 이런 학술적 논문연구가 아니고. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그것도 저는 좀 요구는 하고 있습니다. 왜냐하면 실력을 늘 유지를 해야 되기 때문에 항상 정책연구뿐만 아니라 기본연구를 해도 저는 인정을 해 주고 있습니다, 학술연구를 해도. 
</p>
<p><b>○ 김달수 위원 </b> 그런데 어떻든 내부적으로는 그런 학위가 직급의 근거이고 그걸로만 어떻든 연구원도 뽑고 그러잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 기본적으로 그렇습니다. 
</p>
<p><b>○ 김달수 위원 </b> 기본적으로 그러잖아요. 그러니까 결국 우리가 그러면 할 수 있는 건 외부기관과 협업을 하거나 아니면 요즘 흔히 말하는 융합적 연구를 하거나 아니면 네트워크를 구성해서 그런 연구프로젝트를 진행하거나 그 방법이잖아요. 외부와 협업하는 거잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김달수 위원 </b> 제가 외부기관과의 협업실적을 한번 자료를 요구했는데 올해는 한 스무 군데 정도 협업을 했고. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김달수 위원 </b> 그런데 협업기관이 또 다 역시 똑같은 그냥 연구원이에요, 다들 그냥. 외부 그냥 연구원. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 외부 연구기관이요? 
</p>
<p><b>○ 김달수 위원 </b> 네, 그것도 외부 연구기관, 그냥. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 그렇지만 저희가 또 최근 들어서 점점 늘어나고 있는 게 초빙하고 그다음에 외부 연구위원들의 활용을 굉장히 많이 하고 있습니다. 
</p>
<p><b>○ 김달수 위원 </b> 그러니까 초빙이나 외부 연구위원도 학위를 기반으로 하잖아요, 학위를 기반으로. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김달수 위원 </b> 그렇잖아요. 그렇죠. 그 말씀을 드리는 거예요, 저는. 그러니까 학위를 이렇게 절대적이고 폐쇄적으로 운영을 하니 결국 학위 이외에도 현장에서 10년, 20년 한 사람은 학위 가진 사람보다 훨씬 더 전문적일 수 있잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 현장전문가들이 있습니다.
</p>
<p><b>○ 김달수 위원 </b> 그래서 뭐 기관 얘기하고 네트워크 얘기하고 현장 얘기하고 그런 거 아닙니까, 우리가 그것 때문에. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 앞으로 조금 더 활용하도록 하겠습니다. 
</p>
<p><b>○ 김달수 위원 </b> 그리고 그러한 문제 또 하나, 그래서 보니까 과기부 같은 데에서도 그런 융합연구 활성화 아이디어 공모전도 하고 그렇게 외부와 협업하려는 그런 여러 가지를 많이 하더라고요. 비대면 시대에 어떤 연구협업을 위해서 표준과학연구원인가 그런 데서는 하고 버추얼랩(Virtual Lab) 같은 것도 하고 여러 가지로 많이 노력을 하더라고요. 그런데 우리 경기연구원은 그런 건 잘 안 보여서 그런 외부단체, 현장전문가라기보다는 경력자겠죠. 현장의 오랜 경력을 가지고 있는 그런…….  
</p>
<p><b>○ 경기연구원장 이한주 </b> 현장 경험자. 
</p>
<p><b>○ 김달수 위원 </b> 왜 그런 사람들은 연구과제를 할 때 이름을 올리지 않느냐, 나는 충분히 그런 분들도 같이 책임성 있게 연구하고 이름을 연구자로 올릴 수 있는 그러한 어떤 외부경력자와 외부전문가들과 석박사와 관계없이 충분히 그런 어떤 연구협업을 좀 진행했으면 좋겠다라는 말씀을 드리는 거고. 어떤 경우는 그래서 내부적으로 협업지수 같은 것도 만들더라고요, 내부적으로. 그런 걸 만들어서 그렇게 충분히 현장과 외부와 협업하는 그런 것들도 많이 추진하고 있고. 
</p>
<p style="padding-left:1.2em">  그리고 또 하나는 경기도 시군도 이제 큰 도시들이 많다 보니까 연구원이 속속 생기고 있잖아요, 연구원들이. 그래서 그런 시군 연구원들과도 이런 연구 네트워크를 좀 더 긴밀하게 추진하셔서 경기연구원이 그런 지역 시군 연구원들과의 어떤 견인차 역할도 해 주십사하는 그런 말씀드리고. 그런 면에서 어떻든 경기연구원이 좀 더 이런 융합적이고 협력적인 연구생태계를 만드는 데 좀 더 혁신적으로 하여튼 사업을 벌였으면 하는 그런 말씀을 드립니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 제가 30초만 간단히 말씀드리겠습니다. 위원님 말씀하신 건 저희가 추구하는 방향과도 일치하고요. 다만 시민들과는 ‘도도한 연구’라는 걸 통해서 저희들이 광범위하게 의견을 수립해서 같이 연구를 하고 있고요, 시민들과. 다만 다른 기관과의 협력연구는 저희들이 현장의 경험을, 좋은 현장경험을 가진 사람들을 불러서 하는 것들은 대개 과제를 할 때 토론회를 합니다, 내부적인 토론회를. 
</p>
<p><b>○ 김달수 위원 </b> 그러니까 제 말씀은 토론회나 그런 건 당연히 하는데 그렇게만 하지 말고, 그렇게 어떤 객체화시키지 말고 그분들도 연구의 주체로, 연구자로 연구과제 나올 때 거기에 이름을 올릴 수 있는 좀 그런 일종의 거버넌스형 정책연구를 하라 이거죠. 어차피 지방정부에서도 정책연구를 할 때 다 거버넌스 형태로 하잖아요, 만들 때 다. 그렇게 위원회 만들고 토론회 하고 다 하는데 연구과제도 단순히 그렇게 그냥 연구과정에서 그분들 초정해서 간담회하고 토론회만 거치는 게 아니고 그 과정 전체를 같이 하면서 그 사람들도 하나의 연구책임으로 이름을 올릴 수 있는 그런…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 지금 뭐 없지는 않지만 조금 더 확대하도록 하겠습니다. 
</p>
<p><b>○ 김달수 위원 </b> 이상입니다.
</p>
<p style="padding-left:2.4em">    (이필근 부위원장, 이종인 부위원장과 사회교대) 
</p>
<p><b>○ 부위원장 이종인 </b> 김달수 위원님 수고하셨습니다. 다음 질의하실 위원님, 김재균 위원님 질의해 주십시오.
</p>
<p><b>○ 김재균 위원 </b> 어려운 질문이 아니니까 간단간단하게 좀 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김재균 위원 </b> 지금 인력현황을 보면 감사실장이 공석으로 되어 있는데 언제서부터 감사실장이 공석으로 되어 있었습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사실장은 만들어진 지는 저희들 한 6개월 정도 되는 것 같고요. 아직 도하고 협의 중이라서 이 부분 결론을 못 냈습니다. 
</p>
<p><b>○ 김재균 위원 </b> 아니, 그러면 6개월 정도에 이 자리가 만들어졌다고 그러면 사전에 협의가 어느 정도 됐으니까 이 자리를 만들었을 거 아닙니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김재균 위원 </b> 그럼 6개월 동안 지금 감사실장이 없고 지금 기구표에 보면 원장 바로 밑으로 감사실이 있어요. 어떻게 보면 잘 하고 계시겠지만 그나마 자체에서 정화시킬 수 있는 게 감사실 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 올해 처음 생긴 거고요. 저희들이 도에다가 아주 경험이 좀 풍부한 감사공무원을 파견해 줄 거를 요청해 놓고 있는 상태입니다.
</p>
<p><b>○ 김재균 위원 </b> 감사실을 만들어놨으면 감사실장을 빨리 선임할 수 있는 방법을 모색해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞는 말씀입니다.
</p>
<p><b>○ 김재균 위원 </b> 그리고 지금 우리 연구과제가 기본연구과제, 정책연구과제, 위탁연구과제, 수탁연구과제 이렇게 쭉 있어 가지고 2018년도, 19년도 이렇게 쭉 해 왔어요. 2020년도에 와 가지고는 물론 지금 9월 달이니까 조금 더 연구기간은 있을 거라고 보는데 지금 2020년도에는 기본연구과제가 1건도 없는데 사연이, 이유가 뭐죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇지 않고요. 지금 완료 기준으로 그렇습니다. 대부분 이 박사님들이 연말 기준으로 실적을 맞추시다 보니까 연말에 몰리는 경향이 있는데…….
</p>
<p><b>○ 김재균 위원 </b> 지금 진행 중인 게 그러면 2020년도에 기본연구과제가 몇 건이 있어요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 15건입니다. 12월 말까지 완료 예정인 게 15건이 있어서 전년도에 비해서 적지 않습니다. 
</p>
<p><b>○ 김재균 위원 </b> 그리고 지금 자료에 의하면 경기도 시군으로부터 의뢰받은 연구용역 현황이 있어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김재균 위원 </b> 그런데 2018년도에는 이 연구용역이 많이 들어올 수도 있고 적게 들어올 수도 있는데 2018년도에는 27건으로 해 가지고 12억 3,000만 원 정도 계약금액이 들어왔고요. 2019년도에는 25건 2억 5,000밖에 안 들어왔어요. 그리고 지금 2020년도에 보면 24건으로 7억 8,000. 여기에 대해서는 무슨 해명이 있어야 될 것 같은데요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 시군 연구 말씀하시는 거죠?
</p>
<p><b>○ 김재균 위원 </b> 네, 경기도 및 시군으로부터 의뢰받은 연구용역 현황.
</p>
<p><b>○ 경기연구원장 이한주 </b> 시군에서 저희가 수탁으로 받은 거는 2018년에는 11건이고 2019년에 7건이고 20년 9월 말 현재 10건으로 잡혀 있습니다. 그래서 시군에서 위탁받은 거는 종전에 비해서 그렇게 작은 부분은 아닌데 아까 위원님께서 말씀하신 대로 100만 이상 시군에서 자체 연구기관을 설립하다 보니까 상당 부분은 또 거기서 해소하는 그런 상황이 벌어지고 있습니다. 
</p>
<p><b>○ 김재균 위원 </b> 100만 이상에서 지금 연구소가 설치된 데가 경기도 31개 시군에서 몇 군데로 알고 있습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 고양 그다음에 용인, 수원 세 군데입니다.
</p>
<p><b>○ 김재균 위원 </b> 그렇다고 그래서 시군에서 들어오는 건수가 이렇게 금액 차이가 현저하게 나와요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 금액은 저희들이 이유는 뭐냐 그러면요, 2018년이 지나면서부터는 2019년부터는 경쟁입찰을 하고 있습니다. 저희들이 다른 민간업체하고 경쟁을 해서 시군에 들어가는데 민간업체들이 대부분 저가 입찰을 합니다. 그런데 저희들이 저가 입찰을 하기가 어려운 구조라서 종종 민간업체로 넘어가고 있는 그런 상황이 발생하고 있습니다. 그러나 저희들은 시군 연구과제 하는 게 저희들한테는 저희 임무이기도 하죠.
</p>
<p><b>○ 김재균 위원 </b> 그만큼 경기도연구원이 어떻게 보면 경쟁력이 없다고 볼 수 있고 적체되어 있다고 한편으로는 생각할 수 있는 부분이거든요, 지금. 그리고 아까 여러 위원님들이 무기계약직들 때문에 많은 말씀들을 해 놨는데 지금 예산집행 현황을 보면 2018년도에 보면 경기연구원의 집행률이 89.5%예요. 그리고 인건비를 보면 91%로 되어 있는데 2019년도 같은 경우에는 인건비가 83.4%밖에 일반회계에서 예산을 쓰지 못했고 작년 2019년도 합계는 84.1%밖에 예산을 소화 못 해 냈어요. 그리고 2019년도는 지금 진행형인데 63.1%를 사용했다고 9월 말로 보고가 되어 있는데 인건비를 보면 64.5%를 진행했다고 보는데 우리가 136억을 잡아놓고 9월 달까지 집행한 게 87억 9,000만 원 정도를 지금 예산을 집행했어요. 그러면 앞으로 3개월이 남았다고 그러면 87 나누기 3을 하면 한 28억이나 29억 정도 돼요. 그러면 곱하기 3 해 가지고 한 29억 정도 되는데 87억 더하기 29억 정도 해도 올해도 지금 눈으로 예시할 수 있는 게 19억에서 20억은 인건비에서 불용이 나올 거라고 예상이 됩니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 작년도에 위원님들이 좀 걱정해 주신 것 때문에 올해는 불용액이 굉장히 많이 줄어들 겁니다, 올해 거는요. 그래서 위원님 보고 계신 자료를 제가 지금 정확히 판단을 못 하겠는데 작년도에는 저희들이 욕심을 좀 휘어서 사람들을 조금 많이 뽑지 못했습니다. 그러나 올해 많은 박사님들을 충원해서 올해 불용액은 굉장히 많이 줄어들 겁니다, 위원님.
</p>
<p><b>○ 김재균 위원 </b> 그리고 2019년도의 예산액이 248억 3,000만 원 정도를 잡아 가지고 지금 집행을 한 게 208억을 집행해서 84%가 나왔거든요. 그런데 2019년도에는 84%밖에 집행을 못 했는데 24억 7,000만 원 그 정도로 또 예산을 잡았어요. 솔직히 예산의 근거라는 것은 그 전년도를 기준으로 해 가지고 불용액이 많이 나오면 그만큼 삭감을 해 주는 게 거의 예산의 일반적인 원칙이거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 위원님 말씀이 맞는데요. 저희 예산구조가 제가 지난번 위원님들 계실 때도 설명을 좀 드렸다시피 저희들이 인건비를 100% 지급을 받고 있지 않습니다. 그다음에 행정운영비를 또 받고 있지 않습니다. 그래서 저절로 상황 자체가 불용액이 차기 연도의 자체수입으로 잡아서 넘어가는 구조가 되다 보니까 그 부분들이 늘 일정하게 존재하는 게 사실입니다. 그래서 그 부분들은 언젠가 위원님이 지적하신 대로 완전히 뜯어고쳐야 되는데 그건 저희 혼자만 가지고 되는 일이 아니라 도가 연구원의 예산집행 방식과 합쳐서 나가야 되는 그런 상황이라서 위원님 말씀 지당하게 받아들이면서도 또 저희들이 열심히 노력하는 데가 여기까지다라고 하는 거를 말씀드리고 싶습니다.
</p>
<p><b>○ 김재균 위원 </b> 그렇다면 순세계잉여금 현황을 지금 내달라고 그랬어요. 2017년도에는 19억이 일반회계에서만 순세계잉여금이 나왔습니다. 2018년도에는 21억이 나왔고 거기다가 경기도 공공투자센터특별회계 해 가지고 9억 7,000만 원이 또 순세계잉여금으로 나왔는데 19년도 같은 경우에는 일반회계에서 39억이 남고 9억 5,000이 특별회계에서 남아 가지고 48억이라는 지금 순세계잉여금을 갖고 있는데 이렇게 일반회계에서 예산을 줄일 수 있으면 일반회계에서 줄여줘야 되는 부분인데 그렇지 않고 지금 물고 가고 있다고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 말씀 아프게 받아들이고 있고요. 조금 변명을 하자면 공투센터는 18년에 만들기 시작해서 19년에도 만들어가는 과정에 있었습니다. 그래서 박사들을 충원을 해 가는 과정이었기 때문에 그 인원 때문에 생긴 인건비 불용액인데 아마 올해부터는 그런 일이 없을 거고요. 본원도 작년도에 충원을, 그러니까 박사님들의 정원을 많이 늘렸습니다, 9명 정도. 그 과정에서 그 예산이 불용액으로 남았고 그게 올해 전부 다 넘어왔기 때문에 저희는 예산을 올해 거는 증액을 하지 않고 오히려 약간 감액예산 처리를 해서 올해 예산을 편성했었습니다. 
</p>
<p><b>○ 김재균 위원 </b> 지금 이런 상태라면 순세계잉여금하고 그다음에 일반회계 이 과정을 봐서 본다고 그러면 2021년도의 경기연구원의 예산액은 70억에서 80억을 감액해도 된다는 결론이 나오는 겁니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇게 하면 운영을 못 합니다, 위원님. 절대 안 됩니다.
</p>
<p><b>○ 김재균 위원 </b> 그리고 아까 인건비 때문에…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 아까 말씀드린 대로 인건비하고 행정운영비가 약 30억 정도 부분들이……. 
</p>
<p><b>○ 김재균 위원 </b> 지금 인건비가 무기계약직이 굉장히 싸다고 어느 정도 아까 오셨던 이분들이 말씀을 하셨어요. 그래 가지고 인건비를 한번 올해 수준으로 해 가지고, 지금 인건비가 올해 수준의 인건비를 잡은 게 136억 3,000만 원을 잡아놨어요. 그래 가지고 지금 현원이 104명으로 나눴을 때는 1인당 인건비가 1억 3,000 정도가 되고 136억을 정원인 117명으로 잡을 때 1억 1,000만 원 정도의 지금 인건비가 지급된다고 경기연구원에서는 인건비를 예산으로 올려놨습니다. 그런데 어디는 인건비에 한쪽으로 쏠림 현상이 나지 않느냐라고 지금 볼 수도 있는 충분한 대목이 나온다는 거예요, 이게. 평균적으로 나올 수 있는 게 1억 3,000이나 1억 1,000만 원이 나올 수 있는데 어디는 지금……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 저희 정원은 117명인데 현원은 아까 무기계약직은 별도 정원으로 저희가 따로 있어서 그것들을 합치면 분모가 확 변하게 됩니다. 그래서 무기계약직이 저희들이 57명 플러스 10명 해서 무기계약직 별도 정원이 따로 있습니다, 지금은. 말씀하신 117명은 저희 정원 풀에 나와 있는 표고요. 
</p>
<p><b>○ 김재균 위원 </b> 그러면 인력현황을 보고할 때 어떻게 보면 업무보고 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 
</p>
<p><b>○ 김재균 위원 </b> 따로 관리하는 거는 따로 보고합니까? 아까 그런 말씀 한 번도 없이 그냥 정원이 얼마이고 현원이 얼마이고 만약에 그 조직 내에 있으면 무기계약직이라도 그 현원에다가 집어넣고 해 가지고 보고하는 게 상식적인 예 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다, 위원님. 그 표에 따라서 좀 달라진 걸로 그런데요. 저희들이 보통 기본현황 발표하고 이럴 때는 당구장 표시를 하고 무기계약직 몇 명이 따로 있다 이렇게 하는데 위원님께서 갖고 계신 게 이 표라고 보여지는데 이 표에서는 당구장 표시가 빠져 있어서 그런 것 같습니다. 그러나 저희들 기본보고에는 당구장 표시를 해서 무기계약직 인원을 별도 표시하고 있습니다. 
</p>
<p><b>○ 김재균 위원 </b> 어떤 걸로 계산을 해야 되는 거예요, 그러면? 지금 현원이 그러면, 경기연구원의 지금 현원이 몇 명입니까, 총? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 현원은 104명이 맞습니다. 현원이 104명이 맞는데 저희들이 가지고 있는 별도의 무기계약직은 정원으로 관리하진 않습니다. 
</p>
<p><b>○ 김재균 위원 </b> 무기계약직이 그럼, 별도의 무기계약직은 몇 명입니까, 그러면? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 62명입니다, 62명. 62명이고 단기계약직이 26명이 또 있습니다. 
</p>
<p><b>○ 김재균 위원 </b> 그러면 이거 상세, 지금 말씀하신 그 부분에 대해서 문서로 다시 한번 제출해 주십시오. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 여기 이 표의 첫 번째 페이지에 보면, 이거에 처음에 나누어 드린 거에 보면 첫 번째 페이지에 당구장 표시로 표시가 되어 있습니다. 
</p>
<p><b>○ 김재균 위원 </b> 어디 당구장 표시가 되어 있어요? 무기계약직 정원 66명 중 현원 62명, 계약직 26명……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 김재균 위원 </b> 표기를 그렇게만 해 줬지. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 어떤 거를 말씀하시죠, 그럼? 
</p>
<p><b>○ 김재균 위원 </b> 별도라고 얘기를, 어디에도 나와 있지 않잖아요, 지금. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 이 자세한…….
</p>
<p><b>○ 김재균 위원 </b> 그러면 실질적인 현원과 정원을 다시 한번 달라는 얘기예요, 지금. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 무기계약직 포함해서 재작성한 현원 정원표를 작성하겠습니다. 
</p>
<p><b>○ 김재균 위원 </b> 이상입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사합니다.
</p>
<p><b>○ 부위원장 이종인 </b> 김재균 위원님 수고하셨습니다. 다음은 김강식 위원님 질의해 주시기 바라겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 수원 출신 김강식 위원입니다. 원장님, 작년에 저희가 행감하면서 어쨌든 또 인건비 관련된 부분이나 여러 가지 지적들 해서 아마 반영된 것도 있고 안 된 것도 있지 않을까 싶은데 뭐 거기에 대한 고민들은 있으실 것 같은데 작년에 본 위원이 질문해서 검토해 보시겠다라고 하는 부분들이 어떻게 됐는지에 대한 자료나 이런 게 없어서 제가 한번 여쭤보려고 합니다. 
</p>
<p style="padding-left:1.2em">  성과연봉제 관련해서 성과보고회를 통해 가지고 또 3단계로 해서 평가를 하지 않습니까? 그래서 성과평가서 할 때 양적 평가, 질적 평가, 근무평가들을 하게 되는데 이 부분이 본 위원이 좀 저거 했던 거는 22%에서 근무평가가 30%로 바뀌면서 이 부분들이 성실성이나 주관적인 의견들이 늘어난 부분들은 아니냐라는, 그 부분들을 개선해야 되는 거 아니냐, 오히려 양적 평가나 질적 평가에 대한 부분들을 높여주는 게 평가의 내용들을 주관적인 부분들이나 이런 부분을 줄일 수 있는 거 아니겠느냐라는 것들을 말씀드린 적이 있었거든요. 이 부분들은 어떻게 지금 현재 운영되고 있나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구위원들의 성과평가를 말씀하신 거고요.
</p>
<p><b>○ 김강식 위원 </b> 네, 맞습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 질적 평가가 너무 부족해서 질적 평가를 늘리는 과정을 위원님 잘 아시는 대로 가져갔는데 총 평가 중에서 말씀하신 그 평가 부분들에 관해서는 아직 그 부분은 정리를 하지 않고 있는 상황입니다.
</p>
<p><b>○ 김강식 위원 </b> 그러면 성과보고회 또 할 때 평가위원들을 두시잖아요. 그 부분들에 대한 것들이 내부위원들이 많이 있다라는 거에 검토해 보겠다라고 또 하셨었거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 외부 인원 저희들이 충분히 확보하고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러니까 왜냐하면 어쨌든 성과연봉제나 이런 것들 하면서 이런 평가를 통해서 어쨌든 진행이 되는 부분들이 있어서 이런 부분이 잘 운영이 되는 부분들이 돼야 또 객관적인 부분들에 지표로 쓰이는 것들을……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다. 좀 더 박사급 연구위원 성과평가에 관해서는 1년 동안의 경험을 바탕으로 해서 조금 더 정리를 해 보겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 네. 그리고 작년에 저희 조직개편 용역이라는 보고서가 있었어요, 기조실에서 했던. 거기 보면 인력 효율성이라는 평가항목이 있고 인력 생산성이라는 평가항목이 있습니다. 그런데 인력 생산성이라고 하는 게 직원 1인당 창출한 부가가치의 양을 평가지표로 만들었거든요. 이 부분들을 보면 경기연구원이 서울연구원이나 기타 다른 연구원보다 월등하게 높아요. 그런데 이 부분들, 저는 이렇게 생각하거든요. 월등하게 높은 이유가 좋은 것만은 아닌 것 같아요. 결국은 지금 계속 얘기되고 있는 인건비 대비 일의 양이 많았다라는 얘기밖에 안 되거든요, 제가 판단하기에는. 그 부분에 동의하시나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 지적이 맞고, 그런데 저희가 그렇게 되어지는 이유 중에는 경영평가를 할 때 저희들 경영평가가 1인당 연구업적 실적을 매년도 10~15%가 올라가도록 그렇게 작성이 되어 있습니다. 그래서 이러다 보니까 매년 조금씩 더 해야 되고 이게 수년간 누적되다 보니까 한 사람이 해야 되는 양이 조금 많아졌습니다. 말씀하신 대로 많이 한다고 더 잘하는 거냐라고 하는 질문에 대해서는 다양하게 생각할 수밖에 없는 거는 사실입니다. 그래서 그것도 현재 경영평가에서 어떤 개수 이상이 되면 만점으로 그냥 가는 걸로 하자라고 협의 중에 있습니다마는 아직 확정은 안 됐습니다. 
</p>
<p><b>○ 김강식 위원 </b> 이 부분이 물론 경영평가의 지표에 대한 부분들도 본 위원도 계속, 왜냐면 기간마다 성격들이 전혀 잘 반영되지 않는 부분들에 평가를 하다 보니까 사실, 연구원이죠. 연구원 같은 경우에는 생산성을 요구하는 데가 아니다 보니까, 사실은. 다른 지표들이 기관의 특성들을 반영한 지표들이 돼야 되는데 이 부분이 반영되지 않은 부분들은 저도 개선의 여지들이 있다라고 보고요. 
</p>
<p style="padding-left:1.2em">  어쨌든 저는 그런 부분들 오늘 쭉 얘기하면서 작년에 이어 또 노조의 참고인까지 오셔서 이 부분들이 진행되지 않았던 부분이나 미흡했던 부분들을 또 얘기하게 되는 부분들의 자리가 내년도에는 좀 정리가 돼야 될 필요가 있을 것 같다는 생각을 해 봅니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 고맙습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그래서 어쨌든 예산 구조상에 대한 부분들도 고민을 좀 해야 될 부분이 있을 것 같아요. 저희가 예산을 어느 순간에는 인력비에 대한 부분들 정확하게 하고, 그렇죠? 잉여금에 대한 부분들 빼고 남는 부분들을 반납을 하든 뭘 하든 하는 방식으로 바꿔야 되는 시점이 되지 않을까요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 언제 한번 아주 획기적으로 전환되는 게 필요한데 저희들이 최대한 불용액을 줄여놓은 상태하에서 그 눈에 보여서 그게 올해 정도는 많이 줄어들어서 엄청나게 많이 줄어들 거라고 생각합니다. 
</p>
<p><b>○ 김강식 위원 </b> 저도 그 순세계잉여금에 대한 부분들이 그게 안 남을 수는 없거든요. 안 남을 순 없지만 최소한으로 줄어든 시점에서는 차라리 인건비에 대한 예산들을 100% 반영을 받으시고 그 부분에 노력을 하시는 게.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 도도 어느 정도 공감하고 있는 것 같습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그런 부분들이 앞으로의 이런 논란이 계속 지속되지 않을 수 있는 있는 부분이라고 생각을 합니다. 그 부분에 있어서도 원장님께서 노력을 많이 하시면 의회에서도 그 부분에 대해서 같이 함께 이야기하는 시간이 있었으면 좋습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김강식 위원 </b> 경기연구원 조직도에 경영부원장님이 지금 공석이시잖아요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 
</p>
<p><b>○ 김강식 위원 </b> 김재용 부원장님이 언제 취임하셨었죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 작년 7월 달 정도에 왔고요. 올해 그 무렵에…….
</p>
<p><b>○ 김강식 위원 </b> 한 1년 정도 있으신 겁니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 1년 정도 있으시다 나갔습니다.
</p>
<p><b>○ 김강식 위원 </b> 1년 정도 있다가 또 자리 옮기셨는데 경영부원장이라고 하면 경기연구원의 경영을 맡아서 하시는 분인데 공석으로 계속 남겨두셔도 되는 겁니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 부분도 도하고 같이 협의 중에 있고요. 현재는 연구부원장이 겸직을 하고 있는데 그 부분도 도하고 협력을 해서 조속히 충원을 하도록 하겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 작년의 행감 때 이런 기억이 나요. 김재용 부원장님께서 총선에 출마할 거냐 말 거냐 이런 얘기도 있었고.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 기억합니다. 
</p>
<p><b>○ 김강식 위원 </b> 정무적인 부분들로 들어오다 보니까 계속 이런 부분이 경력 쌓는 부분들에 우려를 안 할 수가 없거든요. 이런 부분들 우려는 불식시켜 주시는 게 원장님의 역할이라고 생각하거든요. 이런 부분에 우려가 있다라는 부분도 한번 지적하면서 어쨌든 그런 부분들에 지금 감사역도 없으시고 경영부원장도 없고 조직에서 중요한 자리에 대한 부분이 공석으로 상당기간 동안 방치되고 있는 부분들은 빨리 조속히 시정하셔서 이 부분들이 원활하게 운영이 될 수 있도록 그 부분들 준비하셔서 운영하시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 감사합니다. 
</p>
<p><b>○ 김강식 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 김강식 위원님 수고하셨습니다. 다음은 정희시 위원님 질의해 주시기 바라겠습니다. 
</p>
<p><b>○ 정희시 위원 </b> 군포 출신 정희시 위원입니다. 원장님, 4시간 연속 답변하시느라고 고생하셨는데요. 저도 10분 발언하기 위해서 4시간 기다렸습니다. 
</p>
<p style="padding-left:2.4em">    (웃   음)
</p>
<p style="padding-left:1.2em">  원장님께 질문하기 전에 유영성 박사님 얼굴도 한번 뵐 겸 잠깐 좀 질문하려고. 박사님께서 굉장히 중요한 연구들을 많이 하신 것 같은데 청년기본소득 만족도 그리고 노동 유인효과 연구를 하셨고 그다음에 지역화폐 경기도 소상공인 매출액 영향분석을 하셨어요. 그 부분에 대해서 결과를 간략하게 좀 요약해 줄 수 있겠습니까? 
</p>
<p><b>○ 참고인 유영성 </b> 제일 마지막 부분 말씀하시는 것…….
</p>
<p><b>○ 정희시 위원 </b> 청년기본소득 만족도 및 노동 유입효과하고 그다음에 지역화폐 경기도 소상공인 매출액 영향분석. 
</p>
<p><b>○ 참고인 유영성 </b> 첫 번째, 청년기본소득 만족도 조사는 저희가 3,500명 정도 경기도민들 샘플로 해서 지금까지 한 세 차례 이상 조사를 했고요. 처음의 결과치는 전체적으로 만족도가 100점 만점에 한 77점 정도 나왔습니다. 그런데 그 이후로도 꾸준히 비슷한 점수긴 한데 상승하는 그런 추세를 보이고 여러 가지 질문 항목들이 있었기 때문에 어떤 경우는 나아진 경우도 있고 조금 줄어든 경우도 있지만 전반적으로는 저희가 만족도상에서 좋다라는 판단을 내릴 수 있는 결과를 얻었습니다. 
</p>
<p style="padding-left:1.2em">  그리고 두 번째, 청년기본소득의 노동 유인효과 연구결과는 지금까지 이런 기본소득을 주면 그 사람들이 일을 안 하고 논다 이런 주장들이 많이 있었는데 저희가 연구를 해 보니까 일을 더 많이 하지도 또 줄지도 않은 통계적으로 그러한 결과들이 나왔습니다. 그래서 일단은 청년기본소득 100만 원을 받고 이것 때문에 일을 덜 하고자 하는 건 아니다라는 결론, 판단을 내렸고요. 
</p>
<p style="padding-left:1.2em">  세 번째, 마지막 부분 지역화폐와 관련된 것은 2019년도부터 사업이 본격적으로 경기도가 시작됐기 때문에 1년 동안의 저희가 조사 자료가 축적이 돼서 지금도 현재 진행 중이긴 한데 1년 동안의 경우들을 한번 분석을 했습니다. 그래서 소상공인들한테 미치는 매출효과가 과연 정말 나올 수 있는 건지 봤더니 유의하게 매출효과가 나왔고 그걸 좀 더 세분화 해 가지고 저희가 정책효과 분석을 했습니다. 그 결과를 그 보고서에 담았습니다. 
</p>
<p><b>○ 정희시 위원 </b> 네, 정리를 하자면 청년기본소득의 만족도가 유의미했고 좋았고 77%대 그리고 노동 유인효과는 아마도 지급한 기본소득 자체가 금액이 적었기 때문에 어떤 의미를 찾기는 어려웠지만 그러나 노동 해이, 모럴해저드는 없었다 이 말씀이신 것 같고 지역화폐 경기도 소상공인 매출액 영향분석에서는 긍정적인 유의미한 결과를 얻었다 이 말씀이시죠? 
</p>
<p><b>○ 참고인 유영성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정희시 위원 </b> 고맙습니다. 원장님께 제가 질문하겠습니다. 한국조세재정연구원 아시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정희시 위원 </b> 여기 신문지상에서도 이미 논란이 되었습니다마는 지역화폐를 통해서 연간 2,000억 가량 손실을 입혔다 이런 취지의 발표를 했어요. 이 부분에 대해서 조금 전에 유영성 박사께서 발언이 있었습니다마는 원장님은 어떤 생각을 갖고 계시는지요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 단연코 말씀드리겠는데 조세재정연구원의 이번 연구는 관점과 방법과 자료에 있어서 저희들이 동의하기 매우 어려운, 일반적으로 과학적 관점에서 동의하기가 어려운 그런 상황을 가지고 있습니다. 자료도 저희들이 보기에는 아주 이상한 자료를 사용했고 간접적인 자료를 사용했고 방법도 통상적으로 얘기될 수 있는 그런 방법을 사용하지 않았습니다. 그래서 저희들 견해를, 지역화폐와 관련된 연구를 직접적으로 연구한 이 건은 저희밖에 없다 이렇게 말씀드릴 수 있겠어서 저희가 그쪽 조세재정연구원하고는 공동토론을 하자, 토론이 이상하면 지금부터 연구라도 같이 하자 이렇게 제안을 해 놓고 있는데 아직 답변은 없는 상태입니다.
</p>
<p><b>○ 정희시 위원 </b> 그렇다면 원장님 생각에는 한국조세재정연구원의 견해가 정치적으로 해석이 될 수 있다 또는 지방정부에 대한 계서적 시각 이런 부분이 있을 수 있다 이렇게 또 볼 수도 있나요? 아니면 바이어스가 있습니까? 에러가 있습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 깊은 내면을 저희들이 짐작해서 말씀드릴 수 없겠지만 그러나 적절한 방식으로 연구하고 적절한 방식으로 발표된 것은 아니다라는 점에 있어서는 분명하다고 말씀드릴 수 있겠습니다. 
</p>
<p><b>○ 정희시 위원 </b> 그런 부분에 대해서는 확신을 하신다? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정희시 위원 </b> 그런데 원장님께 조금 제가 아쉬운 점은 기본소득 그리고 지역화폐를 얼마나 어렵게 만들어 냈습니까? 우리 도에서도 주도를 했지만 또 경기도의회에서도. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 알고 있습니다. 
</p>
<p><b>○ 정희시 위원 </b> 굉장히 힘을 모아서 이 일들을 해 내었는데 이렇게 폄훼된 판단에 대해서 강력한 대응이 없었다 그 부분에 대해서 아쉽게 생각해요. 우리 원장님 생각을 좀…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 저희는 각종 다양한 매체, 방법으로 그거에 대해서 의견을 표명했고요. 특히 무엇보다도 지사의 SNS가 전파력을 매우 많이 갖고 있기 때문에 이걸 통해서도 여러 번 했고 저도 신문의 인터뷰라든가 글을 통해서 했고 당사자들도 했기 때문에 충분히 저희들은 했다고 보고 또 그럼에도 불구하고 어찌 됐건 토론을 하자라고 하는 데에 대해서 응하지 않는 것에 대해서 저희는 매우 유감스럽게 생각하고 있습니다. 
</p>
<p><b>○ 정희시 위원 </b> 이 부분에서는 충실한 데이터를 준비를 해 주셔야 될 것 같고 이 부분에 대해서는 나중에 사과를 받든지 아니면 정정을 요구하든지 할 수 있도록 그리고 그런 부분에 대해서 또 연구원이 가지고 있는 파괴력이 있을 수 있지만 또 의회가 가지고 있는 힘이 있으니까 경기도의회하고 좀 협조를 해서 이 부분에 대해서는 국민들 인식, 도민들 인식을 바꿔놓을 수 있도록 해 주시기 바랍니다. 그렇게 해 주시겠습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 정희시 위원 </b> 원장님, 우리 위원님들 다 이야기한 부분인데 제가 짧게 좀 하겠습니다. 무기직 관련해서 이야기가 많이 나오는데 저의 의견을 좀 말씀드리겠습니다. 저는 이 부분을 단순한 노사문제로 바라봐서는 아니 된다고 생각해요. 노사문제는 원장님과 그 노조의 문제가 되는 거죠. 그런데 실질적으로 이것은 원장님 혼자 해결할 수 있는 그런 문제가 아니에요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 
</p>
<p><b>○ 정희시 위원 </b> 도가 관여할 수밖에 없고 도뿐만 아니라 행안부가 또 관여를 할 수밖에 없는 이런 구조적 문제이기 때문에 노사문제인 동시에 또 경기도 또는 우리 대한민국의 노동정책과 관련된 문제이기 때문에 굉장히 복잡다단하다 그렇게 봐줬으면 좋겠고요. 
</p>
<p style="padding-left:1.2em">  이 노조 분들하고만 몇 번을 제가 만났습니다. 그리고 비전전략담당관도 만났고 공공기관담당관도 만났고 노동국도 만나고 연구원 집행부도 만나고 이렇게 여러 번 만난 바 있습니다. 그래서 다 이유가 있죠. 핵심은 호봉제 개선 문제 그리고 보수총액에 대한 문제 그리고 기본급에 대한 인상 문제 그리고 성과연봉제 도입에 대한 의견 이렇게 요약을 할 수 있겠는데 저는 이 문제에 대해서 노조의견도 들어본 바 있습니다. 대화의 여지가 있느냐 그리고 또 노조의 공공성에 대해서도 제가 이야기를 했습니다. 이익집단인 동시에 또 공공의 일을 하시는 분들이기 때문에 그런 부분을 이야기하니까 굉장히 수용성이 있는 그런 발언들을 하셨고 해서 차제에 이런 대화의 장을 한번 마련하는 것이 좋지 않겠나. 혹시 필요하다면 우리 기재위도 그 자리에 있을 수 있겠다 그런 생각을 좀 했고요.
</p>
<p style="padding-left:1.2em">  어제, 그제 대통령 미 대선이 끝나고 바이든 당선자가 굉장히 감동적인 연설을 했는데 거기 보면 기존에 트럼프 대통령이 가지고 있던 벽을 치고 편을 가르고 그런 정치를 이제 치유하겠다. 그리고 도움을 주는 자로 옳은 위치에 서는 그런 정치를 하겠다 이렇게 말씀을 하는 걸 보고 굉장히 인상을 받았고 또 통합을 이야기하고 민주주의를 이야기했는데 노조 문제를 아까 단순한 노사 문제로만 보지 마시고 이걸 좀……. 다 이유가 있는 것이거든요. 주장과 존재와 다 이유가 있는데 이 부분을 한번 작년부터, 그전부터 우리 의회에서 이야기를 많이 해 왔는데 실질적으로 다 정리가 안 됐으니까 이번 기회에 한번 당사자들을 만나는 그런, 필요하면 저는 그 자리에 있을 용의가 있습니다. 그런 자리를 마련했으면 좋겠다 이런 생각을 합니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 말씀드리자면 우리 연구원에 여러 가지 직군들이 있습니다. 직군 중에서 사실은 3년 동안의 임금 인상률로 보나 또는 고용안전 개선으로 보나 말하자면 가장 빠른 속도로 개선된 그런 직군인 거는 명확합니다. 다만 무기계약직 형태로 아까 위원님께서 말씀하실 때 정원표에 없는, 직제표에 없는 상태로 전환이 되었고 그러다 보니까 서울연구원 같은 경우에는 처음부터 정규직으로 전환되었기 때문에 약간의 저희들하고 편차가 좀 있습니다. 그래서 다소간에 어려움이 좀 있습니다마는 그러나 공공부분에 있는 사람들은 공무원들과 마찬가지로 자기 것을 한꺼번에 모든 것을 요구할 수는 없습니다. 
</p>
<p style="padding-left:1.2em">  저희 박사님들도 아까 말씀드린 평균급여는 적지 않았습니다마는 새로 임명돼서 들어오시는 분들은 상당한 정도로 저희들이 좀 불리합니다. 왜냐하면 원래 계셨던 분들은 호봉제로 계속 올라가버렸기 때문에 그래서 그런 불리함도 있고 하지만 특히 또 관리직 같은 분들은 매우 불리한 그런 상황에 있습니다마는 그러나 이런 것들은 협의해 가면서 해야 되지 어떤 한 직군만 아까 말씀드린 대로 3년에 유달리 다른 것의 3배, 4배까지 올라갔습니다. 이 상태에서 여기만 더 올린다라고 하는 것은, 올라가면 좋겠습니다마는 다른 부분과의 형평성도 있고 또 그 부분을 도에서도 유심히 좀 들여다보는 것 같습니다. 그래서 조금 더 주어서 해결을 하고 싶은 마음 굴뚝 같았습니다마는 그게 쉽지 않은 그런 요소가 있어서…….
</p>
<p><b>○ 정희시 위원 </b> 저는 이게 어떤 보수체계만의 문제는 아니라고 보거든요. 보수체계와 더불어 또 소통 공간을 마련하는 것도 중요하다 그리 생각이 들어서 말씀을 드린 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 하여튼 근본적으로는 저희들이 여러 가지 장치를 마련해서 다양한 개선을 향해서 노력하고 있습니다마는 근본적인 것은 지금보다 10% 정도 더 올려달라 이런 건데 현실적으로 받아들이기가 좀 어려운 측면들이 좀 있었습니다. 
</p>
<p><b>○ 정희시 위원 </b> 제가 보기에는 대화로써 해결할 수 있는 그 지점까지는 왔다고 보입니다. 제가 그동안에 쭉 여러 분들을 만난…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 아마 저도 그렇게 될 거라고 보고 있습니다. 저희가 할 수 있는 최대한을 했다는 것도 본인이 잘 알고 있습니다. 그러나 마지막 단계에서 조금 더 올려야 된다 이런 생각을 하는데 저희들이 더 줄 수 있는 게 없어서 참 안타까운 상황입니다.
</p>
<p><b>○ 정희시 위원 </b> 네, 추가질의 시간을 또 이용해서 질의하도록 하겠습니다. 
</p>
<p><b>○ 부위원장 이종인 </b> 정희시 위원님 고생하셨습니다. 다음은 이제영 위원님 질의해 주시기 바라겠습니다. 
</p>
<p><b>○ 이제영 위원 </b> 성남 출신 이제영입니다. 짧게 짧게 답변해 주세요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이제영 위원 </b> 민선7기 초빙연구원은 모집을 몇 명이나 했는지 혹시 알고 계세요? 
</p>
