<p><b>○ 이제영 위원 </b> 어느 분은 그게 모집공고부터 절차상으로 다 이행이 돼 있거든요, 최종합격까지? 그런 경우 있을 수 있습니까? 누가 뒤에 담당하시는 부장님 계시는…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 제 기억으로는 없는데. 
