<p><b>○ 이제영 위원 </b> 없어요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 다 공고하고 적법처리하고 있어서.
</p>
<p><b>○ 이제영 위원 </b> 그러시면 거기 연구원 중에 이관형 박사님이시죠? 그다음에 정원호 연구위원님, 김병조 연구위원님, 윤성진 연구위원님, 임수강 연구위원님 이 분에 대해서는 여기서 검색해서 바로 그걸 찾아낼 수 있을 거예요. 그러면 채용공고부터 그 최종합격통지까지 그거 다 출력이 가능하거든요. 저도 여기 쭉 제가 출력해서 갖고 있는데 몇 번을 검색해 봐도 그게 있질 않거든요. 그래서 그거를 좀 행감 끝나기 전에 해 주시고.
</p>
<p style="padding-left:1.2em">  제가 사실은 우리 기재위가 열세 분인데 야당은 저 혼자입니다. 그래서 제가 의욕이 앞서다 보니까 많은 것을 제가 지적하려고 자료를 사실 굉장히 많이 요구했거든요. 나중에 아까 원장님도 말씀하셨지만 위원님께서 자료를 너무 많이 요구해서 직원들 힘들었다 이런 얘기를 하는데 제가 의욕이 앞서다 보니까 그렇게 했다라는 걸 이해해 주시고.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 열심히 했습니다. 
</p>
<p><b>○ 이제영 위원 </b> 내년도 행감 때는 제가 필요한 것만, 질의할 것만 딱 사전에 공부를 해서 그렇게 하겠다는 걸 제가 약속을 드립니다. 
