<p><b>○ 경기연구원장 이한주 </b> 감사합니다. 
</p>
<p><b>○ 이제영 위원 </b> 이거는 지금 자료를 주시고요. 제가 봤을 때는 분명히 없었다는 걸 얘기드리고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 확인하겠습니다. 
</p>
<p><b>○ 이제영 위원 </b> 그다음에 1권 521쪽을 보면 여기 초빙연구원 중에 이관형 박사님께서 연구제목이 “경기도 청년기본소득 정책효과 분석: 사전 및 사후조사 비교” 이렇게 돼 있어요. 여기의 책임연구원이십니까, 이분이? 아니에요? 
</p>
<p style="padding-left:2.4em">    (「책임은 아닙니다.」 하는 관계직원 있음.) 
</p>
<p style="padding-left:1.2em">  책임연구원 아니에요? 그 다음에 그 밑에 보면 2019년 DMZ 포럼은 이분이 책임연구원입니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아닙니다.
</p>
<p><b>○ 이제영 위원 </b> 아니에요? 그럼 이게 연구기간을 보면 중첩돼요. 2019년 2월 1일부터 12월 31일까지, 2019년 4월 19일부터 12월 31일까지 연구기간이 같거든요. 이분이, 이관형 박사님이 어느 박사시죠, 전공이?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 여기 저희 초빙박사고요. 
</p>
<p><b>○ 이제영 위원 </b> 박사학위가 어떤 걸로 이분이 박사학위를 받으셨나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 이분은 사회철학이기 때문에 사회현상과 관련해서 좀 포괄적인 연구, 그다음에…….  
</p>
<p><b>○ 이제영 위원 </b> 그건 됐습니다. 이 내용을 보면 이게 전혀 상반된다고 보거든요. 그러면 유사한 것 같으면 동시에 2개 연구에 들어가서 해도 충분히 가능하다라고 보여지는데 청년기본소득 정책효과와 DMZ 포럼하고는 이게 제가 볼 때는 이분이 전공한 내용을 보더라도 전혀 다르고 그다음에 이분을 제가 검색을 해 봤어요. 그랬더니 경기연구원에 오신 이후에 대학동문 인터뷰를 하셨더라고요, 이분께서. 거기 뭐라고 말씀하셨냐면 “지방자치ㆍ지방분권에 관한 연구를 하면서 지방자치ㆍ지방분권에 관한 철학사상적 정당성을 고찰하는 작업을 한다.” 이렇게 얘기를 하셨어요. 그럼 저도 이게 굉장히 중요하다고 보는데 철학사상적 정당성을 고찰시키려고 하면 이게 연구, 짧은 기간에 과연 그게 가능할까. 그렇다라고 하면 이런 경력과 이런 생각을 갖고 계신 분이라고 하면 초빙연구원이 아니라 지속적으로 여기에서 근무하면서 이렇게 해야 효과를 나타낼 수가 있는데 이 초빙연구원이라고 하면 어떤 과제가 주어졌을 때 거기에 꼭 필요한 분, 단기적으로 이렇게 해서 오는 거 아니겠습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 그런데 이분은 본인이 얘기하신 것하고 학위 받은 것하고 여기에서의 일하고는 제가 볼 때 이게 일치되지 않는다라고 생각하는데. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님 제가……. 
</p>
<p><b>○ 이제영 위원 </b> 그 부분에 대해서는 이분을, 지금 이분이 근무하고 계시나요?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 퇴사하셨습니다. 
</p>
<p><b>○ 이제영 위원 </b> 퇴사하셨죠. 그러니까 그렇다라고 하면 이분이 얘기하신 것은 하나 실천도 안 하시고 철학사상이라는 것을 한 번 두 번 얘기해서 그게 철학적 사고가 만들어지는 건 아니지 않습니까? 그러면 면접이나 이런 과정을 거쳐서 선발할 때 이게 제대로 선발이 되지 않은 게 아닌가, 이런 판단을 했는데 그거에 대해서는 짧게. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 우선 퇴직한 이유에 대해서는 저희가…….  
</p>
<p><b>○ 이제영 위원 </b> 내가 보기에 잘했다, 그런 속의 그것까지는 다 알 수가 없어서 잘했다, 아니면 뭔가 우리가 선발하는 데 미흡했다 그렇게 짧게만 답변해 주세요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 정상적으로 종료된 상황이고요. 저희들이 지금 초빙연구원은 9개월 동안 사용하는 것을 원칙으로 하고 있습니다. 더 이상 되면 상시근로자가 되기 때문에 고용을 해야 되는 그런 상황이라서…….  
</p>
<p><b>○ 이제영 위원 </b> 그럼 좋고요. 그다음에 그러면 청년기본소득하고 DMZ 포럼하고 이게 전혀 다른데 여기 연구원으로다가 배치한 이유는 뭐죠?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 이건 초빙한 사람들의 명단이기 때문에 맨 앞에 있는 거고요. 실제는 내부 연구진이 책임을 갖고 하고 있고 이 사람들은 거기의 하나의 어떤 특정 부분에 대해서 서술을 하고 연구하는 그런 부분들이기 때문에…….
</p>
<p><b>○ 이제영 위원 </b> 좋습니다. 그래서, 그거 제가 존중하고요. 그래서 이분이 제가 볼 때는 아마 미학박사이신 걸로 알고 있는데. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다, 철학 쪽입니다.
</p>
<p><b>○ 이제영 위원 </b> 그런데 여기 이 연구원에 초빙연구원으로 와서 이 연구에 대해서는 어떤 성과를 나타냈는지 모르겠지만 뭔가 이게 좀 적절하지가 않았다 이런 판단을 말씀드리고요. 향후에는 물론 본인이 와서 짧게 근무했다 갈 수도 있고 하지만 이런 거에 대해서 좀 더 신중해 줬으면 좋겠다는 의견을 말씀드리고요. 
</p>
<p style="padding-left:1.2em">  시간이 지금 짧아서, 혹시 우리 원장님은 남경필 지사 때 주요정책이 무엇인지는 알고 계십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 남경필 지사님, 따뜻한 복지를 주요……. 
</p>
<p><b>○ 이제영 위원 </b> 주요정책 추진한 것 중에. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 따뜻한 복지를 해서 이렇게 상대 당분들을 모셔다가 거기 부지사도 맡기셨고 그런 걸로 기억하고 있습니다. 
</p>
<p><b>○ 이제영 위원 </b> 네, 알겠습니다. 제가 찾아보니까 채무제로 선언하셨고 버스준공영제 실시를 했고 일하는 청년시리즈로 해 가지고 청년연금, 청년마이스터통장, 청년복지포인트를 하겠다고 해서 의회에서 한 번 삭감도 됐었고 그 다음번에는 이게 통과돼서 일부 시행된 걸로 알고 있거든요. 제가 이 말씀을 드리는 건 지사가 바뀌면 정책방향이 모두 다 바뀌어지더라고요. 그렇죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아무래도 주권자들한테 자기 의견을 밝히고 선택이 됐기 때문에 그 의견들을 따라가야 될 의무가 있겠죠. 
</p>
<p><b>○ 이제영 위원 </b> 그거는 김문수 지사 때, 남경필 지사 때, 우리 이재명 지사 때 보면 이게 바뀌어지면 정책내용이 완전히 바뀌어집니다. 제가 이 말씀을 드리는 건 지금 기본소득단 구성돼 있죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 몇 분이죠, 여기에? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네?
</p>
<p><b>○ 이제영 위원 </b> 기본소득단.
</p>
<p><b>○ 경기연구원장 이한주 </b> 8명 투입돼 있습니다. 
</p>
<p><b>○ 이제영 위원 </b> 8명이 있습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 기본소득에 대해서 제가 연구한 거 여기 지금 보니까 14건에 7억 정도 했더라고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이제영 위원 </b> 그러면 경기도의 기본소득도 물론 중요하다라고 생각을 합니다. 그러면 여기에 14건이라고 하면 굉장히 많은 연구인력이 투입이 됐을 거예요. 그러다 보면 다른 곳에 누수가 될 수 있다고 생각하거든요. 그 부분에 대해서는 제가 원장님한테 또 질문을 드리면 아마 한 3~4분은 설명을 하실 것 같은데. 자, 여기에 집중하다 보니까 누락된 부분이 저는 있다라고 생각합니다. 제가 5분발언할 때 어떤 발언했는지 혹시 원장님 기억하고 계세요?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 도지사님께.
</p>
<p><b>○ 이제영 위원 </b> 네, 제가 5분발언 했었거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 죄송합니다. 보고받지 못했습니다. 
</p>
<p><b>○ 이제영 위원 </b> 제가 뭔 지적을 했냐면 코로나19 감염병 인력관계를 얘기했습니다. 지금 뒤에 자료 찾아봐야 없으세요. 경기도에서는 9월 달에 직제를 신설했어요. 공공의료과하고 감염병관리지원단을 신설해서 저희가 여기서 통과가 됐습니다. 경기도는 이제 직제가 만들어졌어요. 코로나 대응을 최일선에서 어디서 하신다고 생각하십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 경기도에서요?  
</p>
<p><b>○ 이제영 위원 </b> 확진자가 발생이 됐을 때 최일선 어디에서 그걸 대처하는 걸로 생각하고 계세요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 서울대학하고 협업하는 거기서 챙기는 것 같던데요. 
</p>
<p><b>○ 이제영 위원 </b> 보건소에서 하고 있습니다. 역학조사부터 일선에서는 현장에서 움직이는 건 보건소에서 다 움직여지거든요. 그러면 이 코로나 사태가 지금 단기간에 종료될 거라고 인식하는 사람은 거의 없는 걸로 알고 있습니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  (위원장을 향하여) 조금만 더 하겠습니다.
</p>
<p style="padding-left:1.2em">  자, 그러면 제가 5분자유발언 때 이런 지적을 했습니다. 의사직렬에 국장이 딱 한 분 계신데 그분이 교육을 갔어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 국장님.
</p>
<p><b>○ 이제영 위원 </b> 물론 명령은 미리 났기 때문에 코로나 발병은 1월 20일 날 했고 이분 교육은 2월 12일 날 입소한 걸로 알고 있거든요. 그래서 그 부분이 적절하지 않았다. 그러면 교육명령을 취소하고 이 의사를 갖다가 국장으로 다시 환원했으면 뭔가 적극적인 대응이 될 수 있겠다 하는 부분하고. 그다음에 후속적으로 가장 문제된 게 역학조사관입니다. 경기도에 역학조사관이 3명 있었거든요. 그런데 확진자가 많이 발생이 되니까 역학조사관 3명으로 할 수가 없지 않습니까? 그러다 보니까 서울대학병원하고 감염병관리지원단을 만들어서 거기서 역학조사관을 지원받고 그 다음에 공중보건의를, 이건 자의가 아니라 반강제적으로 해서 차출을 했습니다. 이분들을 교육했어요, 2시간. 2시간 교육해서 역학조사의 전문성이 만들어질 수 없다라고 저는 보거든요. 그래서 제가 역학조사관을 만나봤습니다. “어떻게 했느냐, 공중보건의를?” 그랬더니 “현장의 역학조사관하고 같이 몇 번 출장을 가서 조사에 대한 요령을 습득해 갖고 했다.” 이런 얘기를 했습니다. 그러면 그 이후에 보건소에서는 반드시 역학조사관이 보건소별로 있어야 된다. 그래야 대처를 할 수가 있다. 이런 의견들이 지배적이었습니다. 그렇다라고 하면 여기에 대한 대응이 경기도에서 저는 선제적으로 이렇게 직제까지 만들었는데 그러면 경기도만 직제 만들어서 될 게 아니고 시군에서 대응할 수 있는 이런 연계체제가 만들어져야 되는데 이게 이루어지지 않았다. 그럼 여기에 가장 심각한 문제가 뭐냐면 행안부에서 감염병 인력신청을 받았습니다. 제가 별도로 자료 요구를 해서 받았는데 이게 공표가 되지 않은 거라고 해서 인력신청만 받았어요. 여기 경기도에 신청한 걸 보면 2개 시는 한 명도 신청을 안 했습니다, 인력이 필요 없다고. 인력이 필요 없습니까? 저는 이해가 되질 않고요. 그다음에 가장 많이 신청한 데는 18명을 신청했어요. 그래서 제가 시군 보건소의 보건소장이나 거기 의사분들하고 대화를 해 보니까 역학조사관하고 간호사하고 이렇게 몇 명이 있어서 평상시에는 정상적인 업무를 하고 이런 사태가 발생되면 바로 대응할 수 있는 이런 체제를 1개 팀 정도는 만들어서 해야 된다라는 게 중론이었습니다. 
</p>
<p style="padding-left:1.2em">  그러면 저는 이런 것을 경기도가 “새로운 경기, 공정한 세상”을 주장하면 그럼 경기연구원에서도 이게 대처가 되려고 하면 기본적으로 그런 보건소의 인력이 어떤 표준안이 만들어져 가지고 그럼 경기도에서는 이런 안으로 이게 행안부에 요구가 돼서 그 인력을 받아서 선제적으로 대응하는 것을 했어야 되는데 결국에 경기도에서는 아무도 이 생각을 갖지 않았고 시군 보건소에다 인원만 받아 가지고 신청을 하다 보니까 한 명도 신청 안 한 데는 결국 행안부에서 2명씩 임의대로 결정을 해 줬어요. 그럼 지금도 많은 데는 18명, 적은 데는 2명 이렇습니다. 그럼 어느 보건소는 직제를 만들고 어디는 만들지 않았을 때 과연 이게 대처가 시군별로 편차가 클 수밖에 없어요. 그럼 이걸 누가 조정해야 되느냐, 경기도에서 저는 해야 된다라고 생각합니다. 그럼 이런 인력기구를 만들어서 대처하는 건 어디서 해야 되느냐, 저는 경기연구원에서 해야 된다라고 봅니다. 한쪽에 너무 집중해서 하다 보니까 가장 시민들이, 지금 금년도에 가장 핫한 이슈가 뭡니까? 코로나 아닙니까? 경제도 그렇고 향후에 어떻게 될지 이걸 해결하는 게 국가의 가장 큰 과제고 경기도의 가장 큰 과제인데 이런 걸 어떻게 놓치고 연구를 하지도 않고 인력 신청하는데 그냥 시군별로 받아서 진달만 하는 이런 경기도가 과연 이게 새로운 경기가 될 수 있느냐에 대해서는 제가 굉장히 이게 정말 안타깝고 연구원의 역할이 미흡한 게 아니냐 이런 지적을 드리면서 기본소득, 이재명 지사께서 임기 끝나면 아마 다음 지사되면 이렇게 연구에 집중하지 않을 겁니다. 그분은 또 그분이 필요한 거에 대해서 또 다른 연구를 하는 건 당연할 거예요. 
</p>
<p style="padding-left:1.2em">  그렇다라고 하면 한곳에 너무 집중해서 하는 것보다는 경기도에, 제가 예시를 들었습니다. 감염병 인력 이거에 대해서 예시를 들었는데 경기도에 필요한 게 인구 문제부터 수도 없이 많아요. 그러면 그런 거에 대해서 형평성 있게 고르게 발전을 해야만 이게 경기연구원과 도민들한테 혜택이 돌아가는 거지 이런 부분이 한쪽에 치우쳐지면 결국에는 도민들이 피해자가 될 수 있다. 그래서 그 부분은 원장님께서 좀 더 넓게 생각하고 다양한 의견을 수렴해서 이렇게 이런 차질이 발생이 되지 않도록 해 줘야 되는 게 저는 연구원의 업무라고 생각을 합니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 이제영 위원 </b> 그렇게 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 이제영 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 이제영 위원님 수고하셨습니다. 위원님들께 양해 말씀드리겠습니다. 장시간 행정사무감사가 진행되어 휴식을 위하여 10분 정도…….
</p>
<p><b>○ 김달수 위원 </b> 많이 쉬었다 하세요. 
</p>
<p style="padding-left:2.4em">    (「쉬었다 해야지.」하는 위원 있음)
</p>
<p><b>○ 부위원장 이종인 </b> 감사중지를 하고자 하는데 이견 있으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 원활한 감사진행을 위하여 10분 간 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(19시28분 감사중지)
</p>
<p class=''ar''>(19시44분 감사계속)
</p>
<p><b>○ 부위원장 이종인 </b> 좌석을 정돈해 주시기 바라겠습니다. 감사를 계속하겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 염종현 위원님께서…….
</p>
<p><b>○ 김중식 위원 </b> 잠깐만요, 위원장님. 자료가 왔는데요. 자료내용이 신청한 거 하고 좀 다르기 때문에 이거만 신청을 좀 먼저 하고 하면 안 될까요?  
</p>
<p><b>○ 부위원장 이종인 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김중식 위원 </b> 김중식 위원입니다. 공공투자관리센터 관련 2020년 재정사업평가 대상사업 내역을 달라고 한 취지가 아니고요. 평가에서 절감했다고 하는 그 부분을 좀 포함을 시켜달라고, 어떤 내용인지를 해달라고 했는데 대상사업 내역만 이렇게 해 가지고 오셔서 내가 이걸 가지고 참고를 할 내용이 없어요. 그래서 그 취지 알아들으셨나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김중식 위원 </b> 그거 다시 좀 해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 김중식 위원님 수고하셨습니다. 다음은 염종현 위원님 질의해 주십시오. 
</p>
<p><b>○ 염종현 위원 </b> 염종현입니다. 제가 작년 기재위 행감을 보고 이번에도 보니까 경기연구원의 노사 문제, 처우, 임금 문제로 상당한 시간을 할애하고 있습니다. 그래서 금년에 잘 마무리가 되고 내년부터는 이 부분이 또 거론이 안 될 수 있도록 노력을 좀 해 주시기를 간곡히 바라겠습니다. 
</p>
<p style="padding-left:1.2em">  저희가, 이번 원장님께서 부임하셔서 조직진단이나 인력증감을 좀 하신 바가 있나요?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 했습니다. 
</p>
<p><b>○ 염종현 위원 </b> 진단을 하고 나서의 그 결과를 좀 보니까 상당 부분 지금 현재 체제를 좀 보면 부원장이 이제 두 분이시고 감사실장이 한 분, 연구직이 63분 해서 2부원장 1실, 2본부, 5연구실, 2센터, 7부 이렇게 돼 있습니다, 공투는 별도고.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 염종현 위원 </b> 그래서 이거를 2017년, 18년, 19년과 비교를 해 보니까 이른바 경영진, 상층부라 그럴까요? 이 부분이 확대가 좀 많이 됐습니다. 그러니까 1부원장 체제가 2부원장으로 늘어났고 그다음에 감사실이, 아직 감사실장이 부임은 하시지 않았지만 감사실이 생기고, 그다음에 센터 2개를 관할하는 본부가 또 하나 균형본부가 생기고 그래서 이곳이 조직 실무 쪽은 그대로인데 너무 상층부가 비대해진 느낌이 좀 있다. 그래서 그 부분을 지적하는데 여기에 대해서 답변을 좀 한번 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사실장은 100명이 넘어가면 감사실장을 두도록 하는 규정 때문에 강행규정이라서 이 부분은 어쩔 수 없이 진행해야 되는 바가 있었고요. 
</p>
<p><b>○ 염종현 위원 </b> 서울연구원은 감사실이 없는 걸로 알고 있는데요. 
</p>
<p style="padding-left:2.4em">    (「있습니다.」 하는 관계직원 있음.) 
</p>
<p style="padding-left:1.2em">  있습니까? 네, 말씀하세요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희는 100명이 넘으면 두도록 도에서 지도를 좀 하고 있습니다. 그렇게 하고요. 균형본부는 원래 북부연구가 있고 또 시군 센터를 저희들이 따로 두고 있어서 이 부분들을 좀 원활히 하기 위해서 원래는 북부를 조금 키워서 균형본부로 이름을 바꾸어서 시행을 하고 있습니다. 이거는 이게 31개 시군이, 그러니까 인원은 얼마 안 됩니다마는 31개 시군이 저마다 처한 상황이 너무나 달라서 이 부분은 또 독립돼서 검토를 해야 될 필요가 있었기 때문에 이건 그렇다 말씀을 드릴 수 있겠고요. 
</p>
<p><b>○ 염종현 위원 </b> 본부로 해야지 꼭 효율적으로 할 수가 있는 건 아니지 않습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 센터가 2개가 있었기 때문에.
</p>
<p><b>○ 염종현 위원 </b> 센터체제로 양 체제로 특성을 가지고 특화되게 일을 하면 되지. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇게 되면 연구본부가 너무 많은 일을 해서. 
</p>
<p><b>○ 염종현 위원 </b> 아니, 센터는 센터 나름대로 일을 하지 않습니까? 꼭 본부가 돼야 된다고 그 고유의 센터에서 하는 일이 없어지는 건 아니잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그런 면도 있습니다. 그런 면도 있는데 제 생각으로는 그때 그렇게 생각을 좀 했었습니다. 이거는 의도적으로 상층부를 키우려고 했던 건 아니고요. 
</p>
