<p><b>○ 이제영 위원 </b> 여기 보면 이 편차가 굉장히 있어요. 그러면 지금 말씀하신 거대로 연구년도 갔거나 이러면 여기다 표시를 해 줘야 되거든요. 그러니까 자료 만드는 데도 고생하신 게 제가 경기연구원을 다 이해하고 여기 계신 박사님들처럼 다 이해하고 제가 서식까지 그려서 요구한 건 아니거든요. 그럼 거기에서도 이 위원이 왜 이 자료를 요구하는지는 아마 자료 보시면 이해가 됐을 거예요. 소통을 해야 되는데 어느 분도 그거에 대해서 소통이 없었다는 말이에요. 그러다 보니까 자료를 뽑는 데 더 어려움을 겪게 됐고 이 자료를 누가, 제삼자가 보게 되면 어떻게 이해를 할 수 있겠냐 이거죠. 그러면 제가 자료 요구할 때는 연구과제를 얼마만큼 많이 이걸 했느냐를 평가하기 위해서 한 건데 그냥 1건 하고 아무 건도 없는데 옆에는, 또 여기 써 놓은 건 있어요. 입사, 퇴사 이렇게 하면 ‘아, 그럼 이분이 입사를 늦게 했기 때문에 과제가 적게 주어졌구나.’ 판단될 수가 있는데 어떤 건 써 놓고 나머지는 써 놓질 않았다는 말이에요. 
</p>
<p style="padding-left:1.2em">  바꿔 얘기하면 자료를 좀 성실하게 내시질 않은 거다. 왜냐하면 저뿐이 아니라 제가 요구했어도 다른 위원님이 보고 문제가 있다 싶으면 질의할 수도 있는 거거든요. 그럼 이런 것은 여기 계신 박사님들은 매년 같은 자료를 반복해서 내시는 거고 위원들은 2년 하면 또 상임위원회가 대부분 다 바뀌어져서 새로운 분들이 와서 하는데 이런 거는 자료를 좀 성실하게 내주셔야 위원들이 올바로 이해할 수 있는데 좀 아쉽다는 말씀을 드립니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이 자료는 저희들이 정리를 또 하는 자료들이라서 늘 가지고 있는 자료는 아니고 원본 데이터베이스에서 뽑아 가지고 하는 건데 조금 더 위원님들이 보시기 편하게 좀 더 성실하게 자료를 만들도록 하겠습니다. 
