<p><b>○ 정희시 위원 </b> 정희시 위원입니다. 첨예한 문제들은 위원님들께서 이미 다 질의를 했기 때문에 조금 느슨한 이야기를 저는 묻고 싶습니다. 
</p>
<p style="padding-left:1.2em">  우리 경기도가 그동안에 이제영 위원님께서도 말씀하셨습니다마는 기본소득에 대한 연구를 아마 전 세계적으로 이마만큼 많은 자료를 축적한 정부는 없을 거라고 보입니다. 자본주의의 역작용에 대한 치료라 그럴까요? 그런 면에서 기본소득이 중요하고 또 다른 성장기재로서의 기능도 한다는 면에서 동의를 하고요. 그러나 우리 70년대, 80년대 대기업 중심 또 수출주도형, 물론 국민의 희생을 바탕으로 한 그런 성장을 이루어 왔죠. 그러나 여전히 스필오버라는 그 이론이 결국은 기본소득으로 갈 수밖에 없는 그런 약점은 가지고 있었지만 우리 경제는 세계적인 기업들을 만들어냈고 아주 제조업이 단단한 대한민국을 만들어놨습니다. 
</p>
<p style="padding-left:1.2em">  지금 코로나19도 있습니다마는 전환의 시대가 왔는데 거기에 대해서 정부에서는 굉장히 K뉴딜이라든지 이러 전략들을 세우고 있는 것 같습니다. 저는 가끔 유튜브에 문워크라는 유튜버가 있습니다. 대통령께서 기업체를 찾아가서 대화를 하고 많이 감동도 하고 저는 그렇게까지 다니는지를 몰랐어요, 기업 현장에.
</p>
<p style="padding-left:1.2em">  제가 요구하는 것은 이런 부분에 대한 기획을 해야 된다. 문워크가 아닌 경기도 차원에서 이런 기업을 만들어내고 사람을 만들어내는, 그러니까 우리 경기도, 결국은 경기도가 대한민국의 성장엔진이고 또 경기도의 성장엔진을 운전하는 분이 경기도 집행부 총 책임자라면 그 뒤에 나침반 역할을 해 주시는데 그런 기획들을 도에서 한쪽은 기본소득이라든지 이런 부분이 대단히 잘해 오셨는데 그런 부분을 하고 한쪽으로는 성장엔진을 어떻게 만들어내고 그림을 그리고 거기에 또 우리 집행부나 해서 어떤 전략을 만들 것인가 이것들을 해야 된다고 봐요. 그래서 그런 데 대해서 한번 말씀을 듣고 싶어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 말씀하신 대로 기본소득은 전환적인 그런 사고이기는 하지만 그리고 또 저희들이 해야 할 길이기도 하지만 그것만으로는 충분하지 않다는 것은 말씀하신 대로입니다. 더군다나 경제구조라든가 세계경제의 부가가치 재편과정이 빨리빨리 일어나고 있기 때문에 선제적으로 저희들이 기업을 독려하고 기업들이 활성화될 수 있는 구조를 만들어내야 되는 것은 사실입니다. 그래서 위원님 아시겠지만 SK 사업에 대해서도 경기도가 선제적으로 열심히 대응했고 연구원에서도 제조업 르네상스에 관련된 개념들을 만들고 산단 구조조정을 비롯해서 이런 연구들을 저희들이 목표로 정하고 하고 있습니다. 조금 더 정부와 기본방향은 맞추되 그러나 경기도가 특별히 잘할 수 있는 그런 좀 더 열심히 연구하겠습니다. 
</p>
<p><b>○ 정희시 위원 </b> 네, 감사를 드리고요. 그런데 도정을 책임지고 있는 도지사가 보내는 시그널이 굉장히 중요하거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 
</p>
<p><b>○ 정희시 위원 </b> 그동안에 기본소득이라든지 또는 불공정에 대한 발 빠른 대응이나 이런 부분에 대해선 시그널을 잘 해 왔습니다마는 이런 경제 문제에 대해서 시그널을 줄 수 있는 그런 채널이 되든 어떤 그런 연구가 되든 그런 것들을 좀 해야 되지 않을까요?  
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 100% 동의합니다. 
</p>
<p><b>○ 정희시 위원 </b> 그렇게 좀 부탁드리고 하나만 더 말씀드리겠습니다. 제가 이루었던 작은 성과라 그럴까요? 이런 것들을 이야기하고 싶은데요. 조금 전에 염종현 위원께서도 연구원의 장기 발전과제라 그럴까? 장기적으로 인력은 어떻게 할 것이며 또 연구과제는 어떻게 할 것이며 또 예산은 어떻게 이런 거에 대한 이야기를 해야 될 단계가 왔지 않느냐 이야기를 했고요. 또 우리 원미정 위원께서 연구과정 선정은 잘되고 있느냐 그리고 또 어떤 과정을 거쳐서 하느냐 이런 이야기를 하셨는데 제가 복지위에 있을 때 정책커뮤니티를 운영한 바 있습니다. 그것은 집행부하고 우리 위원회하고 그다음에 연구기관하고 해서 매월 하나씩 연구주제를 가지고 커뮤니티를 열었는데 그것은 같이 결국은 삼자가 협의를 해서 연구를 하고 그것을 실질적으로 정책으로, 예산으로 연결할 수 있는 가장 빠른 방식이다 이렇게 판단을 해서 그렇게 했고. 해서 그런 우리 위원회하고 좀 더 소통하고 연구과제로 선정, 또 어떻게 보면 연구원에서 유리한 연구과제들을 선정할 수 있거든요. 이런 핵심 발전방안이라든 이런 것을 포함해서 또 우리 현장에 있는 위원님들이 다양한 의견들을 제시하시고 그러기 때문에 그것들 한번 의견을, 제 의견을 그렇게 드립니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 저희 항상 열린 연구방향이 될 수 있도록 노력을 하고 있는데 의회하고 하다 보니까 또 비교적 소통이 좀 소홀했다는 바가 있습니다. 앞으로 열심히 더 그 부분 챙기도록 하겠습니다. 
</p>
<p><b>○ 정희시 위원 </b> 소통뿐만 아니라 그런 포맷을 한번 생각해 볼 수 있으면 좋겠다 그런 말씀을 드립니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 좋습니다. 
</p>
<p><b>○ 정희시 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이종인 </b> 정희시 위원님 수고하셨습니다. 더 이상 질의하실 위원님 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시면 이상으로 경기연구원 소관 사항에 대한 질의와 답변을 모두 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  위원님 여러분 그리고 이한주 경기연구원장을 비롯한 관계직원 여러분! 장시간 열의를 갖고 감사에 임해 주신 위원님 여러분과 위원님들의 질의에 성의를 다해 답변해 주신 경기연구원장 및 관계직원 여러분께 위원장으로서 감사드립니다. 이한주 경기원장을 비롯한 관계직원 여러분께서는 오늘 여러 위원님들께서 지적해 주신 사항을 겸허히 받아들여 향후 경기연구원의 운영에 적극 반영해 주시기 바랍니다. 또한 오늘 감사 중에 위원님들께서 개선을 요구한 사항에 대해서도 조속히 시정될 수 있도록 노력하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원님 여러분 그리고 이한주 경기연구원장님을 비롯한 관계직원 여러분! 수고하셨습니다. 그러면 이상으로 경기연구원 소관 사항에 대한 2020년도 행정사무감사를 모두 마치겠습니다.
</p>
<p class=''ar''>(20시16분 감사종료)
</p>
<p><hr /></p>
