insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2019.11.12. 화요일] 경기연구원 — 기획재정위원회 2019년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2019년도 행정사무감사(2019. 11. 11. ~ 2019. 11. 22.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=11569" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2019년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 경기연구원
</p>
<p><hr /></p>
<p>일  시: 2019년 11월 12일(화)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(15시56분 감사개시)
</p>
<p><b>○ 위원장 정대운 </b> 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조와 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2019년도 행정사무감사를 시작하겠습니다.  
</p>
<p style="padding-left:1.2em">  위원님 여러분 그리고 이한주 경기연구원장을 비롯한 공직자 여러분! 안녕하십니까? 기획재정위원회 감사위원장 정대운 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 나아가 2020년도 예산안 심사자료 및 정보를 획득하여 도민의 삶의 질 향상에 기여하고자 함이 그 목적인 만큼 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사위원 여러분께서는 도민을 대표하여 집행부 도정 전반에 대해 감사하는 것이므로 명확한 사실에 근거하여 핵심적이고 심도 있는 감사를 통해 소기의 성과를 거둘 수 있는 뜻깊은 시간이 되기를 기대합니다. 아울러 감사에 임하는 집행부 공직자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시길 당부드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장, 부원장과 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 선서를 해야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 경기도의회가 2019년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인출석 여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  경기연구원장 나왔습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 나왔습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 연구부원장 나왔습니까? 
</p>
<p><b>○ 연구부원장 이상대 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 경영부원장 나왔습니까? 
</p>
<p><b>○ 경영부원장 김재용 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 연구기획본부장 나왔습니까? 
</p>
<p><b>○ 연구기획본부장 문미성 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 균형발전본부장 나왔습니까? 
</p>
<p><b>○ 균형발전본부장 김동성 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 북부연구센터장 나왔습니까? 
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 시군연구센터장 나왔습니까? 
</p>
<p><b>○ 시군연구센터장 류시균 </b> 네. 
</p>
