<p><b>○ 행정지원부장 손호철 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 재정지원부장 나왔습니까? 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네. 
</p>
