</p>
<p><b>○ 홍보ㆍ정보부장 이덕환 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 경기도공공투자관리센터장 나왔습니까? 
</p>
<p><b>○ 경기도공공투자관리센터장 김도일 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 경기도공공투자관리센터 총괄기획부장 나왔습니까? 
</p>
<p><b>○ 경기도공공투자관리센터총괄기획부장 이상미 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 경기도공공투자관리센터 투자분석평가1ㆍ2부장 나왔습니까? 
</p>
<p><b>○ 경기도공공투자관리센터투자분석평가1ㆍ2부장 하태권 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 다음은 선서요령을 설명드리겠습니다. 선서는 증인들을 대표하여 원장이 발언대로 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인께서는 자리에서 오른손을 들어주시면 됩니다. 그러면 증인께서 선서를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라 기획재정위원회 소관 업무에 대한 2019년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2019년 11월 12일 직위 원장, 성명 이한주. 이상 선서합니다. 
</p>
<p><b>○ 위원장 정대운 </b> 모두 자리에 앉아 주시기 바랍니다. 계속해서 간부인사와 업무보고를 받도록 하겠습니다. 경기연구원 원장은 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원장님, 소개해 주셔서 감사합니다. 안녕하십니까? 경기연구원 이한주입니다. 오늘 위원님들을 모시고 2019년 경기연구원 업무에 대해 보고드리게 되어 기쁘게 생각합니다. 우리 연구원은 경기도의 새로운 정책플랫폼으로서 경기도민의 삶의 질 향상을 위해 경기도정 현안을 해결하고 경기도 미래비전을 제시하는 등 임직원 모두가 열정을 다해 정책개발에 매진하고 있습니다. 향후에도 연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  그리고 보고에 앞서 연구원의 주요 간부를 소개해 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 이상대 연구부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 김재용 경영부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  문미성 연구기획본부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 균형발전본부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김도일 경기도공공투자관리센터 소장입니다. 
