<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  빈미영 휴먼교통연구실장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동영 생태환경연구실장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박경철 연구기획부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김도균 정책분석부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  주요 간부를 소개해 드렸습니다. 다음으로는 마침 참고인으로 참석한 저희 기관 노동조합……. 
</p>
<p style="padding-left:1.2em">  죄송합니다. 너무 길어서 다음 페이지로 넘어가서, 송구스럽습니다. 
</p>
<p style="padding-left:1.2em">  손호철 행정지원부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박인숙 재정지원부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  배미성 성과관리부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이덕환 홍보ㆍ정보부 겸 대외협력부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상미 공공투자관리센터 총괄기획부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  공공투자관리센터 1ㆍ2부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  죄송합니다. 페이지가 넘어가서 그런 상황이 벌어졌습니다. 송구합니다. 
</p>
<p style="padding-left:1.2em">  간부소개를 마치고 연구원 주요업무를 보고드리기 전에 노조에서도 참고인으로 참석했기 때문에 소개를 드리고자 합니다. 
</p>
<p style="padding-left:1.2em">  이은환 노조위원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  하는 김에 마저 할까요? 
</p>
<p><b>○ 위원장 정대운 </b> 아뇨, 놔두세요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 강철구 부위원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  조희은 부위원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  지금부터 연구원의 주요업무를 보고드리겠습니다. 보고순서는 기본현황, 주요 연구사업 추진전략, 연구사업 추진체계, 2019년 주요성과, 2019년 분야별 성과 순으로 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 1쪽 기본현황입니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 연구원 조직은 본원이 2본부 2센터 5실 7부로 구성되어 있고 부설기관인 경기도공공투자관리센터가 3부로 구성되어 있습니다. 우리 원의 인력은 본원에 원장 1명, 부원장 2명, 연구직 54명, 관리ㆍ정보ㆍ기능직 24명 등 81명이 근무하고 있으며 부설조직인 경기도공공투자관리센터에는 투자분석직 8명과 관리직 1명 등 9명이 근무하고 있어 본원과 경기도공공투자관리센터를 합하면 총 90명의 정규직원이 근무하고 있습니다. 정규직 외 별도 정원으로서 계약직원 91명이 있는바 여기에는 초빙연구위원 11명, 연구원 54명, 행정원 10명, 계약직 16명이 근무하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 2쪽 주요기능입니다. 자료를 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 3쪽 예산 현황에 대해 보고드리겠습니다. 올해 총 예산규모는 278억 원으로 일반회계 227억 원, 수탁용역사업 특별회계 30억 원, 공공투자관리센터 20억 원이 배정되어 있습니다. 일반회계의 수입ㆍ지출내역을 보다 상세히 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  수입항목은 경기도 출연금이 188억 원으로 일반회계 예산의 82.6%를 차지하고 있습니다. 주요 지출항목으로는 인건비가 130억 원으로 57.3%를 차지하고 있으며 연구사업비는 68억 원으로 30%의 비중을 보이고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 4쪽 연구사업 추진전략을 말씀드리겠습니다. 허락하시면 자료로 갈음하겠습니다. 이후 원 내외 토론과정을 거쳐 민선7기 도정방향에 부합하는 추진전략을 수립하여 도민의 요구에 부응하는 조직으로 변화해 나갈 것입니다. 
</p>
<p style="padding-left:1.2em">  다음은 5쪽 연구사업 추진체계입니다. 우선 정책방향 및 대안을 수립하는 연구과제사업이 있습니다. 연구과제사업으로는 학술적 역량강화를 위한 기본연구과제, 도정 지원을 위한 단기정책과제와 중장기 전략과 비전을 제시하기 위한 전략정책과제, 내외에 정책 이슈와 대안을 제시하는 이슈&진단 등을 운영하고 있습니다. 또한 대내외 소통과 협력을 위한 정책세미나, 학술지 발간, 콘텐츠 홍보, 의정교류 등 연구부대사업을 수행하고 있으며 효율적 연구 지원을 하기 위하여 정보자료 지원, GIS사업, 전산사업 등 연구지원사업을 수행하고 있습니다. 아울러 향후 연구원의 역량강화를 위해 인적자원 개발에 보다 중점을 두어 추진하기 위한 기본계획을 수립하고 있습니다. 
</p>
<p style="padding-left:1.2em">  2019년 주요성과에 대해 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  6쪽 연구성과입니다. 2019년 9월 30일 기준으로 연구과제 및 정책현안 분석 완료 301건, 진행 98건 등 총 399건을 수행하였거나 수행하는 중입니다. 2019년 계획 대비 79.8%에 해당합니다. 137건의 연구과제 추진을 통해 경기도의 정책 및 시군 중장기 발전전략을 제시하였습니다. 또한 262건의 정책현안 분석을 통해 민선7기 핵심공약인 기본소득, 남북협력 및 평화경제, 일자리 전략, 4차 산업혁명 선도 등 변화하는 도정 주요이슈에 역점을 두고 대응하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 7쪽 주요연구 목록입니다. 경기도의 남북 환경협력방안연구, 경기비전 2030, 정부의 재정분권 추진과 경기도 재정혁신방안연구 등 주요 연구과제를 수행하였습니다. 경기도의회 및 경기도에서 의뢰하여 수행한 정책연구과제는 총 52건에 달하며 자체 32건을 포함하면 84건이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 8쪽 2019년 분야별 연구성과에 대해 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 연구방향입니다. 정책환경 및 주요 트렌드에 입각하여 대한민국과 경기도가 당면한 문제를 해소하고 혁신과 발전의 발판을 마련한다는 기본방향을 설정하였습니다. 
</p>
<p style="padding-left:1.2em">  주요내용입니다. 4차 산업혁명으로 인한 사회경제 패러다임 변화에 대응하여 공유경제, 스마트시티 등 새로운 비즈니스 모델을 창출하기 위하여 노력하였습니다. 저성장, 양극화, 청년실업, 저출산, 고령화 문제를 해결하기 위하여 새로운 복지모델을 구축하기 위하여 노력하였습니다. 미세먼지, 인공지능, 구제역, 메르스, 지진 등 도민의 안전과 건강을 향상시키기 위하여 빅데이터를 활용한 예보 시스템을 구축하는 데 기여하였습니다. 지방분권 강화에 따라 실질적 권한 강화를 위한 제도개선, 지방의회의 실효성 강화 및 주민주권 실현을 위한 연구를 수행하였습니다. 
</p>
<p style="padding-left:1.2em">  남북평화협력 시대의 도래에 부합하는 남북교류 및 경제협력 연구를 수행하였습니다. 경기도 지역 간 발전 및 삶의 질 격차를 줄이기 위한 인프라 확충 및 경기도 동북부지역 지원, 투자확대를 위한 연구를 수행하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 GRI 중기 8대 어젠다 및 주요과제입니다. 연구원은 대내외 환경변화와 주요 이슈를 분석하여 GRI 중기 8대 어젠다를 설정하였고 이에 근거하여 주요과제를 마련하였습니다. 자세한 내용은 자료를 참고하시길 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  다음은 각 부서별 성과에 대하여 간략히 요약하여 보고드리겠습니다. 보고자료 10쪽부터 16쪽이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 자치분권연구실입니다. 주요 연구로는 지방 행ㆍ재정 기능강화와 재정립ㆍ지방분권, 남북협력 등의 연구를 하고 있습니다. 2019년에는 정부 및 공공부문의 역량 강화, 지방분권, 남북관계, 기본소득형 국토보유세 등 관련 연구를 수행하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 11쪽 도시주택연구실입니다. 주요 연구분야는 국토 및 지역개발정책 제도, 수도권 정책과 그린벨트, 주택정책, 도시재생, 도시ㆍ농촌설계, 공간 및 지리정보 관련 정책 등을 연구하고 있습니다. 2019년 연구방향은 개발이익 도민환원제를 마련하고 경기도 공공발주사업의 효율적 관리와 공공성 확보방안, 규제로 인하여 특별한 희생을 한 지역에 대한 특별한 지원대책 마련 등을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 경제사회연구실입니다. 주요 연구분야는 지역경제 및 산업정책, 4차 산업혁명 등 신성장사업, 문화ㆍ관광산업 연구 등을 연구하고 있습니다. 2019년 연구방향은 4차 산업혁명과 연계한 미래형 혁신산업단지의 조성, 기본소득 및 지역화폐의 도입방안 연구, 혁신적 창업시스템 구축을 통한 일자리 창출 확대 등을 수행하였습니다. 특히 일본과의 경제 마찰에 즈음하여 소ㆍ부ㆍ장 산업의 현황과 발전방안을 연구한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 13쪽 교통물류연구실입니다. 주요 연구분야는 삶의 질이 보장되는 교통환경 조성, 안전하고 편리한 대중교통서비스체계 제공, 편리하고 효율적인 광역교통체계 구축, 4차 산업혁명과 연계한 지능형 교통체계 구현 등을 연구하고 있습니다. 2019년 연구방향으로 새경기 버스 준공영제, 경기교통공사 설립, 남북 연결 철도사업 추진을 위한 기초조사 및 철도물류체계 개선, 수도권 미세먼지 저감대책으로 전기버스 도입 확대 등에 관한 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 생태환경연구실입니다. 주요 연구는 지속가능 발전과 녹색경제, 상하수도 정책, 환경안전 및 보건, 폐기물, 자원순환, 대기 및 유해물질, 자연환경과 공원ㆍ녹지, 기후변화 및 에너지정책 등을 연구하고 있습니다. 경기도 미세먼지 노출평가 및 건강지도 작성, 경기도 수소차 보급 활성화를 위한 충전 인프라 구축방안 등의 연구를 수행할 예정입니다. 2019년 연구방향으로는 경기도 미세먼지 집중배출원 분석 및 관리방안, 남북 환경협력방안, 한강하구 평화적 활용을 위한 남북협력방안 등에 집중하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 북부연구센터입니다. 주요 연구분야는 경기북부지역 삶의 질 향상, 지자체 남북교류협력 및 통일 정책, DMZ 및 접경지역 등을 연구하고 있습니다. 2019년 연구방향으로는 한반도 신경제지도 구상과 경기도 전략, 남북개발협력포럼 운영, 군사시설규제 등의 재조정입니다. 특히 이번에 DMZ포럼을 성공적으로 수행하여 국제적으로 경기도의 위상을 높이는 데 크게 기여하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 시군연구센터입니다. 주요 연구분야는 경기도, 31개 시군과 공동 정책의제를 발굴하여 경기도와 시군 간 협치를 지원하였으며 도내 시군 연구기관과 네트워크를 구축하여 정책연구 및 협치를 강화하기 위한 연구를 하고 있습니다. 부족한 인원으로 열심히 연구하고 있다고 말씀드리고 싶습니다. 
</p>
<p style="padding-left:1.2em">  다음은 17쪽 연구지원사업 중 연구부대사업 부분으로 경기도의회, 경기도, 시민단체, 전문가 등의 네트워크 구축을 통해 의정발전방안의 모색을 위한 포럼을 운영하고 있으며 시군의 주요현안에 대하여 경기도, 경기도의회, 시군, 전문가 등이 참여하여 정책 의견수렴 및 현장밀착형 솔루션 지원을 위한 의정연구 교류를 진행하고 있습니다. 또한 정책세미나포럼, 동향분석과 전망, GRI학술지 발간, 콘텐츠 홍보, 대외협력교류를 추진하고 있습니다. 자세한 내용은 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 18쪽 연구지원사업 부문으로 정보자원 지원, 전산사업, GIS사업을 추진하고 있습니다. 자세한 사업 내용은 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 19쪽 경기도 공공투자관리센터입니다. 경기도 공공투자관리센터는 경기도 공공투자사업에 대한 전문적 관리를 통한 재정투자의 합리성ㆍ효율성 그리고 책임성 제고를 목적으로 설립된 기관으로서 경기도의 재정건전성 확보를 위한 컨트롤타워가 되겠다는 비전을 가지고 있습니다. 2019년 사업방향으로는 투자분석전문기관으로서 경기도 재정사업에 대한 투자의사결정이 객관적이고 합리적으로 이루어질 수 있도록 지원하고자 하였으며 나아가 지방분권시대 재정사업 거버넌스 혁신 및 지방정부의 정책역량을 강화하기 위한 사업을 추진하고자 하였습니다. 주요 사업으로는 투자심사 대상사업에 대한 사전검토, 재정사업평가, 중앙투자심사 및 민간투자사업 업무지원, 투자심사 이력관리 및 제도개선 연구 등을 수행하였습니다. 자세한 사업 내용은 자료를 참조해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요업무를 모두 마치겠습니다. 들어주셔서 감사합니다. 
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 정대운 </b> 경기연구원장 수고하셨습니다. 다음은 감사 질의 답변 순서입니다만 감사에 앞서 출석하신 참고인은 이미 원장님께서 소개했기 때문에 일일이 소개는 하지 않겠습니다. 바쁘신 와중에도 출석해 주셔서 감사위원장으로서 감사의 말씀드립니다. 위원님들께서 참고인에게 질의하실 사항은 우선적으로 진행해 주시면 감사드리겠습니다. 감사의 효율적인 진행을 위해 질의는 일문일답으로 하되 우선 위원님들 한 분당 15분씩 질의를 드리도록 하겠습니다. 본질문이 끝나면 감사 진행상황과 시간 등의 제반여건을 감안해 추가질문을 진행하도록 하겠습니다. 다만 원활한 감사 진행을 위해 추가질문 시 거수로 신청해 주시면 감사위원장이 감사 상황 및 질의 순서에 따라 발언시간을 드리도록 하겠사오니 위원님들의 양해 부탁드립니다. 만약 시간의 제약으로 인해 준비하신 질의를 미처 다 하지 못하신 위원님께서는 추후 서면으로 질의가 가능하오니 이를 활용해 주시기 바랍니다. 또 위원님들의 질의사항 중 원장을 비롯한 증인의 답변이 어려울 경우 부원장 및 본부장, 실장, 부장 등의 실무자가 답변해도 좋겠습니다. 먼저 질의에 앞서 추가자료를 요청하실 분 있으면 추가자료를 요청해 주시기 바랍니다. 추가자료 요청하실 분 계십니까? 없나요?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)  
</p>
<p><b>○ 신정현 위원 </b> 아까 전에 했던 건데 마저 마무리를 못 하고 끝내서요.
</p>
<p><b>○ 위원장 정대운 </b> 어떤 거죠? 자료요청? 네, 말씀하세요.
</p>
<p><b>○ 신정현 위원 </b> 제가 드리고 싶은 자료요청은 각 연차별 1인당 연구실적 5개년을 받아보고 싶은데 연차별로 책임기준만 하는 것이 아니라 각 연구위원들이 현재 수행하고 있는 공동연구 그리고 정책연구, 이슈&진단과 같이 참여하는 모든 연구를 카테고리화해 가지고 제출해 주시기를 부탁드리겠습니다. 이슈&진단, 현안대응, 공동을 모두 포함해 달라는 부탁입니다. 이상입니다.
</p>
<p><b>○ 위원장 정대운 </b> 감사합니다. 장시간 행정사무감사를 해야 되는데 우리 원장님은 자리에 앉아서 진행하도록 하겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 감사합니다.
</p>
<p><b>○ 위원장 정대운 </b> 그리고 우리 부원장, 본부장, 실장, 부장님들은 혹시 위원님들의 요구가 있을 때는 발언대로 나오셔서 직ㆍ성명을 얘기하고 답변을 해 주셔야 됩니다. 질의하실 위원님, 김우석 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김우석 위원 </b> 포천 출신 김우석 위원입니다. 원장님 오랜 만에 뵙는데요. 작년에 했던 약속이 기억나서 한번 여쭤볼게요. 제가 그때 뭐라고 말씀을 드렸었느냐면 경기도가 ‘세계속의 경기도’로 캐치프레이즈를 하고 있는데 GRI도 ‘세계속의 GRI’가 돼야 되는 거 아니냐라고 한번 여쭤본 적이 있어요. 그때 “아, 맞습니다. 그렇게 하겠습니다.” 말씀하셨거든요. 기억나세요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 기억나고 있습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그동안 그런 ‘세계속의 GRI’를 목표로 활동을 하시면서 분명히 애로사항이 있었을 것 같은데 한 번도 그 애로사항에 대한 이야기가 없어서 참 잘 진행이 되는구나라고 판단을 하고 있었어요. 좀 어떠신지요? 
</p>
