<p><b>○ 김우석 위원 </b> 거기에서는 “연구원의 효과적 운영을 위한 심의의결기구로서 연구위원회와 심의위원회를 둘 수 있다.” 이렇게 되어 있어요. 그래서 정관에 위임을 받아 제정된 규칙이 있는 거죠. 그런데 심의위원회를 보다 보니까 좀 특이사항이 있더라고요. 통상 법제처에서 권고하는 것들은 그리고 저희가 경기도 내에서 위원회를 구성할 때는 통상 어떻게 이루어지느냐면 “위원회의 위원 수는 몇 명 이내로 한다.”, “당연직 위원은 누구누구로 한다.” 예를 들면 몇 명으로 구성할 수 있고 위촉직 위원들도 어떻게 어떻게 한다라고 명시가 되어 있고 또 하나는 심의의결을 해야 되는 부분이기 때문에 가부동수가 나오면 안 돼서 홀수를 권장한다라고 법제처에서는 권고를 하고 있어요, 위원회 구성할 때. 그런데 경기연구원 심의위원회를 보면 상당히 불투명하게 되어 있어요. 그래서 여쭤볼게요. 심의위원회가 지금 현재 몇 명으로 구성되어 있죠? 
