<p><b>○ 김우석 위원 </b> 말씀하세요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 심의위원회는 경기연구원의 연구 자체를 제외한 나머지 연구 보조행정을 전체적으로 여기서 결정을 합니다. 예컨대…….
</p>
<p><b>○ 김우석 위원 </b> 되게 중요한 기구죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 원장이 판단을 할 때까지 자료를 제출해 주는 매우 중요한 기관인 거는 맞습니다마는 그러나 연구원에서 사람을 뽑거나 이럴 때 가장 중요하게 제가 의견을 들어야 되는 부분들은 역시 실장님들입니다, 연구 일선을 담당하시는. 그래서 이쪽에 속한 분들을 많이 배치를 하는 게 보통이고요. 그럼에도 불구하고 일반 간부가 아닌 분들의 의견을 청취하기 위한 조항을 좀 넣어놨습니다. 이게 본래는 노동조합이 아니라 비보직자로 들어가 있던 것들인데 그 조항을 지난번 규정개정을 하면서, 제가 오기 전입니다마는 노동조합 약관명으로 돼 있어서 그 약관명이 제가 오기 전까지의 관행은 2명이었습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그러니까 관행인 거잖아요, 지금 계속해서 말씀하시는 부분은. 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 김우석 위원 </b> 이건 지금 규칙이에요, 약속인 거고. 그러니까 약속을 여러 가지로 해석할 수는 있어요. 관행상 이랬었다라고 말씀하실 수 있어요. 그런데 여기에서는 뭐라고 되어 있냐면 “추천하는 자”예요, 그냥. 그럼 이걸 좀 바꿀 필요는 있어 보이죠, 지금?
</p>
<p><b>○ 경기연구원장 이한주 </b> 어떻게……. 
</p>
<p><b>○ 김우석 위원 </b> 명확하게 하기 위해서 위원회 정수를 정하고. 그렇죠? 그게 좀 오해의 소지가 없지 않겠습니까? 어떠세요? 이 조문대로라고, 이 규칙대로라고 한다면 노동조합은 6명 중에 5명을 추천해도 돼야 되는 거예요, 그냥.
</p>
<p><b>○ 경기연구원장 이한주 </b> 6명을 인원을 정하지 않았기 때문에 5명이 될 수도 있습니다, 말씀하신 대로. 그러나 경영부원장하고 연구기획본부장…….
</p>
<p><b>○ 김우석 위원 </b> 그러니까 이게 심의위원회를 10명 이내로 한다, 20명 이내로 한다 하더라도 이 규칙상에서 “노동조합이 추천하는 자”로만 되어 있으면 인원수와 무관하게 추천하면 되는 거예요, 그냥.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그거는 그렇지 않다고 생각합니다. 이건…….
</p>
<p><b>○ 김우석 위원 </b> 그래서 이제 지금 말씀하시는 관행을 얘기하시는 거고. 그러니까 관행보다 우선하는 건 규칙이라고 말씀을 드리는 거예요. 그러니까 관행상 이래왔다고 계속 주장하시는 것보다는 이걸 좀 명확하게 조정하는 게 어떻겠냐라는 의견을 좀 드리는 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 말씀하신 대로 이 조항의 다소간의 불명확한 조항에 대해서 저희들이 이 부분을 명확히 해서 정비하도록 하겠습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그렇죠. 왜냐하면 이거를 명확하게 해 주셔야 하는 이유는 이 심의 위원회가 하는 일이 상당히 중요하다고 보는 거예요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 김우석 위원 </b> 이게 지금 보면 거기 나와 있는 채용, 재임용, 연봉 뭐 이런 거예요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다. 
</p>
<p><b>○ 김우석 위원 </b> 되게 중요한 사항이기 때문에 심의위원회 구성하는 부분에 대해서 좀 명확하게 해 주셨으면 좋겠다고 요청을 드리는 거고요, 좀 더 말씀드릴 게 있는데 시간이 거의 다 돼 가네요. 추가질의 시간에 좀 말씀을 드리고요.
</p>
<p style="padding-left:1.2em">  그리고 지금 이사회의 의결을 통한다고 하셨어요, 아까 전에. 인원수 조정하는 부분을. 근데 이야기를 듣다 보니까 여러 가지 의견을 수렴해서 원장님께서 판단한다, 그럼 이거 수시로 아무 때나 원장님 판단에 의해서 이게 결정이 될 수 있는 건가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 그러지는 않습니다. 원장이 판단할 수 있다고 해서 모든 걸 원장이 자다가 일어나서 하는 건 아니고요. 
</p>
<p><b>○ 김우석 위원 </b> 여러 가지 의견을 수렴하셔 가지고 좋은 방향으로 이끌기 위해서 조정을 하실 것 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 해서 이사회에 제출하고 이사회에서 판단해 주시면 그 판단을 따르고 있습니다. 
</p>
<p><b>○ 김우석 위원 </b> 사실 이제 연봉이라든지 제명 관련해서는 노조 쪽의 이야기도 좀 더 많이 반영이 되어야 될 것 같은데 구성원 6명 중에서 추천하는 자 1인으로 되어 있는 것 같은데 이게 비율이 좀, 어떻게 생각하세요? 맞다고 생각하세요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 지금 말씀하신 노조와의 관계는 우선 임금과 단체협약에 대한 규정이 있고 또 분기별로 한 번씩 정상적으로 저희들이 노사협의회를 하고 있기 때문에…….
</p>
<p><b>○ 김우석 위원 </b> 정상적으로?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 노사협의회를 통해서 충분히 의견개진을 하고 있으며 또 이런 경우에 노동조합원이 아닌 사람들도 있기 때문에 전반적인 의견수렴을 하여야 하고 특히 노동조합에서 이의제기를 하면 그 문제에 대해선 저희들이 업무 효율의 관점에서 그 부분들을 협의하고, 그러나 부득이한 경우 업무 효율상 필요하다고 한다면 규칙대로 실시를 하고 있습니다.
</p>
<p><b>○ 김우석 위원 </b> 더 질문드릴 건 추가질의 시간에 하고 시간이 마무리돼서 저는 이만 마무리하도록 하겠습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 김우석 위원님 수고하셨습니다. 다음 질의하실 위원님, 박관열 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 박관열 위원 </b> 광주 출신 박관열 위원입니다. 원장님, 안녕하세요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 박관열 위원 </b> 7쪽에 보니까 저성장, 양극화, 청년실업, 저출산, 고령화 문제 이게 참 우리 과제, 난제잖아요. 이 문제를 하나 해결 않고는 대한민국 미래 참 없다고 보여지는데 경기도는 그런데도 불구하고 해결해야 되잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇게 생각합니다.
</p>
<p><b>○ 박관열 위원 </b> 지금 분야별 성과에 저성장, 양극화, 청년실업, 저출산, 고령화를 말씀하셨는데 어떤 성과가 있나요? 연구성과. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 말씀하신 대로 어느 것 하나 쉽지 않은 국가적 난제에 해당하는 거는 위원님들이나 똑같이 생각하고 있습니다. 저희들이 그래서 이런 것들에 대한 포괄적인 관점을 갖기 위해서 기본소득을 매우 중요한 개념으로 갖고 양극화나 아니면 고령화나 저출산에도 저희들은 포괄적으로 적용된다고 판단해서 기본소득에 대한 연구들을 부지런히 하고 있으며 또한 고령화와 관련된 별도의 연구들 그다음에 양극화에 대한 여러 가지 연구들, 토지보유세 등을 포함하여 연구들을 수행하고 있습니다. 다만 이런 것들이 성과가 나고 이러기에는 꽤 많은 시간이 걸릴 거라고 판단되고 또 저희들은 명확히 나타날 거라고 믿지만 그러나 시간이 흐르면서 여러 가지 효과들과 중첩되어 나타날 수 있기 때문에 효과를 분리하는 일은 또 별도의 노력이지만, 그러나 저희들이 이 부분을 위해서 도정과 위원님들을 반영하기 위한 여러 가지 노력들을 하고 있다 이렇게 말씀드릴 수 있겠습니다.
</p>
<p><b>○ 박관열 위원 </b> 저도 기본소득이 그 대안의 하나라고 생각은 하고 있습니다. 그렇지만 이게 저성장, 양극화, 청년실업, 저출산, 고령화는 과제연구만 하는 게 아니라 대안을 좀 제시해 가지고 적절히 경기도가 대안을 제시해, 경기연구원이 특히 좀 대안을 제시해 주셨으면 좋겠고. 
</p>
<p style="padding-left:1.2em">  그리고 경기지역 간 발전 및 삶의 질 격차가 있잖아요. “중첩규제, 인프라 확충, 산업기반 조성, 문화ㆍ교육ㆍ환경 등 동북부지역 주민의 삶의 질 강화를 위한 특별한 지원과 투자 확대.” 특별한 지원과 투자 확대라고 말씀 주셨는데 실제 최근에 경기연구원에서 조사한 것 있잖아요. 경기도 중첩규제 비율분석, 알고 계시죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네
</p>
<p><b>○ 박관열 위원 </b> 거기에 광주가 2.4고 또 어저께도 내가 말씀드렸습니다마는 양평이 1.79, 이천이 1.76 이런 수치는 원장님 잘 알고 계시죠, 그게 뭘 가리키는지?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 박관열 위원 </b> 내가 왜 이걸 말씀드리냐면 특별한 지원과 투자 확대라고 그랬잖아요. 그런데 보면 실제 이게, 이것도 경기연구원 자료예요. 산업단지 면적비율을 보면 이게 0인 곳이 몇 군데 있어요, 경기도에. 산업단지가 없다는 것 아니에요. 고양시, 과천시, 광명시, 광주시, 구리시 그리고 양평군, 하남시. 이게 산업단지가 없으면 그 지역주민들이 뭘 먹고살아야 되나요? 일자리가 없다는 것 아니에요, 좋은 일자리가? 그런 좋은 일자리를 경기연구원이 이렇게 정책과제로써 수립을 해 줬으면 좋겠다는 말씀을 드리는데 답변 좀 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님 말씀하신 대로 지역 간 격차 문제 그다음에 또 한국사회 전체가 앓고 있는 잠재성장률 저하에 따른 고용축소 문제, 이런 문제는 매우 중요한 문제입니다. 경기연구원에서는 연초부터 우선 손쉬운 연구를 좀 수행하였습니다. 의원님 중의 한 분과 협력을 하였습니다. 김명원 도의원과 협력을 해서 건설산업 일자리 및 숙련기능인력 확대와 관련된 기획을 하였고 그 기획이 도에 반영되어서 현재 집행 중에 있다 이런 말씀을 좀 드리겠습니다. 가장 저희들로 보기에는 비교적 손쉬운 그런 상황이어서 그렇게 진행을 했고요.
</p>
<p style="padding-left:1.2em">  그다음에 산업단지 등과 관련하여서는 저희들이 중간의 연구로써 제조업 르네상스와 관련된 연구를 5월 달부터 수행을 하였습니다. 아니, 4월 달부터 수행을 하였습니다. 그래서 저희들이 연구하였는데 다행히 대통령께서 똑같은 제목의 제조업 르네상스 계획을 발표해서 아직 정부로서도 내용을 충분히 확충은 못 하였습니다. 기본적으로 방향은 저희와 같은 방향이었고 이것은 연구내용을 전부 우리 경제실로 이전하였고 경제실에서 그중에 정책을 선택하기로 하였습니다. 기본적인 내용은 뿌리산업에 대한 확충이었고요. 뿌리산업이라고 하면 조립 그다음에 가공 이런 것들을 의미하게 되겠습니다.
</p>
<p style="padding-left:1.2em">  그런 것들을 의미하였고 그다음에 일반 중소제조업에 대한 역량강화 사업이 있습니다. 예를 들자면 대기업 퇴직자들을 활용하여 이분들의 기초적인 영리마케팅 등의 역량을 강화할 수 있는 사업 등을 말하고 있습니다. 이런 것들을 전달하여서 도가 그 부분에 대한 연구들을, 정책화 혹은 사업화를 강구하고 있다 이렇게 말씀드릴 수 있겠습니다. 다만 말씀하신 대로 지역 간 격차에 대한 도 정책은 처음부터 우리 도정에 있어서 특별한 희생에 대한 특별한 보상이라는 이름으로 매우 강렬한 인상을 가진 정책으로써 있습니다마는 이 부분들이 위원님 잘 아시는 대로 수정법이라든가 하는 것들과 깊은 연관이 있었고 도정부에서 그리고 경기연구원에서도 이 부분을 어떻게 풀어나갈 수 있을지에 대한, 부단히 노력하겠습니다. 이 부분들이 쉽게 안 된다면 잊지 않고 계속해서 연구하고 정부와 같이 협력하여, 예를 들자면 국가균형발전위원회를 저희들이 주로 같이 협력을 하고 있는데 협력해서 위원님들이 겪고 계신, 그리고 주권자들이 겪고 계신 고통에 대해서 저희들이 보답이 될 수 있도록 노력하겠습니다. 
</p>
<p><b>○ 박관열 위원 </b> 우선 과천, 광명시, 구리시, 하남시 이런 곳들은 도시화가 완벽하게 진행은 안 됐지만 그런 지역에는 상업시설이라든가 나름대로 생활기반시설이 만들어져 있어요. 그런데 고양이나 광주나 양평 같은 곳은, 특히 광주나 양평은 적어도 우리가 아까도 규제 피해지수를, 중첩규제 피해지수가 지금 2.49고 양평이 1.79고. 굉장히 규제피해가 굉장히 높게 돼 있는 곳에는 그런 어떤 문제를 적어도 국가나 그리고 경기도가 해결해서 산업단지를 유치할 수 있도록 좀 노력을 해 줘야 되는 것 아닙니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 도지사께서도 당청 그다음에 광역협의회의를 할 때 이 문제를 꾸준히 제기하고 있고요. 저희 연구원에서도 최근 GTX의 개통과 더불어 실효성 있는 산업단지 개발을 위한 연구들도 저희들이 열심히 하고 있다 이렇게 말씀드릴 수 있겠습니다. 없는 데는 자족기능 강화를 위한 저희들 연구, 3기 신도시와 관련하여 자족기능 강화연구를 하고 있고 광명시 등 낙후 산업시설과 관련해서는 제조업 르네상스와 관련된 연구로써 이 부분들을 연구원에서 지적하여 저희들이 되는 대로 도로 이전하고 도에서 가능한 범위 내에서 사업화시키려는 그런 과정에 있다 이렇게 말씀드릴 수 있겠습니다. 말씀하신 대로 산업단지는 경기도가 허가권을 가지고 있음에도 불구하고 이 부분들이 지역갈등이라든가 그다음에 산업재배치 문제라든가 또는 최근 산업단지들이 전반적으로 쇠퇴화되어지고 있기 때문에 쉽게 쉽게 결정내리기가 좀 어렵다는 점을 이해를 해 주시고요. 
</p>
<p><b>○ 박관열 위원 </b> 그런데도 불구하고 경기연구원이 활발한 연구를 통해서 그런 지역에 산업단지가 만들어질 수 있도록 노력 좀 해 주시고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 더욱 노력하겠습니다.
</p>
<p><b>○ 박관열 위원 </b> 그리고 또 이게 지금 규제 증축비율, 이제 읍면동으로 가보면 실제 광주시 남종면 같은 경우는 3.94입니다. 그러면 3.94라는 수치는 원장님 잘 알겠지만 규제로 4겹을 덮은 것 아닙니까? 네 번을. 그런데 실제 거기 인구가 꾸준히 계속 줄어들고 있는 상황인데 거기에 환경을 가서 보시면 굉장히 유수하고 환경 그 자체가 굉장히 좋습니다. 과거에 조선시대 때에는 거기서 백자를 구워 가지고, 사옹원에서 백자를 구워서 왕실에 진상이 있던 곳 아니에요. 혹시 복원에 대해서 경기연구원이 연구해 볼 생각은 없습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 이 부분 저희들이 최근에는 연구가 없었습니다마는 이 부분 점검을 좀 하도록 하겠습니다. 특히…….
</p>
<p><b>○ 박관열 위원 </b> 아니, 적극적으로. 그렇게 그냥 미지근하게 말씀하지 마시고 한번 적극적으로 연구할 생각이 없으시냐고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 추후 광주시장과 이 부분 적극적으로 협력해서 할 수 있도록 하겠습니다. 
</p>
<p><b>○ 박관열 위원 </b> 그리고 이게 작년 행감에 장애인 채용기준 미달을 지적했지 않습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 박관열 위원 </b> 그런데 경기연구원 2019년 업무보고 자료를 보면 여전히 지금 채용기준이 미달된 상태예요. 어떻게 된 겁니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 한 분을 채용해서 저희들이 기준을 충족하였습니다마는 퇴사를 하는 바람에 다시 또 미달 상태로 되었습니다. 오늘 마침 경기도로부터 저희들이 사전협의를 반드시 하도록 돼 있는데 박사 연구인력, 위원님들께서 주신 인력을 아직 송구하게 못 채우고 있었습니다. 여러 가지 사정은 있습니다마는 송구합니다. 그런데 최근에, 오늘 아침에 나머지 인력을 뽑아도 좋다라고 하는 허락을 받아서 이번에 뽑을 때는 박사님이 됐든 석사님이 됐든 아니면 직원이 됐든 어떤 분이라도 반드시 장애인과 또 저희들이 늘 못 채우고 있는 부분을 채울 수 있도록 하겠습니다. 별도의 공고를 내는 한이 있더라도 이 부분은 하도록 하겠습니다. 
</p>
<p><b>○ 박관열 위원 </b> 경기연구원은 경기도 모범사례가 돼야 되잖아요, 그렇지 않습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그러겠습니다.
</p>
<p><b>○ 박관열 위원 </b> 꼭 그렇게 좀 해 주시고. 2019년 경기연구원 인력증원에 대해서 시군 정책 연구지원과 조직혁신을 위한 인력증원과 결원ㆍ충원 필요성에 대해 지난해 이야기했었죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 박관열 위원 </b> 지금 현재 인력충원 추진현황은 어떻게 되어가고 있습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구원에서, 저희 연구원에 가장 중요한 게 박사님들인데 그 박사님들 총 열네 분을 지금 충원해야 되는 상황입니다. 올 초에 6명을 충원하여서 몇 분만 더 하면 되었으나 그러나 그 사이에 또 두 분이 나가셨습니다. 그래서 총 열네 분을 충원해야 됐고 올해와 내년 초에 걸쳐서 박사님들 열네 분을 조속히 채용하도록 하고 직원 분들도 정규직 두 분과 계약직 세 분이 현재 결원 상태입니다. 그래서 이 부분도 충원하도록 하겠습니다. 
</p>
<p><b>○ 박관열 위원 </b> 광주시 태전동 태전지구 교통대책 방안 지금 연구하고 계시잖아요, 우리 조응래 박사가 하고 계시는데. 지난 10월에 중간보고를 했어요, 경기도 광주시청에 와서. 그런데 관계자들, 광주시 공무원들이 참 잘했다는 평가를 해 줘 가지고 참 저도 기분이 좋았는데. 그와 같이 경기연구원이 그런 평가를 받을 수 있도록 연구과제를 좀 잘 해 주셨으면 좋겠다는 생각입니다.  
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 칭찬해 주셔서 고맙습니다. 격려로 알고 더 열심히 하겠습니다. 
</p>
<p><b>○ 박관열 위원 </b> 수고하셨습니다. 이상입니다.
</p>
<p><b>○ 위원장 정대운 </b> 박관열 위원님 수고하셨습니다. 다음 질의하실 위원님, 거수로 신청해 주시기 바랍니다. 일단 한 분 받고 다음 준비할게요.  
</p>
<p><b>○ 위원장 정대운 </b> 이혜원 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이혜원 위원 </b> 네, 질문하겠습니다. 지난 8월 달에요, 경기연구원에서 연구과제 발굴을 위한 수요조사를 했습니다. 저 그렇게 들었고 우리 위원들한테 경기연구원 정책연구과제를 제출하라고 해서 제가 경기도 어린이 병원비 100만 원 상한제와 관련된 정책연구를 제안한 바 있습니다. 혹시 들으셨나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 이혜원 위원 </b> 그런데 지금 이번에 행감 때문에 제출된 업무보고를 제가 계속 찾았어요. 그리고 오늘 보니까 경기도의회와 경기도에서 의뢰한 52건의 정책과제 중 어디를 봐도 제가 제안한 정책이 없습니다. 이거 어떻게 된 겁니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 잘 지적해 주셨습니다. 위원님께서 말씀하신 그 주제는 저희들이 딱 정확히 맞는 전공자가 없어서 이 부분을 내년도에 위탁연구로 수행하기로 결정을 해 두었습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 아, 그렇습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그래서 진행될 예정입니다. 다만 저희들이 내부연구가 안 될 때에는 외부에 줘서 하거든요, 관련 전문가들로 해서. 그 부분은 그렇게 진행될 예정이라고 말씀드리겠습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 그러면 친절하게 진작 저한테 얘기 좀 해 주시지. 그랬었어요. 저 너무 서운했잖아요. 지금 계속 찾아봤는데 없어 가지고. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 송구합니다. 앞으로는 거론해 주신, 말씀해 주신 내용들에 대해서 꼭 보고를 하도록 하겠습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 앞으로는 친절하게 좀 알려주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 일을 하는 게 더 중요하다고 생각해서 그런 일이 벌어졌습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 그래서 준비한 게 갑자기 머릿속이 하얘졌습니다. 어쨌든 제가 지난번에 5분발언에서 말씀드렸던 것처럼 사실은 무상급식도 저희가 단계적으로 시행하고, 시간이 좀 걸리긴 했지만 우리 아이들에게 국가가 최소한의 식사는 제공해야 된다고 하는 이런 공감대를 형성했듯이 어린이 보건비도 가정형편 때문에 치료받지 못하는 일이 없도록 최소한 어린이들만큼이라도 경기도가 좀 책임져 보자, 그래서 경기도 실정에 맞는 이런 연구과제를 해서 그 결과를 토대로 논의를 시작했으면 좋겠다 이런 생각을 하기 때문에 좀 심도 있게 연구를 해 주시고 도교육청에서도 제 5분발언 답변이 왔는데 “도에서 이 정책을 시행한다면 적극적으로 돕겠다. 적극 지지한다.” 이러한 답변이 왔기 때문에 정말 가능하도록 잘 연구해 주셨으면 좋겠다는 부탁을 드리겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 이것 도하고 협력해서 이 부분과 관련해서 실행 가능성 여부부터 검증하고 위원님께는 되는 대로 바로 알려드리도록 하겠습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 네. 다음은 연구원 보수규정에 관련해서 제가 말씀 좀 드리겠습니다. 연말에 성과연봉 지급하고 계시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 그런데 보니까 기존에 D등급은 성과급을 주지 않았는데 이번에 개정이 됐더라고요. 그래서 D등급은 50%, 기존에는 성과급을 안 줬는데 이번에 개정되면서 50%를 지급하고 C등급은 기존에 50%를 줬는데 이번에 75%, C등급과 D등급은 상향조정이 됐고, 기존에 없거나 낮았던 게 상향조정이 됐고 대신 A등급이나 B등급, 좀 많이 받았던 분들은 하향조정이 됐더라고요. 그래서 50%에서 25% 이렇게 하향조정이 된 걸로 알고 있습니다. 이건 성과급 평준화를 만들었단 얘기죠? 성과급을 평준화시켰다는 걸로 받아들이면 됩니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 좀 플랫화되었습니다. 평평해졌습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 그렇죠? 성과급의 본질적인 목적이 무엇인지 말씀해 주실 수 있습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 성과급은 위원님께서 말씀하신 대로 성과에 따른 생산성에 맞는 급여를 기준으로 하는 그런 임금규칙입니다. 그래서 생산성 측정을 하고 그거에 맞도록 임금을 벌려주는 제도로서 현재 저희 연구원에서의 성과연봉은 전체 급여가 두 부분으로 나눠져 있습니다. 하나는 기본연봉으로 되어 있고요. 기본연봉과 그다음에 성과급여로 이루어져 있는데 성과급여는 대체로 기본연봉의 22%에 해당하는 부분으로 구성돼 있습니다. 그래서 쉽게 얘기하면 8 대 2의 구조를 가지고 있었고 성과연봉이 2에 해당하는, 실제로는 20% 조금 넘습니다. 개인마다 또 차이가 있을 수 있을 겁니다. 이렇게 되어 있는데 이 성과연봉은 50%에서 150%의 스프레드를 가지고 있습니다. 그게 아까 말씀하신 대로 A에서 D등급으로 퍼져 있고 통상적인 분포는 기관의 실정에 맞추어서 하는데 다양한 선택이 있을 수 있다고 생각합니다. 
</p>
<p><b>○ 이혜원 위원 </b> 네. 그래서 이 규정을 변경하는 배경이 말씀하신 것 말고 또 있을까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 2018년 상반기에 개정된 조정인데요. 원래는 0%에서 200%로 성과급이 되어 있었습니다. 그게 2018년 상반기로, 제가 오기 전 일이라서 상반기로밖에 기억이 안 되는데요. 이때 50에서 150%로 스프레드가 축소되었고 축소되는 과정에서 다소간에 평평하게, 좀 균등화가 되어 있었습니다. 그래서 이건 그 당시에 여러 가지 고려가 있었을 것으로 생각합니다, 추측건대. 가장 중요한 이유는 문재인 정부 출범 이전에 그때 모든 공공기관을 성과급여로 하겠다고 하는 기획재정부의 의도가 있었고 이게 기관에서 무리하게 강행되었던 그런 측면이 있습니다. 물론 저희는 판단 나름이겠습니다마는 아까 말씀하신 대로 20% 성과급이기 때문에 나머지는 사실상 호봉제인데 무리한지에 대한 것들은 저 개인적으로 그렇게 무리한 건 아니라고 판단하는데 그러나 그때 분위기가 그 이전 정부의 성과연봉제들을 없애자라고 하는 분위기가 공공기관 전체의 경향과 조류였고 저희 연구원에서도 그게 반영되었지 않았나 이렇게 생각합니다. 
</p>
<p><b>○ 이혜원 위원 </b> 네. 이거와 관련해서 혹시 노동조합의 입장은 무엇인지 아십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 노동조합은 뭐 직접 들어보시죠. 
</p>
<p><b>○ 이혜원 위원 </b> 혹시 노동조합 위원장님 잠깐 답변 좀 해 주실 수 있으시죠? 
</p>
<p><b>○ 참고인 이은환 </b> 경기연구원 노조위원장 이은환입니다. 성과연봉에 대해서는 사실 저희 구성원들이 22%의 연봉을 떼서, 사실 풀링해서 경쟁을 통해서 가져가는데 그 22%가 너무 과도하다. 그리고 지금은 0~200%에서 50~150%로 바꿨지만 그 역시 1등과 꼴등의 차이는 1,600만 원의 연봉 차이가 있습니다. 그래서 그거에 대해서 사실 협력연구를 한다고 하지만 실제로는 다 모두가 경쟁자입니다. 제가 자료를 줌으로 인해서 저 박사가 더 좋은 성적을 받고 저보다 많은 연봉을 받아갈 수도 있는 그런 상황이고요. 그래서 문제의식은 딱 두 가지입니다. 22%가 너무 과도하다. 그리고 1등과 꼴등의 차이가 너무 크다. 그래서 협력연구, 융합연구가 참 힘들다. 위화감이 너무 크다. 그렇게 요약해서 말씀드리면 될 것 같습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 네, 고맙습니다. 저도 사실 이와 관련해서 성과급 평준화는 당연히 동의를 하고 있고요. 다만 혹시 이것으로 인해서 노노갈등이 생기지 않을까라고 하는, 예를 들어서 이 성과급 평준화가 성과급 본질적인 목적인 성과 유인 독려가 일부 퇴색된다라고 하는 우려들이 나오고 있어서 이거와 관련해서 이런 유인책을 어떻게 구성할 것인지 좀 듣고 싶었던 거고요. 어쨌든 이렇게 하향조정된 연구원들의 사기저하를 어떻게 극복할 건지, 보수규정을 바꾸는 것 말고 서로가 동의할 수 있는 그런 또 다른 기준책이 있는지 그게 좀 궁금해서 물어봤습니다. 제가 연구원 성과평가서를 보니까 이번에 평균점수가 94.8점이 나왔더라고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 이혜원 위원 </b> 이 점수와 성과급 지급과 관계가 있나요? 최고점수가 98.5점으로 나왔고 최저점수가 88.2점으로 나왔던데 평균 94.8점. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 잠깐만 그 자료 제가 확인 좀 하겠습니다, 어떤 자료인지. 
</p>
<p><b>○ 위원장 정대운 </b> 담당자 없어요? 담당자가 좀……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 자료 받아서 제가 대답하겠습니다. 위원님, 말씀 중에 큰 개요를 말씀드리자면 기관의 책임자로서 저는 주권자들 그다음에 도와 의회의 명령을 받들어서 생산성 있게 일을 추진해야 한다는 명령을 받고 있습니다. 그건 저의 책무라고 생각하지만 또 한편에서 우리 구성원들의 행복을 책임져야 되는 그런 자리이기도 합니다. 위원님들께 좀 부탁을 드리고 싶은 말씀은 저희가 연봉 구성이 호봉급 대 성과급이 8 대 2로서 보는 각도에 따라서 어떤 분들은 “이건 너무 호봉급이 많다.” 이렇게 보실 수 있는 분이 있고 또 어떤 분들은 “다 100% 호봉급 하지 왜 그러느냐?” 이렇게 보시는 분들이 있을 수 있을 겁니다. 국책연구원들도 경우에 따라서 많이 다르기는 합니다만 어떤 데는 기본급이 30% 정도까지 떨어져 있는 데도 있고 어떤 데는 여전히 호봉제로 하고 있는 데도 있습니다. 저희들이 그 과정에서 균형점을 잡아가는 과정이고 생각하건대 가장 좋은 급여체계는 정확히 생산성과 비례하는 급여체계 이게 가장 바람직한 체계라고 생각합니다. 특히 저희 연구원은 1995년에 만들어졌기 때문에 이미 한참 시니어들이 있습니다. 한참 시니어들 같은 경우에 이미 경력급이 매우 누적되어 있는 이런 상황이고 새로 들어오시는 분은 낮은 경력급에서 시작할 수밖에 없는 그런 상황입니다. 
</p>
<p style="padding-left:1.2em">  그런 상황 속에서 보자면 구성원 간에 성과평가를 하고 성과급여를 많이 올려주고 싶은 그런 한편의 주장에 대해서 내부갈등을 유발할 수 있는 아주 중요한 그런 폭발력 있는 소재일 거라고 생각합니다. 그러나 그렇다고 해서 또 마냥 평균화된 임금에 매몰되어 있을 수도 없다고 생각합니다. 그래서 이 부분과 관련해서는 저희 연구원에서 균형점을 찾을 수 있도록 노력해야 될 것이며 우선 거기에서 가장 중요한 것은 성과평가가 올바로 돼야 된다고 그렇게 생각했습니다. 저희 경기연구원이 거의 모든 박사님들이 계신데 240점이 성과평가 만점이었습니다. 240점이 넘으면 다 똑같습니다, 저희가 그동안에 보았던 것들은. 그런데 작년도 성과평가를 해 봤더니 230점대 한 분 계시고 나머지 전원이 240점이 넘었습니다. 이건 물론 열심히 해 주신 결과로서 저는 한편으로 흡족하기도 했지만 또 아까 말씀하신 대로 그게 기반이 돼서 성과평가, 성과연봉제가 정착이 돼야 함에도 불구하고 그게 무력화되어지는 이런 상황이었습니다. 그래서 성과평가를 조금 더 평가다운 평가가 될 수 있도록 개선하려는 노력을 올해 하였던 것이고요. 그런 측면에서 위원님이 말씀하신 대로 한편으로는 성과 현재의 것을 건드리는 것은 너무 여러 가지 복잡하기 때문에 성과평가를 할 수 있는 방법에 대한 개선을 하고 싶었습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 네. 시간이 없어서, 평가서를 보니까……. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  30초만 더 할게요. 그 점수를 제가 보면서 ‘아, 생각보다 너무 점수가 높다.’ 이런 판단이 들어서 물어봤던 거고요. 어쨌든 원장님께서 말씀하신 것처럼 성과평가가 좀 올바로 돼야 된다. 그리고 또 계속 말씀하셨던 균형점을 잘 잡자, 구성원들과. 같이 그랬으면 좋겠고 특히 노동조합과 잘 협의해서 이런 것들을 잘 잡아나가셨으면 좋겠다 하는 당부를 드리면서 마치도록 하겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 고맙습니다, 위원님. 
</p>
<p><b>○ 위원장 정대운 </b> 이혜원 위원님 수고하셨습니다. 유광혁 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 유광혁 위원 </b> 동두천 출신 유광혁 위원입니다. 우선 이은환 노조위원장님 잠깐 자리 앞으로 나와 주세요. 저 역시도 성과연봉제에 대해서 질의를 하고자 했는데 앞서서 존경하는 이혜원 위원님께서 대부분 많이 말씀해 주셨는데 방금 전까지 원장님이 나름 노사협의를 통한 성과연봉제에 대한 보완점을 얘기하시고 그리고 절충점을 찾고자 하는 노력을 하셨다는데 노조위원장님으로서는 어떠한 평가를 하고 계시는지요? 
</p>
<p><b>○ 참고인 이은환 </b> 성과연봉제에 대해서는 사실 그 어떤 논의도 없었고요. 원장님께서 노사협의회를 말씀하셨는데 사실 이번 노사협의회에서 성과연봉제에 대해서 언급은 있었습니다, 저희 노측에서요. 그런데 그때 “그건 굉장히 익스플로시브한 사안이니 다음에 얘기합시다.” 그렇게 해서 넘어갔었고요. 실제적으로는 성과연봉제에 대해서 논의된 적은 없습니다. 
</p>
<p style="padding-left:1.2em">  그리고 평가제도가 원장님이 오셔서 정말 좋으신 취지로 그렇게 변경을 하셨지만 일단은 그에 대해서 노사 간 합의가 없었다는 게 저희들은 가장 큰 문제라고 생각을 하고요. 그리고 몇 가지 쟁점이 있긴 한데 그중에서도 소급 문제라든지 아니면 근무평가라고 있습니다. 저희 연구원은 평가제도가 두 가지가 있는데요. 하나는 연구량에 대한 평가 그리고 하나는 말 그대로 근무평가, 정성적인 평가입니다. 평가지표가 성실성, 리더십, 책임감 그런 굉장히 다분히 주관적인 평가입니다. 그게 기존에 한 22% 정도에서 30%로 이번에 늘어났습니다. 그에 대해서도 사실 저희 구성원들이 많이 문제제기를 했었고요. 그래서 그런……. 
</p>
<p><b>○ 유광혁 위원 </b> 네, 거기까지 듣겠습니다. 자리에 돌아가셔도 되겠습니다. 
</p>
<p style="padding-left:1.2em">  원장님, 방금 위원장님의 말씀을 들었는데 사실상 제가 질의에 앞서서 참 많은 고민이 있었어요. 원장님의 조직의 동력 추진을 위한 부분에 대해서 노력하시는 걸 모르는 건 아닌데 사실 노조의 입장은 또 이렇게 다른 거예요. 그렇죠? 이게 기존의 협의체나 어떤 개념에 대해서 논의가 확실히 안 돼 있는 게 지금 행정사무감사 현장에도 비쳐지는 거거든요, 아쉽게도. 이런 점에 대해서는 어떠한 소회를 갖고 계시나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들이 아시겠습니다마는 최근 노동조합에서 노동청에 진정하고 법원에 고발하는 사건들이 있었습니다. 매우 가슴 아프게 생각합니다. 이 부분들에 노동조합에서는 어떤 문건에서, 제가 문건은 정확히 기억 안 납니다마는 이런 부분이 문제가 되는 게 아니라 “원장이 대화에 응하지 않아서 대화에 응하게 하려고 진정과 고발을 하였다.” 이렇게 하는 것도 제가 정확히 문건이 기억이 안 납니다만 봤습니다. 그 부분을 읽으면서 참 마음 아팠습니다. 저 스스로 노동조합에 대해서 많은 애정을 가지고 있었던 사람인데 이런 소리를 듣게 되는구나 하고 마음 아팠고요. 어찌 됐건 제 불찰로 생각합니다. 
