<p><b>○ 유광혁 위원 </b> 사실상 성과연봉제 자체가 너무 강압적으로 정부의 지시에 의해서 저희가 실시하고 그 부분에 있어서 합의되지 않은 채 그리고 법률 쪽에서도 너무나 다양했는데 사실 그 전 정부에서 너무나 무리하게 해 가지고 지금까지 이런 문제들이 불거지는 것 같아요. 그런데 애초에 여기 오셨을 때 여러 가지 노력을 하셨겠지만 아쉽게도 지금 현 상황이 지금 우리의 위치인 것 같은데요. 사실상 성과연봉제에 대해서는 다양한 해석들이 있는 것 같아요, 그 자체에 대해서도. 어떠한 평가 기준이나 이런 모호한 점에 대해서도 많은 문제점을 제시하고 또 어떤 학계에서는 중장기적인 계획에 맞춰서 공공의 영역에서 평가 기준과 목표를 유연하게 대처하는 방법으로 해결해야 되지 않겠느냐 그러한 의견도 제시하는데 무엇보다도 중요한 게 사실상 구성원과의 공감대예요. 그게 없이는 그 어떤 것도 안 되는 거거든요. 사실 이 문제는 다시 한번 면밀히 검토하셔서 저 이후에 다른 위원님들이 아마 이 건에 대해서 질의하실 텐데 명확하게 하실 필요는 있으실 것 같아요.
