<p style="padding-left:1.2em">  지난 도정질의 때 제가 질의했던 거 우리 원장님 보셨죠? 도정질의 때 안 보셨나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그때 못 보고 나중에 자료로만 받았습니다.
</p>
<p><b>○ 신정현 위원 </b> 아, 그러셨어요? 알겠습니다. 일단 우선은 취업규칙에서부터 좀 이야기를 시작하겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 신정현 위원 </b> 취업규칙, 우리가 마지막 개정한 게 언제인가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 꽤 오래됐습니다. 2012년입니다.
</p>
<p><b>○ 신정현 위원 </b> 그렇죠. 2012년입니다. 일반적으로 공공기관들은 경영평가를 받죠. 우리 연구원은 경영평가 받나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 받습니다. 
</p>
<p><b>○ 신정현 위원 </b> 경영평가를 받을 때 노동에 대한 문제를 지적받으면 항상 취업규칙을 그때그때 개정하는 게 일반적입니다. 그런데 경기연구원 이제까지 12년부터 7년여간 단 한 번도 개정하지 않은 이유가 뭘까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 경기연구원은 취업규칙에 의해서 근로를 규율하는 게 아니라 인사규정과 내부에 있는 규정을 가지고 규율하였기 때문에 특별한 필요를 못 느꼈을 걸로 판단됩니다. 
</p>
<p><b>○ 신정현 위원 </b> 그건 지금 말이 안 되는 얘긴데요. 노사가 있고 근로자, 노동자들이 있는데 이 취업규칙이 가장 근거가 되는 것인데 이것에 대한 중요성을 못 느꼈다라는 게 말이 됩니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 취업규칙은 인사ㆍ복무 규정들을 한곳에 모아서 규정한 것인데 경기연구원의 다른 곳에 이미 있었기 때문에 노사 양측에서 필요성을 공감하지 않고…….
</p>
<p><b>○ 신정현 위원 </b> 노동의 기준이 되는 것이 취업규칙이고요. 그 하위에 인사ㆍ복무 규정이 있는 것이고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 말씀이 맞습니다. 
</p>
<p><b>○ 신정현 위원 </b> 네, 그래서 2019년까지…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 원래 규정에도 있습니다. 
