<p><b>○ 신정현 위원 </b> 그러니까요. 그런데 2012년부터 지금까지 한 번도 손 안 댔잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그런 걸로 판단됩니다. 
</p>
<p><b>○ 신정현 위원 </b> 매우 매우 중요한 실책이고요. 노동부에서도 이거 시정요구 받으셨죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이번에 노동조합이……. 
</p>
<p><b>○ 신정현 위원 </b> 받으셨잖아요. 제가 공문 봤습니다. 받으셨죠? 시정…….
