<p><b>○ 신정현 위원 </b> 네, 참조로 받았어요, 저는. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 노동조합이 제기한 문제에 대해서 혐의가 없었다고 판단하고……. 
</p>
<p><b>○ 신정현 위원 </b> 아니, 혐의문제가 아니고 이거에 대해서 수정하지 않은 문제를 지적받으셨죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 단서조항에 있었습니다. 취업규칙을 개정할 것을 권고하였습니다. 
</p>
<p><b>○ 신정현 위원 </b> 그러니까요. 연구원 측에서 노동문제에 대해서 얼마만큼이나 무관심했는가에 대한 단적인 예입니다, 원장님. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 2019년도까지 법 개정되었던, 이제까지 노동법 관련 개정되었던 부분들 어느 정도까지 개정된 부분들이 적용됐는지 다 체크해 가지고 제출해 주시기 바랍니다. 현재까지 적용되지 않은 부분들이 대다수겠지만 2019년도 법 개정 부분까지 다 적용되었는지를 체크해서 제출해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 노동법……. 다시 한번 말씀해 주시겠습니까? 
</p>
<p><b>○ 신정현 위원 </b> 2019년도의 법 개정 부분까지 다 적용되었는지를 확인해 주셔서, 지금의 이 취업규칙이, 체크해서 제출해 달라고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이 취업규칙상의 문제점을 검토해 달라 이 말씀이십니까? 
</p>
<p><b>○ 신정현 위원 </b> 그렇죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 신정현 위원 </b> 그렇다면 저는 궁금한 게 또 이런 겁니다. 뒤에 또 한번 보시면요. 제가 면담을 해 보면서 8시부터 9시, 18시부터 19시까지는 근로시간으로 인정이 되지 않는다고 그러네요. 맞나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 본인이 유연근무제를 신청할 경우에는 가능합니다. 저 스스로도 8시부터 근무가 시작하는 걸로 신청을 했습니다. 
</p>
<p><b>○ 신정현 위원 </b> 9시부터 18시까지 근무하고 보통 야근을 할 경우 있잖아요. 그럴 때 저녁 6시부터 7시까지 근로시간으로 산입이 안 되죠? 지금 어떻게 하고 계십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 제가 확인해 보겠습니다. 
</p>
<p style="padding-left:2.4em">    (경기연구원장, 관계직원에게 확인 중)
</p>
<p style="padding-left:1.2em">  관리직에 해당하는 특별한 문제인데요. 포괄근무제가 적용이 되기 때문에 앞뒤 한 시간씩 빼고 적용한다 이렇게 얘기를 합니다. 그러면 돈을 안 주는 게 아니라 그 부분은 그럴 만한 사유가 있다 이렇게 말씀드리겠습니다. 
</p>
<p><b>○ 신정현 위원 </b> 근로시간으로 인정하느냐 안 하느냐를 제가 여쭤본 건데 그 시간은 근로시간으로 인정이 지금 안 되어 있는 것이죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 포괄근무제로 포괄적으로 인정되어 있는 것 같은데요, 위원님. 이 부분 다시 점검해 보겠습니다. 
</p>
<p><b>○ 신정현 위원 </b> 확인해서 알려주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 비급여인지 판단해 달라는 얘기죠? 
</p>
<p><b>○ 신정현 위원 </b> 네, 제가 말씀드릴게요. 이런 것들이 바로 취업규칙에 자세하게 들어가야 되는 부분이거든요. 그런데 2012년 마지막 개정됐던 건 중식시간으로서 12시부터 13시까지만 되어 있고요. 시간외근무에 대해서는 일절 거기에 대한 어떤 근거조항이 없습니다. 다시 말하면 현재 관리직을 비롯해서 다른 직종도 8시부터 9시, 18시부터 19시에 대해서 실제로 근무했음에도 근무한 시간으로 인정되지 않는 것이죠. 어찌 보면 임의로 근로를 제공하고 임금을 받지 못하는 이러한 상황이 될 수도 있는 것입니다. 그렇기 때문에 취업규칙을 제가 보여드리면서 문제를 제기하는 것은 이것을 가지고서 만약에 노조 측에서 부당하게 이 해당 시간에 대해서 근로를 했기 때문에 이것에 대한 근로시간의 수당을 지급하라라고 한다면 지급을 하셔야 될 수도 있는 거예요, 해석에 따라서.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 당연히 법적 절차에 따라서 하라고 그러면 저희가 안 할 이유가 없습니다. 당연히 하겠습니다. 
</p>
<p><b>○ 신정현 위원 </b> 알겠습니다. 그러면 이 부분에 대해서는 충분히 더 검토를 하셔서 노조 측과 또 한번 의논을 해 나갔으면 좋겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님 말씀 중에 말씀드리겠습니다. 계약직 같은 경우에는 당연히 인정되고요. 관리직 같은 경우에는 공무원하고 똑같이 월 10시간의 초과근로가 인정되기 때문에 이런 현상이 발생했고 이것들이 임금을 안 주거나 공공기관으로서 임금을 착취하거나 이러고자 하는 의도는 전혀 없었음을 말씀드립니다. 다만 취업규칙에 적용되지 않았던 부분에 대해서는 말씀하신 대로 현재 취업규칙을 작성 중에 있다는 걸 말씀드리겠습니다.
</p>
<p><b>○ 신정현 위원 </b> 알겠습니다. 그 부분에 대해서도 여전히 현재 52시간제라는 큰 틀 안에서 노동시간으로 산입되느냐 안 되느냐의 중요한 문제입니다. 이것이 산입되었을 때에는 대다수의 관리직 노동자들은 52시간 이상 한참 넘은 시간을 근로하는 것으로 볼 수 있기 때문에 초과근무에 대한 문제가 발생되는 것이죠, 52시간 이상으로. 그래서 이 문제는 매우 예민한 문제이기 때문에 확인을 해 주시고 또 취업규칙에도 노사 간의 협의를 통해서 넣어주시기를 부탁드립니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 성과연봉제를 이어가도록 하겠습니다. 성과연봉제가 언제 우리나라에서 처음 시작됐는지 알고 계시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 모릅니다. 
</p>
<p><b>○ 신정현 위원 </b> 잘 모르십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 2008년도 이명박 정부 때 시작이 됩니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 전에도 있었습니다. 
</p>
<p><b>○ 신정현 위원 </b> 이명박 정부 때 공공기관 중심으로 성과연봉제를 하라는 지침이 내려갑니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그때 방만경영 관련된 개념이 있었지만 성과연봉제는 이전부터 있었던 겁니다. 
</p>
<p><b>○ 신정현 위원 </b> 성과연봉제가 가지고 있는 핵심은 이런 겁니다. 신자유주의 경제정책의 일환입니다. 인간은 자신의 이익을 위해서 움직인다라는 이 근거 위에서 만들어진 게 바로 성과연봉제입니다. 이것은 성과를 낸다라는 좋은 빌미를 제공하기도 하지만 결국 개인, 개인은 서로를 위해서 살아가는 존재가 아니라 개인의 이익을 위해 살아가는 존재라는 아주 경제학 철학적인 근거가 있는 것이죠. 이것이 사실은 영업직 혹은 일반 기업직에게는 이런 부분들이 적용되어 실제로 성과를 내기도 했습니다. 하지만 연구를 수행하고 있는 연구원들에게 성과연봉제, 그렇게 해 가지고 자신이 받을 연봉의 일부를 떼어서 실제로 받을 수 있는 연봉의 최대 800~1,000만 원까지 받지 못하는 일들이 벌어졌을 때 이제 옆에서 함께 일하고 있는 동료 연구원들을 함께 일하는 서로 협력하는 대상이 아니라 어떻게든 이 사람보다 더 좋은 점수를 받기 위해서 이 사람을 짓밟고 올라가기 위한, 결국은 연구원이라는 한 조직 안이 공동체가 아니라 서로가 경쟁하고 그 위에 올라서기 위한 그러한 공간으로, 냉소주의가 팽배한 공간으로 갈 수 있다라는 것이고요. 이러한 문제는 비단 지금 제가 말씀드리는 하나의 실례를 들 필요도 없이 많은 국가들과 연구자들이 이런 금전적인 보상을 통해서 업무 효율성을 이루어낼 수 있다라는 데 매우 부정적인 결과들이 최근에 나오고 있거든요. 그럼에도 불구하고 성과연봉제를 강화시키려고 하는 의도가 무엇일까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 답변해도 됩니까?
</p>
<p><b>○ 신정현 위원 </b> 해 주십시오.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님께서 신자유주의 정책과 성과연봉제를 연결하신 것에 대해서…….
</p>
<p><b>○ 신정현 위원 </b> 간단하게 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 전반적으로 동의합니다. 그러나 저희는 공무원에 준하는 조직이고 저희들이 해야 되는 것은 열심히 일해서 여러분들께, 주권자들께 답하는 길이 저희들 일이라고 생각합니다. 그래서 성과연봉제는 성과평가를 하지 않을 수는 없습니다. 그걸 연봉으로 만드느냐 하는 것은 둘째 문제지만 성과평가는 반드시 해야 되는 문제라고 생각합니다. 
</p>
<p><b>○ 신정현 위원 </b> 네, 동의합니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그다음에 또 말씀하신 것 중의 한 가지, 직원들의 급여를 떼어서 그걸 성과평가로 준 게 아니라 저희는 원래부터, 위원님들께 저희들이 출연금을 요청할 때부터 기본연봉 부분과 성과연봉 부분을 따로 요청을 합니다. 그래서 기본연봉 부분은 호봉제로 매우, 현재로서는 이게 격차가 큰데요, 호봉연봉제로 하고 그다음에 위원님들께 받은 내용을 가지고, 그것을 50~150% 사이 가지고 성과연봉제로 나눠 드리고 있습니다. 관점의 차이이기는 하지만……. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p><b>○ 신정현 위원 </b> 설명을 다 들었으니까요, 제가 설명을 드릴게요. 뒤에 한번 보세요. 2008년도 이전까지 기본연봉과 성과급이 나갔던 것이고요. 정확히 말하면 성과급을 지금 현재 성과연봉으로 주고 계신 거예요. 맞죠? 맞습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 신정현 위원 </b> 정률적으로 지급됐던 것이기 때문에 기본연봉 플러스 성과급 자체가 연봉이었던 것이에요. 그게 개개인의 성과에 따라서 성과급을 차등지급한 게 아니란 말입니다. 그런데 어느 순간 성과연봉제를 하겠다고 하면서 누군가와 개개인의 차이가 재작년까지는 최대 3,000만 원까지 나는 이런 결과를 낳았고요. 그나마 작년부터는 최저와 최고가 1,600만 원의 차이가 나는 결과가 나와 준 것이죠. 결과적으로는 같은 연봉을 쭉 받아왔던 사람들이 그 연봉의 일부가 성과연봉이라는 이유로 최대 1,600만 원까지 차이가 나버리는 이것이 어떻게 말씀하신 대로 서로가 경쟁을 통해서, 아니죠. 내가 원래 받고 있었던 연봉의 일부를 떼어가서 다른 누군가 더 좋은 성과를 낸 사람에게 갖다 줘야 되는 상황이 된 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 저는 떼어준다는 말에 동의하기 어렵습니다. 저희들이 위원님들께 출연금을 주십사라고 부탁할 때는 “성과연봉 부분이 이만큼이고 기본연봉 부분이 이만큼입니다.” 이렇게 저희들이 신청을 합니다. 여러분들이 주신 겁니다.
</p>
<p><b>○ 신정현 위원 </b> 자, 그거는 성과급으로 성과평가를 통해서 연봉을 차등지급하도록 결정하신 거는 우리 연구원장님이시잖아요, 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 원래 있었던 거고요. 제가 지금 하는 거는 성과연봉을 강화하겠다는 게 아니라 그 부분은 손도 안 댔고요. 성과평가 방식을 지금같이는 안 된다. 왜냐하면 1명도 안 빼고 1명 딱 됐는데요. 만점 안 받은 사람이 1명 정도밖에 안 되는 성과평가에는 문제가 있다는 판단을 했습니다. 
</p>
<p><b>○ 신정현 위원 </b> 성과연봉제의 가장 큰 맹점 중의 하나는 결과적으로 채점을 하는, 점수를 부과하는 분들에게 종속될 수밖에 없다라는 게 핵심문제예요. 많은 기업들과 공공기관들이 그런 문제에 노출이 되었던 것입니다. 그런 부분들에 대해서 우리 원장님께서도 심각하게 고민하셔야 됩니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다.
</p>
<p><b>○ 신정현 위원 </b> 잠시만요, 이제 참고인 잠깐 현장 앞으로 나와주시기 바랍니다. 자리에 들어가 주시고요. 성과연봉제에 대해서 설명을 쭉 해 왔었는데요. 성과연봉제를 통해서 실제로 업무 혹은 연구실적이 매우 효율적으로 늘어났습니까?
</p>
<p><b>○ 참고인 이은환 </b> 그렇지 않다고 생각을 하고요. 예를 들면 노조위원장이다 보니까 조합원들을, 최근에 47명의 박사들을 만나고 다녔습니다, 개인적으로요. 그때 제가 들었던, 사실 제가 듣고서도 제 귀를 의심했던 이야기가 있었는데 뭐냐 그러면, 모 박사님은 자기는 어차피 C니까, 우리는 A, B, C, D가 있습니다. 그래서 자기는 어차피 열심히 해 봤자 C 받을 거니까 열심히 할 필요가 없다라고 생각한다는 얘기를 하더라고요. 그렇습니다.
</p>
<p><b>○ 신정현 위원 </b> 그런 게 어찌 보면 서로가 서로를 경쟁자로 보고 내 경쟁에 치우치게 되면 결과적으로는 내가 열심히 연구하겠다라는 의지보다는 그냥 ‘연구를 그렇게 열심히 해서 뭐 하겠어.’라는 냉소주의에 빠진다라고 들리는데 그렇다고 볼 수 있나요?
</p>
<p><b>○ 참고인 이은환 </b> 네, 저는 그렇다고 생각을 합니다. 
</p>
<p><b>○ 신정현 위원 </b> 지금 연봉을 덜어내는 것이 아니다. 애초에 처음부터 이 연봉은 기본연봉을 주고 성과연봉을 차등지급하는 방식이기 때문에 연구박사님들의 연봉을 뺏는 것이 아니다라고 얘기를 하시는데요. 그러니까 떼어가는 것이 아니다라고 말씀을 하시는데요. 실제 박사연구직들은 성과연봉을 통해서 그렇게 느끼고 계시나요, 공정하게?
</p>
<p><b>○ 참고인 이은환 </b> 그 용어가, 성과급과 성과연봉의 차이를 잘 모르시더라고요. 성과급은 원장님이 하신 게 맞습니다. 기본연봉을 주고 거기다 더 잘하는 사람에게 인센티브를 주는 게 성과급이고요. 성과연봉이란 거는 제 연봉에서 기본급이 있고 나머지 그 기본연봉 그리고 성과연봉을 합한 게 제 연봉인데, 성과연봉이라는 거는 제 연봉에서 떼 가지고 풀링을 해서 우리는 그게 진짜 무한경쟁이라고 생각을 하는데, 제로섬 게임이죠. 제가 많이 받아가면 분명히 적게 받아가는 사람들이 생깁니다. 저희는 100% 상대평가이기 때문에 점수가, 지금 아까 전에 여기 이혜원 위원님께서도 말씀하셨지만 점수를 보니까 다 90몇 점에서 80몇 점 사이, 하등한 사람 아무도 없습니다. 
</p>
<p><b>○ 신정현 위원 </b> 네, 알겠습니다. 자리에 들어가 주시고요. 30초만 마무리 발언을 좀 하고 마지막으로 말씀하실 기회를 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그렇습니다. 이 성과연봉제가 가지고 있는 가장 큰 맹점은 연구원 내에서도 양질의 연구결과를 낼 수 있는 어떤 방법으로써 작동하는 것이 아니라 마치 닭장 속에서 계란을 낳기 위해서 닭공장처럼 닭알을 낳기 위해서 있는 닭처럼 그냥 연구실에 앉아서 하루에도 몇 번씩 연구물을 쓰기 위해서, 1년에 10개가 넘는 연구 성과물을 내기 위해서, 그리고 오늘 하루 내가 무슨 글을 썼는지조차도 기억 못 하게 만들어버리고 그리고 이 연구의 성과를 통한 보람조차도 느끼지 못하게 만드는 결과를 내어버렸습니다. 이러한 성과연봉제가 과연 지금 이 시기에, 이 시대에 공정의 가치를 최우선하는 이런 공간에서 과연 꼭 필요한 것인가라는 질문을 다시 한번 드리겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 위원님의 문제의식에 깊이 공감하고 저희들이 개선할 점이 있을지 여부는 조금 더 열심히 찾아보도록 하겠습니다. 감사합니다. 
</p>
<p><b>○ 위원장 정대운 </b> 신정현 위원님 수고하셨습니다. 김강식 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김강식 위원 </b> 수원 출신 김강식 위원입니다. 먼저 좀 확인을 하고 싶은 게 있는데요, 연봉 관련해서요. 지금 원장님께서 말씀하신 거는 기본연금 플러스 성과연봉이라고 하는데 그럼 연봉계약들을 작성하실 것 아니에요, 연간에. 근로계약이 아니더라도. 거기에 명기되는 건 이 2개가 다 포함된 총액으로 그러면 연봉이 되는 겁니까, 아니면 기본 호봉이라고 했던 그 부분으로 되는 겁니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 말씀드릴까요?
</p>
<p><b>○ 김강식 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 연봉이라는 건 사후적 개념입니다, 성과연봉제하에서는. 그러니까 처음에 기본연봉이 얼마라는 사실을 알려줍니다, 알고 있습니다. 왜냐하면 저희 기본연봉은 아까 말씀하신 대로 대략 80% 선에서 결정되었는데 저는 이게 보기에 따라서 어떤 사람들은 너무 성과가, 기본급이 많다라고 보실 수도 있고 어떤 분들은 성과연봉이 왜 있냐 이렇게 판단하실 수도 있습니다. 그러나 처음에 드릴 때는 기본연봉을 알려드리고 성과연봉 부분은 따로 정해져 있습니다, 총액이. 그것들을 성과에 따라서 배분하기 때문에…….
</p>
<p><b>○ 김강식 위원 </b> 제가 여쭤본 거는 전체 포함이 돼 있는…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 아닙니다.
</p>
<p><b>○ 김강식 위원 </b> 여쭤보고 싶었던 건 그런 거예요. 연간에 보면 저희가 이제 4대보험 같은 것들을 납부하잖아요. 보통 그게 월 수령액 기준으로 해서 4대보험료가 책정이 되거든요. 건강보험료 같은 경우는 전체 받은 것들을 해서 내년도에 정산이 돼서 받아지니까 지금 말씀하신 것들대로 나중에 총 받아진 것들에 대해서 내년도에 정산하는 개념이고, 국민연금 같은 경우는 지금 신고하는 금액들로 받아지거든요. 그래서 지금 추가적으로, 나중에 1년 쭉 내다가 성과급에 따라서 급여의 총액이 바뀔 텐데 이 부분이 어떻게 지금 정리가 되고 있는지가 궁금해서 한번……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 잠깐 여쭤보고 말씀드리겠습니다. 
</p>
<p style="padding-left:2.4em">    (경기연구원장, 관계직원에게 확인 중)
</p>
<p style="padding-left:1.2em">  네, 사후정산. 
</p>
<p><b>○ 김강식 위원 </b> 사후정산, 그것도 올라간 금액만큼 해서 납부를 계속 하고 있는 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김강식 위원 </b> 그러면 이게 계속 많이 받을 때는 높게 평가가 되지만 일정금액만큼 줄었을 때는 또 더 많이 내는 부분들이 발생될 수 있거든요, 국민연금 같은 경우.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그럴 거라고 생각합니다.
</p>
<p><b>○ 김강식 위원 </b> 근데 이건 좀 불합리할 수도 있다라는 생각이 좀 들어서. 왜냐면 어떨 때는, 많이 늘었을 때는 그 부분을 좀 적게 낼 수 있는 부분도 있지만 오히려 그 다다음 해에 가면 또 정산해 가지고 이게 줄어들지 않거든요, 1년 차이로 냈기 때문에.
</p>
<p><b>○ 경기연구원장 이한주 </b> 받은 거에 대한 거기 때문에 늘거나 줄 수 있다고는 생각합니다. 위원님, 참고로 말씀드리면 저희 연봉계약서는 기본연봉 계약기간하고 기본연봉을 알려주고 성과연봉에 대해서는, 성과연봉은 보수규정에 따라 지급한다 이렇게 되어 있어서…….  
</p>
<p><b>○ 김강식 위원 </b> 그 내용들을 조금 정리된 자료를 한 번만 주시면 제가 그것 좀 보고 확인할 수 있도록 해 주시면 좋을 것 같습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님. 복사하는 시간이 걸리니까 이거는 바로 드리겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 알겠습니다. 그리고 지금 계속 말씀하시는 것 속에서 어쨌든 경기연구원의 연구기관으로서의 어떤 연구의 질적인 부분들, 이런 부분들을 높이기 위해서 성과연봉 이런 부분들을 하나씩 도입하시고 어쨌든 평가에 대한 부분들, 개선하시려고 하는 부분들, 그 부분에 대해서는 좋은 뜻으로 받아들이고 있습니다마는 그런데 지금 연구원에서 정성평가 방법들이 지금 어떻게 진행되고 있는 걸까요? 연구평가에 대한.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 조금 자세히 말씀드리겠습니다. 그 연구량이 있습니다. 연구량은 예전이나 지금이나 240점으로 똑같습니다. 그러나 똑같은 연구에 대해서 질적인 평가가 다르기 때문에 똑같은 하나의 정책연구를 했을 경우에 이것에 대해서 얼마를 질적으로 평가해 주느냐 이런 문제가 남습니다. 이건 모든 연구원이 다 똑같은데요. 경우에 따라서는 곱하기도 하고 경우에 따라서는 더하기도 합니다. 지금까지는 곱하기였습니다. 0.8에서 1.1을 곱해서 양적 평가에 대해서 평가를 하고 합산한 게 연구총량으로 정리가 되었던 것입니다. 그게 240점 만점이었는데 240점은 모두 1을 곱했을 때 240점을 얻은 사람이 모두 1을 얻었을 때 나올 수 있는 점수입니다. 그러나 이 부분에 있어서 저희들이 1단계 평가를 3단계 평가로 조금 더 세분화하고자 하였습니다. 특히 강조하고 싶었던 것은 본인이 질적 평가를 하는데 본인이 참여하는 부분들을 좀 줄이고 외부평가를 하도록 이 부분을 하였습니다. 이거는 저희만의 그런 게 아니라 연구의 외부평가는 보통의 통상적인 방법입니다. 이 부분들을 개선하고자 하였습니다. 그래서 정성평가가 특별히 변동된 것은 없고요. 아까 말씀하신 대로 240점 만점에 1명만 빼고 전원이 240점 이상을 얻는 이런 상황 속에서 저희들이 질적 평가를 곱하기로 하지 않고 외부시각에 의해서 더하기로 바꾸는 과정을 수행했기 때문에 이 부분에 대해서 총 94점을 부여했는데요. 
</p>
<p><b>○ 김강식 위원 </b> 제가 알고 있는 내용들을 좀 보면 일단 이 평가를 함에 있어서 1단계는 연구성과 보고회를 한다고 되어 있거든요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 김강식 위원 </b> 그다음에 2단계에서는 발간점검 위원회를 거치고 3단계에서 보고서 서면평가를 하게 돼 있는데 이 연구성과 보고회를 통해서 1차적으로 평가를 받잖아요. 그러면 성과보고의 1단계 평가를 할 때 평가위원들은 어떻게 구성이 되고 있는 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 정하는 내부규칙이 있습니다, 내부규칙이 있어서 그 규칙……. 
</p>
<p style="padding-left:2.4em">    (경기연구원장, 관계직원에게 확인 중)
</p>
<p style="padding-left:1.2em">  부원장님과 연구부원장님 말씀하신 겁니까? 
</p>
<p><b>○ 김강식 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 실장님, 담당연구원이 속해 있는 실장님 그다음에 원내에 있는 전문가 그다음에 도내에 있는 관련공무원 이렇게 참여해서 성과를 보고하고 평가를 받습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러니까 이 부분이, 저는 내부적인 평가위원들은 보통 내부평가 위원으로 구성되어 있다라고 봐도 될까요? 왜냐하면 도내에 있는 공무원이라 하더라도 외부에 어떤 전문성이 있거나 이 부분들을 전공했던 분들 말고라도 그냥 비전공자들도 포함돼서 지금 이 부분들을 평가하게 되어 있는 건 아닌가……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 비전문가라기보다는 연구성과 보고회는 그 연구의 속성을, 연구의 질적인 평가도 평가지만 연구의 속성을 잘 이해할 수 있는 분으로 구성을 했습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그럼 아까 말씀 중에 외부평가를 하신다고 했는데 이 부분은 어디 들어가는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그건 마지막에 보고서 서면평가가 있습니다, 저희가. 이 부분은 이제 새로 신설한 내용인데요. 이것들은 외부평가 위원회의 블라인드 테스트로써 할 수 있도록 저희들이 이번에 새로 규정을 했습니다.
</p>
<p><b>○ 김강식 위원 </b> 본 위원이 생각하기에는 연구성과 보고회 할 때 오히려 외부평가를 통해서 하지 않으면, 그 부분들이 외부평가를 좀 반영해서 하는 것이, 왜냐하면 이 부분들이 내부평가를 하다 보면 불필요한 오해들이 지금 노조에서도 좀 우려하고 계시는 부분들처럼. 어쨌든 보면 내부에 있는 구성원들에 대한 경영진이나 이런 부분들이 들어가다 보면 연구원장의 어떠한 의도적으로 무언가 이렇게 이루어지지 않느냐, 커트되지 않느냐, 거기서 평가되지 않느냐에 대한 우려를 살 수 있을 것 같다는 생각이 들어서 1차 연구성과 보고회할 때 외부평가를 받아서 최종적으로 서면평가할 때 거꾸로 하는 부분에 대해선 어떻게 생각하십니까? 마지막 단계에서 내부적으로 결정하는 부분들에 대해서.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 지금 3단계로 개선한 것은 통상적으로 연구기관에서 하는 것들을 좀 따랐고요. 말씀하신 대로 외부평가 위원회 블라인드 테스트를 먼저 받고 그다음에 성과보고회를 통해서 내부점검을 하도록 하자라고 하는 얘기는 또 나름대로 충분히 검토할 가능성이 있다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  그럼에도 불구하고 저희들이 그 평가의 독립성이 일정한 만큼 들어가야 되는 거는 사실이라고 생각합니다. 그래서 어떤 형태로든지 객관적 평가가 좀 들어갔으면 하는 게, 저희들이 성과연봉은 건드리지 않은 채 성과평가 방식만 약간 바꾼 그런 내용이다 이렇게 말씀드리겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 네, 그래서 말씀을 드리는 거예요. 이 성과평가 방식에 대한 부분들이 조금 더 전체에 있는 지금 구성원들이 납득할 수 있고 그 부분들에 있어서 대응할 수 방식으로 가지 않고 지금 하다 보면 오해에 대한 요지들이 분명히 있고 그 부분들이 반영될 수 있지 않을까라고 바라볼 수 있는 시각이 있을 거라는 생각 때문에 한번 말씀을 좀 드려봤고요.
</p>
<p style="padding-left:1.2em">  이제 근무성적평가규칙 개정안을 보면 아까 노조위원장님께서도 잠깐 말씀하셨는데 성과평가서에서 성과평가가 70%, 이분이 양적 평가가 50%, 질적 평가 20% 그다음에 근무평가가 30%라고 해서 바뀌게 되었다고 알고 있거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇게 판단할 수 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그래서 근무평가 비율이 22%에서 30%로 늘어난 결과죠, 사실은. 전에 22%에서. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇게도 판단할 수 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 네, 그러면 어떻게 보면 이게 연구 외의 질적인 부분들을 평가하기 위한 부분인데 여기서 근무평가라는 부분들이 아까 말씀하실 때는 성실성이라든지 여러 가지 이런 부분들이거든요. 그러니까 연구 외적인 부분들의 평가점수가 지금 올라가는 부분들이거든요. 이 부분들의 평가는 성과에 대한 부분들보다는 어쨌든 질적인 부분들보다 외적인 요인들에 대해서 평가점수가 높아졌기 때문에 그 부분들을 평가하는 것들에 대한 부분이 또 외부적인 어떤 다른 요인으로 적용될 수 있지 않을까에 대한 우려들도 하고 있는 것 같아요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 충분히 우려 이해합니다. 다만 위원님, 양 평가와 질 평가를 합친 게 성과평가고 그다음에 근무평가가 거기에 첨부되어 있는 이런 상황입니다. 지금까지 질 평가에 대한 게 매우 이렇게 다소 자의적인 특성이 있었기 때문에 이 부분을 개선해야 했고 아까 말씀하신 대로 이게 240점 만점 기준인데 만점이 거의 대부분 다 넘는 상황 속에서 저희들이 지금 질적 평가를 통해서 개선하려는 시도를 하였기 때문에 지금까지는 모두가 다 만점이니까 근무평가가 거의 대부분을 차지하고 있었습니다. 그러나 이번에 근무평가를 새로 함으로써……. 
</p>
<p><b>○ 김강식 위원 </b> 아니, 그래서 저는 여기 개정안에서 보면 이 근무평가가 30%로 늘어나는 과정에서 오히려 연구의 질이라든지 이런 부분들을 말씀하시려면 성과평가의 70%에 대한 부분들의 비중이 높아지는 부분들이 맞는 것이지 그 연구의 내용보다 외적인 어떤 그런 근무의 상황들하고 연계된 이런 근무평가의 비중이 높아지는 게……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님, 맞습니다. 위원님 말씀이 맞고요. 저희들이 그럼에도 불구하고 근무평가는 통상적으로 표준편차가 매우 작은 범위 내에서 주고 있다는 사실 그다음에 실정의 평가가 있고, 담임평가가 있기 때문에 이 근무평가가 자의적으로 될 가능성은 많지 않다는 사실을 말씀드리겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그럼에도 어쨌든 성실성이나 리더십, 아까 주관적 평가들이 들어갈 수 있기 때문에 이 부분들에 대한 부분들도 다시 한번 좀 검토해 보시는 것들이 필요하다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 검토하겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 왜냐하면 이런 부분들이, 이 평가체계들이 어떻게 보면 연봉하고도 관련이 있을 수도 있고 그런 부분들이 변경되기 때문에 근로하시는 분들, 그렇죠? 노동자들에 대한 부분들의 합의들이 이루어져야 되는 부분들이 있고. 그래서 아까 우리 존경하는 김우석 위원님이 얘기하신 심사위원회의 구성이나 이런 부분들이 다 연결되어 있다고 보거든요. 그 부분들이 지금 노조와의 관계 속에서 의견들에 대한 부분들이 서로 시각적인 부분에서 달리하고 있는 부분들에 대한 의견들을 내고 계신 거라고 생각이 돼서, 이런 부분들 하나하나가 지금 어쨌든 제도를 바꾸고 변경함에 있어 가지고 이런 의견들을 청취하고, 아니면 좀 더 무엇이 합리적인 것인가에 대한 부분들에 고민을 좀 더 하시는 게 바람직하지 않을까라는 의견을 드려봅니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 매우 감사하게 생각하고요. 지금 현재 이 건과 관련 해서는 노동청에 진정이 들어갔고 법원에서 판단을 하고 있기 때문에 그 판단이 나오면 그걸 기준으로 해서 저희들이 신속히 조치하고 위원님 말씀을 깊이 새겨서 참조하도록 하겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 네, 시간이 얼마 안 남아서 짧게 뭐 하나 다른 건으로 한번 말씀을 드려보겠습니다. 
</p>
<p style="padding-left:1.2em">  제가 지난 7월 달에 경기연구원에서 황해경제구역 용역들을 재위탁했다 철회하는 기사를 본 적이 있었거든요. 재위탁규정 위반이다라는 논란이 좀 있었는데요. 다른 과정들 속에서도 이런 위탁과제들을 경기도 산하기관에서 받아서 이 부분들 일정 부분을 떼고 나머지 부분들을 외부로 용역하시는 경우들이 또 있으신 사례가 있을까요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 위탁받은 것 중에서 일부를 재위탁하는 경우 말씀하시는 겁니까? 수탁 받은 것 중의 일부를 위탁하는 것…….
</p>
<p><b>○ 김강식 위원 </b> 그렇죠. 재위탁을 하면 안 되는 규정들이 있거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 잠시 관계자한테 얘기 좀 듣겠습니다. 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 재정지원부장 박인숙입니다. 그러니까 저희가 수탁과제 해서 외부로 위탁 내보낼 경우에는 입찰 시 단독이행만 가능하다고 할 경우, 하도급 가능하다고, 그러니까 하도급이 가능한지 여부에 대해서 발주기관의 승인을 받아라 뭐 이럴 경우, 그다음에 외부위탁을 내보낼 때 아주 설문조사같이 큰 단위의, 저희가 내부적으로 설문조사 요원들 몇백 명씩을 컨트롤할 수 없기 때문에 그렇게 대단위 설문조사인 경우……. 
</p>
<p><b>○ 김강식 위원 </b> 그러니까 전체 받아서 일부분에 대한 내용만 주는 건……. 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 일부분만 내보내는 겁니다. 
</p>
<p><b>○ 김강식 위원 </b> 그거는 재위탁으로 보지 않는데 이 사업내용들을 받아서 일정 부분들에 대한 이익을 남겨놓고 나머지를 주는 건 사실은 경유하는 것들인 거잖아요. 그래서 그런 연구용역들을 받아서 수행하시는 것들이 이 사례를 보면 이 1건이면 다행인데 하다 보면 이런 부분들의 사례들이 더 있느냐, 제가 자료를 요청한 적이 있었는데 이걸 보고서 요청을 했는데 이 사례조차도 저한테 자료로 오지가 않았더라고요. 그래서 없다라고 하셔서 제가 한번, 제가 질문을 잘못해서 그 자료가 그렇게 온 건지, 아니면 다른 건들에 대한 내용들은 있는데 질문의 의도를 잘 파악을 못 하셔서 그런지 몰라서 이 자리를 통해서 다시 한번 여쭤보는 겁니다. 그래서 이런 사례들, 지금 경기연구원이 황해경제구역 용역과 관련된 이런 사안들이 있지 않습니까? 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네. 
</p>
<p><b>○ 김강식 위원 </b> 그래서 이런 사례들에 대한 것들이 있는지에 대한 내용을 좀 파악하셔서 그것도 자료로 다시 한번 요청을 드리겠습니다. 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 알겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 이상입니다. 
</p>
<p style="padding-left:2.4em">    (정대운 위원장, 정승현 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 정승현 </b> 김강식 위원님 수고하셨습니다. 또 다음 질의하실 위원님, 민경선 위원님 질의해 주십시오. 
</p>
<p><b>○ 민경선 위원 </b> 고양의 민경선 위원입니다. 질의 전에 우리 이한주 원장님께 감사말씀을 드립니다. 국민의 자존심인 독도와 관련해서 토론회를 주관해 주시고 주최해 주신 데에 대해서 의회를 대신해서 감사드리고 앞으로도 이와 관련된 것은 계속적으로, 지속적으로 했으면 좋겠다는 생각입니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 더욱 노력하겠습니다. 
</p>
<p><b>○ 민경선 위원 </b> 고맙습니다. 지난 행감 때 지적한 사안입니다. 제가 지적했던 내용이 과제 수행 시에 연구원의 소신과 철학을 보호해 줬으면 좋겠다. 그래야 가치가 있고 예를 들면 본인들의 생각과 주관과 여러 가지 그동안 공부했던 내용과 다르게 집행부의 의견을 수렴하는 연구는 좀 지양했으면 좋겠다. 그에 대해서 여러 가지 대안을 마련해 줬으면 좋겠다는 의견을 전달한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  그래서 그 부분에 대해서 여러 가지 잘하고 있다고 보는데 제가 한 예를 들겠습니다. 저희가 DMZ 토론회를 했었어요, 두 차례인가. 제가 토론자로 참여했는데 ‘한국인과 외국인이 본 DMZ의 이미지와 가치’라는 중요한 이슈&진단을 했고 그다음에 또 ‘DMZ 도로는 굽은 흙길로’라는 이슈&진단을 한 바 있습니다. 그래서 상당히 의미 있는 내용이라서 활용을 많이 하고 있는데 이 내용에서 말씀하신 내용을 보면 DMZ와 남북 접경지역을 활용할 시에 가장 우선시하는 핵심가치가 무엇이냐라고 조사를 했는데 환경적 가치가 81.9%라는 응답이 나왔고 경제적 가치가 11.5%라는 응답이 있다라고 하면서 DMZ의 생태자연에 대한 보호에 중점을 두고 자연과 문화유산 보호를 위한 제도적 장치가 마련돼야 된다라는 게 주 시사점이고 결론 부분입니다. 그런데 문제는 집행부가 실제로 지금 DMZ 관련사업이 23개 사업이면서 한 230억 정도의 예산이 급박하게 추진되고 있는데 너무 주먹구구식입니다. 그런데 그와 관련된 토론을 했는데 DMZ 관리 및 사업의 효율성을 위한 조직대안이라고 또 우리 경기연구원에서 주제발표를 했습니다. 그러니까 이슈&진단이 추구하는 결론과 예를 들면 집행부가 요구해서 토론자로 참여했을 때의 내용이 상충되는 거죠. 그런데 연구자는 똑같습니다. 그래서 정말 의아해 했는데 어떤 게 맞는 것이냐. 그러니까 이런 부분에 대한 객관성이 담보되고 연구자에 대한 어떠한 신뢰나 그다음에 연구에 대한 철학을 좀 보여줬으면 좋겠다. 집행부의 의지에 따라서 이렇게 좌우되면 과연 정책을 수반하거나 또 잘못되면 우리 의회에서도 그 근거를 가지고 잘못된 판단을 할 수 있거든요. 그에 대한 의견을 좀 묻고 싶습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 혼선을 드려서 송구합니다. 저희들은 연구결과에 대해서 혹은 연구방향에 대해서 같이 초창기에 연구방향은 검토하지만 연구결과에 대해서는 집행부가 관여하지 않습니다. 말씀하신 대로 소신과 철학을 가진 연구가 필요하기 때문에 그렇다고 생각합니다. 지금 말씀하신 건에 대해서는 우리 여기 현장에 관계자가 있으니까 이정훈 센터장에게 그 내용을 들어보도록 하겠습니다. 
</p>
<p><b>○ 민경선 위원 </b> 네, 간단하게 말씀해 주십시오. 
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 북부연구센터장 이정훈입니다. 말씀하신 팩트가 정확하게 맞으신 거고요. 그런데 예를 들어서 주민들이 환경가치를 당연히 높게 평가했고 거기의 보호를 전제로 하면서 개발해야 된다는 논지를 제가 썼고요. 그런데 DMZ와 관련된 사업이 한 10여 개의 우리 경기도 내 조직 그다음에 공공기관에 산재돼 있어서 누구도 컨트롤하지 못하는 상황에 있다는 걸 DMZ사업의 효율화를 위한 토론회에서 제가 발제를 했고요. 그 두 부분이 예를 들어서 위원님께서는 그 부분을 이걸 개발을 해야 되는 논리를 낸 것으로 말씀을 하신 걸로 제가 이해를 하는데……. 
</p>
<p><b>○ 민경선 위원 </b> 그런 뉘앙스로도 받아들일 수 있고요. 조직 부서 간에 협력이 안 되기 때문에 이것을 분화된 것을 기능을 합쳐서 여러 가지 추진할 수 있는 어떤 조직을 만들자는 거잖아요? 
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 그렇습니다. 그래서……. 
</p>
<p><b>○ 민경선 위원 </b> 그런데 자칫 조직을 만들었을 경우에 여러 가지 의견수렴이나 협업에 대한 부분이 무시될 수 있고 그러면 결국은 의도한 대로, 예를 들면 기관장이 의도하거나 그 조직의 수장이 의도한 대로 흘러갈 공산이 큰 거죠. 그러면 DMZ가 갖고 있는 생태적 그다음에 환경적 가치나 환경의 비가역성을 감안해야 되는데 이 부분이 훼손될 여지가 있다는 것이죠. 다만 그걸 논박할 수 있는데, 서로 다양한 의견이 있으니까. 저 같은 경우는 여러 가지 다른 기관과, 시간이 걸리더라도 충분한 논의테이블을 만들면 한 조직에서 이끌어가는 것보다는 오히려 신중하고 다양성을 담보할 수 있고 오히려 이게 안전장치가 될 수 있지 않겠느냐는 고민을 해 본 거죠. 그래서 그런 부분에 대해서 예를 든 것이니까 그런 부분이 감안됐으면 좋겠다는 생각입니다. 
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 제가 간단하게만 좀 말씀드릴까요? 
</p>
<p><b>○ 민경선 위원 </b> 저도 또 질문할 게 많으니까……. 
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 네, 알겠습니다. 
</p>
<p><b>○ 민경선 위원 </b> 이따 다시 추가할 때 다시 한번 답변 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 말씀에 100% 공감합니다. 
</p>
<p><b>○ 민경선 위원 </b> 네, 고맙습니다. 이은환 노조위원장님 오셨는데 질문을 별로 안 하시는 것 같아요. 그래서 또 한참 오전부터 기다리셨을 텐데, 나와주시겠습니까? 
</p>
<p style="padding-left:1.2em">  위원장님, 마이크 켜시고. 오늘 그동안에 여러 가지 집행부의 신뢰나 이런 부분에 대한 불신이 좀 컸었던 것 같습니다. 오늘 행정감사 하면서 원장님이 말씀하시는 내용이 여러 가지 신중하면서도 수용 여지 같은 경우도 비추셨는데 좀 느낌이 어떠십니까? 
</p>
<p><b>○ 참고인 이은환 </b> 원장님이 말씀하신 대로 함께 그렇게 해 주시면 너무나 좋죠. 그런데 저는 사실 궁금한 게 저희가 노사협의회 때도 느꼈지만 이게 얼마나 강제력이 있을까? 노력한다는 말은 어디서나 그렇게 잘 할 수가 있죠. 그래서 사실……. 
</p>
<p><b>○ 민경선 위원 </b> 서로 신뢰 회복이 중요하다고 봅니다. 그런데 저는 여러 가지 소통 부족 부분, 아까 원장님께서 좀 유감스럽다는 말씀을 했는데 또 원장님 나름대로 대화로써 일정 부분 할 수 있는데 예를 들면 노동청에 진정을 하거나 법원에 고발한 것은 경영자 입장에서는 상당히 불쾌할 수도 있습니다. 그러니까 이런 부분은 좀 신뢰관계의 회복이 중요하다. 그런 과정에서 지금 여러 가지 과제가 있는데 제가 보기에는 이게 단기간에 해결될 수 있는 과제도 있지만 실질적으로 여러 가지 논의를 통해서 할 부분도 있다고 보는데 위원장님은 어떻습니까? 
</p>
<p><b>○ 참고인 이은환 </b> 네. 그래서 최근까지도 물밑에서 여러 가지 논의들을 하긴 했었습니다. 저희가 소송 건 그리고 노동부 진정 건에 대해서 요구안도 있고요. 그런데 서로 더 진척이 없어서 그게 참 난감하긴 합니다. 
</p>
<p><b>○ 민경선 위원 </b> 네. 보니까 지금 경영진과 노동조합 간의 관계 그다음에 연구직, 관리직, 무기계약직 그다음에 같은 그룹 내에서도 다른 의견이 있을 수 있다고 봅니다. 그래서 충분한 의견수렴 절차가 필요할 것 같습니다, 원장님도 마찬가지고요. 그래서 그런 부분에 심혈을 기울여 주셨으면 좋겠다는 생각이고 특히 지금 경기연구원의 문제만은 아닌 걸로 알고 있습니다. 제가 알기로는 경기도 산하 공공기관이나 타 시도의 지방연구원도 똑같은 문제에 봉착했다고 봅니다. 그래서 이 부분에 대해서 지금 상당히 행정감사 진행상황도 타 기관 또 타 지역 지방연구원에서도 유심히 관찰하고 있는 걸로 알고 있습니다. 그래서 경기도가 선도해 가는데 이 부분도 잘 매듭을 풀었으면 좋겠습니다. 그래서 여러 가지 질문과정에서 많은 내용이 나올 것도 있지만 우리 위원장님께서 오늘 나오심에도 상당히 고민을 많이 하고 나오셨으리라고 생각하는데 의회에 바라는 게 있으면 좀 말씀해 주시면 좋겠습니다. 
</p>
<p><b>○ 참고인 이은환 </b> 오늘 성과연봉도 그렇고 평가제도도 그렇고 이렇게 많이 논의가 됐는데 이것이 어떻게 진행되고 있는지 잘 살펴봐 주시면 참 좋겠다고 생각이 듭니다. 
</p>
<p><b>○ 민경선 위원 </b> 네. 그리고 원장님도 최근에 존경하는 신정현 위원님이 도지사님을 상대로 도정질문하면서 많이 새로운 것을 알게 되시고 또 고민을 많이 했을 것 같습니다. 그리고 또 상대적으로 스트레스도 많이 받았을 것 같은데 의회에 바라는 게 있다면 좀 말씀해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 우선 각오부터 말씀드리는 게 도리일 거고요. 저는 연구원이 경기도 주권자, 도정과 의회 운영에 열심히 봉사할 수 있기를 바라는 마음이 우선이고 그다음에 연구직 같은 경우에 서울연구원과 비교해서 다소 피해의식이 있습니다. 그 피해의식은 뭐냐 하면 지난 몇 년 동안 연구원들은 물론 경력가급 해서 호봉ㆍ승진 부분은 있었는데 대개 2%~2.5% 사이로 쭉 승진을 해 왔습니다마는 그러나 기본연봉 자체가 오르지 않았던 경험이 있습니다. 이 경험들이 연구직들을 좀 불편하게 하는 점이 있어서 그 부분들에 대해서 살펴봐 주시길 바라고 연구원의 핵심적인 문제 중의 하나는 연구인력에서 현재 무기계약직으로 전환된 분들이 성향도 다르고 매우 다양한 속성을 가지고 있습니다. 이분들이 경기연구원에서 생산적으로 정착할 수 있도록 하는 게 가장 급선무라고 생각합니다. 지금도 근본적으로는 거기에서 기인된 문제고 이것들이 잘 될 수 있도록 최선의 노력을 다해서 위원님들 앞에 기쁜 낯으로 보고드릴 수 있게 되기를 희망합니다. 
</p>
<p><b>○ 민경선 위원 </b> 네. 제가 이번에 노조위원장님을 참고인으로 신청할 때 내심 걱정도 많이 했습니다. 그 이유가 뭐냐 하면 제가 지금 10년째 의정활동을 하고 있는데요. 이 경우와는 조금 다르지만 근로여건 개선을 위해서 버스업체가 너무 인권을 유린한다라고 해서 제보를 접하고 그분을 설득해서 증인으로 채택해서 증인으로 나왔습니다. 그래서 그 실태를 고발하고 실제로 그 실태를 경기도도 인정하고 그에 대한 개선을 업체에 요구하겠다라고 해서 단기간에 해결될 줄 알았습니다. 그런데 그 증인으로 채택되신 분이 3개월 후에 동료들의 외압에 의해서 사직을 했습니다. 왜냐하면 여러 가지 압박이, 동료가 동조하고 이렇게 해 줘야 되는데 오히려 집행부로부터, 경영진으로부터 동료들한테 압박하니까 동료들이 그걸 못 이겨서 “너만 나가면 편하다.” 해서 사직한 경우가 있습니다. 그래서 그런 부분에 대해서는 오늘 원장님이 그건 보호해 주시고 오히려 이 자리가 시발이라고 생각하고 소통하고 단기간에 안 되지만 자주 만나고 또 의회가 중재ㆍ조정하는 역할을 하게 되면 아주 모범적인 선례가 될 수 있다고 보고 또 그에 대한 부족한 부분은 또 예산으로 집행부와 논의하고 같이했으면 좋겠다는 생각입니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 지당하신 말씀이고 따르도록 하겠습니다. 
</p>
<p><b>○ 민경선 위원 </b> 고맙습니다. 원장님 하여간 오늘 좋으신 말씀해 주셨는데 믿겠고요. 
</p>
<p style="padding-left:1.2em">  노조위원장님 오셨는데 한 말씀. 고민이 많으실 텐데, 스트레스받고 또 여러 가지 외압도 내부적으로 있을 것 같은데 용기를 가지셨으면 좋겠고 오히려 또 단계적으로, 급박하게 요구하는 것보다 단계적으로 단계 단계 하는 부분도 있습니다. 지금 노조가 생긴 지 2년밖에 안 됐지 않습니까? 그러니까 차근차근 하면 이게 선례가 돼서 다른 연구원에도 모범사례가 될 수 있고 산하기관에도 또 도움을 줄 수 있기 때문에 서로 머리를 맞대고 좀 고성을 할 때는 만나서 고성도 하고 하지만 여러 가지 고발이나 이런 것보다는 대화로써 푸는 방법이 좋겠다는 생각입니다. 그래서 그 과정에서 좀 불리하거나 어려운 점이 있으면 의회에 요구하고 그래서 의회가 또 중재하고 조정하는 역할을 하는 것이 좋겠다는 생각입니다. 한 말씀 부탁드리겠습니다. 
</p>
<p><b>○ 참고인 이은환 </b> 위원님 말씀하신 것처럼 모든 걸 다 대화로 풀고 싶습니다. 오죽했으면 그랬을까. 대화로 풀 수 있게 많이 살펴봐 주십시오. 
</p>
<p><b>○ 민경선 위원 </b> 네, 알겠습니다. 자주 만나겠습니다. 원장님도 자주 만나겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 민경선 위원 </b> 이상입니다. 
</p>
<p><b>○ 부위원장 정승현 </b> 민경선 위원님 수고하셨습니다. 다음 유영호 위원님 질의해 주십시오. 
</p>
<p><b>○ 유영호 위원 </b> 용인 출신 유영호 위원입니다. 원장님, 오늘 분위기가 전과 다르게 좀 무겁죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아뇨, 안 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 안 그래요? 저는 수일 전부터 굉장히 무겁게 진행될 거라고 알았어요. 여기 계시는 관리직 분들이 분주하게 왔다 갔다 하고 기재위를 찾아들고 위원님들을 찾고 해서 ‘아, 전과는 좀 다르게 진행이 되겠구나.’ 하는 그런 걸 느꼈는데요. 지금 여러 위원님들이 제기된 문제점을 쭉 말씀하셨는데 바라보는 시각이 다 다릅니다. 틀린 게 아니라 다름이 있었다는 것을 서로 다 이해하고 저부터도 그렇게 생각합니다. 조직의 발전을 위해서 좀 더 전향적인 모습을 가져줬으면 하는데 원장님을 비롯한 경영진들이 먼저 노력해 주셨으면 하는 그런 당부를 드리고요. 저를 포함해서 우리 기재위 위원님들이 경기연구원에 대한 애정 깊다는 것 아시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 잘 알고 있습니다. 
</p>
<p><b>○ 유영호 위원 </b> 그러면 시작하도록 하겠습니다. 원장님이 평가하시는 올해 경기연구원의 최고의 성과를 꼽는다면 무엇인지 몇 가지만 한번 말씀해 주세요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이 자리를 빌려서 위원님들과 제 뒤에 있는 저희 직원들께 감사말씀드리는데 너무 많은 일들을 했습니다. 국제회의 2건, 아까 말씀드린 대로 기본소득 국제회의와 DMZ포럼 국제회의는 저희 역량에 불가능하다고 처음에는 생각했지만 매우 훌륭히 수행했다고 생각하고 연구로서도 저희 기본소득연구단과 그다음에 남북관련연구단 그리고 국토보유세연구단 그다음에 도민환원제 이런 것들을 매우 훌륭히 연구했습니다. 물론 이런 것들을 제가 도드라지게 말씀드렸습니다마는 무엇보다도 각 실에서 자기 맡은 바 도정을 백업하는 박사님들과 실장님들, 특히 실장님들의 도움이 매우 컸다고 생각합니다. 
</p>
<p><b>○ 유영호 위원 </b> 제가 의원의 입장으로서 개인적으로 평가를 하자면 우선 작년 행감 때 여러 지적사항이 있었죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 그런데 한두 가지를 제외하고는 모두 완료가 됐다는 점 일단 감사의 말씀을 드리고요. 또 개인적인 의원의 입장에서 다시 하나를 살펴보자면 여러 가지 연구원 사업 중에서 연구부대사업이 있죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유영호 위원 </b> 그중에서도 도의원들과 관련된 의정연구교류분야의 협업이 전보다 많이 활발하게 진행되었고 그다음에 연구원들의 지역에서의 각종 토론회 참여 등 교류도 많이 늘었다는 점을 높이 평가합니다. 저 또한 연구원들과 함께하는 토론회를 수차례 참여했고요. 그다음에 12월 중에 요즘 전국적으로 뜨거운 화두로 떠오르고 있는 장기 미집행 공원 문제 있죠? 공원 일몰제와 관련해서 연구원의 김한수 박사가 발제하는 지역토론회를 지금 준비하고 있습니다. 그래서 그런 점을 감사하게 생각하고 있습니다. 
</p>
<p style="padding-left:1.2em">  원장님께서는 작년 부임 이래 첫 업무보고를 시작으로 행정사무감사 그리고 연말에 예산심의, 올 초에 업무보고를 통해서 연구원의 혁신, 체질을 개선하고 연구원의 위상을 재정립하라는 주문과 그거에 대한 과제로써 저희 기재위에 시급한 지원을 요청하셨어요. 그렇죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 기억하시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유영호 위원 </b> 양질의 연구인력과 깊이 있는 연구를 위해서 무엇보다도 예산확보가 필요했죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 지금도 기억되는데 예산확보를 위해서 동분서주하던 박인숙 재정부장의 모습이 지금도 생각됩니다. 또 예산심의 과정에서 여러 논란이 있었어요. 삭감을 비롯해서, 굉장히 큰 금액의 삭감 논의가 있었죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유영호 위원 </b> 그럼에도 불구하고 원안대로 예산을 확보하고 집행이 됐습니다. 오늘 답변 중에도 연구인력 확보에 대한 애로사항을 잠깐 말씀하셨는데 결과적으로 원하는 예산을 수립하고 지원했죠, 저희가? 그럼에도 불구하고 결과는 실패였습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 송구합니다. 
</p>
<p><b>○ 유영호 위원 </b> 연구인력 확보를 위한 예산이 얼마인지는 기억하고 계십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 인건비 말씀하시는 건가요? 
</p>
<p><b>○ 유영호 위원 </b> 네. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 인건비가 전체의 한 35% 정도 차지하고 있습니다. 위원님들께서 주신 188억 중에서 35% 정도입니다. 
</p>
<p><b>○ 유영호 위원 </b> 본 위원이 단순하게 계산을 해 봤는데요. 연구인력 충원의 실패로 불용처리되기 직전인 예산이 한 25억이 넘을 것 같던데. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 위원님, 맞습니다.
</p>
<p><b>○ 유영호 위원 </b> 물론 다음 주에 있을 예산심사 과정에서 그에 대한 여러 가지 의논들이 논의되겠지만 원하는 인력을 확보한다는 것이 어려울 수도 있습니다. 이건 경영진도 알고 기재위 위원들 모두 다 알고 있었어요. 확보했어야죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 송구합니다. 
</p>
<p><b>○ 유영호 위원 </b> 송구하다는 그런 답변이 그냥 그렇게 쉽게 나와서는……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니요, 그게 지당하신 말씀이라고 생각하고요. 스스로 창피하게 생각합니다, 그 부분이 이렇게 된 데에 대해서는. 
</p>
<p><b>○ 유영호 위원 </b> 근본적인 연구인력 확보, 아까 말씀하신 것 있죠. 집행부 쪽에서, 비전전략담당관실인가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 미래.
</p>
<p><b>○ 유영호 위원 </b> 아, 미래전략담당관 그쪽에서도 관여를 하죠, 인력수급에 관해서? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 그러니까 무엇 때문에 인력 확보가 안 되는지 속시원하게 설명 좀 해 주세요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 여러 가지 원인이 있는데 첫 번째는 저희들 의사결정이 좀 늦어지는 원인이 있습니다. 저희들이 박사급 연구원을 뽑아놓으면 이 연구원은 저나 위원님들이나 또는 도 누구라도, 이런 분들보다도 훨씬 긴 연구기간을 갖게 되시는 분들입니다. 매우 소중한 분들이기 때문에 함부로 뽑을 수 없는 건데 지금 박사들 인력시장은 대학하고 연구원들이 선점투쟁을 벌이고 있습니다. 좀 일찍 해서 일찍 뽑고 일찍 채용하고 이런 투쟁을 벌이고 있는데 저희들 의사결정이 다소 늦어진 감이 있었고 또 일부는 저희들이 뽑아놓은 상태에서 이탈하는 경우들도 있습니다. 아까 말씀드린 대로 저희 급여가 낮은 것은 아닙니다만 국책연구기관에 비해서 중위권은 저희들이 가고 있어서 지방연구원으로서 낮다고 말씀드릴 수 없습니다만 또 상대적으로 바라는 기대임금들이 서로 다르기 때문에 들어왔다가 나가는 경우들도 좀 있었고 또 몇 분은 좋은 인력을 뽑아놓은 결과이기는 합니다만 좀 더 나은 곳으로, 대학이라든가 하는 곳으로 간 경우들도 있었습니다. 그래서 결과적으로 현재 14명의 공석이 있었고 오늘이라도 허가가 떨어져서 저희들이 이 인원을 뽑을 수 있게 돼서 열심히 노력해서 최선을 다해서 좋은 인력을 뽑을 수 있도록 노력하겠습니다.
</p>
<p><b>○ 유영호 위원 </b> 단순히 그런 기대임금의 미스매칭 때문에 그런 사안이 발생한다고 100% 받아들이기 힘들고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 연구하기에 조성되는 경기연구원의 환경이라든가 연구 분위기 같은 것에서 혹시 조직의 경직성 같은 것도 원인이 있지 않을까요? 오늘 노조위원장님을 비롯해서 전부 다 하시고 싶은 말씀을 다소 자제하시면서, 원장님도 마찬가지지만 이렇게 표현을 하시는 것 같은데 살펴보고 들어본 바에 따르면 자유롭게 연구할 수 있는 그런 분위기가 너무 없다. 또 경영진에서 보면 성과가 있어야 되잖아요. 그래서 그건 아까도 서두에 말씀드렸다시피 양면성이 다 있다고 생각을 해요. 그래도 올 6월인가요, 경영부원장님 새로 오셨잖아요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 7월.
</p>
<p><b>○ 유영호 위원 </b> 7월인가요? 원래 경영본부에서 경영부원장 체제로 확대 승격이 됐죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 혹시 위원님들 중에 그 사실 알고 계셨던 위원님들 계신가요, 조직개편이 돼서 경영부원장님이 새로 오셨다는 내용을? 
</p>
<p style="padding-left:2.4em">    (「개별적으로 인사를 하셔 가지고.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그게 언제쯤 들으셨어요? 저희가 사실, 물론 그런 직제나 조직이 개편되고 하는 건 이사회를 통해서 하고 있죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 유영호 위원 </b> 그렇지만 연구원 소관 상임위인 저희는 좀 알고 있지 않아야 될까요, 조직개편 정도는? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 사전적으로 보고를 드렸어야 되는데 일부 위원님들께만 드린 것 같아서 그 부분 시정하도록 하겠습니다.
</p>
<p><b>○ 유영호 위원 </b> 그 일부 위원 중에 저는 끼지 않았군요. 자꾸 실망스럽다는 생각이 드는데요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 죄송합니다. 
</p>
<p><b>○ 유영호 위원 </b> 그러다 보니까 경영분야에서 아까 박사급 연구인력, 핵심적인 경기연구원을 이끌어 갈, 연구분야를 이끌어 갈 연구인력을 모집하고 채용을 전부 담당하잖아요. 승격이 됐는데도 왜 이렇게 안 될까. 그리고 왜 기존에 물 밑에 가라앉아 있다가 갑자기 이러한 노사갈등 문제가 나오고 갑자기 성과연봉제니 성과급제니 그런 급여체계에 대한 말도 튀어나오고 하니까 그래서 좀 살펴봤어요. 그 와중에 경영부원장님이 10월 18일 날 경향신문 인터뷰 기사 실렸는데 좀 뜻밖이었습니다. 뭐라고 났느냐면 “선거공약 전문가 김재용, 86세대는 부패보다 무능이 문제. 구호 세대에서 정책 세대로 대전환을” 그리고 “한총련 초대 의장 출신 김재용 연구부원장” 하고 이렇게 경향신문에 났어요. 그래서 제가 부원장님한테는 말씀드렸는데 ‘이게 어떻게 났을까?’ 다시 한번 보니까 10월 17일 날 국회에서 “권력의 탄생과 성공의 법칙” 해서 출판기념회를 가지셨다고 나왔어요. 저는 그걸 보는 순간 ‘아, 이게 뭐지?’ 그런 생각이 들고 우리 위원님들 그 소식을 접하고 ‘뭐야?’ 다 그런 생각을 하셨습니다. 이게 잠깐 왔다가는 정무적인가, 경영부원장이라는 자리가 잠시 스쳐가는 자리인가, 속 시원히 여기에 대한 답변을 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 경영본부장에서 경영부원장으로 직제개편을 한 건 다른 것들도 개방직으로 일부 하면서 직제개편을 하였습니다. 그 와중에서 저희들이 저희 연구원의 행정기획능력이 좀 떨어진다는 사실을 판단하였고 이래서 조금 직급을 높여서 뽑기로 판단하였습니다, 이사회의 승인을 받아서. 경영부원장께서 저희들이 했을 때 여러 선택지가 없었습니다. 신청하신 분이 한 분이었고 한 분을 놓고 판단하였습니다. 그래서 당시 심사위원들, 추천위원회에서 한 분에 대해서 만장일치로 가판단을 해 주셔서 저희들이 선택을 하였던 것이고 한총련 의장이라든가 하는 것들은 사전적으로 알지 못한 채 저희들이 뽑았습니다. 다만 경영부원장도 정치적 선택의 자유가 있는 사람으로서 본인이 업무시간 외에 선택하는 것은 본인의 자유라고 생각합니다. 
</p>
<p><b>○ 유영호 위원 </b> 간단명료하게 깔끔하게 답변을 잘 들었고요. 김재용 부원장님 생각을 들어봐야죠. 
</p>
<p><b>○ 경영부원장 김재용 </b> 경영부원장 김재용입니다. 우선 상당히 송구스럽습니다. 저 때문에 이렇게 문제를 일으키는 것 같아서. 그렇지만 저는 부임하면서, 책을 썼던 것은 꽤 오래된 일입니다. 그래서 그 기간이 겹쳤기 때문에 그런 거고 계획을 해서 생겼던 것은 아닙니다. 그리고 경영부원장으로서 제가 능력은 많이 부족하지만 매일 아침 6시부터 늦게까지 직무를 충실히 수행했다고 본인 스스로 생각하고 있습니다. 제가 그 외에 정치적인 그런 문제에 대해서 요구를 받고 얘기하는 부분에 있어서 잘 아시겠지만 언론이 자의적으로 해석하는 부분도 굉장히 컸고요. 그런 부분들이 컸기 때문에 조금 오해하시는 부분도 있다 이렇게 말씀드리고 싶고요. 저는 경영부원장으로서 역할을 더욱더 지금보다 더 열심히 직무를 수행하겠다 이런 말씀을 드리겠습니다. 
</p>
<p><b>○ 유영호 위원 </b> 말씀 잘 들었습니다. 액면 그대로 받아들이겠습니다. 위원장님, 이상입니다.
</p>
<p><b>○ 부위원장 정승현 </b> 유영호 위원님 수고하셨습니다. 다음 임채철 위원님 안 하셨죠? 임채철 위원님 질의해 주십시오. 
</p>
<p><b>○ 임채철 위원 </b> 성남 출신의 임채철 위원입니다. 제가 방금 전에 부원장님 관련해 가지고 이게 보니까 굉장히 중요한 자리더라고요. 이사회 회의록을 보니까, 경기연구원장 유고 시 업무를 승계하는 순서가 있죠? 몇 번째 정도 되는 거예요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 세 번째로 기억하고 있습니다. 
