<p><b>○ 임채철 위원 </b> 그럼 첫 번째는……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 첫 번째는 저고요. 두 번째는 연구부원장이시고 세 번째가 경영부원장입니다.
</p>
<p><b>○ 임채철 위원 </b> 그런데 보니까 이게 지난 6월 11일 날 직제 개정이 되고 그때 들어오신 건데 말씀하신 대로 굉장히 중요한 자리라고 하셨는데 혹시 전공이나 이런 쪽은 이쪽하고 조금 맞으신가요? 이쪽을 전공하셨나요? 경영을 전공하셨든가, 주로 보니까 재정이라든가 행정 쪽에 책임을 맡고 계신데 전공분야는 어떻게 되시는지 혹시…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 제가 박사학위까지 다 하신 분이기 때문에 그 중간 전공들을 다 알고 있지 못해서……. (경영부원장을 향해) 간단히 좀 말씀해 주시지요. 
</p>
<p><b>○ 경영부원장 김재용 </b> 저는 학부에서는 정치외교학을 했고요, 그다음에 석사는 일본 게이오대학에서 공공정책을 했습니다. 그리고 와세다대학에서 공공경영을 했습니다. 그래서 이 분야와 딱 맞는 부분이다 이렇게 말씀드릴 수 있겠습니다. 
</p>
<p><b>○ 임채철 위원 </b> 일정 정도 연관은 있으시네요, 그러면. 행정도 좀 하시고 정책도 하시고. 일단 저희가 그런 의심, 왜냐하면 이게 너무 우리가 지난 기사로서 확인했을 때 보면 내년에 출마를 하실 것처럼 기사가 나오고 해서 단순하게 경력 쌓기로 우리가 경기도 조직개편까지 해 드린 거 아닌가 이런 합리적인 의심이 들어서 여쭤본 거고요. 방금 전에 말씀하셨으니까 우리 경기연구원을 위해서 끝까지 책임 있는 자세 가져주셨으면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  제가 또 하나 원장님께 단도직입적으로 여쭤볼게요. 우리가 지금 사실은 존경하는 신정현 위원님께서 지난 5분자유발언을 끝내고 나서…….
</p>
<p style="padding-left:2.4em">    (「도정질의.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  도정질의였죠, 5분자유발언이 아니라. 도정질의를 끝내고 나서 직원들이 약간 동요가 있었던 것 같아요, 경기연구원에서도. 부담감들을 많이 느끼시는 것 같아요. 그래서 이 관련해 가지고 혹시 징계를 하거나 누가 발언을 했다거나 정보를 줬다거나 이런 거 캐시거나 이럴 계획 있으세요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 전혀 없습니다. 
</p>
<p><b>○ 임채철 위원 </b> 징계 안 하신다는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 임채철 위원 </b> 감사합니다. 제가 급여테이블을 봤습니다. 급여테이블 자료를 요청해서 봤더니요, 연구직 테이블이 있고 초빙연구원 테이블이 있고 연구원ㆍ행정원에 관련된 테이블을 자료로 받았어요. 보니까 2012년에 급여테이블이 조정이 돼 가지고 연구직의 경우에는 직급별로 4.19~7.66% 정도씩, 4~7% 정도씩 올랐더라고요. 보니까 낮은 직급들이 좀 인상률이 높았어요. 그래서 바람직한 현상이구나 이렇게 판단을 했는데 초빙연구원 같은 경우라든가 연구원ㆍ행정원의 경우에 보면 이게 2017년까지 아예 급여테이블 변동이 없었더라고요. 그게 작년에, 2019년 8월에 연구원이나 행정원은 한 5% 정도 일괄적으로 보수가 인상이 됐고요. 연구직이라고 하면 보통 선임연구원들 얘기하시고 박사님들 얘기하시는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 다 포함됩니다만 연구원이라 하면 통상적으로 정규직화되기 전에는 선임연구위원이나 연구위원을 말했고 그다음에 연구직이라고 할 때는 연구원이라고 하는 게 고유명사이자 저희 연구원에서는 또 보통명사로 사용돼서 임시직으로 들어온 석사급 연구원들도 줄여서 연구원이라고 불렀었습니다. 
</p>
<p><b>○ 임채철 위원 </b> 연구직에는 관리직ㆍ정보직도 다 포함이 되는 건가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 안 그렇습니다. 
</p>
