</p>
<p><b>○ 경기연구원장 이한주 </b> 연구직은 그동안에 매우 오랫동안 임금인상이 없었습니다, 아까 모두에 말씀드린 대로. 다만 호봉인상은 있어서 급여는 꾸준히 2%~2.5% 사이의 인상이 있었습니다만 그다음에 임금인상이 없었습니다. 동시에 석사급 연구원, 저희들이 혼동을 피해서 석사급 연구원이라고 부르는데 이분들은 사실 호봉인상조차 정체되어 있는 상태로 지속되어 왔었습니다. 그래서 이분들에 대한 임금인상의 필요성이 크게 강조되었고 이렇기 때문에 이 부분에 대해서만, 도에서도 알고 있었기 때문에 이 부분에 대해서 임금인상이 있었다 이렇게 말씀드릴 수 있겠습니다. 
