<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 그러나 그 말에 설명이 좀 필요한데요. 저희 연구원은 아까 말씀드린 대로 박사 연구원들이 중심으로 되어 있는 연구기관이었습니다. 그래서 박사급 연구위원 혹은 선임연구위원들이 필요에 따라서 석사 연구원들을 본인이 요청하는 사람으로 해 주면 그분들을 충원하였습니다. 그리고 또 프로젝트가 끝나면 나가기도 하고 또는 다음 프로젝트로 이어지기도 하는 게 관행이었고, 쭉 이어진 관행이었습니다. 그래서 대부분 박사 1명이 석사 1명의 보조를 받아서 연구하는 체제를 유지하다가 이게 작년 연말부터 정규직으로 전환되었습니다. 그래서 저희는 희망하는 사람 전원을 3차에 걸쳐서 탈락되면 그다음, 탈락되면 그다음 해서 3차에 걸쳐서 전원을 저희들이 정규직 무기계약직으로 전환을 시켰습니다. 그래서 석사급 연구원이 있고 그다음에 또 아까 말씀드린 대로 저희들이 인력을 충원하고 이러면서 지금까지는 박사님 대 석사님들의 매칭이 일대일로 되었습니다. 말하자면 교수가 조교를 데리고 연구하는 이런 방식이었는데 이 방식이 이제는 지양되지 않으면 안 되는, 왜냐하면 일대일로 정원관리를 해 주지를 않습니다, 도가. 그리고 이미 다른 연구원들도 그런 체제를 거의 대부분 다 면했습니다. 그래서 저희들도 원래는 사실상 박사급 연구원에 속해 있던 석사급 연구원이지만 그 고용관계의 실질적 권한이 지금은 이분들이 모두 다 통괄돼서 연구원에 통합되어 있는 상황인데 또 박사님은 박사님들대로 석사님은 석사님들대로 현재까지 내가 뽑아놓은 사람, 나하고 일했던 사람 이런, 말하자면 연구관의 도제 관계가 어느 정도 남아 있어서 이런 부분들이 사실은 연구원 운영에 현재 매우 중요한 기제가 되고 있다 이렇게 말씀드릴 수 있겠습니다. 
