</p>
<p style="padding-left:1.2em">  제가 우리 야근내역도 보니까, 야근내역 제가 자료를 한번 받아봤어요. 야근내역을 받아봤더니 그 자료에 보니까, 보내주신 자료 근무자 야근내역 중에 보면 정규직하고 비정규직 연평균 내역을 보니까 2017년, 2018년, 2019년 3개년 치를 주셨는데 2017년의 자료를 봤을 때는 정규직과 비정규직의 야근이 별 차이가 없어요. 그런데 2019년에 보니까 정규직의 경우에는 157시간, 비정규직의 경우에는 63시간으로 이상하게 현저하게 줄어들었어요, 비정규직이. 비정규직의 처우가 개선이 된 건 아닌 것 같은데. 아까 전에 합리적인 의심이 드는 건 뭐냐면 실제로 야근을 하는데도 불구하고 체크를 못 하는 거죠. 본인의 근로계약과 관련된 문제가 혹시 문제될 소지가 있으니까.
