<p><b>○ 임채철 위원 </b> 네, 그러면 또 밑에 보니까 다른 또, 약간 반대……, 약간 느낌이 좀 달라요. 연구원과 비연구원을 가지고 구분한 자료에 보면 2017년엔 별 차이가 없었어요. 근데 2019년도에는 비연구원들만 야근내역이 급격히 증가했어요. 그건 또 어떤 이유일까요?
