<p><b>○ 경기연구원장 이한주 </b> 저희 연구원이 타 연구원에 비해서 행정ㆍ관리직이 아주 소수인, 다소 업무량의 비율이 좀 덜 맞아 있는 그런 구조가 됩니다. 그래서 비연구원, 행정직하고 관리직이 되는데 이분들이 2019년 들어서 사람을 더 뽑고 또 아까 말씀드린 대로 국제행사를 좀 하고 이러다 보니까 업무량이 사실 굉장히 많이 늘었습니다. 이래서 비연구원을 긴급히 요청해서 최근에 5명의 증원을 받았습니다마는 그동안 업무과로로 인해서 몇 분이 또 퇴직을 하셨습니다. 그래서 이런 현상이 발생했다고 말씀드리겠습니다.
