</p>
<p style="padding-left:1.2em">  제가 아까 전에 한마디만 드리고 싶은 말씀 좀 드리고 마무리 짓겠는데요. 아까 전에 제가 우리 박사님들, 계약직들 석사연구원 1명씩 매칭을 해 가지고 같이 일을 했다고 하셨는데 이 단기계약직 근로자들의 비중이 상당히 높다는 걸 많이 느꼈어요. 그러니까 입ㆍ퇴사가 너무 빈번한 거예요. 작년에 보니까 퇴사자 숫자도 꽤 되고 입사자, 그러니까 제가 4대보험 자격취득 상실내역을 받아봤는데 그 내역에 보니까 상당히 단기계약이 많고 퇴사가 너무 빈번하더라고요. 그런데 그게 그분들이 퇴사를 딱 예상을 하고 들어와서 바로 나가면 다행인데 책임제 연구원들께서, 박사급 연구원들께서 재계약의 가능성 여부를 계속 얘기를 하시는가 봐요. 그러니까 실제로 노동법상에 보면 사실 해고 예고는 한 달 전에 해야 되지만 이분들이 나가라 할 때까지 본인이 나가야 되는지를 확실히 알지 못하고 계속 근무하다 나가는 경우들이 많이 있다고 들었습니다, 제가.
