<p><b>○ 김강식 위원 </b> 석식하시고.
</p>
<p><b>○ 부위원장 정승현 </b> 본질의 끝나고 지금 추가질의하실 위원님들이 계시죠? 몇 분 계시죠? 두 분인가요? 어떻게 할까요? 이 추가질의까지 아예 끝나고 마칠까요, 아니면 위원장은 식사를 지금 얘기를 하는데 어떻게 했으면 좋겠어요? 아예 추가질문까지 다 끝내고 오늘 감사종결을 그렇게 할까요?
</p>
<p><b>○ 김우석 위원 </b> 어떠세요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들이 결정하면 그대로 합니다. 
</p>
<p><b>○ 김우석 위원 </b> 추가질의 시간이 무제한으로 풀리는 거죠, 이제부터는?
</p>
<p><b>○ 부위원장 정승현 </b> 지금까지 해 왔던 대로 그렇게 하도록 하겠습니다. 지금 추가질의하실 위원님 몇 분 계세요? 지금 세 분 계신가요?
</p>
<p><b>○ 김우석 위원 </b> 네 분이요. 
</p>
<p><b>○ 부위원장 정승현 </b> 그럼 식사를 하시고 추가질의를 하는 걸로 하고. 
</p>
<p><b>○ 민경선 위원 </b> 위원장님도 식사하고 하자고 하시더라고요. 
</p>
<p><b>○ 부위원장 정승현 </b> 네, 제가 질문을 아직 안 해서. 그럼 제 질문까지 마치고 식사하는 걸로 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 민경선 위원 </b> 부위원장님, 그 자리에서 해도 될 것 같습니다. 
</p>
<p><b>○ 부위원장 정승현 </b> 해도 될까요? 양해해 주신다면 이 자리에서 간단히 좀 몇 가지만 여쭙도록 하겠습니다, 원장님. 우선 우리 노조위원장 오늘 증인으로 참석하셔서 여러 가지 의견들……, 잠깐 좀 자리정돈해서 다시 질의하도록 하겠습니다. 
</p>
<p style="padding-left:2.4em">    (정승현 부위원장, 정대운 위원장과 사회교대)
</p>
<p><b>○ 위원장 정대운 </b> 본질의가 정승현 위원님만 남은 거죠? 우리 정승현 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정승현 위원 </b> 노조위원장님 오셔서 서로 불편한 관계에서 오늘 말씀도 주시고 또 원장님 답변 주시고 하셨는데 사실 아쉬움이 우선 참 많습니다. 어쨌든 노사 양쪽 입장을 들어보면 들어볼수록 또 충분히 이해하면서도 또 한 지붕에서 같이 늘 맞대고 살아야 되는 그 관계에서 왜 이렇게 결국은 소송, 진정까지 갔는가. 아까 위원장 말씀하신 것처럼 오죽했으면 소송하고 진정까지 갔겠는가라고 말씀하셨습니다마는 또 오죽했으면 임원진에서는 소송, 진정까지 갈 수밖에 없도록 놔뒀겠는가라는 생각도 해 보게 됩니다. 그래서 앞서 위원들께서 여러 가지 합리적인 대안들 또 말씀들을 많이 주셨기 때문에 저도 간곡히 부탁드린다라면 어쨌든 소송에 대한 또 진정에 대한 결과가 나와야만 이후의 판단이나 또 합리적인 선택들을 하실 수 있다라고 볼 수도 있겠습니다마는 그 전에라도 충분히 좀 소통하고 대화해서 이 문제를 원만하게 해결했으면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  저는 기본적으로 노사 간의 협상의 1원칙도 대화고 2원칙도 서로 대화하고 3원칙도 대화라고 생각합니다. 서로 대화, 얼굴 맞대고 대화하게 되면 충분히 저는 풀어낼 수 있다라고 보여지기 때문에 어쨌든 소송결과 또 진정결과만 기다리지 마시고 하루빨리 서로 협상 테이블에 앉으셔서 이 문제가 원만히 해결되고 그로 인해서 우리 연구원이 또 본연의 역할을 할 수 있도록 그렇게 좀 기대해 마지않습니다, 원장님.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 귀한 말씀 감사하게 생각합니다. 
</p>
<p><b>○ 정승현 위원 </b> 노조위원장님 저 뒤에 지금 계십니다만 그 자리에서 답변 좀 부탁드리겠습니다. 제가 드린 말씀에 대해서 좀 충분히 이해하고 그렇게 하실 용의가 있으신가요? 
</p>
<p><b>○ 참고인 이은환 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 그렇게 좀 하시고요. 본질의를 하도록 하겠습니다. 지금 경기연구원에서 앞서 원장님도 말씀하셨습니다마는 기본소득박람회나 DMZ 관련 포럼, 큰 행사를 하셨었잖아요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 저는 사실 이 행사들을 직간접적으로 관여하면서 과연 경기연구원에서 이 행사들을 하는 게 바람직한가라는 생각들을 해 보게 됐어요. 엄연히 청내에 주무부서가 있고 또 기관이 있는데, 그런데 끝나고 나서 왜 경기연구원에서 또 할 수밖에 없었는가라는 측면으로 사실 이해를 하게 됐다라는 것들이죠. 그런 측면에서 어쨌든 경기연구원이 우리 경기도가 갖고 있는 또 이 지사가 갖고 있는 그런 가치실현을 위해서 굉장히 큰 역할들을 해 왔다라는 측면에서 이 자리를 빌려서 고생하셨다는 말씀을 드리고 싶어서 제가 이 말씀을 드렸고.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 감사합니다.
</p>
<p><b>○ 정승현 위원 </b> 또 하나는 지금 내년도 예산 요구하셨죠, 본예산? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그런데 지금 감액해서 요구하셨죠? 오히려…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 몇천만 원 정도 감액됐습니다.
</p>
<p><b>○ 정승현 위원 </b> 그니까 오히려 올해 예산보다 감액해서 요구를 하셨던 부분들이 그동안 저희 기재위에서, 상임위에서 예산절감 내지는 예산의 효율성 집행을 늘 주문했고 그 부분을 연구원에서 겸허히 받아들여서 저는 이렇게 예산을 신청하셨다라고 보여집니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그런 점에서도 어쨌든 그 사고들을 굉장히 높이 산다라는 얘기를 좀 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  앞서 지금 부원장님 새로 오셨는데 우리가 지금 임원 추천, 원장님 지금 경기연구원의 임원이 지금 어떻게 구성되어 있죠? 지금 이사장, 원장, 감사 둘, 그리고 이사…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사 1명이고요. 
</p>
<p><b>○ 정승현 위원 </b> 감사 원래 2명 두게 돼 있잖아요, 정관에. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사는 아직 두지 않았습니다만……. 
</p>
<p><b>○ 정승현 위원 </b> 원래 정관에 감사 2명 두게 돼 있죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 아, 그런가요?
</p>
<p style="padding-left:2.4em">    (경기연구원장, 관계직원에게 확인 중)
</p>
<p style="padding-left:1.2em">  네, 선임직하고 당연직. 
</p>
<p><b>○ 정승현 위원 </b> 네, 그렇게 돼 있죠. 그리고 이사가 30명 있는데 지금 이사는 몇 명으로 구성되어 있죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 11명으로 구성돼 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 30명 이내에 두게 되어 있죠, 지금?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그러면 11명, 2명. 14명이 총 임원이라고 봐야 되겠네요? 부원장님도 임원에 들어가는 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그럼 15명으로 봐야 되겠네요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 13…….
</p>
<p><b>○ 정승현 위원 </b> 이사장, 원장, 부원장, 감사 둘 그리고 여기에 이사 11명.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 
</p>
<p><b>○ 정승현 위원 </b> 이렇게 11명 하면 총 16명이네요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 위원님 말씀이 맞습니다.
</p>
<p><b>○ 정승현 위원 </b> 그렇죠. 그 임원들을 선임할 때 최종적으로 이사회의 의결을 거쳐서 선임을 하잖아요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그러면 그 전에 추천절차는 어떻게 진행되죠? 이사회가 상정되기 전에. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그때는 모집공고를 냅니다. 
</p>
<p><b>○ 정승현 위원 </b> 네, 공고 내서 1차 심사를 하고 면접을 하죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그 심사와 면접은 어떻게 진행을 하는 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그런데 심사도 이사회에서 합니다. 
</p>
<p><b>○ 정승현 위원 </b> 심사도 이사회? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 면접도 이사회에서? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 최종적으로는 이사회를 거쳐야 합니다. 
</p>
<p><b>○ 정승현 위원 </b> 제가 여쭤보는 이유가 있는 거죠. 원장님 짐작하셨겠습니다마는 추천도 이사회, 면접도 이사회 그리고 최종의결도 이사회. 이런 과정들, 이게 과연 맞는가라는 생각을 저는 해 보게 되거든요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 와중에 도에서 심사위원을 추천받습니다. 그래서 최종적으로 이사회에서 결정한다 이 뜻입니다.
</p>
<p><b>○ 정승현 위원 </b> 심사위원, 도에서?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그래서 제가 작년 행감 때 임원추천위원회 제안을 좀 했었죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그러셨습니다.
</p>
<p><b>○ 정승현 위원 </b> 그전에 워낙 임원 추천하는 과정에서, 임원 선출하는 과정에서 여러 가지 말썽들이 있어서 임원추천위원회를 좀 도입해 볼 생각이 없으시냐. 그리고 그 부분에 대해서 충분히 좀 검토해서 판단하시겠다라고 했는데 제가 임원추천위원회를 제안했던 부분은, 물론 도에서 심사추천위원회를 하신다고 하지만 임원추천위원회를 구성하면 기본적으로 도에서 추천하고, 의회에서 추천하고, 자치연구원에서 추천해서 추천된 위원회를 통해서 뭐든 이사회에 상정되기 전 과정들을 추진하는 것 아닙니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그래서 제가 좀 제안을 드렸던 부분인데 지금 이 부분에 대해서는 전혀 검토가 안 되고 있나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 심사위원 추천이 임원추천위원회의 기능을 대신한다고 생각해서 그 부분들을 지내왔는데. 위원님, 저희들로서는 특별하게 이제…….
</p>
<p><b>○ 정승현 위원 </b> 저는 이제 그렇습니다, 원장님. 아시다시피 지금은 사실 의회의 구조가…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 정승현 위원 </b> 의회구조가 지금 1교섭단체로 구성되어 있다 보니 인사추천위원회를 일방적으로 도에서 추천하더라도 사실 의회에서 이 부분에 대해서 크게 문제 삼지 않을 수도 있고 또 문제 삼지 않아 왔죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그러나 만일 이게 2교섭단체 내지 3개 교섭단체가 존재하게 된다라면 이 부분에 대해서는 분명히 사후에 얘깃거리가 된다라는 것들이죠. 과연 이 추천위원회를 인정하겠느냐 그거죠. 그런 측면에서 향후 연구원을 위해서라도 임원추천위원회를 좀 긍정적으로, 적극적으로 검토하는 게 바람직하다라는 생각을 해 보게 됩니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 검토하겠습니다. 임원추천위원회의 도입을 적극적으로 검토해서 결과 보고드리겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그러는 게 제가 봤을 때는 이후에도 연구원이 이 문제로 인해서 다른 잡음이 없을 것 같고 떳떳할 것이다라는 판단하에서 제가 제안을 드린 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 잡음이 있었던 적은 없는데 그러나 말씀하시는 게……. 
</p>
<p><b>○ 정승현 위원 </b> 지난번에 원장님 오시기 전에 뽑기까지 얼마나 말이 많았습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 그래서 제가 말씀을 드립니다. 두 번째로 지금 연구원에서 여러 가지 과제들을 수행하고 있는데 크게 정책연구 그리고 수탁과제들 그리고 또 일부는 위탁사업을 하고 그리고 나머지 이슈&진단을 통해서 우리가 과제수행들을 하고 있잖아요. 그중에 우리가 정책연구 현황들을 보면 기타 도나 의회에서 의뢰해서 연구를 하는 경우도 있지만 자체적으로 도정의 어떤 현안 또 내지는 사회의 이슈가 돼서 자체적으로 판단해서 연구하는 경우들이 있단 말이죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그러한 연구를 수행했었을 때 그 이후에 연구결과물들에 대한 활용이랄까? 그 부분은 어떻게 진행이 되고 있어요, 지금? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 도 의뢰연구가 아니라 자체연구는 어떻게 활용하느냐 이런 말씀이십니까? 
</p>
<p><b>○ 정승현 위원 </b> 네, 자체. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 자체개발을 할 때는 막연히 개발하는 게 아니라 당시의 상황과, 도의 상황과 국가적인 상황을 고려해서 자체개발을 하는 겁니다. 그러나 그 연구개발을 하는 거는, 연구보고서는 좋은 연구를 만들어서 저희들이 전달하는 경로들이 있습니다. 약 2만 명 정도 되는 데이터베이스를 대서 이런 연구가 진행됐다는 거를 전파하고 그 전파에 대한 활용은 저희 자체연구의 경우에는 특별히 저희들이 추적하지는 않고 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그래서 자체연구한 그 목록들을 보니까 굉장히 어쨌든 우리나라 전체든 또 우리 경기도든 정책적으로 굉장히 중요한 현안들이 주 내용들이에요. 그래서 이런 귀중한 정책과제들을 수행했는데 과연 이런 결과물들이 잘 반영되고 쓰여졌으면 좋겠다, 활용됐으면 좋겠다라는 생각을 해 보게 되는데 과연 이게 지금 어떻게 활용되는지에 대해서 좀 의문이 들어서 여쭤봤는데 다행스럽게 관련기관 내지는 부처에 결과물들을 지금 다 보내고 있다는 얘기죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그러고 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그래서 좀 아쉬움이 있다라면 그런 결과물들이 어떻게 활용되는지에 대한 피드백도 됐으면 좋겠는데 사실 그것까지 우리가 파악하기는 현실적으로 좀 어려움이 있는 부분이 있겠죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 알겠습니다. 마지막으로 두 가지만 간단히 여쭙겠습니다. 킨텍스에서 지난 DMZ포럼 하면서 그때 6개 테마에 11개 섹션인가 그렇게 기억이 돼요. 그렇죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 그중의 하나가 한반도 접경지역에 대한 관리위원회를 구성하자라는 안이 제안된 걸로 기억이 돼요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 굉장히 많은 예산들을 들여서 이런 포럼을 개최하고 있고 거기에서 여러 가지 테마를 가지고, 섹션 각 연구주제를 가지고 토론하게 되고 안들을 내놓게 되는데 이게 포럼이 그냥 포럼을 위한 포럼 자체로 끝나선 안 되겠다, 거기서 제안된 안들이 또 다시 논의가 되는 과정들이 있어야 되겠다라는 생각을 해 보게 되거든요. 그중의 하나가 접경지역에 대한 관리위원회 설치 문제인데 이 부분은 저만 중요하다라고 판단할 수 있고 아니면 연구원에서도 중요하게 판단할 수도 있다고 보여지는데 혹시 사후에 이 부분에 대해서 재조명되거나 논의가 된 부분들이 있었는지요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 당연한 말씀이시고요. 접경지역위원회는 저희만 제안한 게 아니라 대통령께서 올해 6월 달에 핀란드를 가셨을 때 오슬로에서 선언을 2개 하셨습니다. 그중의 하나가 접경지역위원회고 저희들이 이번에 9월 19일 날 포럼을 연 것 중의 하나는 대통령의 의지를 충분히 받들고 또한 경기도가 가지고 있는 매우 중요한 상황을 반영했던 겁니다. 그래서 접경지역위원회에 대해 대통령이 주장하신 후에 이게 진행이 사실 잘 안 됐었습니다. 그래서 저희들이 열심히 촉구를 했고 이 부분과 관련해서 국가균형발전위원회와 통일부에서 이 부분에 대한 움직임이 있고 움직임이 가시화되는 대로 위원님들께 보고를 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  또한 이때 주요하게 제기되었던 게 DMZ평화상에 대한 제안이었습니다. 이 부분과 관련해서는 저희 연구원이 1차 연구를 마무리 지으면, 아직 저희들이 어느 단위에서 연구할지 지금 DMZ포럼의 DMZ 정리작업을 하고 있는데 거기서 결정이 되면 저희들이 평화상과 관련해서 경기도를 위해서 어떤 규모로 어떻게 하는 게 좋을지 이런 부분에 대해서 수습을 하도록 하겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 하여튼 그 연장선상에서 여러 가지 고민을 하고 계신다는 말씀을 들으니까 참으로 다행이라는 생각이 들고요. 
</p>
<p style="padding-left:1.2em">  마지막으로 지난 5월인가 6월에 민주연구원하고 정책연구협력을 위한 업무협약식을 가진 바 있었죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 이 업무협약식을 가진 구체적인 이유는 지역이나 현장에 필요한 의제, 각종 정책들을 공유하고 같이 연구해 보자라는 측면에서 업무협약식을 가진 걸로 알고 있는데 그 이후에 이 부분과 관련해서 더 진전이 있거나 실질적으로 서로 협의해서 연구를 하고 있는 부분들이 있나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 이후, 저희 연구원 입장에서는 입법사항들에 대한 부분도 건드릴 데가 있기 때문에 그런 점이 국가적인 관점이 필요했고 민주연구원은 또 각 지역들에 대한 구체적인 정책개발이 필요했기 때문에 업무협약을 하는 것은 당연하다고 생각해서 저희들이 했습니다. 다만 그 뒤에 정치일정이 매우 빠르게 진행돼서 개별적으로 원장들끼리 통화를 통해서 어떤 연구를 좀 더 했으면 좋겠다, 이런 교류는 있었습니다만 구체적으로 업무와 관련된, 연구교류와 관련된 일은 아직 없었습니다. 
</p>
<p><b>○ 정승현 위원 </b> 네. 어쨌든 이 부분도 모든 언론에 노출이 돼 있고 또 다 알고 있기 때문에 지금 정말 연구원에서 감당하고 있는 그런 여러 가지 역할들을, 일들을 놓고 보면 과연 여기까지, 국책연구까지 같이 겸해서 이렇게 할 수 있는 여력이 있을까라는 생각도 해 보게 되지만 또 한편으로는 경기도정뿐만 아니라 대한민국사 전반에 관한 사항까지도 역할을 하고 있다라는 측면에서 경기연구원의 역할들이 저는 굉장히 크게 기대가 되거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 감사합니다. 
</p>
<p><b>○ 정승현 위원 </b> 그래서 이 부분에 대해서 좀 더 부응할 수 있도록 역할을 해 주시기를 당부드리면서 제 질문 마치도록 하겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 고맙습니다. 
</p>
<p><b>○ 정승현 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장 정대운 </b> 정승현 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  본 위원장도 한마디 하겠습니다. 제가 이렇게 행정사무감사를 보면서 예전의 어떤 일이 떠오르는 생각이 듭니다. 내가 우리 수석님한테도 여쭤봤지만 이 행정사무감사가 참 중요한데 또 2020년도 예산과 직결되는 게 있고 어떻게 보면 경기도민 1,360만의 대표성을 띠고 의원님들을 뽑아서 여기 의회에 보냈습니다. 집행부를 견제하고 도민의 삶의 질을 위해서. 경기연구원도 마찬가지로 조직의 연구하는 부분이 아마 있을 겁니다. 
</p>
<p style="padding-left:1.2em">  우리 연구부원장님, 한번 물어볼게요, 그 자리에서. 부원장님 2016년도도 계셨죠? 
</p>
<p><b>○ 연구부원장 이상대 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 그때 기억나시죠? 한 기관장이나 기관에서 잘못했을 때, 문제 일으켰을 때 그때 예산 2016년도인가 전체 잘렸죠, 상임위에서? 
</p>
<p><b>○ 연구부원장 이상대 </b> 네, 맞습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 맞죠? 그때 예결위원장이 누구였습니까? 
</p>
<p><b>○ 연구부원장 이상대 </b> 알지만 말씀은 안 드리겠습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 누구예요? 접니다. 뭘 생각했겠습니까? 저는 이렇습니다. 지금 연구원 원장님한테도 유감의 표명을 하고 노조위원장한테도 표명을 합니다. 지금 여기 다 도민들이 보고 있을 건데 이 지경까지 가도록 상임위에서는 뭐했는가, 내가 수석님한테 물어봤어요. 우리 연구원 원장님은 여기 들어온 지, 이재명 지사 민선7기 때 들어온 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 그리고 노조위원장님도 같이 7기 때 들어온 건가요? 아니죠? 언제 들어오셨죠? 
</p>
<p><b>○ 참고인 이은환 </b> 입사일을 말씀하시는 건가요? 
</p>
<p><b>○ 위원장 정대운 </b> 네. 
</p>
<p><b>○ 참고인 이은환 </b> 저는 2015년도에 입사했습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 맞습니다. 왜 그러냐면 저는 존경하는 민경선 위원하고 3선의원입니다. 8대, 9대에 있었습니다. 최소한 어떤 부분들이 있으면 연구원도 마찬가지로, 원장님도 “이런 일이 생겼다.” 그리고 노조위원장님도 이런 이런 부분이 있으면 행정사무감사 때 이런 얘기가 나오면 그것은 그 조직의 예산을 잘라달라는 것밖에 안 됩니다. 왜 그러냐면 다음에 예산심사 때는 분명히 그런 부분들을 짚고 넘어갑니다. 예결위도 마찬가지입니다. 그런 심사의 잣대가 되는 거예요. 그러면 그 전에 연구원장님도 사전에 이런 일이 됐다, 존경하는 정승현 부위원장님도 말씀했지만. 그래서 상임위가 있는 것 아니겠습니까? 노조위원장도 마찬가지입니다. 어떤 어떤, 연구원에서 어떤 부당하고 노사가 생각과 방법이 다 틀릴 수는 있지만 감사까지 오지 않고 정당하게 전문위원실에 요청해서 기재위 위원님과 한번 이런 이런 토의 좀 할 수 있는 어떤 부분도 요청할 수 있는데 이런 부분이 아쉽습니다. 
</p>
<p style="padding-left:1.2em">  제가 연구부원장님한테 말씀드린 것은 그때 그 경험들을 봤던 당사자이기 때문입니다. 이런 것들은 앞으로 좀 심도 있게 서로가 고민하고 서로 머리를 맞대고 안 되면 도민이 선출한 대표기관인 의회가 있으니까, 의회가 조정역할 아니겠습니까? 그걸 했으면 남들이 바라봤을 때, 우리 존경하는 신정현 위원님만 있는 것이 아니라 전체 여기를 통해서 사전에 어떤 교감을 했으면 행정사무감사에서 이런 얘기 안 나옵니다. 보면 뭐라고 하겠습니까? 조직이 다 무너졌다. 기재위 무너졌다. 연구원 다 무너진 겁니다. 아마 2020년 예산 잘릴 일만 남은 거죠. 앞으로 이런 부분들은 사전에, 이런 일이 있으면 의회하고 소통을 해 줬으면 좋겠습니다. 그렇게 해 주시죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 감사합니다. 
</p>
<p><b>○ 위원장 정대운 </b> 원활한 감사 진행과 저녁이 됐기 때문에 감사중지를 하려고 하는데 위원님들 괜찮겠죠? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 원활한 감사 진행을 위해서 20시 30분까지 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(19시04분 감사중지)
</p>
<p class=''ar''>(20시37분 감사계속)
</p>
<p><b>○ 위원장 정대운 </b> 좌석을 정돈해 주시기 바랍니다. 감사를 계속하겠습니다. 
</p>
<p style="padding-left:1.2em">  질의하실 위원님 거수해 주시기 바랍니다. 김강식 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김강식 위원 </b> 수원 출신 김강식 위원입니다. 원장님, 지금 성과연봉제에 해당되는 분들이 몇 분 정도 되시는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희 박사님들은 다 적용이 되셔서요. 박사님들이 60명 정도 적용되고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 60분? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 지금 뽑으신 분들, 박사님들은 대부분 다 적용되십니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러면 전체 정원이 아까……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 67명, 박사 정원이 67명입니다. 
</p>
<p><b>○ 김강식 위원 </b> 지금 어쨌든 성과연봉, 기본연봉 플러스 성과연봉이 전체 연봉이라고 그러셨잖아요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김강식 위원 </b> 성과연봉이라는 부분들을 평균으로 계산해 보니까 평균 1,600, 전체 하다 보면 1,600 정도가 되고 아까 평가에 의해서 비율을 나눈 게 한 50%에서 150% 이 비율 정도……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 비율이 아니라 성과연봉은 50에서 150으로 나눠주게 돼 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 네. 50에서 150 나눠주는 걸로. 그러면 단계를 둬서 하는 건가요? 단계를 둬서 그 범위 내에서 결정해 가지고? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러면 그 단계가 많이 있는 건가요, 구간이? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 단계가 5단계 정도 있습니다. AㆍB⁺ㆍBㆍCㆍD 이렇게 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 아까 질의과정에서 보면 몇 년 동안 기본연봉에 대한 부분들이 동결돼 있었다라는 얘기를 들었는데.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김강식 위원 </b> 이 부분들에 대한 부분들은 그냥 계속 고정으로 동결해도 문제가 없는 건가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 부분들을 저희 박사님들이 말씀은 잘 안 하시는데, 점잖으셔서. 그 부분들이 굉장히 좀 불만이십니다. 전혀 안 오른 건 아니고 1년이 지날 때마다 호봉으로 올립니다. 2%에서 한 2.5% 정도 해서 호봉이 올랐을 뿐 기본연봉 자체는 오르질 않았습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그러면 저는 제안을 좀 하고 싶은데요. 이 부분들 속에서 지금 현재 그 50에서 150 정도 돼 있는 구간들 그다음에 평균 한 1,600 정도 돼 있는 금액들, 우선 1,600 정도 되는 금액들을 기본연봉에 일부를 편입시켜서 그 나머지 부분들을 구분하고 그 구분의 구간을 조금 폭을 줄여보는 것들에 대한 내용을 한번 고민해 보실 수는 없을까라는, 그게 어떤 문제점이 있을까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 말씀하신 내용은 호봉제하고 성과연봉제의 비율이 지금 약 8 대 2 정도인데 호봉 부분을 9로 가고 성과를 한 1로 가자 이런……. 
</p>
<p><b>○ 김강식 위원 </b> 어느 쪽이 됐든, 8.5 대 1.5가 됐든. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이런 것도 생각해 보실 수 있다 이런 뜻입니다. 
</p>
<p><b>○ 김강식 위원 </b> 22%가 너무 과하다고 한다면 그 부분들에 대한 내용들이, 사실 3배 정도 차이 나는 거잖아요, 50에서 150 정도 되면. 그리고 기본연봉들이 몇 년 동안 동결돼 있는 부분들이라고 하면 기본적으로 차이가 꽤 많이 날 것 같다는 생각이 들어서, 나중에 맨 위와 맨 아래 단계에 대한 부분들로 구분하자면. 그 부분들은 그렇게 한다고 하면 문제점이나 아니면 그 부분들에 대한 것들을 변경한다면 어떤, 지금 추가하신 어떤 부분들 속에 방향성이 안 맞는 부분들이 있을까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 말씀하신 부분도 충분히 생각하실 수 있는 부분이라서 저희들이 이 부분을 염려하시는 부분과 또 저희들한테 주어진 소명이 있어서 조금 더 생산성 있게 할 수 있으려면 또 그건 그것대로 필요한데 현재로서는 보통 사용하는 방법이 성과연봉제를 늘리는 게 보통 사용하는 방법입니다. 그래서 이 부분은 무겁게 생각해서 여러 가지 많은 고려들을 하겠습니다. 저희들한테 주어진 건 두 가지 가설이 다 있습니다. 임금이 평균적으로 평균화됐을 때 좋은 성과가 있다는 평가도 있고 또 그렇지 않고 평가를 달리하는 게 좋다는 게 있어서 저희들이 좀 많은 고민을 하겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 알겠습니다. 그런 부분도 포함하셔서 고민을 좀 더 해 주시면 좋겠다고 생각을 하고요. 
</p>
<p style="padding-left:1.2em">  그다음에 작년 행감 때도 지적이 돼서 이 부분들 개선이 됐다고 되어 있는데 지금 연구원 안에서 연구사님들이 바깥 쪽에, 외부특강이나 출강 같은 것들을 하실 때 지금 복무관리는 철저히 하신다고 되어 있는데 이 부분들이 보니까 어쨌든 개선을 한다라고는 되어 있지만 실제 근무시간 내에 가시는 경우가 있고 외에 가시는 경우가 있으실 텐데 근무시간 내에 갈 때 이런 부분들이 규정들이나 이런 거에서 잘 관리가 되고 계신가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 그건 일일이 다 저희들이 허락을 받아야 되고요. 그거에 대한 제 원칙은 그렇습니다. 근무시간, 비록 1시간을 하든 2시간을 하든 그게 학부 강의가 된다든지 우리 직원들의 전문성이 발휘되어지는 게 아니라면 허락을 하지 않고 있습니다. 다만 일반대학원에서 석ㆍ박사를 가르친다든지 아니면 전문적인 토론회에 참여한다든지 이럴 때는 가능하면 좀 열어줘서 나가서 우리 연구원들의 전문성도 발휘하고 또 그렇게 되는 방향으로 선언을 했고 그런 방향으로 하고 있습니다. 다만 지나치게 많을 경우에는 그 부분들은 통제가 필요해서 그 부분도 그렇게 통제하고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 여기 제가 갖고 있는 자료를 보면 사실은 전문성이라고 하는 건 본인의 연구분야나 이런 부분들에 대한 부분인데 어떤 것 보면, 모르겠어요. 제가 여기 부서, 연구실 이름하고 나갔던 것들에 대한 요청사유에 대한 내용들을 보다 보면 특히 경기북부센터 이런 쪽에는 경기북부 권역들에 대한 내용들에 어떤 지자체에 나가든 이런 부분들보다 그냥 경기도 전역, 어떻게 보면 남부 쪽에 있는, 수원이 됐든 이 인근에 있는 데 와서 바깥에 나간다는 요구를 하고 나가신 경우들이 상당수 있더라고요. 그러면 그 전문성이라는 부분하고 지금 하고 있는 일에 대한, 연구에 대한 분야가 구분되어 있을 텐데 이런 부분들이 그렇게 이루어지는 것들에 대한 것들은 지금 이걸 봐서는 말씀하신 거랑 다른 내용 아닌가라는 생각이 좀 드는데 이런 건 어떻게 지금 되고 있는 건가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 그 부분은 철저히 되기가 조금 어려운 부분이 있었고요. 전문성이라고 하더라도 제가 오자마자는 학부 강의들을 조금 많이 했었습니다. 그런데 학부 강의는 위원님들이 다 아시다시피 크게 전문성을 요구하지 않는 부분이 많습니다. 그리고 또 특수대학원도 전문성이 크게 요구되지 않아서 저는 전문토론회나 아니면 일반 석ㆍ박사 강의 가는 것들은 주어진 시간 내에서 그 부분들을 허락하려고 하고 있습니다. 그러다 보니 또 남부에 있던 분이 북부로 가서 근무하게 되거나 또는 북부에서 하시던 분이 남부에 오시는, 이게 순환이 되어지니까 그 과정에서 남아있던 과정이라든가 이런 것들을 하시는 경우들이 좀 있을 수 있다고 생각합니다. 
</p>
<p><b>○ 김강식 위원 </b> 네. 그래서 이런 부분들이 사실은, 그러면 이게 지금 하고 있는 연구, 어쨌든 어떻게 보면 부서 같은 거고 지금 여러 가지 몇 개로 나눠져 있잖아요. 제가 그냥 봤을 때는 대부분은 잘 지켜지고 있는 것 같아요. 그런데 특히나 유달리 북부센터가 생긴 지 안 돼서 그런지 몰라도 그쪽에 있는 분들이 가신 내용들을 그냥 쭉 이렇게 들여다만 봐도 상당수가 그렇게 되고 있지 않다. 그래서 그런 부분들에 대한 것들이, 저는 모르겠습니다. 이게 과제하고 아니면 전문성이 있어서 그렇게 하시는지는 모르겠지만 그냥 봐서는 연구실하고의 내용들이 좀 매칭이 안 되는 것 같아서 한번 말씀을 드린 거고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 조금 더 들여다보겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 또 어떨 때는 그냥 단순, 관련도 없지만 심사를 간다든지 이런 경우들이 있더라고요. 이런 부분들은 복무 관련해서는 조금 더, 잘하고 계신다고, 여기 완료가 됐다라고 얘기하고 계시지만 실제적으로 2019년도 것을 보면 그런 내용들이 좀 있거든요. 그래서 그런 부분들도 포함해서 다시 한번 이 부분들의 관리나 이런 부분을 철저히 해 주셨으면 좋겠고……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 근무태세 강화를 다시 한번 점검해 보겠습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그래서 근무시간, 저는 모르겠습니다. 강의를 하시든 토론을 가시든 공식적인 부분들의 출강이나 경기도가 원하는, 지자체가 원하는 부분들 이외에 또 가다 보면 소득들도 생기고 하는 부분들이 있을 때 무분별하게 그 부분들이 허락되고 수락되면 그 부분들이 또 약간의 문제점이 있다고 보여지는데 그 부분들은 어떻게 생각하시나요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 당연히 지당하신 말씀이고요. 저희들이 급여를 풀페이를 주는데 급여추구적 행동을 하는 건 어떤 아주 제한된 범위일 수밖에 없다고 생각합니다. 1년에 저희들이 허락하는 범위가 보수를 받는 건 400만 원 정도로 제한을 하고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 그런 부분이 있는 거군요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 원고가 됐든 뭐가 됐든 400만 원 정도로 제한을 하고 있고 있습니다. 
</p>
<p><b>○ 김강식 위원 </b> 알겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 정대운 </b> 김강식 위원님 수고하셨습니다. 신정현 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 신정현 위원 </b> 우선 제가 먼저 앞서서 드렸던 말씀 중에 취업규칙 말씀을 드렸었습니다. 좀 안타까웠던 얘기는 취업규칙에 대한 내용을 부탁드렸을 때 이미 인사복무 규정을 통해서 노동 관련된 일들을 이미 담아오셨다라고 말씀하셨잖아요. 그럼 그거에 대한 내용들도 충분히 같이 갖고 와서 저한테 근로자에 대한 노동시간, 이것들을 규정하는 내용들을 부탁드렸을 때는 그것들을 같이 저희한테 보여주셨으면 더 좋았을 것 같아요. 그래서 그런 부분들이, 사실은 인사복무 규정은 취업규칙의 하위규정입니다. 그런 측면에서 이런 부분들은 답변할 때 같이 갖고 왔으면 좋았다라는 생각이 들고요. 그래서 관련돼 가지고 부서 규정들이 있을 겁니다. 근로시간을 포함한 지금 현재 연구원에서 취하고 있는 대부분의 내용들이 담겨져 있는 자료를 저한테 제출해 주시기를 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 신정현 위원 </b> 진짜 제가 하고 싶었던 얘기를 이제야 진행을 하도록 하겠습니다. 저는 하나의 글을 읽어드리도록 할 텐데요, 들어봐 주시기 바랍니다. “근로기준법 개정에 따른 주 52시간 준수 불가에 따른 고충사항을 행정지원부장 등 관련 업무 담당자들에게 지속적으로 문제를 제기하였으며 2018년 7월 1일 이후 해당 시간 26주 중 17주를 이미 52시간을 초과하여 근무하였습니다.” 여기 그 밑의 내용은 또 아주 깁니다. 한 꼭지만 더 읽자면 “2019년 하반기에 예정된 전산고도화사업, 경기도 종합감사 등으로 이미 이 법을 준수하기란 불가능한 상황입니다.” 이렇게 이야기가 적혀 있습니다. 이거 읽어보신 적 있으신가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그거 저한테 올라온 서류가 아니지만 제가 구해서 읽어봤습니다. 사실 제가 읽어봐야 되는 서류는 아니었습니다. 
</p>
<p><b>○ 신정현 위원 </b> 아, 그러세요? 고충처리위원회에 올라오는 서류는 안 보십니까, 따로? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 고충처리위원회에서 저한테 권고한 사항에 대해서 제가 처리하고 고충처리위원회에서 전결처리한 사항에 있어서는 그대로 진행됩니다. 
</p>
<p><b>○ 신정현 위원 </b> 좋습니다. 자, 이제 제가 드리고 싶은 말씀은 이런 겁니다. 이미 52시간을 초과해서 근무하는 분들이 있습니다. 분명히 노동하고 있지만 노동하지 않는 사람으로 대우받는 분들이 있습니다. 52시간까지는 합법적으로 근무하는 노동자이지만 52시간이 지나고 나면 투명인간처럼 근무하시는 분들이 있어요. 원장님, 아시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 신정현 위원 </b> 아시느냐고 여쭤봤습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그럴 개연성에 대해서 인정하고 있습니다. 
</p>
<p><b>○ 신정현 위원 </b> 인정해 주셔서 감사합니다. 실제로 우리 경기연구원뿐만이 아닐 겁니다. 공공 산하기관 대부분이 현재 52시간제를 지키지 못하는 현황입니다. 그럼에도 불구하고 이러한 고충처리 통보서에 대한 내용이 사실은 이렇게 답변이 적혀 있습니다. “소속 부서장에게 책임소재를 명확히 하겠다. 그에 따른 업무지시를 명확히 하겠다. 52시간제를 필히 준수하겠다. 보상휴가 제도를 활용할 것을 권고하겠다.” 어떻게 들리십니까, 원장님? 이 문제를 해결하기 위해서 소속 팀장, 과장이 이 문제를 해결할 수 있습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 답변드려도 되겠습니까? 
</p>
<p><b>○ 신정현 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 이한주 </b> 52시간제는 정부의 개혁적인 정책이었고 경기도를 비롯해서 저도 그 부분에 대해서 적극 찬동을 하고 있습니다. 올 초부터 52시간제에 대한 계도를 저희들이 지속적으로 공문 등을 보내서 하고 있습니다만 경기연구원의 업무가 항상 일정하게 되지 않기 때문에 때로는 연구원들이 조금 더 일하는 시간도 있고 때로는 덜 일하는 시간도 있을 겁니다. 그러나 연구원에서는 52시간을 준수하도록 저희들이 끊임없이 얘기를 하고 있습니다만 위원님 말씀하신 대로 52시간 제도가 올해, 내년 이렇게 정착되어가는 기간이라는 거, 그래서 위원님께서 생각하듯이 저희들이 그 부분을 공공부문이 모범적으로 정착시켜야 될 필요가 있다는 것에 대해서 충분히 인식하고 하고 있습니다. 
</p>
<p><b>○ 신정현 위원 </b> 그래서 여쭤보고 싶은 게 이겁니다. 52시간제 단계별로 하겠다고 하지만 대안이 없어요. 여기에서도 부서장에게 책임소재 명확히 하겠다, 이게 마치 허공의 메아리 같은 느낌입니다. 사실은 이 문제를 진짜 해결하고자 하신다면 인력충원을 하는 게 먼저일 겁니다. 하지만 그것이 어렵다라는 거 아시죠? 그리고 저희도 너무 잘 알고 있습니다. 인력을 늘리는 데에는 한계가 있죠. 그렇다면 적어도 관리자급이라면 그 이상의 경영부원장님도 계시고 원장님도 계시지 않습니까? 불합리한 업무구조가 있다라면 개선할 수 있는 대안들을 연구하시고, 연구원들이 다 계시는데 그 연구 하시고 이 구조적 문제들을 개선하기 위한 대책을 마련하셨어야지 저는 마땅하다고 봅니다. 더군다나 연구원이잖아요. 이런 것에 대한 대안을 만들어 보자고 연구할 수 있는 풀들이 충분히 있지 않습니까? 정작 그런데 내부적인 모순에 대해서는 해결할 수 있는 대안을 제시하지 못하고 있습니다. 그것 마련하시라고 경영부원장님, 원장님, 무기계약직 12호봉이어도 받을 수 없는 5배 이상의 연봉, 6배 이상의 연봉 받으시는 겁니다. 그 역할 꼭 해 주셔야 됩니다, 원장님. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 신정현 위원 </b> 다음 주 월요일 날 종합감사가 있습니다. 그때 52시간제를 도저히 수행하지 못하는 현재의 문제를 진단하시고 이것을 어떻게 개선할 것인지에 대해서 대안을 마련해서 그날 보고해 주시기를 부탁드립니다. 가능할까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 52시간 준수를 위한…….
</p>
<p><b>○ 신정현 위원 </b> 대안을, 대책을 마련해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구원의 노력을 위원님께 말씀드리도록 하겠습니다. 최선을 다해서 준비하겠습니다.
</p>
<p><b>○ 신정현 위원 </b> 아마도 경영진 차원에서만 마련하기는 어려울 겁니다. 마침 오늘 저희 노조 측에서도 와있으니까 좀 대화를 하시죠. 그리고 서로 중요한 내용들 중에 오해된 것들은 좀 푸시고 마땅히 협조할 것들은 협조하시면서 이 문제에 대한 현황을 잘 분석해 주시면 감사하겠습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 고맙습니다. 
</p>
<p><b>○ 신정현 위원 </b> 다음으로는 이 부분입니다. 근무가 방대해질 것입니다. 내년도부터는 박사가 증원되죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 신정현 위원 </b> 그럼 현재 일대일 매칭, 석사 직군과 일대일 매칭 가능합니까, 안 됩니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 불가능합니다. 
</p>
<p><b>○ 신정현 위원 </b> 불가능합니다. 현실적으로 어렵죠. 그렇다고 한다면 저는 지난번 도정질의를 통해서 한번 언급했던 동일노동 동일임금에 대한 문제제기를 다시 한번 드리고자 합니다. 아마도 올해 협상을 통해서 이런 얘기가 오갔을 겁니다. 우리가 너희들의 임금만큼 할 수 있는 노동을 단순화시켜 줄게. 그 적은 연봉만큼 일하게 해 줄게라는 이야기가 오고 갔지만 실제로 그것을 당사자가 바라지도 않았고요, 그것이 실제로 이루어질 수도 없었습니다. 왜? 단순업무라고 표현했던 PT 만드는 작업들, 서칭하는 작업들 외에도 또 박사들이 필요한 작업들이 너무 많았거든요. 업무는 여전히 전문성을 필요로 한 방대한 업무였던 겁니다. 그런데 심지어 내년이 되면 박사들이 증원이 돼서 2명 혹은 3명까지 박사를 서포트해야 되는 석사직 업무들이 점점 늘어나기 시작합니다. 그래서 제가 보여드리고 싶은 게 바로 뒤에, PPT로 제가 띄워드릴 건데요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)  
</p>
<p style="padding-left:1.2em">  이토록 방대한 업무를 수행해야 하는 우리 경기연구원의 직원들에게 지금 주어지는 급여는 이 표와 같습니다. 그리고 이 표에서 보여지는 내용대로라면 우리는 현재 서울연구원 혹은 인천연구원에서 근무하는 직원들의 약 60~70%의 업무만을 주는 게 당연하죠. 무기계약직이 되었다고 해서 매년 항상 반복되는 계약이 사라졌을 뿐 이미 4년 전, 5년 전부터 석사 연구직이 지속적으로 요구해 왔던 동일노동에 대한 동일임금 이 부분은 정말 중요한 가치라고 생각하고 경기연구원의 자존심 문제라고 생각합니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 동의합니다. 
</p>
<p><b>○ 신정현 위원 </b> 그래서 이 부분에 대해서 우리 원장님 말씀 한번 듣고 싶습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 우선 동일노동 동일임금 혹은 동일가치노동에 대해서 말씀해 주신 것에 대해서 감사하게 생각합니다. 제 평소 지론이기도 하고 그렇게 돼야 된다고 믿고 있습니다. 그러나 동일노동이라고 했을 때 그 동일노동이라고 하는 건 성과평가가 전제돼야 된다는 사실에 대해서 기억해 주시기 바랍니다. 평가가 없는 동일노동은 말하자면 그냥 획일적인 노동에 불과하다 이렇게 생각합니다. 그래서 이 부분들이 평가의 중요성을 다시 한번 말씀해 주시는 거라고 생각하고 이 부분들에 대해서 깊이 새기겠습니다. 
</p>
<p><b>○ 신정현 위원 </b> 그러면 그 말씀대로라면 우리 경기연구원의 석사연구진들이 서울연구원과 인천연구원에 비해서 평가할 때 뒤지기 때문에 적은 연봉을 받는다는 말씀이십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 그 말이 아니고요. 그래서 앞으로 동일노동 동일임금을 잘 새겨서 평가가 제대로 될 수 있도록 노력하겠다는 말씀입니다.
</p>
<p><b>○ 신정현 위원 </b> 그 평가는 지금 이분들의 노동 강도와 노동량이 어느 정도인지를 평가하시라는 겁니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그것까지 포함해서…….
</p>
<p><b>○ 신정현 위원 </b> 그것이 핵심인 것이에요. 성과급을 주실 것 같으면 그걸 평가하시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 박사님들을 비롯해서 전체적으로 평가가 돼서 주권자 여러분들의 기대에 부응할 수 있도록 노력하겠고요. 또 서울연구원과 비교해서 다소 저희들이 급여가 좀 낮은 건 사실이지만 아까 말씀하신 대로 박사들도 다소 저희들이 조금 낮습니다. 그래서 저분들만 낮은 게 아니라 박사들도 낮고 전체적으로……. 
</p>
<p><b>○ 신정현 위원 </b> 잠시만요. 박사는 제가 여쭤본 게 없고요, 박사는, 사실은 이미 시니어들은 1억 이상을 받으시잖아요. 그러니까 지금 제가 그 부분까지 터치하고 싶지는 않고요. 지금 이 시간에 상대적으로 적은 연봉으로 과다한 업무를 하고 있는 석사직 연구원……. 위원장님, 딱 2분만 더 주시면 안 됩니까? 한 꼭지만 더 하겠습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 네. 
</p>
<p><b>○ 신정현 위원 </b> 그 부분에 대해서 더 신경 써주셔야 됩니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 지당하신 말씀입니다.
</p>
<p><b>○ 신정현 위원 </b> 뒤를 보시면 마지막 제 한 꼭지는 바로 이겁니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)  
</p>
<p style="padding-left:1.2em">  연구원ㆍ행정원 보수 표준안입니다. 원장님, 이 내용 잘 아시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 신정현 위원 </b> 그런데 분명히 행정원이 채용됐을 때는 행정보조원으로 뽑혔습니다. 맞죠? 관리직군을 도와주기 위한 보조직으로 뽑히셨습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 계약직으로 뽑힌 사람입니다.
</p>
<p><b>○ 신정현 위원 </b> 계약직도 뽑혔지만 그 역할이 행정보조직이었습니다. 원래 이름은 그겁니다. 행정보조직이라고 뽑혀서 심지어 연봉테이블에도 12호봉 이상으로 올라갈 수가 없습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다. 
</p>
<p><b>○ 신정현 위원 </b> 지금 현재 18년 차로 일하고 계시는 직원도 계시죠? 그분도 여전히 12호봉에 갇힌 상태로 3,000만 원 이하의 연봉을 받고 있지만 또 이제 막 갓 석사를 졸업한 24, 25 된 입사자보다도 급여나 직책이 훨씬 더 낮은 데 있을 수밖에 없죠. 저는 이러한 불편한 부분들이 사실은 우리가 의지를 갖고 있다면 얼마든지 풀어낼 수 있다라고 생각을 하는데요. 바로 이것에서 제안을 잘 해 주신 것 같아요. 제가 지금 보여드리는 바로 이게 처우개선에 대한 처음에 경영진의 제안사항이었죠. 그때는 현 12단계의 보수테이블을 32단계로 확대하겠다라는 개선안을 하나 내놓으셨던 것입니다. 맞죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 신정현 위원 </b> 이것이 불가능한 게 아니라는 것입니다. 경영진의 의지가 있다면 여기에서 30년을 일해도 12호봉의 호봉테이블에 갇힌 채 이곳에서 충성을 다해 일한 사람에게 충분한 보상, 거기에 따른 대우를 할 수 있다라는 것입니다. 가능하다라는 것이죠. 원장님, 이 부분에 대해서 검토하시고 긍정적으로 봐주실 의사가 있으신지요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저건 저희들이 이미 검토했던 사항이고요. 재정이 허락하고 그다음에 도하고 협의가 되는 대로 저희들이 하겠다는 의지를 표현했던 겁니다. 다만 저희들이 위원님들과 도에서 돈을 타 쓰는 사람으로서 신분이 올해에는 안정되었고 한 번에 안 되면 차근차근 해 나가자는 의지가 있고 여러 번 천명했습니다. 말씀하신 대로 원래 연구직은 개별 박사님 단위로 채용되신 분들입니다. 그분들의 사연은 서로 다 틀립니다, 지금 57명을 채용했지만. 제가 연구원에 처음 왔을 때 그분들이 저에게 어떻게 어떻게 해 주십사 하는 요청들을 많이 했는데 그 부분들이 서로 다 다릅니다, 자기 미래 진로를 어떻게 설계하느냐에 따라서. 그러나 제가 송구스러운 말씀은 그분들을 지금 정확하게 어떻게 해서 하는 게 연구원의 생산성 향상에 가장 도움이 되겠다 하는 것에 대해서는 아직 그 부분 합의가 도출이 안 됐습니다. 그래서 그 부분 열심히 해서 노력하겠습니다만 쉽지 않은 난제들이 사실은 많이 깔려있습니다. 
</p>
<p><b>○ 신정현 위원 </b> 정말 어려운 난제인 거 압니다. 하지만 그 난제를 풀어내시라고 우리 원장님 이 자리에 계신 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다. 
</p>
<p><b>○ 신정현 위원 </b> 뒤에 보이시는 저 업무분장표를 잘 보시더라도 여기에 누가 무기계약직, 행정보조직인지, 누가 관리직인지 구분되지 않죠? 구분되지 않습니다. 모두 각자가 전문적인 일을 하고 있고 자기 일에 책임지는 일을 하고 있습니다. 다시 말하면 하고 있는 업무수행이든 직책이든 전문성이든 관리직과 행정보조직을 구분할 수 없다라는 겁니다. 이 또한 동일노동 동일임금이라는 철학 아래 당장 이 사람을 관리직으로 바꿔 달라라는 요구를 하지 않습니다. 저도 그 얘기를 들었습니다. 다만 아까 말했던 호봉테이블 문제나 착실하게 일했을 때에는 나도 언젠가는 30년 일해도 주임이 아니라 그래도 대리 한번 달 수 있겠지. 20년 일하면 과장 달 수 있겠지라는 희망을 가진 직장이 될 수 있기를 간절히 바라는 이들의 마음입니다. 마지막으로 이 노동자들의 희망을 들으시고 어떤 입장을 표현하고 싶으신지를 저희 위원님들한테 얘기해 주시면 감사하겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들이, 특히 민주당 위원님들께서 노동자에 대한 애정을 가지신 것에 대해서 감사드립니다. 저도 똑같은 사람으로서 이 부분에 대해서 열심히 노력하고 싶은 마음은 똑같습니다. 그러나…….
</p>
<p><b>○ 위원장 정대운 </b> 원장님, 정의당도 있어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 정의당은 더욱더…….
</p>
<p><b>○ 위원장 정대운 </b> 그렇게 한 정당을 얘기하면 안 돼요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 해서 같은 뜻들을 가진 선량한 위원님들이시기 때문에 저도 위원님들 뜻에 적극 동참합니다. 다만 현실에 있어서 어려움, 그다음에 저희들은 단지 직업인이 아니라 또 한편으로는 절반쯤 공무원이기 때문에 그것들에 대해서 생각을 하지 않을 수 없습니다. 여러 가지 사항을 고려해서 저희들이 최선의 균형을 잡아나가려고 노력하고 있다는 점을 말씀드리고 그동안에 미숙한 게 있었더라도 참고 지켜봐 주시면 감사하겠습니다.
</p>
<p><b>○ 위원장 정대운 </b> 신정현 위원님 수고하셨습니다. 유광혁 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 유광혁 위원 </b> 동두천 출신 유광혁 위원입니다. 우선 먼저 이은환 노조위원장님, 원장님은 자리에 앉으시고요. 앞으로 나와 주십시오. 
</p>
<p><b>○ 위원장 정대운 </b> 노조위원장님은 직함, 성명을 얘기해 주고 해야지 속기사가 다 적을 수 있습니다. 
</p>
<p><b>○ 참고인 이은환 </b> 경기연구원 노조위원장 이은환입니다.
</p>
<p><b>○ 유광혁 위원 </b> 오늘 긴 시간 동안 자리에 계셔 주셔서 너무 감사하고 수고가 많으십니다. 사실은 단도직입적으로 한번 여쭙고 싶어요. 오늘 이 자리에서 많은 위원님들의 이야기를 들으셨고 해당 원장님도 계시고 한데 사실 노조에서 이번 감사 때 가장 화두가 됐던 성과연봉제에 대한 입장이 정확하게 어떤 것인지 한번 듣고 싶습니다. 
</p>
<p><b>○ 참고인 이은환 </b> 저희 박사급 노조 조합원들을 비롯해서 비조합원들도 아마 제가 지금 말씀드리는 것에 대해서 크게 이견이 없으리라고 생각이 드는데요. 첫 번째는 성과연봉 22%, 저희 연봉의 22%를 떼고 서로 경쟁을 통해서 가져간다는 게, 싸움을 통해서 가져간다는 게 22%는 너무 과도하다. 그리고 지금 그 격차가 0~200%에서 50~150%로 완화가 되었지만 사실 그게 기재부 지침이었나요? 
</p>
<p><b>○ 유광혁 위원 </b> 그럼 나름 노조에서 도출된 %나 그런 절충안은 어느 정도인가요? 
</p>
<p><b>○ 참고인 이은환 </b> 사실 그것에 대해서 조합원들과 함께 논의를 해 본 적은 없습니다. 왜냐 그러면 정말 이건 저희에게 꿈만 같은 얘기거든요. 그러니까 우스갯소리로 이런 얘기를 합니다. 노조가 싸워 가지고 끝판왕이라고, 그게. 진짜 상상도 못 할 일이었습니다. 지금 이렇게 논의가 되는 것도 사실 저희들한테는 너무나 기쁜 마음으로 말씀을 드리는데요. 그래서 사실 몇 %까지 줄였을 때가 좋을까라고 논의조차 사실은 못 해 봤습니다, 지금까지. 
</p>
<p><b>○ 유광혁 위원 </b> 사실상 그런 논의를 어느 정도 해야 차후에 우리 원장님과 노조랑 같이 어떤 합의를 갖고 협의를 갖고 교섭을 할 수 있는 방법도 있을 텐데 그런 부분에 대해서 돌아가셔서 한 번쯤 고민을 하시고요. 자리로 돌아가셔도 되겠습니다. 
</p>
<p><b>○ 참고인 이은환 </b> 감사합니다. 
</p>
<p><b>○ 유광혁 위원 </b> 제가 사실 오늘 하루 종일 성과연봉제라는 개념에 대해서 굉장히 혼란스러운 마음도 있고 나름 정리되는 마음, 여러 가지 감정이 교차하고 있는데요. 사실 성과연봉제라는 제도 때문에 그 이면에 있는 어떤 일들에 대해서 제가 자칫 놓치는 게 아닌가 그런 우려가 좀 있습니다. 왜 이런 얘기를 하느냐면 사실은 양쪽의 얘기를 들여다보면 상호 신뢰가 지금 많이 떨어진 상태다. 그런 점에 있어서 굉장히 앞서서 우리 존경하는 정승현 부위원장님과 정대운 위원장님, 기타 민경선 위원님까지도 어느 정도 그 절충안에 대한 이야기, 합의점에 대한 이야기를 제시하셨던 것 같아요. 그런데 사실 성과연봉제라는 제도 자체는 여러 가지 시각으로 바라볼 수는 있지만 저희 현재로서는 많이 폐지가 되는 부분도 있고 그 부분에 있어서는 동력을 이끌어내는 어떤 수단의 방법으로도 인정되는 부분적인 방법들이 있는데요. 사실 그 내용적으로 봤을 때는 상호신뢰 확보 부분이 먼저 앞서서 중요하다는 생각을 해요. 원장님께서는 사실 이 행감이 끝나고 종합감사가 있잖아요. 많은 미션들이 있고 그런 부분이 있을 텐데 오늘 댁에 돌아가셔서 한 번쯤 고민해야 될 게 사실 공감대에 대한 부분이 아쉽다는 생각을 합니다. 각자 어떠한 위치에 있든 어떠한 의도에 있든 사실상은 제도 안에 갇혀 있지 말고, 어찌 보면 제도에 대한 워딩에 우리가 너무 갇혀 있는 거거든요. 우리가 분명히 놓친 것이 공감되는 부분이거든요. 이 점에 대해서는 한 번쯤 고민해야 될 때가 온 것 같고요. 사실 근본적인 문제에 대한 해결책이 중요하다고 봐요. 성과연봉제가 절충이 되든 폐지가 되든 적용이 되든 우리가 양질의, 경기도민을 위한 양질의 연구결과를 얻어내야 되는 방법을 논의해야 되는데 그 방법에 대한 이슈는 놓친 채 너무 표면적인 걸로 가는 게 지금 현재 상황이 아닌가 싶거든요. 이 성과연봉제를 제외하고 혹시 양질의 어떤 연구결과물과 제고 환경을 가질 수 있는 그러한 개선안에 대해서 혹시 고민한 적은 있으십니까, 원장님? 어려운 얘기입니다, 이거. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 매일 고민하는 주제 중의 하나고요. 잠깐 쉬는 중에 위원님께서 경기연구원의 연구성과에 대한 임팩트 팩터, 얼마나 영향을 미치는지에 대한 질문이 있으셨고 질문 중에도 중간에 또 있으셨습니다. 남의 연구원 얘기를 해서는 안 되겠습니다마는 정부연구기관 중에 아주 조그만 연구기관이 있습니다. 박사가 40명밖에 안 되는 연구기관인데 그 연구기관에서 나온 연구성과에 대해서는 대학에 있는 연구자나 아니면 정부기관에서나 대개 그냥 그대로 사실이라고 생각하고 쓰는 경향들이 좀 있습니다. 저도 그런 연구기관이 되었으면 좋겠다는 생각을 합니다. 그러기 위해서 어떻게 하면 잘 될 수 있을까 하는 노력을 하고 있는 것도 사실이고요. 
</p>
<p style="padding-left:1.2em">  위원님 말씀하신 대로 경기연구원은 내부조직원들의 공감대 형성이 대단히 중요한 사실인 것만은 맞습니다. 그러나 또한 저희들이 가야 할 목표가 있는 것도 사실입니다. 송구스럽게 제가 그 목표가 이렇게 잘 공감대를 이루어서 잘 되었다라고 위원님 여러분께 말씀드려야 되는데 상황이 그렇게 되지 못한 것에 대해서 송구스럽습니다. 그리고 창피하게 생각합니다. 열심히 노력하겠습니다. 
</p>
<p><b>○ 유광혁 위원 </b> 네, 말씀 여기까지 듣고요. 말씀 내용을 좀 정리하자면 비전이 있되 비전이 공유가 돼 있지 않다는 거잖아요, 지금. 그렇죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유광혁 위원 </b> 그 부분이 굉장히 좀 안타까운 현실인데 비전을 공유하기 위해서는 어떤 방법이 있을지 다 같이 한번 노력할 때인 것 같습니다. 그렇죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유광혁 위원 </b> 여담으로 제가 관심 있는 토픽이 있어 가지고 경기연구원 자료를 자주 살펴보고 다운 받아 보고 그러는데 창피한 얘기지만 가끔 토픽에 대한 여러 가지 논문을 읽어봤을 때 참 비슷비슷한 내용의 논문들이 참 많이 있었어요. 제가 당선되고 처음 경기연구원 결과물을 봤을 때 이런 점이 좀 안타까웠고 행감 때도 한 번쯤 다루었던 내용이죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유광혁 위원 </b> 사실 이러한 점도 개선이 돼야 되는데 막상 이 문제에 대한 해결책이나 원인을 분석했을 때 단순히 연구원이나 원장님에 대한 어떤 비난이 아니라 어떤 근무환경이나 그럴 수밖에 없었던 점, 여러 가지의 고민되는 것들이 많더라고요. 지금 우리가 문제를 해결하기 위해서는 단순한 하나의 키만 필요할 때는 아닌 것 같고요. 다각적인 시각에 대한 접근 그리고 그거에 대한 문제를 해결할 수 있는 협업에 대한 얘기가 분명히 필요한 것 같습니다. 노조위원장님이나 원장님 그리고 기타 직원 여러분은 이 점 꼭 명심하시고 제가 다음 우리 종합감사 때 똑같이 소회를 한번 여쭤볼 테니까 그 사이에 한번, 이번 주에 멋지게 고민 한번 해 보시죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 고맙습니다. 
</p>
<p><b>○ 유광혁 위원 </b> 알겠습니다. 이상입니다. 
</p>
<p><b>○ 위원장 정대운 </b> 유광혁 위원님 수고하셨습니다. 김우석 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김우석 위원 </b> 바로 질문 좀 드릴게요. 학술연구 관련해 가지고 저명한 학술지에 게재된 논문을 보자 해서 리스트를 받아본 적이 있어요. 그럼 일단 학술지에 게재되면 수준이 좀 높은 정도로 이해하면 되는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그리고 또 한 가지는 그거와 관련해서 피인용률이라는 단어가 있죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김우석 위원 </b> 피인용률은 어떤 뜻을 의미하는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 여러 기관에서 합니다. 학술지는 저희들이 보통 한국에서 학술지 인정기준에 따라서 정의된, 학술지능재단에 등록된 학술지를 KCI 잡지라고 하고요. 또 외국에서 SCI 잡지, 외국 겁니다. 
</p>
<p><b>○ 김우석 위원 </b> 일단 그런 건 아실 것 같고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 다 있습니다. 그래서 그런 데 등록된 게 권위 있는 인정된 학술지라고 얘기하고 피인용지수는 영문일 경우에는 임팩트 팩터라고 하는 것을 측정해서 발표를 합니다. 어떤 논문의 임팩트 팩터가 몇 점 이렇게 돼서 시간이 지나면서 그게 표시됩니다, 다른 사람들이 인용했을 경우에. 우리나라에서도 그것들을 일부 하기는 합니다. KCI 논문은 점검되고 있고 그다음에 또 구글에서도 일부 제공하고 있습니다. 
</p>
<p><b>○ 김우석 위원 </b> 네, 제가 이해를 했고요. 다른 위원님들도 피인용률에 대한 이해를 하셨을 것 같은데 그러면 숫자 1이라는 건 어떤 의미일까요, 피인용률에서? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 임팩트 팩터 1이요? 
</p>
<p><b>○ 김우석 위원 </b> 네. 쉽게 얘기하면 많이 활용이 된다는 뜻인가요, 아니라는 뜻인가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 1은 그다지 많이, 어느 정도 그냥 보통……. 
</p>
<p><b>○ 김우석 위원 </b> 거의 경기연구원에서 발표했던, 게재했던 논문의 피인용률이 1을 벗어나지 못한다는 사실을 확인했고요. 여러 가지 이유가 있을 것 같긴 해요. 그 부분을 여쭤보는 이유는 많이 노력함에도 불구하고 대외적인 이러한, 서로 아는 그런 상황이 있을 거라고 생각을 합니다. 일단 현상을 좀 짚어봤고요. 
</p>
<p style="padding-left:1.2em">  이 부분과 관련해서 질 평가 부분을 한번 여쭤볼게요. 질 평가 부분을 하기 위해서 세 단계로 점검을 하신다고 말씀하셨는데 1단계 성과보고회는 제가 봤을 때는 씨앗을 감별하는 단계라고 생각을 해요. 건강한 씨앗을 골라내고 또 발아를 시켜서 키워내는 과정이 마지막 단계, 1ㆍ2ㆍ3단계로 이해를 하고 있는데 예를 들면 병아리 감별사가 인삼씨앗을 구분하면 안 되겠죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 
</p>
<p><b>○ 김우석 위원 </b> 동의하십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김우석 위원 </b> 그러면 전공자가, 그러니까 전공에 대한 다른 전공자, 비슷한 전공이어야 이해도가 높을 것 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그래서 아까 존경하는 김강식 위원님께서 1단계에 있던 성과보고 관련해 가지고 외부기관의 전문 동종ㆍ동일 전공자들의 어떤 객관적 평가가 필요하지 않느냐라는 얘기를 하셨거든요. 그 부분에 대해서 저도 상당히 동의가 되는 부분이라, 우리 원장님께서도 동의가 되시는지? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그래서 이러한 것들이 질 평가를 위한 여러 가지 모델이 있을 건데 이런 것들도 염두에 두셔서 모델을 한번 다시 점검해 보시는 게 어떨까 제안을 드리고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김우석 위원 </b> 두 번째, 석사연구원들 처우개선을 아까도 신정현 위원님께서 데이터를 구해 주셨는데 왜 그럴까 곰곰이 생각을 해 봤어요. 서울연구원도 있고 인천연구원도 있는데 그러면 총 파이가 좀 다르지 않을까라는 생각을 해 봤거든요. 연구원의 예산이 좀 다를 것 같다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 좀 다릅니다. 
</p>
<p><b>○ 김우석 위원 </b> 예산과 또 운용하는 인력규모가 좀 다를 것 같다는 생각이 들어요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그런데 맨날 평가되는 게 서울연구원은 이런데 경기연구원은 왜 이러냐라는 질타를 많이 받고 계신다는 말이에요. 그러면 거꾸로 경기연구원에서는 “같은 수준의 대우를 할 수 있도록 의회에서 좀 협조를 해야 되는 거 아니냐?”라는 요구를 하셔야 하는 게 아닌가 싶은 생각이 들거든요. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 왜 안 그렇겠습니까? 저희들이 서울은 어떤 사이에 경기도하고 인구가 똑같았다가 이제는 서울은 950만으로 줄었고 경기도는 1,360만으로 늘어서 사실은 연구수요는 경기도가 더 많습니다, 지역도 넓고. 그래서 경기도가 서울연구원 이상으로 되어야 된다는 데는 분명하고 인력이나 예산규모가 전체적으로 3분의 2 정도 규모입니다, 저희들이. 좋게 보아서 3분의 2 정도……. 
</p>
<p><b>○ 김우석 위원 </b> 그래서 우리 신정현 위원님께서 고민하셨던 12단계의 캡 부분을 해결하기 위해서는 그러면 경기연구원도 서울연구원 정도의 예산을 운용하면 가능하지 않을까 싶은 생각이 들거든요. 가능하십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀드리기가……. 사실 제 생각은 경기연구원이 수월성을 보여주고 위원님들께 손을 좀 벌릴 생각이었습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그런 각오로 지금 열심히 노력을 하고 계신 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 먼저 성적을 올리고 나서 인정을 받아야지 돈부터 달라고 하고 성적 올리겠다 하는 건 좀 겸연쩍은 생각이었습니다. 
</p>
<p><b>○ 김우석 위원 </b> 일단 질 수준과 석사연구원들 노동의 가치를 동일시했었을 때 이 보수체계가 정상화되려면 서울연구원처럼 예산을 늘려주는 게 맞다는 생각이 들거든요. 그래서 그 부분을 저희가 해결해 나가는 과정에 있어서 한 가지 제안드리고 싶은 게 뭐냐 하면 GRI 발전을 위한 위원회를, 저희 위원들도 좀 참여하는 단계에서 위원회를 한번 구성해 보는 건 어떨까 싶은 생각이 들거든요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 관련규정을 검토해서 특별한 문제가 안 생긴다면 시행하도록 하겠습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그리고 지금 우리 경영부원장님께 한번 여쭤볼게요. 오늘 이한주 원장님께서 여러 가지 사항에 대해서 검토를 하겠다고 말씀하시거든요. 몇 가지 정도 검토를 하시겠다고 하셨나요? 일단 오늘 오고 간 얘기가 그냥 말장난은 아닌 거니까 검토를 하실 것 아닙니까? 
</p>
<p><b>○ 경영부원장 김재용 </b> 검토하시겠다는 말씀에는 하겠다는 그런 의지가 충분히 들어있다고 생각합니다. 
</p>
<p><b>○ 김우석 위원 </b> 그렇죠? 검토를 하고 나서는 검토된 내용을 공유하는 게 상당히 중요하잖아요. 
</p>
<p><b>○ 경영부원장 김재용 </b> 네, 저희 직원들도 지금 다 기록하고 있고……. 
</p>
<p><b>○ 김우석 위원 </b> 검토내용에 대해서 저희 기재위 위원님들께 보고를 해 주시길 부탁드리고 기간은 언제까지 가능할까요, 그게? 올해 안에는 가능할까요? 
</p>
<p><b>○ 경영부원장 김재용 </b> 검토한 결과에 대한 내용을 말씀하십니까? 
</p>
<p><b>○ 김우석 위원 </b> 왜냐하면 검토된 내용을 갖고 다시 정리한 다음에 논의를 해야 뭐가 좀 개선점이 나올 것 아니에요? 
</p>
<p><b>○ 경영부원장 김재용 </b> 사안에 따라서 다를 수 있는데 원장님하고 협의해서……. 
</p>
<p><b>○ 김우석 위원 </b> 뭐 단기적으로 해결할 수 있는 부분도 있을 거고 조금 논의의 시간을 가질 필요도 있을 거고 하지만 검토된 내용들은 서로 공유를 했으면 좋겠다는 거예요. 그러면 그 의견 공유는 언제쯤 가능할 수 있을지 여쭤보는 거고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 제가 말씀드리겠습니다. 위원님들 주신 말씀 중에는 구조적인 문제에 해당하는 것도 있고 또 단기적인 문제에 해당하는 것도 있을 수 있겠습니다. 어떤 문제는 올 연말까지 해결하기 어려운 문제들도 적지 않게 있습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그러니까 해결해내라고 강요를 하는 게 아니라, 답을 내놓으라는 게 아니라 검토된 내용에 대해서 정리가 돼서 공유가 돼야 다시 논의를 하고 개선을 할 거잖아요. 그 정도……. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 그냥 검토 자체가 관련법규나 아니면 도ㆍ정부하고 협의를 하지 않는 검토가 좀 무의미해서……. 
</p>
<p><b>○ 김우석 위원 </b> 제가 왜 날짜를 요청드리냐면 지난 1년 동안 의원 생활하면서 “검토하겠습니다.”라고 해서 답변이 온 경우는 한 번도 없어요. 왜 안 하냐고, 언제까지 갖고 오라고 해야 갖고 오시더라고요. 그래서 미리 이 기간을 한번 정해 보고 논의를 해 보자라고 말씀을 드리는 거고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 연말까지 가능한 것들은 연말까지 가능하고……. 
</p>
<p><b>○ 김우석 위원 </b> 안 된 것들은 안 된 대로 보고를 해 주시길 요청드리고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김우석 위원 </b> 마지막으로 아까 전에 말씀드렸던 질 평가 부분에 대한 것, 그러니까 좋은 연구성과를 내보자라고 하는 논의는 모두가 동의를 하실 거라고 저는 믿고 있어요. 그런데 이런 좋은 제도를 한번 실현해 보자고 하면 기본적으로 법에서는 예고를 하죠. 이런 것들을 시행하겠다. 언제부터 그 효과가 발효가 된다라고 얘기를 하거든요. 1단계부터 3단계까지의 평가제도까지 검토를 또 해 보신다고 하셨으니까 그게 안착이 된다면 언제부터 시행이 되면 좋을까요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그걸 논의하는 과정이 어느 날 갑자기 논의해서 툭 꺼낸 게 아니라 논의하는 과정도 적지 않게 길었습니다. 그래서 구성원들이 여러 번에 걸쳐서 또 각 그룹에 따라서 논의가 좀 있었기 때문에 저희들은 올해부터라도 했으면 좋겠다 이렇게 생각하고 있습니다. 시급한 문제라고 판단합니다. 
</p>
<p><b>○ 김우석 위원 </b> 그러면 올해부터면 이게 픽스가 되고 검토가 돼서 합의가 된 이후를 말씀하시는 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들이 그걸 공표한 게 7월 1일입니다. 그래서 7월 이전까지는 전 규정을 따라가고 7월 1일부터는 새 규정을 따라가는 게 맞다고 생각하는데요. 전 규정을 새 규정 가지고 저희들이 시뮬레이션 해 봤습니다. 전체 박사님들 중에서 한 분만 순위가 바뀌었습니다. 그래서 지금 새로운 규정이 순위를 심각하게 바꾸는 규정이 아니라 다만 평가를 할 때 외부평가를 도입하자는 데 의미가 있었다 이렇게 말씀드릴 수 있습니다. 
</p>
<p><b>○ 김우석 위원 </b> 그 부분은 하여튼 1단계부터 같이 하는 걸로 얘기를 하셨고요. 이게 시뮬레이션은 현상을 보는 거잖아요? 그런데 뭔가 새로운 것들을 도입하기 위해서는 준비단계라는 게 필요하고 그 전에 필요성에 대해서 합의를 봤기 때문에 시작을 하는 거잖아요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김우석 위원 </b> 그런데 그것을 시뮬레이션 했더니 큰 차이가 없다고 해서 소급적용을 하면 안 되는 거잖아요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 소급적용 아닙니다. 올 전반기는 원래 규정으로 하고 그다음에 공포되고 난 이후에 신규적용……. 
</p>
<p><b>○ 김우석 위원 </b> 올해 1월부터 7월까지는 그 전 규정으로 하고 바뀐 이후는 바뀐 성과로 하는데 말씀하신 것처럼 1단계 성과보고에는 외부전문가들이 함께 참여하는 구조로 하시겠다는 말씀이신 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 김우석 위원 </b> 네. 충분히 설명 들었고요. 지금까지 많은 시간 고생하셨고 또 좋은 논의의 자리가 됐던 것 같아요. 사실 이렇게 오랜 시간 논의되는 건 경기연구원이 그만큼 중요하고 가치가 있고 또 기재위원님들이 기대하는 바도 크고 사랑하는 마음이 크기 때문이라고 생각하고요. 함께 동참해 주시고 좋은 방향으로 갈 수 있도록 함께 논의했으면 좋겠습니다. 이상입니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 고맙습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 김우석 위원님 수고하셨습니다. 유영호 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 유영호 위원 </b> 원장님을 비롯한 우리 연구원분들 늦게까지, 많이 피곤하시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 괜찮습니다. 
</p>
<p><b>○ 유영호 위원 </b> 저희가 먼젓번 추경 때 연구원의 예산 삭감했었죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 초기에? 
</p>
<p><b>○ 유영호 위원 </b> 네. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 많이 하셨습니다. 
</p>
<p><b>○ 유영호 위원 </b> 그때 좀 버티시지 그러셨어요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들이 하시는데 버틸 방법이 저희들한테 없습니다. 
</p>
<p><b>○ 유영호 위원 </b> 지금 제가 언급하고 싶은 얘기를 앞에서 발언한 위원님들께서 말씀을 다 하셨어요. 제가 여태까지 경기연구원과 관련돼서 행감이라든가 보고, 그때 회의, 기재위에서 회의한 자료를 쭉 찾아봤는데 지금처럼 이렇게 진지하게 연구원의 기본적인 문제에 대해서 논의하고 안타까워했던 적이 한 번도 없더라고요. 그래서 이번 기회가, 그걸 남한테 맡길 수도 없고, 아까 제안하셨는데 연구원에서 이 문제를 어떻게 해결해 나갈지 자체 용역을 한번, 셀프 용역이라고 하면 결과를 저희가 어떻게 받아들일지 모르겠지만 저는 그게 가장 좋은 자기고백이라고 생각하거든요. 그래서 그런 것도 한번 해서, 우리 민경선 정책위원장님이 한번 주도가 돼서 하시는 게 어떤가 저는 그 생각도 해 봤습니다. 해 봤고요. 
</p>
<p style="padding-left:1.2em">  그리고 아까 정승현 부위원장님이 지적하신 임원 추천위원회 관련된 것 있죠? 이것 굉장히 필요하다고 생각합니다. 그래서 그것도 해 보시고 저희가 균형발전본부가 새로 생겨서 지난번에 저희가 북부연구센터에 가서 일하실 인력들이 불편하지 않을까 걱정을 많이 했잖아요. 그건 어떻게 좀 해소가 됐습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 기숙사하고 장소 말씀하시는 겁니다. 
</p>
<p><b>○ 유영호 위원 </b> 네. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 장소가 매우 비좁았기 때문에 그 바로 아래층, 저희들이 쓰고 있는 바로 아래층이 마침 장소가 비어서 저희들이 그 장소를 임차해서 인테리어를 했고 거기서 근무를 하고 있습니다. 큰돈 들이지 않고 저희들이 근무장소는 개선을 좀 하였습니다. 반면에 또 위원님들이 도와주셔서 기숙사 정주여건을 개선하라라고 하는 도움을 주셨습니다. 매우 감사하게 생각하고 있고요. 그런데 다만 저희들이 한 1억 8,000 정도의 도움을 받았고 그다음에 여성기숙사 임차보증금 반환액 그다음에 명년도에 남성기숙사 보증금 반환액 합쳐 가지고 금액을 찬찬히 해 나가고 있는 과정인데 다만 우리 근무자들이 원하는 환경은 오피스텔 정도의 수준이었는데 그 근처 오피스텔도 많지 않았고 또 금액도 오피스텔을 하기에는 다소 무리가 있는 금액이어서 연립주택을 임차해서 하고 있습니다. 그래서 어떤 분들은 연립주택에서 하느니 그냥 아파트에 공동으로 있겠다 이런 분들도 또 심경의 변화를 일으킨 분들도 있어서 이 부분은 계속해서 저희들이 최적상황을 찾도록 업데이트를 하겠습니다. 
</p>
<p><b>○ 유영호 위원 </b> 잘 알겠습니다. 그건 각자의 생각이 틀릴 겁니다. 그런데 사실은 가장 편안하게 안정감을 가지고 연구에만 몰두하는 그런 분위기를 만들어 가면 좋으니까요. 그건 계속해서 신경 써 주시고요. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 유영호 위원 </b> 경기관광공사에서 해마다 하던 DMZ포럼을 성격에 맞지 않다 그래 가지고 우리 연구원으로 하게끔 저희가 했잖아요. 그래서 올해 처음 하셨는데 아까 그거에 대해 굉장히 만족감도 표하셨고 또 저희가 보기에도 위탁시켜서 그 위탁업체 관리라든가 그쪽에 대해서도 조금 바라보는 시각이 틀린 걸 갖고 있어요. 그래서 그건 종합감사 때 아마 같이 다뤄서 같이 논의하고 개선점을 찾아가는 게 좋을 것 같고요. 
</p>
<p style="padding-left:1.2em">  그다음에 한 가지가, 이것도 종합감사 때 제가 하도록 하겠습니다. 이상입니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 알겠습니다. 명심하겠습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 유영호 위원님 수고하셨습니다. 민경선 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 민경선 위원 </b> 고양의 민경선입니다. 위원님들이 마무리하는 발언인 것 같은데, 저는 구체적인 질문을 하려고 했는데 상당히 당황스럽습니다. 원장님께서 앉아서 하시죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 말씀드리겠습니다. 얼굴 뵈면서 하니까 저도 좋습니다. 
</p>
<p><b>○ 민경선 위원 </b> 앉아도 보이는데요. 원장님의 말씀 중에도 나왔지만 저희가 지난 행감과 경기연구원에 대한 질의 내용이 다른 것 같습니다. 연구 성과에 대한 질의가 컸는데 오늘 같은 경우는 구성원들의 처우개선에 대한 게 집중된 것 같습니다. 그래서 그 부분을 잘 전향적으로 검토했으면 좋겠다는 생각이고요. 저는 우리 원장님께서 말씀하셨듯이 주권자에 대한 노력, 연구실적에 대한, 생산성에 대한 부분에 대해서 언급한 바 있는데 연구 질 평가에 대해서 우리 김우석 위원님하고 김강식 위원님이, 존경하는 위원님들이 말씀하셨고 객관적으로 평가했을 때 지금 1년 이상이 지났는데 원장님 보시기에 1년 전과 지금의 질적 평가는 어떻다고 보시는지, 연구실적에 대해서 어떻게 보고 계십니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 우리 박사님들이 객관적으로 판단할 때는 괜찮으신 분들입니다. 그리고 저도 신뢰하고요. 그러나 아직도 개선의 여지는 있다고 판단합니다. 그리고 조금 더 개선했으면 좋겠고요. 방법론이 됐든 내용이 됐든 정책적인 함의가 됐든. 그래서 제가 그러기 위해서라면 박사님들을 잡무에서 해방시킬 필요가 있겠다. 예컨대 교정한다든가 PPT 준비를 한다든가 뿐만 아니라 방법론을 확실하게 사용하기 위해서라면 또 오래되신 분들도 있습니다, 사실은. 통계처리 새로운 기술을 제공한다든가 이런 것들을 하고 싶습니다. 그러기 위해서 연구원의 공통의 오버헤드 기능을 가져야 된다 이런 생각을 했습니다. 그리고 또 석사 연구원들이 들어오는 입직 경로가 숫자만큼입니다, 박사님들이 뽑으셨기 때문에. 그래서 공통의 역량 개발도 좀 필요하다 이렇게 생각했습니다. 그리고 또 아까 신정현 위원님께서도 말씀하셨듯이 이제는 일대일 구조가 불가능합니다, 원천적으로. 해서 다른 연구원들처럼 많은 연구원들이 이미 일대일 구조가 다 진작부터 깨졌습니다. 저희가 할 수 있는 한 오버헤드 기능을 모아서 박사님들이 저생산성 업무, 편집, 그다음에 교정 이런 일에서 벗어나게 해서 조금 더 우리 박사님들이 본래 가지고 계셨던 창의적인 업무를 할 수 있도록 하고 싶은 게 제 생각이고 그 과정에서 정말 중요한 것은 또 그러면 과거는 어땠고 앞으로는 어땠고 개개인들은 어떤지 이런 데 대한 평가들이 필연적입니다. 위원님들이 말씀하신 동일노동 동일임금 사무치게 주장했던 사람으로서 왜 모르겠습니까. 그러나 그것 이전에 연구원은 연구원 나름대로 가야 할 길이 좀 있다라는 생각들에서 여러 위원님들의 생각을 100% 받아들이면서도 해야 할 그 일을 굉장히 무겁게 생각하고 있습니다. 
</p>
<p><b>○ 민경선 위원 </b> 네, 알겠습니다. 저도 질적 평가에 대해서 고민을 하고 있지만, 실제 작년과 올해가 나아졌다 이런 부분을, 왜냐하면 작년에는 많이 안 읽었어요. 올해는 더불어민주당 경기도의회 정책위원장을 맡으면서 여러 정책을 다뤄야 되다 보니까 많이 읽게 됩니다. 그래서 아마 내년도 정도 되면 올해와 내년에 대한 비교는 주관적이지만 제 나름대로의 질적 평가를 할 수 있을 것 같습니다. 그런데 양적 평가 부분에 대해서 지난번에 성과중심주의적으로 하다 보니까 양에 대한 평가에 대해서 좀 부정적인 시각으로 지난 행감 때도 지적을 한 바 있지만 올해 평가를 보면 구체적으로 들어가면 사업계획과 실제 실행과제 수행 수가 현격히 떨어집니다. 그래서 왜 그런지 그 원인을 알고 싶고. 예를 들면 너무 계획을 많이 잡은 건지, 올해 목표를. 그런데 지난해 실적과 지지난해 실적과 비교했을 때도 현격히 떨어집니다. 정책과제 수나 기타 기본과제 수, 위탁연구, 수탁연구, 정책현안분석 같은 경우도 현격히 떨어지거든요. 그 원인이 무엇인지, 아니면 여러 가지 추구하는 바가 있어서 그러신지를 좀…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 답변드리겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 추진했을 때의 계획과 달라진 점이 무엇인지 여쭙고 싶습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 전년도하고 비교했을 때 2011년도에는 저희들이 기본과제, 정책과제, 위탁과제, 수탁과제가 본격적인 과제들이고 현안대응은 짧게 대응하는 거라서 현안분석은 덜 중요하게 생각하고 있습니다. 그런 점에서 보면 2017년에는 연구과제, 아까 말씀드린 네 가지 범주의 연구과제가 158건이었고 2018년에는 182건이었는데 지금은 9월 현재까지 완료되었거나 진행 중인 게 176건이라서 현격하게 떨어진다라고 하는 말씀에는 저희들이 조금 그렇지 않다고 말씀드리고 싶고요. 다만 저희들이 목표로 했던 것에 대해서 진도가 덜 나간 건 사실입니다. 연말까지 대부분 다 달성할 수 있도록 노력하겠습니다만 위원님께 그렇게 보이게 된 이면에는 저희들이 연구과제를 설정하면서 인력 충원을 전제로 해서 설정을 했었는데 인력 충원을 다 못 했습니다. 그래서 나누어 한다고 했는데도 좀 부족했고 특히 인건비들이 많이 남아있기 때문에 그 인건비가 좀 쌓여서 미집행이 많이 있는 것에 대해서는 매우 송구스럽게 생각합니다. 
</p>
<p><b>○ 민경선 위원 </b> 그러면 근본적인 문제에 들어가면 인력 충원에 대한 풀은 있지만 실질적으로 보고에도 보면 실제 연구직에 열네 분이 결원입니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 민경선 위원 </b> 그 부분은 왜 그렇죠? 왜 충원이 안 되는 근본적인 이유가 있을 거 아니에요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 근본적인 이유는 없고요. 저희 연구원이 정원이 61명이었는데 그동안 관행적으로 51명밖에 안 뽑아왔었습니다. 그래서 그 원인에 대해서는 여러 가지가 있겠습니다만 인건비 부족액을 덜 뽑음으로써 채우려고 했던 그런 예산상의 다소간 구부러짐이 좀 있었던 건 지난번 누누이 말씀드렸었습니다. 그래서 이제는 그런 게 있으면 안 되겠다 싶어서 필요한 건 쓰고 없으면 달래고 이게 맞는 태도겠다 싶어서 그 부분을 다 충원하려고 노력을 했고요.
</p>
<p style="padding-left:1.2em">  또 김우석 위원님 말씀대로 저희가 연구 수요가 급격히 늘어나는데 이 인원만 가지고 안 돼서 저희들이 도에 얘기를 했고 위원님들께 예산을 요청했더니 위원님들께서 7명을 주셨습니다. 그래서 현재 68명 연구 정원을 가지고 있습니다. 그런데 저희들이 다 못 채운 이유 중의 하나는 우선 의사결정이 조금 늦어졌습니다, 연구원을 뽑을 때마다. 연구라고 하는 건 박사들이 나오는 시기가 있습니다. 그래서 그 시기에 맞춰서 바로바로 돼야 되는데 아무래도 저희들은 감독기관도 있고 그러다 보니까 그게 조금 늦어졌고 경쟁에서 저희가 유리한 점도 있고 불리한 점도 있습니다, 박사를 충원할 때. 국책연구기관이라 하더라도 시골에 있기 때문에 거기에 가고 싶어 하지 않는 사람도 있지만 또 어떤 기관들보다는 저희들이 급여가 좀 낮거나 아직도 사람들이 막연히 지방이라고 하는 의식을 갖는 경우들도 있고 해서 다양한 복합적인 이유 때문에 비록 경쟁률은 매우 높았습니다만 저희들이 충분히 뽑을 수 없었습니다. 그래서 여러 가지 요인이 복합되어 있어서 그렇게 되었다라고 말씀드립니다.
</p>
<p><b>○ 민경선 위원 </b> 여러 가지 복합적인 부분에 대한 분석이 필요할 것 같습니다, 지금 구성원에 대한 분석도 있지만. 왜냐하면 질적인, 그러니까 아까 말씀하신 신뢰받는 경기연구원, 연구원 운영에서 의문시 안 하고 할 수 있는 연구원을 만들겠다고 하셨으니까 오히려 지금 있는 연구원들을 더 보강하는 노력도 필요하지만 새로 뽑는 인력에 대해서도 조건 부분이 잘 돼야 우수 인력이 올 수 있지 않겠습니까? 그런 것에 대한 전반적인 고민이 필요할 것 같습니다. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 좋은 충고 감사드립니다. 
</p>
<p><b>○ 민경선 위원 </b> 수고하셨습니다. 감사합니다. 
</p>
<p><b>○ 위원장 정대운 </b> 민경선 위원님 수고하셨습니다. 정승현 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 정승현 위원 </b> 원장님, 잠깐 앉으시고요. 노조위원장님 잠깐 나오시겠어요. 늦게까지 고생 많으신데요. 좀 정리하는 측면에서 제안이라면 제안이고 제 의견, 아마 이건 제 의견뿐만 아니라 우리 상임위원회 위원들 전체 마음이지 않을까 싶은 생각을 해 보게 되는데요. 앞서 정회 직전에 위원장께서 경기연구원에 대한 예산에 대해서 언급을 하셨어요. 언급한 이유는 어쨌든 경기연구원 내 조직문화에 대한 부분들에 있어서 안정적으로 갔었을 때와 또 그렇지 않았었을 때 의회에서 바라보는 시각 차이는 분명히 다르다. 그런 측면에서 위원장님께서 경각심을 갖게 하기 위해서 그런 말씀을 하셨다라고 저는 보고 있습니다.
</p>
<p style="padding-left:1.2em">  실질적으로 오늘 상임위 내내 위원장님 들으셔서 아시겠습니다만 소위 말하는 노측과 사측 입장에 대해서 위원님들께서 많은 말씀을 하셨는데 주로 어쨌든 우리 노조 측 입장을 대변하는 역할들을 많이 하셨어요, 그런 발언들을. 지금 그렇게 느끼셨죠?
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그래서 그 부분에 있어서 지금 위원장님께서도 이런 자리 또 이런 시간 갖는 자체가 상당히 기쁘게 생각하신다라고 그렇게 말씀하셨고요. 그래서 말씀인데 어쨌든 그럼에도 불구하고 아까 원장님께서는 또 이렇게 답변하셨어요. 이 부분에 대해서 위원님들께서 말씀하신 부분에 대해서 충분히 검토하고 또 여러 가지 긍정적인 답변들을 충분히 하셨습니다. 그런 와중에도 어쨌든 분명한 것은 단기적으로 해결할 수 있는 문제가 있고 또 중장기적으로 검토해야 될 부분들이 분명히 있다라고 또 말씀하셨는데 그 부분에 대해서도 위원장님께서는 인정을 하시는 거죠? 
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그러나 어쨌든 아까 제가 질문 시간에 서로 소통, 대화를 좀 제안했는데 사실 이게 또 송사에 휘말려있는 상태에서 서로 마주 앉는다는 자체가 상당히 서로가 불편할 수도 있거든요. 그러나 어쨌든 오늘 이 행감을 통해서 위원장님께서 충분히 보고 들으셨기 때문에 그런 의지를 갖고 또 의회를 믿는다라면 현재 소송문제랄지 진정서 부분에 있어서 이걸 혹시 취하할 의향은 없으신지? 
</p>
<p><b>○ 참고인 이은환 </b> 대화로 모든 게 해결이 된다면 충분히 그렇게 할 것입니다, 저는. 
</p>
<p><b>○ 정승현 위원 </b> 오늘 어쨌든 충분히 입장들은 확인하셨잖아요, 이 자리에서. 저희 위원들 역시 또 그런 측면에서 질의를 하셨고. 물론 혼자 결정할 사안은 아니라고 보여집니다. 가서 충분히 논의해 보셔야 될 사안이라고 생각은 되지만 어쨌든 오늘 충분히 경험을 하셨기 때문에 현재 지금 진행하고 있는 소송과 진정서 건에 대해서 취하하실 용의가 있는지 제가 한번 여쭤본 거고요. 그런 속에서 서로 협상테이블에 앉는 것과 그렇지 않고 지금 소송이 제기된 상태에서 협상테이블에 앉는 건 분명한 차이가 있다라고 보여지거든요. 그래서 그 부분에 대해서 긍정적으로 검토해 볼 용의가 있으신가요?
</p>
<p><b>○ 참고인 이은환 </b> 네, 오늘 위원님들께서 많은 질문도 하시고 말씀도 주셨는데요. 그중에 저희가 소송에 관련된 심의위원회 구성문제 그리고 성과평가에 대한 문제 그리고 성과연봉문제 이런 것들이 정말 논의를 통해서 개선될 수 있다라면 언제든지 소 취하할 수 있다라고 저는 생각합니다. 다만 저희가 걱정되는 건 “노력하겠습니다. 검토하겠습니다.”라는 말이 얼마큼 강제력이 있을까, 얼마큼 실행이 될까가 사실은 저희들은 가장 걱정이 되는 거거든요. 
</p>
<p><b>○ 정승현 위원 </b> 그 부분에 대해서는 아까 말씀하셨지만 단기적으로 해결할 수 있는 부분, 또 중장기적으로 검토해야 될 부분들이 있습니다만 어쨌든 원장님이 저희 13명 위원들 앞에서 그렇게 빈 말로 그냥 이 자리를 모면하기 위한 답변은 하지 않으셨을 것으로 저희들은 그렇게 믿어지거든요. 그런 믿음이 있다라면 그 부분에 대해서 저는 긍정적으로 검토해 보셨으면 좋겠다라는 생각이에요. 
</p>
<p><b>○ 참고인 이은환 </b> 네, 알겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그 부분에 대해서 그러고 나서 깨끗하게 정말 협상테이블에 앉을 수 있는 계기가 됐으면 좋겠다라는 제안을 드려봅니다. 
</p>
<p><b>○ 참고인 이은환 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 하여튼 오늘 수고하셨고요. 들어가셔도 되겠습니다. 원장님, 앉아서 답변하셔도 되고요. 지금 우리 연구원의 연구사업 추진…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 마지막인데 서서 답변하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 처음 모두에 업무보고하시면서 우리 연구원의 연구사업 추진전략 중의 하나 세부사항에서 마지막으로 서로 화합하는 조직문화 조성에 대해서 언급이 돼 있거든요. 모든 구성원들이 서로 배려하며 화합함으로써 즐겁고 신나는 연구문화를 조성한다라는 게 우리 추진전략의 세부사항에 들어가 있습니다. 또 오늘 어쨌든 질의 과정을 통해서 원장님께서 최선의 성의 있는 답변들을 저는 보여주셨다고 봅니다. 그래서 이 부분에 대해서 앞서 노조위원장도 사실 그런 발언을 하셨습니다만 이 부분들이 오늘 이 자리에서 그냥 검토해 보겠다 내지는 연구해 보겠다라는 그런 자리로 끝날 게 아니라 추진전략 세부사항에도 나왔고 오늘 또 위원님들께서 여러 가지 사안들에 대해서 제안을 하신 만큼 그 부분에 대해서 앞서 연구원장님께서 말씀하셨던 것처럼 지금 장기적으로, 여러 가지 당장 다 모든 걸 해결하기는 어렵다라는 거 저희들 알고 있습니다. 그래서 이런 부분들에 대해서 단기적으로, 아까 유광혁 위원이 얘기하셨나요? 연말까지 제출할 수 있는 부분은 검토 사안들에 대해서 제출하시겠다고 답변하셨는데…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 김우석 위원님이십니다.
</p>
<p><b>○ 정승현 위원 </b> 네, 김우석 위원이 말씀하셨죠. 그렇게 답변하신 것처럼 전향적으로 뭔가 결실을 맺을 필요가 있다라는 판단이 드는데 정말 그렇게 하실 수 있는지요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 노동청 진정 건은 이미 결론이 나와서 저희들한테 통보가 다 왔습니다. 그다음에 재판부 건은 아직 남겨두고 있습니다. 저희는 저희들이 민사소송을 제기한 당사자가 아니라서 소 취하 여부에 대해서는 저희들이 아무것도 할 수 있는 일이 사실은 없습니다. 
</p>
<p><b>○ 정승현 위원 </b> 당연히 그렇죠. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그럼에도 불구하고 저희들이 위원님들께서 걱정하셨던 내용들, 그다음에 주권자들이 경기연구원에 대해서 갖고 있는 생각들, 그다음에 경기연구원 운영과 관련된 사항들을 종합적으로 검토해서 판단을 하겠습니다. 다만 내부에서 운영은 지금도 그렇고 과거에도 그랬듯이 언제나 소통할 준비는 늘 돼 있다는 말씀을 드리고 싶습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그러니까 그런 소통들이 단순히 소통으로 끝나는 게 아니라 오늘 위원님들께서 질의하셨던 내용들이 충분히 감안이 될 필요가 있다. 물론 그 내용들을 전체 다 담아내지 못한다라는 거 우리가 질의하면서도 또 한편으로는 알 수 있습니다. 그러나 최소한의 그런 부분들도 노조 측에서도 인정한 만큼, 노조 측에서도 100% 다 취하려고 욕심을 가지고 접근하면 안 되는 거고 연구원 경영진에서도 모든 걸 지키면서 가려고 해서는 안 된다라는 것들이죠. 말씀하셨던 것처럼 서로 배려하는 속에서 대화가 됐으면 좋겠다라는 말씀입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 깊은 감사말씀드립니다. 
</p>
<p><b>○ 정승현 위원 </b> 그래서 그런 진정성을 가지고 양 노사 측이 대화를 통해서 원만하게 해결이 됐으면 좋겠고 그렇게 돼야만 저희들이 아까 위원장 말씀하셨던 것처럼 예산심의하고 의결할 때도 마음 편하게 내지는 긍정적인 시각으로, 시선으로 바라보면서 예산심의를 할 것 아닙니까? 그렇게 좀 해 달라는 것입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 노력하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 정대운 </b> 정승현 위원님 수고하셨습니다. 저도 발언 하나 해도 되죠? 마무리 발언하면서. 서세요, 마지막이니까. 제가 이건 꼭 해야 될 것 같아서요. 왜냐하면 원장님, 우리가 올해 2019년도도 연구를 위한 연구는 하지 않았잖아요? 제가 늘 10대 들어와서, 기재위 들어왔을 때 그런 얘기를 많이 했습니다. 연구를 위한 연구 하지 말아라. 정말 도민의 혈세 가지고 전략적이든 정책적이든 연구를 가지고 도민들에게 반영 결과가, 그냥 연구과제가 연구해서 어디 서랍장에서 자는 것보다 그 연구를 통해서 도민들에게 직접 반영돼서 그 결과물이 나오는 것이 좋겠죠. 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 2020년도에는 정말 고민해야 됩니다. 왜 그러냐 하면 내가 비유해서 한번 들어볼게요. 우리 경기연구원은 31시군 아시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 31시군의 도민들을 위해서 정책적인 개발과 연구를 하는 기관 맞죠? 우리 도민 혈세로 지급하니까. 맞죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 그러면 서울시 연구원은 어떤가요? 거기도 똑같죠? 서울시도? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 서울시는 단일 시이기 때문에. 
</p>
<p><b>○ 위원장 정대운 </b> 서울은 25개 구잖아요. 서울시도 서울시민을 대변하고 정책적인 부분에서 만들어진 거죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 그러면 예를 한번 들어볼게요. 우리 경기연구원의 사무실 앞에 미세먼지, 소음, 진동, 이것도 내가 한 오염물이라고 보거든요. 서울시에서 거기 경기연구원 앞에다가 쌓아놓으면 원장님은 어떻게 하겠어요? 도민들 대표연구기관에서. 그대로 다 같이 협력해서 그냥 받아야 되는 건가요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 그럴 리는 없죠. 
</p>
<p><b>○ 위원장 정대운 </b> 안 되죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 그러면 이거 문제 삼아야 되죠? 제가 말씀드리고 싶은 건 11월 5일, 이건 광명의 문제가 아니거든요. 서울 구로차량기지 이전 반대 그거 아시죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 들었습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 이것은 사실 31시군을 관장하는 사람은 누구죠, 경기도에? 도민의 대표가? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 의원님들하고 도지사……. 
</p>
<p><b>○ 위원장 정대운 </b> 그러니까 지사 아니겠습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 의원님들도 똑같이 반영한다고 생각하고 있습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 그렇죠. 그런데 이것이 광명의 문제가 아니라 서울시 구로구에 있는 민원을, 소음, 미세, 진동, 여러 부분들의 민원을 해결해서 광명으로 차량기지를 옮기려고 하는 걸 내용 들으신 적 있죠? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 
</p>
<p><b>○ 위원장 정대운 </b> 그런데 아무런 얘기가 없어요. 왜 그러냐면 지사님도 마찬가지고 이런 부분들을, 과연 이것이 합당한가 이런 부분들을 경기연구원에서 이런 것을 전략적 과제로 해서 이 부분을 같이 해야 됩니다. 어떻게 생각하시는가요? 아니, 이것이 광명의 문제가 아니라 서울시 문제잖아요. 서울시하고 경기도의 문제죠. 예를 들어서 서울시장의 집 앞에 있는 쓰레기를 잔뜩 이재명 지사 집 앞에다가 버리면 그거 좋겠습니까? 이런 부분들을, 이것이 전략적 과제입니다. 왜 그러냐면 지사님 입장이야 지금 송사에 말려 있어서 제대로 못 하고 있는 것도 있지만 진짜 이런 것은 경기연구원이 도민들의 삶의 질을 제대로 연구과제로 해서 도출할 생각은 없으신지요? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들이 경기도를 사랑하시는 마음에 대해서 저희들하고 똑같습니다마는 지금 말씀하신 내용은 7호선 연장사업과 관련돼 있다고 들었습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 구로차량기지를 광명으로 옮기는 부분에, 이건 광명을 떠나서 경기도 31개 시군을 이재명 지사가 도민을 대표하고 있으니까 이것이 과연 도민들의 연구전략 아니겠습니까? 이걸 2020년도에 전략을 담아서 도가 선도적으로 얘기를 해 줘야 하는데 기자회견, 그러면 광명시를 서울로 편입을 시키든가. 그런데 그렇게 얘기해도 집행부에서는 아무런 얘기가 없기 때문에 혹시 도 집행부에서 우리 연구기관에 혹시 이것이 내년도 2020년도의 전략과제로 해서 경기도의 31개 시군에 속해 있는 광명시가 구로의 민원사항인 소음, 미세먼지, 진동 관련해서 옮기는 부분에서 정책적으로 연구해서 도출, 그래야 국토부에다 어떤 납득할 수 있는 부분을 할 것 아니겠습니까? 
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 제가 듣고 있기로는 7호선 연장사업으로서 일부 주민은 반대하고 일부 주민은 찬성한다고 듣고 있습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 그렇지 않습니다. 거의 다 반대하기 때문에, 그러니까 전략과제로 할 용의가 있냐는 거죠, 도민을 위해서. 
</p>
<p><b>○ 경기연구원장 이한주 </b> 이건 상당히 중요하기 때문에 도와 협의해서 이 문제에 대한 연구방침을 정하겠습니다. 
</p>
<p><b>○ 위원장 정대운 </b> 그래요. 그거 검토하시고요. 이재명 지사님은 여기 광명시에 아무런 관계를 안 두는 것 같아요, 그렇게 해도. 서울시로 차라리 옮겨가라고 하든가. 어쨌든 오늘 장시간 우리 위원님들이 지적했듯이 그냥 “검토하겠습니다. 검토하겠습니다.” 끝나지 마시고 어떤 결과물이 안 나오더라도 최소한 단계가 있는 거예요. 진행과정들을 위원님들한테 공유해 주시고 우리 존경하는 정승현 부위원장님이 말씀했잖아요. 자기를 스스로 내려 놓지 않으면 어떤 실타래가 풀리지 않습니다. 서로 한 발자국 양보해서 우리 경기연구원이 정말 도민들의 정책연구를 하고 있다 이런 모습도 도민들한테 보여야 되겠죠? 
</p>
<p style="padding-left:1.2em">  어쨌든 장시간 고생하셨습니다. 더 이상 질의하실 위원님이 안 계시므로 경기연구원 소관에 대한 질의와 답변을 모두 마치도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기연구원 원장을 비롯한 관계자 여러분! 장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위해 자료 준비와 위원님들의 질의에 성실히 답해 주신 집행부 관계자 여러분께 위원장으로서 감사드립니다. 경기연구원장을 비롯한 관계 여러분께서는 오늘 여러 위원님들께서 지적해 주신 사항을 겸허히 받아들여 도정에 적극 반영해 주시기 바랍니다. 또한 오늘 감사 중에 위원님들께서 개선을 요구한 사항에 대해서도 조속히 시행될 수 있도록 노력을 다해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 관계 여러분! 수고하셨습니다. 그러면 이상으로 경기연구원 소관 사항에 대한 2019년도 행정사무감사를 모두 마치겠습니다. 
</p>
<p class=''ar''>(21시53분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(13명)
</b></p>
