            <div','경기도의회',false,'{"legacy_id": "audit-11569", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=11569"}'::jsonb,'2019-11-12'::date,'2019-11-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-11569');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2018.11.13. 화요일] 경기연구원 — 기획재정위원회 2018년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2018년도 행정사무감사(2018. 11. 12. ~ 2018. 11. 23.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=10849" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2018년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기연구원
</p>
<p><hr /></p>
<p>일  시 : 2018년 11월 13일(화)
</p>
<p>장  소 : 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(11시40분 감사개시)
</p>
<p><b>○ 위원장 정대운 </b> 좌석을 정돈해 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2018년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 정대운 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다.
</p>
<p style="padding-left:1.2em">  행정사무감사는 경기도의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민 삶의 질 향상에 기여하고자 함이 목적으로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도 정책연구의 산실인 경기연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 전반을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 연구원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장, 부원장 및 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다.
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2018년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부할 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어나 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  경기연구원 원장 나왔습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 위원장 정대운 </b> 부원장 나오셨습니까?
</p>
<p><b>○ 경기연구원부원장 김군수 </b> 네.
</p>
<p><b>○ 위원장 정대운 </b> 연구기획본부장 나왔습니까? 안 나왔습니까?
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네, 여기 있습니다.
</p>
<p><b>○ 위원장 정대운 </b> 답변하셔요. 경영본부장 나왔습니까?
</p>
<p><b>○ 경영본부장 박정란 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 북부연구센터장 나왔습니까?
</p>
<p><b>○ 북부연구센터장 이외희 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 공존사회연구실장 나왔습니까?
</p>
<p><b>○ 공존사회연구실장 박충훈 </b> 네.
</p>
<p><b>○ 위원장 정대운 </b> 공감도시연구실장 나왔습니까?
</p>
<p><b>○ 공감도시연구실장 봉인식 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 상생경제연구실장 나왔습니까?
</p>
<p><b>○ 상생경제연구실장 이수행 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 휴먼교통연구실장 나왔습니까?
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 생태환경연구실장 나왔습니까?
</p>
<p><b>○ 생태환경연구실장 이기영 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 연구기획부장 나왔습니까?
</p>
<p><b>○ 연구기획부장 장윤배 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 홍보ㆍ정보부장 나왔습니까?
</p>
<p><b>○ 홍보ㆍ정보부장 이인애 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 행정지원부장 나왔습니까?
</p>
<p><b>○ 행정지원부장 이용원 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 재정지원부장 나왔습니까?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 연구지원부장 나왔습니까?
</p>
<p><b>○ 연구지원부장 배미성 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 대외협력부장 나왔습니까?
</p>
<p><b>○ 대외협력부장 이덕환 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 공공투자관리센터 총괄기획부장 나왔습니까?
</p>
<p><b>○ 공공투자관리센터총괄기획부장 이상미 </b> 네, 나왔습니다.
</p>
<p><b>○ 위원장 정대운 </b> 다음은 선서의 요령을 말씀드리겠습니다. 선서는 전체 증인을 대표하여 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시면 됩니다.
</p>
<p style="padding-left:1.2em">  그러면 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2018년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서 지방자치법 시행령 제43조5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2018년 11월 13일 원장 이한주.
</p>
<p><b>○ 위원장 정대운 </b> 모두 자리에 앉아 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  그러면 원장 나오셔서 간부소개와 업무보고를 간략히 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 안녕하십니까? 경기연구원장 이한주입니다. 오늘 위원님들을 모시고 2018년도 경기연구원 업무보고와 민선7기 업무방향을 주권자의 전당에서 보고드리게 되어서 기쁘고 감사하게 생각합니다. 우리 경기연구원은 경기도의 싱크탱크로서 경기도민의 삶의 질 향상을 위해 경기도정 현안을 해결하고 경기도 미래비전을 제시하는 등 임직원 모두가 열정을 다해 정책개발을 추진해 가고 있습니다. 향후에도 경기도와 경기도의회 그리고 연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드리겠습니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 주요간부를 소개해 드리겠습니다.
</p>
<p style="padding-left:1.2em">  김군수 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정훈 연구기획본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박정란 경영본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이외희 북부연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박충훈 공존사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  봉인식 공감도시연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이수행 상생경제연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  송제룡 휴먼교통연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이기영 생태환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  장윤배 연구기획부장 겸 정책분석부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  배미성 연구지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이인애 홍보ㆍ정보부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용원 행정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박인숙 재정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이덕환 대외협력부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상미 공공투자관리센터 총괄기획부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  공공투자센터는 아직 소장이 공석인 관계로 총괄기획부장이 인사드렸습니다.
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 배부해 드린 보고자료의 목차를 봐 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  보고순서는 기본현황, 연구사업 추진전략, 연구사업 추진체계, 2018년 주요성과 그리고 2018년 4/4분기 및 향후 주요업무계획을 말씀드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  짧은 주요업무보고 가장 짧은 책으로 별도 요약보고돼 있는, 자료가 많아서……. 말씀드리도록 하겠습니다. 먼저 제1쪽 기본현황입니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기 비전제시와 정책개발 기능을 수행하고 있습니다. 연구원의 조직은 본원이 2본부, 1센터, 5실, 7부로 구성되어 있고 부설기관인 경기도공투센터가 3부로 구성되어 있습니다. 현재는 민선7기 연구원의 미션을 효과적으로 수행할 수 있는 조직개편을 진행작업 중에 있습니다. 우리 원의 인력은 본원이 부원장 1명, 연구직 52명, 관리ㆍ정보ㆍ기능직 22명 등 76명의 정규직원과 85명의 기간제근로자로 총 161명이 근로하고 있으며 공공투자센터에는 투자분석직 7명, 관리직 3명 등 총 10명이 근무하고 있습니다. 기관장의 장기간 공백 등으로 발생한 10명의 박사급 연구직 결원에 대해서는 조속하게 채용하여 향후 연구에 차질 없이 대비하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 2쪽 주요기능입니다. 2쪽 주요기능은 자료를 갈음하겠습니다. 다만 북부연구센터가 동북부 관련 연구를 위하여 특별히 특화되어 있다는 사실을 강조드리겠습니다.
</p>
<p style="padding-left:1.2em">  3쪽 예산현황에 대해서 보고드리겠습니다. 올해 총예산 규모는 246억 원입니다. 일반회계 201억 원, 수탁용역사업 특별회계 30억 원, 공공투자관리센터 15억 원으로 구성돼 있습니다. 일반회계의 수입ㆍ지출내역을 보다 세부적으로 말씀드리자면 수입항목은 경기도 출연금이 154억 원으로 일반회계 예산의 76.8%를 차지하고 있으며 또한 일반 수탁용역사업 15.5억 원과 전기 이월금 19.3억 원이 총예산의 일반회계 예산의 17.3%를 이루고 있습니다. 지출항목으로는 인건비가 91억 원으로 45.3%를 차지하고 있으며 연구사업비는 84억 원으로 42.1%의 비중입니다.
</p>
<p style="padding-left:1.2em">  다음은 4쪽 연구사업 추진전략입니다. 이 연구사업 추진전략은 이미 작성되어 있던 것으로서 현재는 GRI 발전전략과 조직개편 작업을 진행 중이며 완료되는 대로 기획재정위원회에서 다시 말씀드릴 기회를 주시면 와서 다시 보고드리도록 하겠습니다. 아울러 도의회 등 원내외 토론과정을 거쳐서 민선7기 도정방향에 부합하는 추진전략을 적극적으로 수립하여 도민의 요구에 부응하는 조직으로 지속적으로 변화해 나갈 것을 다짐드립니다.
</p>
<p style="padding-left:1.2em">  다음은 5쪽 연구사업 추진계획입니다. 우선 정책방향 및 대안을 수립하는 연구과제사업이 있습니다. 연구과제사업으로는 학술적 역량 강화를 위해 기본연구과제, 도정 지원을 위한 단기정책과제와 중장기 전략과 비전제시를 위한 전략정책과제, 내외에 정책 이슈와 대안을 제시하는 이슈&진단 그리고 정책Brief 등을 운영하고 있습니다. 또한 대내외 소통과 협력을 위한 정책세미나, 학술지 발간, 콘텐츠 홍보, 의정교류 등 연구부대사업을 수행하고 있습니다. 그리고 효율적 연구를 지원하기 위한 정보자료 지원, 지리정보시스템인 GIS 사업, 전산사업 등 연구지원사업을 수행하고 있으며 향후 통계자료분석을 지원할 예정입니다. 아울러 향후 연구원의 역량 강화를 위해 HRD에 보다 중점을 두어 추진하기 위해 기본계획을 수립하고 있다는 점은 아까 말씀드린 저희 조직개편과 관련이 있다는 점을 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  2018년 주요연구성과에 대해 보고드리겠습니다. 6쪽 연구성과입니다. 9월 30일을 기준으로 연구과제 및 정책현안분석 완료가 199건이 수행되었으며 현재 진행 중인 78건 등 총 277건을 수행하거나 현재 수행하고 있습니다. 2018년 계획 대비 83.4%에 해당합니다. 118건의 연구과제 추진을 통해 경기도의 정책 및 시군 중장기 발전 전략을 제시하였습니다. 또한 159건의 정책현안분석을 통해 민선7기 핵심공약인 기본소득, 남북협력 및 평화경제, 일자리 전략, 4차 산업혁명 선도 등 변화하는 도정 주요이슈에 역점을 두고 대응하고 있다고 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 7쪽 주요연구목록입니다. 남북평화협력시대 경기도 남북교류협력 기본구상과 전략연구, 경기 중부내륙지역 종합발전계획, 통일경제특구 기본구상 등 13건의 전략연구과제를 수행하였습니다. 경기도의 공공기관과 협력 네트워크를 구축하고 경기도경제과학진흥원, 차세대융기원 등 경기도 내 경제과학기술 관련 공공기관이 모두 협력하여 4차 산업혁명 경기도 모델 구축 및 실행계획 연구를 수행하는 등 3건의 협력연구를 진행한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 8쪽 2018년 4/4분기 주요계획에 대해 말씀드리겠습니다. 우선 민선7기를 맞이하는 연구원은 다음과 같은 혁신방안을 준비했습니다. 먼저 31개 시군과 협력연구 강화입니다. 협치의 촉진을 위해 경기도 내 31개 시군 및 경기도 차원의 공동과제를 발굴하고 시군 정책연구를 강화하겠습니다. 이를 위한 전담조직을 신설하고 관련 분야의 연구인력을 확충하겠습니다. 아울러 경기도 31개 시군 및 공공기관 간 연구성과 공유를 확대하고 협력연구를 강화하겠습니다. 아울러 도의회 의원님들과 공동연구를 수행하는 과제를 준비 중에 있습니다. 다음으로 미래가치 지향적 도정현안 대응을 강화하겠습니다. 민선7기의 핵심 전략과제인 공정건설 생태계 구축, 국토보유세 도입 및 기본소득 정책추진, 지역화폐 활성화, 평화경제 등 이를 전담할 연구조직과 인력을 확충하겠습니다. 또한 남북협력 강화와 경기북부 발전을 위한 북부연구센터의 기능을 대폭 강화하도록 하겠습니다. 관련 박사급 인력을 충원하고 연구활동을 강화하도록 하겠습니다. 경기연구원은 개인의 연구성과가 조직의 연구성과로 연결될 수 있도록 관련 제도와 조직문화를 개선하겠습니다. 연구원의 재정기반을 강화하기 위해 수탁과제 활성화를 위한 지원체계도 마련하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 2018년 4/4분기 및 향후 주요연구과제 사업계획입니다. 경기도의 중장기 비전과 전략제시를 위한 전략과제 현황은 10쪽의 자료와 같습니다. 지방분권, 4차 산업혁명과 스마트시티, 경기북부의 오늘과 미래, 경기비전 2030, 건설산업 공정성 강화방안 등의 과제를 수행하고 있습니다. 연간 15건 내외의 전략과제를 수행하고 있습니다. 전략과제라 함은 정책과제 중 중요도가 높거나 학제적 연구가 필요한 중대형 과제를 의미합니다.
</p>
<p style="padding-left:1.2em">  다음은 각 부서별 계획에 대해 보고드리겠습니다. 보고자료 11쪽부터 16쪽까지 있습니다. 먼저 공존사회연구실입니다. 주요연구분야는 지방 행ㆍ재정 기능 강화 및 재정립ㆍ지방분권, 남북협력 등을 연구하고 있습니다. 민선7기 조직개편방안 연구, 주요공약인 자치경찰제 도입방안 등 연구를 수행하고 있습니다. 향후 기본소득형 국토보유세 도입방안 연구, 남북 평화협력 및 한반도 통합정책 연구 등을 수행할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽 공감도시연구실입니다. 주요분야는 국토 및 지역개발정책과 제도, 수도권 정책과 그린벨트, 주택정책, 도시재생, 도시ㆍ농촌의 설계, 공간 및 지리정보 관련 정책 등을 연구하고 있습니다. 공익적 임대주택 공급 확대를 위한 민간의 역할에 관한 연구, 경기도 삶의 질 Brief 등의 연구를 수행하고 있습니다. 민선7기 주요연구로는 개발이익 도민환원제를 마련하고 경기도 공공발주사업의 효율적으로 관리 및 공공성을 확보할 수 있는 방안, 규제로 인해 특별한 희생을 치른 지역에 대한 특별한 지원대책 마련 등을 수행할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 13페이지 상생경제연구실입니다. 주요연구분야는 지역경제 및 산업정책, 4차 산업혁명 등의 신성장산업, 문화, 관광산업의 연구 등을 하고 있습니다. 민선7기 주요 연구방향으로는 4차 산업혁명과 연계한 미래형 혁신산업단지의 구축과 조성, 기본소득 및 지역화폐의 도입방안에 대한 실행연구, 혁신적 창업시스템 구축을 통한 일자리 창출 확대 등을 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 14쪽 휴먼교통연구실입니다. 주요연구분야는 삶의 질이 보장되는 교통환경을 조성하고 안전하고 편리한 대중교통서비스체계를 제공하며 편리하고 효율적인 광역교통체계를 구축하고 4차 산업혁명과 연계한 지능형교통체계의 구현 등을 연구하고 있습니다. 민선7기 주요 연구방향으로는 새경기 버스 준공영제, 경기교통공사의 설립, 남북연결 철도사업 추진을 위한 기초조사 및 철도물류체계의 개선, 수도권 미세먼지 저감대책으로 전기버스 도입 확대 등에 관한 연구를 강화할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 15쪽 생태환경연구실입니다. 주요연구분야는 지속가능발전과 녹색경제, 상하수정책, 환경안전 및 보건, 폐기물 및 자원순환, 대기 및 유해물질, 자연환경과 공원ㆍ녹지, 기후변화와 에너지정책 등을 연구하고 있습니다. 통합 물관리를 위한 한강유역 거버넌스 구축방안, 제4차 산업혁명과 환경관리 등을 수행하고 있습니다. 민선7기 주요연구방향으로는 경기도 미세먼지 집중배출원 분석 그리고 관리방안, 남북 환경협력 방안, 한강하구의 평화적 활용을 위한 남북협력 방안 등에 집중할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 북부연구센터입니다. 16페이지 되겠습니다. 주요연구분야로는 경기북부지역 삶의 질 향상, 지자체 남북교류협력 및 통일정책, DMZ 및 접경지역 등을 연구하고 있습니다. 민선7기 주요 연구방향으로는 한반도 신경제지도의 구상과 경기도 전략의 매칭, 남북개발협력포럼을 운영, 군사시설규제의 재조정 등입니다. 현재 각 부서별로 내년도 사업계획을 수립 중이며, 11월 8일에는 연구원 전 직원이 참여하는 연구사업 발표회를 개최하였고 내년도 주요 연구과제와 연구의 방향을 심도 있게 토론한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 17쪽 연구지원사업 중 연구부대사업 부문입니다. 경기도의회, 경기도, 시민단체, 전문가 등의 네트워크 구축을 통해 의정발전방안의 모색을 위한 포럼을 현재 운영하고 있으며 시군의 주요현안에 대하여 경기도, 경기도의회, 시군, 전문가 등이 참여하여 정책의견 수렴 및 현장밀착형 솔루션 지원을 위한 지역혁신토론회를 진행하고 있습니다. 또한 정책세미나포럼을 진행하고 있으며 동향분석과 전망, GRI학술지 발간, 콘텐츠 홍보, 대외협력교류 등을 추진하고 있습니다. 자세한 사업은 17페이지 내용을 참조해 주시기 바라며 전체적으로 사회공헌활동도 110건 정도 진행하고 있다 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 18쪽 연구지원사업 부문입니다. 정보자원 지원, 전산사업, GIS사업을 추진하고 있습니다. 자세한 사업내용은 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 19쪽 경기도 공공투자관리센터 운영입니다. 2018년 1월 4일 경기도 공공투자관리센터 설치 및 운영 조례가 제정됨에 따라 경기연구원은 4월 4일 이사회를 개최하여 경기도의 공공투자사업에 대한 관리를 전담하는 경기도 공공투자관리센터를 부설기관으로 설치할 계획을 의결하였고 2018년 4월 11일 경기도 공공투자관리센터 경기연구원 부설기관으로 설치하였습니다. 현재 투자분석직 7명과 관리직 3명 등 총 10명의 채용을 완료한 상태이며 소장과 투자분석직 1명에 대한 공개채용 절차가 진행되고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽 기간제근로자 정규직 전환입니다. 정부와 경기도의 계획 및 가이드라인에 따라 상시ㆍ지속적 업무에 종사하는 비정규직의 원칙적 정규직 전환을 원칙으로 삼아 추진하고 있습니다. 그동안 경기연구원 노동조합과 협의하여 정규직 전환 기본계획을 수립하였고 전환심의위원회를 거쳐서 전환 대상자들의 직무를 점검하였고 직군별 의견수렴의 절차를 거쳐서 전환직무, 전환직종, 전환방법을 확정하였습니다. 향후 전환심의위원회의 결과에 따른 관련 규칙을 개정하고 정원 승인을 도정부에 요청을 하여 전환평가 및 처우개선 등을 추진할 예정입니다.
</p>
<p style="padding-left:1.2em">  마지막으로 21쪽부터는 붙임자료입니다. 21쪽부터 24쪽은 2017년 행정사무감사에 대한 조치결과이고 25쪽은 3년간 도의회 요청과제의 현황, 끝으로 26쪽은 부서장 명단입니다. 참고 부탁드립니다.
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요 업무보고를 모두 마치겠습니다. 들어주셔서 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 정대운 </b> 원장님 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 질의시간은 제한하도록 하겠습니다. 우선 위원님 한 분당 10분씩 드리고 추가질의는 5분을 드리도록 하겠습니다. 그리고 위원님들의 추가질문이 끝나면 감사진행 상황과 시간 등 제반 여건을 감안해 추가질문을 계속할지 여부를 결정하도록 하겠습니다. 원활한 감사진행을 위해 부득이 시간제한을 두게 된 점을 널리 양해해 주시면 고맙겠습니다. 만약 시간적 제약으로 인해 준비하신 질의를 미처 다 하지 못하신 위원님께서는 추후 서면으로 질의가 가능하오니 이를 활용해 주시기 바랍니다. 또 위원님들의 질의에 대한 원장의 답변이 어려울 경우 업무담당 실장 및 부장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직ㆍ성명을 분명히 밝히고 답변해 주시기 바랍니다. 그러면 질의하실 위원님 거수로 신청받겠습니다. 먼저 유영호 위원 하고 그다음에 빔프로젝트를 사용해야 되기 때문에 민경선 위원님.
</p>
<p><b>○ 민경선 위원 </b> 아직 준비가 안 됐습니다.
</p>
<p><b>○ 위원장 정대운 </b> 그럼 신정현 위원님?
</p>
<p><b>○ 신정현 위원 </b> 저도 빔 써야 돼 가지고요.
</p>
<p><b>○ 위원장 정대운 </b> 그러면 조금 이따가 준비되시면 한 번에 일괄적으로 빔프로젝트 사용하실 분 쭉 연결해서 갈 테니까요. 준비되시면 전문위원실에 말씀하시기 바랍니다. 유영호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 유영호 위원 </b> 안녕하세요? 용인의 유영호입니다. 먼저 질문에 앞서 연구원 칭찬부터 하고 들어가겠습니다. 생태환경연구실 송미영 선임연구원 얘기인데요. 평택시, 안성시, 용인시가 전에 공동으로 경기도 수자원공사를 통해서 의뢰한 과제가 있습니다. 진위ㆍ안성천 및 평택호 수계 수질개선과 상하류 상생협력방안 연구용역이거든요. 이 연구는 3개 지자체가 아주 오랜 기간 동안에 첨예하게 대립하고 아주 쉽지 않은 과제였는데 이해관계자의 시선을 의식하지 않고 아주 디테일한 모범적인 연구결과물로 호평을 받은 그런 사안입니다. 경기도는 이를 토대로 해서 상수원 갈등 해소와 진위ㆍ안성천, 평택호 수계 수질개선 상하류 상생발전을 위한 상생협력추진단을 발족하여 운영 중에 있습니다. 조만간 민관 거버넌스 정책협의에 많은 기대를 하고 있습니다. 저는 연구원들의 연구과제 수행에 기대가 상당히 큽니다. 공정성, 신뢰성, 중립성 문제는 치우침 없는 연구과제 수행으로 해결할 수 있다고 생각합니다.
</p>
<p style="padding-left:1.2em">  그러면 질문을 하도록 하겠습니다. 첫 번째 질문입니다. 용역을 의뢰한 기관에 대해서 결과물에 대한 만족 정도를 파악하는 시스템과 참여 연구원에 대한 인센티브 반영에 대해서 질문드리도록 하겠습니다. 용역 의뢰기관의 만족도를 조사하는 설문에 참여한 사람의 개인정보가 유출돼서 연구원으로부터 불만과 항의를 받은 사실이 있다는 것을 제가 들었습니다. 이를 토대로 한 성과급 지급 등 평가에 민감하여 발생한 것으로 생각되는데 현재는 어떤 식으로 평가가 이루어지고 반영되는지에 대해서 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 우선 송미영 연구원의 결과에 대해서 저희들이 칭찬을 들으니까 좀 더 열심히 해야 되겠다는 생각이 들었습니다. 만족도 상승을 유도하기 위해서 연구원 개인별로 특정행위를 하였다는 것은 있을 수 없는 일이고요. 현재는 만족도조사를 저희들이 연구 끝나면 하고 있는데 그 부분에 대해서는 돌아가서 점검을 좀 해 보겠습니다. (관계직원을 향하여) 우리 담당자 중에 이 문제 혹시 알고 계시나요? 이런 일이 있었습니까?
</p>
<p style="padding-left:2.4em">    (경기연구원장, 관계직원에게 확인 중)
</p>
<p style="padding-left:1.2em">  저희가 지금 확인되지 않고 있어서요, 위원님께서 말씀해 주시면 이 부분에 대해서 철저히 파악을 해서 다시 한 번 보고드리도록 하겠습니다.
</p>
<p><b>○ 유영호 위원 </b> 그러면 설문은 하죠? 지금도요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 유영호 위원 </b> 그래서 그 설문결과를 인센티브라든가 성과급 지급하는 데 반영합니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 만족도 설문결과는 인센티브의 질 평가에 반영을 일부 하고 있습니다.
</p>
<p><b>○ 유영호 위원 </b> 그러면 그 내용을, 이것도 좀 시간이 어느 정도 흐른 사안이거든요. 직접적으로 그 설문에 참여한 사람을 알아 가지고 발생했던 사안이라 제가 체크하는 의미에서 질문을 드린 거니까 그거 한번 확인해 보시고 향후 이러한 일이 절대로 발생하지 않도록 교육 좀 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 있을 수 없는 일이라고 생각하고요. 끝나고 말씀을 주시면 저희들이 조금 더 제도개선에 도움이 되겠습니다.
</p>
<p><b>○ 유영호 위원 </b> 네. 그럼 다음 질문드리겠습니다. 연구원에서 외부특강 현황을 살펴보면 2017년에 69건, 2018년 현재 34건으로 나타났습니다. 외부특강 시 강의료를 1회 20만 원에서 60만 원 받고 있다고 하는데 외부특강 시 복무상 출장결재인지 아니면 외출결재인지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 외부특강을 할 때는 전부 원장의 허가를 받고 특강을 하도록 되어 있습니다. 이 경우, 경우에 따라 다르겠습니다만 예컨대 경기연구원에 가까이 있는 인재개발원 같은 경우에는 간단한 결재를 하고 그렇지 않고 시간을 할 때는 거기에 합당한 조처를 취해서 하고 있습니다. 전부 원장의 허가를 받고 그렇게 하는 걸로 되어 있습니다.
</p>
<p><b>○ 유영호 위원 </b> 전에 보면 감사관실의 그런 지적을 받아서 2016년 6월 1일 자로 관련 규정의 정비가 완료됐는데, 규칙 개정이 시행되고 있는데 그거 철저히 지키고 계시는 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 아울러 연구원에 강의를 출강하시는 분들이 꽤 많이 있었는데요. 경기연구원의 전문성을 높이기 위해서 학부 강의는 대부분 다 지양시키도록 노력하고 있고 다만 전문적인 연구역량 함양을 위해서 대학원 강의인 경우에는 다소 여유를 줄 생각으로 있습니다.
</p>
<p><b>○ 유영호 위원 </b> 저도 그쪽으로 가는 방향이 바람직하다고 생각하고 있습니다. 대학교 출강을 살펴보면 2017년에 14건, 2018년 현재 11건으로 나타났는데요. 대학교 출강 시에 매주 개인 연가를 등록하고 출강하고 있습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 유영호 위원 </b> 그다음에 경기도하고 경기도의회 토론회나 간담회 관련된 질문인데요. 경기도의회에서 토론회를 개최하면 거기에 참여하는 관련 집행부 공무원은 참석수당을 받지 않습니다. 경기도의회와 경기도에서 토론회 개최 시에 연구원 박사가 발제 또는 토론일 경우에 1시간당 얼마를 수령하는지 또 토론자로 참석 시 복무결재는 출장인지 아니면 외출결재인지, 출장이면 출장비를 받는지 거기에 대해서 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 제가 좀 준비가 덜 돼서 이건 관련자한테 답변을 하도록 부탁해도 되겠습니까?
</p>
<p><b>○ 유영호 위원 </b> 네.
</p>
<p><b>○ 대외협력부장 이덕환 </b> 대외협력부장 이덕환입니다. 말씀하신 원내 직원들이 외부에 토론이나 발표 나갈 때는 대외활동이라는 제도를 이용하고 있습니다. 대외활동을 이용해서 나갈 때는 출장비를 지급하지 않고 있습니다.
</p>
<p><b>○ 유영호 위원 </b> 출장비는 지급하지 않고 그러면 토론에 참가한 수당은 받고 있는 거네요?
</p>
<p><b>○ 대외협력부장 이덕환 </b> 우리 원내에서 주관하는 행사일 때는 내부직원이기 때문에 수당을 주지 않고 있습니다. 그런데 외부에서 타 기관에서 주최ㆍ주관한 행사에 한해서는 그쪽 주관에서 주는 기준대로 아마 받는 걸로 저는 알고 있습니다.
</p>
<p><b>○ 유영호 위원 </b> 그럼 경기도의회나 경기도에서 하는 건 어떻습니까?
</p>
<p><b>○ 대외협력부장 이덕환 </b> 그것은 법적으로는 받을 수 있다고 저희는 알고 있고요. 경기도 집행부에서도 그렇게 주고 있는 걸로 알고 있습니다.
</p>
<p><b>○ 유영호 위원 </b> 그러면 하나 더 말씀드릴게요. 토론자 참석수당하고 출장비 수령은 아까 이중수령이잖아요, 그렇게 가면?
</p>
<p><b>○ 대외협력부장 이덕환 </b> 네, 맞습니다.
</p>
<p><b>○ 유영호 위원 </b> 그래서 출장비는 지급하지 않는다?
</p>
<p><b>○ 대외협력부장 이덕환 </b> 네.
</p>
<p><b>○ 유영호 위원 </b> 그렇게, 확실하신 거죠?
</p>
<p><b>○ 대외협력부장 이덕환 </b> 네.
</p>
<p><b>○ 유영호 위원 </b> 알겠습니다. 그러면 거기까지 답변 감사합니다. 그래서 앞으로는 이쪽에 관해서 다른 기관에서 논란의 여지가 상당히 많이 있습니다. 그래서 연구원에 대한 평가시스템하고 외부특강 및 출강 시에 복무관리를 철저하게 준수하고 내부에서는 관리해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 대외협력부장 이덕환 </b> 말씀하신 내용 명심해서 이 부분에 차질 없도록 하겠습니다.
</p>
<p><b>○ 위원장 정대운 </b> 유영호 위원님 수고하셨습니다. 다음 질의하실 위원님 거수해 주시기 바랍니다. 김우석 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김우석 위원 </b>  몇 가지만 짧게 좀 여쭐게요. 경기연구원 경영평가 실적보고서를 보면 총점이 2017년도에 B가 나왔는데 뭐 B 정도, 여러 가지 리더십 전략, 조직 인적자원관리, 재정정보관리, 기관성과 이런 게 있어요. 그런데 B등급이 나왔는데 재정정보관리가 유독 눈에 띄게 낮은 평가를 받고 있는데 어떤 이유에서 이런 지표들이 나오나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 부분은 제가 검토가 덜 됐습니다.
</p>
<p><b>○ 김우석 위원 </b> 취임하신 지 얼마 안 되셔서 잘 모르시겠는데 아시는 분 있으면 답변 좀 부탁드릴게요.
</p>
<p><b>○ 연구지원부장 배미성 </b> 연구지원부장 배미성입니다. 그 당시 저희가 재정관리 쪽 지표에 있어서 중기재정계획이라고 연구원의 전반적인 계획을 수립하고 그 수립에 따른 재정에 대한 파트별 재정운영계획이 수립돼야 되는데요. 그게 좀 구체적으로 시나리오별로 수립되는 부분이 조금 부족해서 저희가 미진한 바가 있었습니다.
</p>
<p><b>○ 김우석 위원 </b> 이것은 누가 계획을 잡는 거죠?
</p>
<p><b>○ 연구지원부장 배미성 </b> 그거는 전체적인 계획은 저희 연구원에서 전사적으로 수립을 하고 재정에 대한 부분은 또 재정파트에서 별도로 하고 있습니다.
</p>
<p><b>○ 김우석 위원 </b> 근데 이게 처음 지적되는 부분은 아니죠? 계속 비슷한 내용의…….
</p>
<p><b>○ 연구지원부장 배미성 </b> 두 개 연도에 연속으로 저희가 지적을 받은 바가 있습니다.
</p>
<p><b>○ 김우석 위원 </b> 향후에는 이런 것들이 보완될 가능성이 있어 보이시나요?
</p>
<p><b>○ 연구지원부장 배미성 </b> 네, 저희가 재정파트에 중기사업계획의 굵직한 핵심사업에 대해서 연도별로 최소 5년 정도의 중기재정계획을 수립하는데요. 저희 전사적인 계획에 맞추어서 재정사업이 잘 이루어지도록 향후에는 좀 더 구체적으로 시나리오별로 재정계획 수립을 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 2019년도에도 예산이 증액됐죠?
</p>
<p><b>○ 연구지원부장 배미성 </b> 네, 맞습니다.
</p>
<p><b>○ 김우석 위원 </b> 그 부분도 관련해서 꼼꼼하게 예산편성을 하셔야 될 것 같다는 생각이 들고요.
</p>
<p><b>○ 연구지원부장 배미성 </b> 네, 알겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 그리고 지금 또 하나 궁금한 게 이 업무보고 자료를 보다 보면 연구사업비 부분이 상당한 비중을 차지하더라고요, 인건비하고.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 김우석 위원 </b> 그런데 이 연구비 편성과 배정은 어떤 식으로 이루어지나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구비는 저희들이 편성을 할 때 올해 같은 경우에도 각 실별로 명년도 연구사업계획을 발표하고 그 발표사업을 기반으로 해서 저희 연구심의위원회에서 심의를 거쳐서 확정되어집니다. 자체 발굴도 있고 실국 발굴도 있고 또 도청에서 요청한 사항도 있고 이런 것들을 합산하여 평가합니다.
</p>
<p><b>○ 김우석 위원 </b> 하여튼 예산이 들어가는 부분들은 모든 도민들이나 저희 위원님들도 관심사항이잖아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 김우석 위원 </b> 그래서 꼼꼼한 계획 그리고 집행을 통해서 이런 재정부분에 대한 논란이 없었으면 싶겠다라는 그런 판단에서 말씀을 드렸고요. 경기연구원이 경기도 도정발전을 위해서 역할을 잘하고 있다고 판단되는데 사실 경기도를 넘어서 대한민국을 선도하고 또 국제적인 수준의 어떤 학술적인 그런 역할들이 필요하다는 생각이 드는데 그런 계획들은 있으신지 여쭤볼게요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님께서 말씀하신 부분에 저희 경기연구원의 설립목적은 경기도뿐만 아니라 국가까지도 포함돼서 있습니다. 따라서 경기도는 1,300만이나 되는 사실은 군대 없는 국가 수준의 단체이기 때문에 경기도에서 해결되면 국가에서도 해결될 수 있는 문제, 예컨대 국토보유세라든가 지역화폐라든가 하는 연구들을 저희들이 선도적으로 할 생각들이 있습니다. 열심히 노력하도록 하겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 아까도 원장님께서 향후 계획에 대해서 북부연구센터의 어떤 기능을 강화하겠다라고 말씀을 해 주셨잖아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 김우석 위원 </b> 구체적으로 어느 정도까지 고민을 하고 계시는지 시간을 충분히 드릴 테니까 한번 설명을 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 북부연구센터가 그동안에는 북부가 군사규제에 대응하여 발전이 지체되었고 그것에 대한 연구에 국한되어 있었습니다. 도로라든가 교통이라든가 문화라든가 하는 부분들에 대한 연구들을 수행하고 있었는데 현재 문재인 대통령 집권 이후에 남북관계가 급속히 변화하였기 때문에 북부는 단순히 북부규제가 아니라 앞으로 미래지향적인, 그러니까 북한과의 평화공존 관련된 발전업무가 중요한 이슈로 대두되었기 때문에 그쪽 부분에 대한 연구인력을 현재 2인 정도 추가하여 뽑을 생각이고 그다음에 북부연구센터의 현재 사무공간이 매우 좁기 때문에 이 공간에 대한 것도 지금 확충을 준비 중에 있다 이렇게 말씀드리겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 얼마 전에 국가균형발전위원회의 경기도에서 선제적으로 예타를 면제하는 사업들을 가닥을 잡았다는 기사가 나왔잖아요? 알고 계신가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 잘 못 들었습니다.
</p>
<p><b>○ 김우석 위원 </b> 철도 신분당선하고 포천-도봉 간 철도사업을 예비타당성조사를 면제함으로써 균형발전을 이끌어내겠다는 의지표명인 것 같은데…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 도청에서 말씀했던 거 얘기하시는군요.
</p>
<p><b>○ 김우석 위원 </b> 네, 그런 부분과 관련해서 어차피 균형발전 키워드를 끌고 온다면 그런 주제들도 선도적으로 역할을 해 주시는 게 어떻겠느냐라는 말씀을 드리고 싶고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그 부분 검토해서 별도 보고드리겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 업무보고서 10페이지에 보면 북부연구센터 이외희 센터장님이 연구책임을 갖고 있는 ‘경기북부의 오늘과 미래’ 이게 지금 어느 정도 진척이 되어 있나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 이거 지금 현재 진행 중인 연구고요. (관계직원을 향하여) 진행사항 말씀 좀 해 주시죠.
</p>
<p><b>○ 김우석 위원 </b> 제가 문건을 보다 보니까 올해 이번 달에 마무리가 되는 것 같은데 설명 좀 부탁드리겠습니다.
</p>
<p><b>○ 북부연구센터장 이외희 </b> 북부연구센터장 이외희입니다. 그 과제는 11월 15일이 과제완료가 되는 기간이고요. 한 2주 정도 오탈자 해서 12월 초나 중순경에 발행될 예정입니다.
</p>
<p><b>○ 김우석 위원 </b> 연구수행 기간이 어느 정도였죠?
</p>
<p><b>○ 북부연구센터장 이외희 </b> 3월 15일부터 해서 11월 15일까지 진행…….
</p>
<p><b>○ 김우석 위원 </b> 그 내용 좀 간단히 소개해 주실 수 있나요?
</p>
<p><b>○ 북부연구센터장 이외희 </b> 내용은 경기북부를 17개 시도랑 비교를 해서 각 부분별로 도시ㆍ교통ㆍ환경 한 11개 부분이 되겠습니다. 그렇게 해서 경기북부가 지금 어느 시도랑 비교했을 때 어느 정도의 위치에 있는지 그 현황을 살펴보는 것이 되겠습니다. 왜냐하면 계속 대선 때나 지방선거 때마다 분도 이야기가 나왔는데 저희 북부연구센터 차원에서 경기북부 지역이 어느 정도의 위상인지 그것을 살펴보고자 하는 그런 연구가 되겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 하여튼 북부권에 계시는 의원님들은 분도론에 대해서 충분한 근거자료가 될지 기대를 하시는 것 같더라고요.
</p>
<p><b>○ 북부연구센터장 이외희 </b> 그런데 그것은 하나의 현황을 살펴보는 잣대라고 보시면 되겠습니다. 그걸 기반으로 해서 분도에 완전히 직접적으로 연결되는 그런 과제는 아니고요. 그냥 북부지역을 전반적으로 한번 이해하자는 그런 차원의 전략과제가 되겠습니다.
</p>
<p><b>○ 김우석 위원 </b> 그런 전략과제의 시작점이 결국은 경기북부의 균형발전을 끌어내는 초석이 될 것 같다는 생각이 들고요. 앞으로 북부연구센터의 활발한 연구활동 기대해 보도록 하겠습니다. 저는 이것으로 질의 마치도록 하겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 감사합니다.
</p>
<p><b>○ 위원장 정대운 </b> 김우석 위원님 수고하셨습니다. 유광혁 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 유광혁 위원 </b> PPT 준비가 조금 안 된 것 같습니다.
</p>
<p><b>○ 위원장 정대운 </b> 그러면 자료요구하실 분들 얘기해 주시기 바랍니다, 자료요구. 자료요구 안 계시나요? 우리 위원님들 양해해 주시면 원활한 행정사무감사 진행과 중식으로 관련하여 연구원에 대한 감사를 중지하고자 하는데 이의 없으십니까? 없으세요, 오후에 진행할 건데?
</p>
<p><b>○ 유광혁 위원 </b> 잠깐 위원장님, 현재 자료가 돼 있나요? PPT…….
</p>
<p><b>○ 위원장 정대운 </b> 아직 준비 안 돼 있어요.
</p>
<p><b>○ 유광혁 위원 </b> 알겠어요.
</p>
<p><b>○ 위원장 정대운 </b> 그러면 중식을 위해서 14시까지 감사를 중지하겠습니다.
</p>
<p class=''ar''>(12시28분 감사중지)
</p>
<p class=''ar''>(13시59분 감사계속)
</p>
<p><b>○ 위원장 정대운 </b> 좌석을 정돈하여 주시기 바랍니다. 그러면 계속해서 경기연구원에 대하여 행정사무감사를 실시하겠습니다.
</p>
<p style="padding-left:1.2em">  질의하실 위원님, 유광혁 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 유광혁 위원 </b> (전문위원실 직원을 향하여) 자료 좀 띄워주세요.
</p>
<p><b>○ 위원장 정대운 </b> 우리 위원님들이 동의하시면 장시간 질의를 해야 되고 또 원장님이 저번에 보니까 다리가 조금 안 좋으신 것 같아. 앉아서 해도 되겠죠?
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  자리에 배석하십시오.
</p>
<p><b>○ 유광혁 위원 </b> 먼저 새롭게 부임하신 이한주 연구원장님과 우리 경기연구원 직원분들 많이 응원하고요. 앞으로 잘하시리라고 생각하고 있습니다. 또한 직업적 안정을 위해서 기간제근로자를 정규직 전환한 점에 있어서도 많이 응원을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  다만 이런 응원이 내부적인 데에서만 해서는 될 건 아닌 것 같고요. 경기도민 전체의 응원을 받아야 되는 상황인데, (전문위원실 직원을 향하여) 잠깐 자료를 한번 보여주시겠어요? 그러면 자료가 현재 준비가 안 됐다니까 우선은 편하게 말씀을 드리겠습니다.
</p>
<p style="padding-left:1.2em">  경기연구원 자유게시판을 한번 제가 살펴보다가 다음과 같은 어떤 사항을 보게 됐어요. 석사 연구원에 대한 어떤 채용의 건에 대한 문의가 있었는데요. 어떤 특정 연구원이 업무능력이나 스펙이나 그런 거 없이 현재 자리에 채용이 됐고 그리고 일대일이라는 매칭이라는 어떤 제도로 현재 석ㆍ박사 연구원들이 같이 업무를 진행한다고 합니다. 그래서 제가 자료요청을 일대일 매칭이라는 게 어떤 것인지 요구를 했는데 이걸 상세히 저한테 말씀을 안 해 주시고 자료도 준비를 안 해 주셨어요. 혹시 이거 준비하신 분이 답변하실 분 계십니까?
</p>
<p><b>○ 행정지원부장 이용원 </b> 행정지원부장 이용원입니다. 지금 현재 정규 연구진 박사 1인당 어떤 연구지원을 위해서 한 분씩 석사급 연구원을 이렇게 지원하고 있습니다.
</p>
<p><b>○ 유광혁 위원 </b> 그게 일대일 매칭이라는 거죠?
</p>
<p><b>○ 행정지원부장 이용원 </b> 네, 그런 의미입니다.
</p>
<p><b>○ 유광혁 위원 </b> 그러면 사실상 대학교나 이런 데에서도 석사ㆍ박사 혹은 박사와 교수님의 이런 매칭작업들이 많이 있잖아요. 그런데 이게 고스란히 연구원에서도 이런 방식이 취해진다면 사실 채용에 있어서는 어떤 유대관계가 있는 분들이 되기가 좀 유리하지 않겠어요? 그런 점은 어떻게 생각하십니까?
</p>
<p><b>○ 행정지원부장 이용원 </b> 저희가 채용을 할 때 2016년 말부터는 다 공개채용을 하고 있습니다. 하면서 서류전형이나 면접을 통해서 하고 있고 그렇기 때문에 이런 채용에 대해서는 그동안 경기도 감사나 감사원 감사도 많이 받아왔는데 그런 부분 특별히 이렇게 지적돼 있지는 않았는데 위원님이 말씀하신 그런 부분은 돌아가서 다시 한 번 검토를 해 보겠습니다.
</p>
<p><b>○ 유광혁 위원 </b> 그래요. 지금 현재 정부에서는 사실 채용비리 같은 것을 생활적폐로 인정을 하고 있고 저희 경기연구원이 그렇다고 생각하지 않지만 그래도 누구보다도 공정성 있게 가야 되는 부분이 필요한 것 같아요. 주신 자료 보니까 채용 공정성 관련 파악된 민원이 없다고 나왔어요. 왜 없는 것 같으세요? 민원을 어떻게 해소하고 할 수 있는 창구가 없어요, 지금. 그리고 현재 홈페이지에 있는 자유게시판 관리도 전혀 안 되고 있고 활성화가 돼 있지 않아요. 그러니까 이 점 역시 사실상 얼마나 취업예정자들이 많이 고민을 하고 취업에 있어서 걱정거리가 많겠어요. 그런데 저희 경기연구원 채용 건에 대해서는 이런 점이 많이 비껴 나갔으면 좋겠고요. 제가 비교를, 동 건 관련해서 서울연구원의 사례를 부탁했는데 사실 석사 연구원 건에 대해서는 같으나, 혹시 석사 연구원에 있어서 논문이나 이런 부분에 대해서 검토를 하고 참고를 하실 때가 있나요, 채용에 있어서?
</p>
<p><b>○ 행정지원부장 이용원 </b> 지금 현재까지는 없는데 무기계약직 이번에 정규직 전환과 관련해서 공개채용 절차가 있는데 그때에는 논문발표를 추가해서 우수한 직원이 채용될 수 있도록 노력할 예정입니다.
</p>
<p><b>○ 유광혁 위원 </b> 좋은 소식인 것 같고요. 서울연구원에서는 사실 건별로 현재 석사 연구원을 논문심사를 하고 있습니다, 현재. 그 점도 꼭 참고해 주셨으면 좋겠습니다.
</p>
<p><b>○ 행정지원부장 이용원 </b> 네, 알겠습니다.
</p>
<p><b>○ 유광혁 위원 </b> 그리고 우리 이한주 원장님, 지금 보시면 채용시험에 있어서는 원장님께서 축소할 수도 있고 나름 응용할 수 있는 부분이 있는 것 같아요, 지방 출자ㆍ출연기관 인사조직지침에 따라서. 이 점을 참고하셔서 채용에 있어서도 이걸 보완해 주셨으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 지금 위원님께서 말씀하신 내용들을 저희들이 충분히 명심해야 하고요. 다만 지금 정규직 전환과 관련하여 저희들이 좀 불분명한 내용들이 있어서 그 제도 보완을 하는 중이기 때문에 정규직 전환을 하면서 지금 말씀하신 내용들을 보완할 수 있도록 하겠습니다.
</p>
<p><b>○ 유광혁 위원 </b> 알겠습니다. 그러면 다음 질의를 하도록 하겠습니다. 경기 공공투자관리센터에 대해서 제가 질의를 몇 가지 하겠습니다. 항간에는 사실 이게 처음 시작할 때부터 행정 중복에 대한 지적이 있었습니다. 특히나 지자체 대형 재정투자사업은 정부에서 사전에 심의를 거쳤는데 굳이 경기도 행정 중복 지적이라는 표현에 있어서 공공투자관리센터가 있어야 되느냐 이런 것들이 있는데 이 점에 대해서 어떤 차별화나 대안을 갖고 계시는지요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 정부 공투센터에서 하는 건 규모가 저희들보다 큰 규모를 하고 있기 때문에 저희들은 작은 규모까지 하고 있어서 반드시 중복되는 건 아니라고 말씀드릴 수 있겠습니다, 저희는 작은 규모들까지 전부 다 들어가는 거라서. 지금 저희 공투센터에서 아직 본격적으로 공투사무를 못 보고 있는 이유 중의 하나는 공투소장님을 아직 모시지 못했고요. 그다음에 공투 매뉴얼을 충분히 확보를 정해놓지 않았습니다마는 일부에서 나오는 얘기는 1억 이상을 정하느니 10억 이상을 정하느니 이래서 정부에서 하는 예타나 공투 쪽보다는 아무래도 저희들이 촘촘해질 것 같아서 행정감사가 업무 중복을 최대한 피하면서 할 수 있도록 하겠습니다.
</p>
<p><b>○ 유광혁 위원 </b> 현재 방금 말씀하신 대로 소장님을 뽑지 못했잖아요. 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 몇 차례 노력을 했습니다마는 아직도 노력을 못 해서 이번에는 비장한 각오로 미리 관계기관에 다들 소문을 좀 내가면서 뽑을 수 있어서 이번 기회에는 확실히 뽑을 수 있을 거라고 생각하고요.
</p>
<p><b>○ 유광혁 위원 </b> 앞에서 한 얘기랑 상반적인 내용이기는 하지만 보도자료나 이런 걸 살펴보니 소장 자격요건이 현실감이 없다는 얘기도 있어요. 그 점 어떻게 생각하십니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그런 점도 있고요. 또 한 가지는 이 부분은 그냥 박사학위 소지자라고 아무나 될 수 있는 게 아니라 상당한 정도로 노하우와 경험이 축적된 사람이 필요해서 전국적으로 따지면 경기도 정도 되는 커다란 기 조직의 공투센터장으로 오실 수 있는 분이 전국적으로 따져서 몇 분 되시지 않습니다. 기관 이름을 들어선 안 되겠습니다마는 KDI에 있는 공투센터에 있는 멤버들, 서울에 있는 멤버들 정도인데 그분들이 저희가 공투센터장을 뽑을 때 정년이 60세 제한이 있습니다, 저희가 지금. 그래서 그분들이 거기서 충분히 급여를 받고 있기 때문에, 거기도 정년이 같고요. 그래서 그분들을 모시기가 좀 어려운 상황에 있어서 이번에 저희들이 규정을 좀 개정해서 그 공투센터 소장에 관해서는 정년을 조금 늘려놓고 뽑을까 싶어서 그런 생각 중입니다. 그러면 분명히 될 거라고 생각합니다.
</p>
<p><b>○ 유광혁 위원 </b> 네, 잘 알겠습니다. 그리고 이미 지나간 일이지만 사실상 공공투자관리센터의 위치가 과연 적절했느냐의 얘기도 많이 나와요. 이 점 또 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들 의견을 주시면 그거 반영하겠습니다. 제가 들어와서 보니까 공투센터에 관해서는 이해하기 어려울 정도로 독립성을 강조해 놓았고 조직으로부터도 그렇고 그다음에 예산으로부터도 모든 게, 심지어는 장소로부터도 독립을 해 놔서 저희들이 운영하기가 사실상 상당히 좀 어렵습니다. 그리고 장소도 그다지 넉넉한 장소가 아니고 해서 저희들 할 수만 있으면 경기연구원에 합쳐서 그렇게 운영하는 게 저희들로 봐서는 인력운영도 그렇고…….
</p>
<p><b>○ 유광혁 위원 </b> 현재 그렇게 구상을 하고 계십니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 저는 구상하고 있고 도청하고 협의 중인데 저희 공투센터 규정에 독립성의 해석이 장소, 모든 것으로부터의 독립성인 것처럼 해석하는 분위기가 그동안에 있었더라고요. 그러나 공투사업의 독립성으로만 해석을 좀 하면…….
</p>
<p><b>○ 유광혁 위원 </b> 네, 알겠습니다. 원장님, 이해됐고요. 시간이 거의 다 됐는데요. 저는 다른 건 없고 경기연구원이 지금까지 해 왔던 부분들을 잘 살펴보면, 사실 요즘 경기북부에 대한 연구나 연구조사 결과에 보면 흡족한 부분도 있고 사실 어제 균형발전기획실에 대한 감사를 했는데 그 건에 대한 어떤 조사자료나 그런 것들이 충분히 도움이 많이 됐어요. 그 점에 대해서는 진짜 많이 칭찬해 주고 싶고요. 앞으로 좀 더 노력을 하셔 가지고 연구원에 있어서 대한민국 최고의 연구원이 됐으면 좋겠습니다. 열심히 하십시오. 이상입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 배전의 노력을 하겠습니다.
</p>
<p style="padding-left:2.4em">    (정대운 위원장, 박관열 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 박관열 </b> 유광혁 위원님 수고하셨습니다. 그럼 다음 질의하실 위원님께서는 거수로 신청해 주시기 바랍니다. 신정현 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 신정현 위원 </b> 고양 출신의 신정현 위원입니다. 먼저 경기연구원, 제가 이렇게 표현을 하겠습니다. “베일에 싸인 기관” 먼저 여기 앉아계신 분들 중에 행정감사 자료요청받는 담당자 누구시죠? 잠깐 앞으로 나와 보세요.
</p>
<p style="padding-left:1.2em">  공공투자관리센터 내에 배치된 책상 사이즈를 좀 말씀해 주십시오.
</p>
<p><b>○ 행정지원부장 이용원 </b> 죄송합니다. 지금 정확히 기억은 안 나지만 대략적으로 2.5m에서 이렇게 개인이 사용…….
</p>
<p><b>○ 신정현 위원 </b> 들어가세요. 제가 경기연구원에 연락을 해서 책상 사이즈를 여쭤봤습니다. 행감에 필요해서 당연히 물어본 것이었죠. 담당자는 자기가 행감에서 대답할 위치가 아니므로 말하지 못하겠다, 현장에 있는 사람에게 물어보라고 하더라고요. 행감의 대상이 이곳에 있는 분들로 한정됐습니까? 위원이 물어보면 그 답변을 특정인에게만 하도록 내부적으로 합의를 했나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 아닙니다. 그런 사실 전혀 없고요.
</p>
<p><b>○ 신정현 위원 </b> 매우 불쾌합니다. 뭔가 베일에 싸여 있다라는 건 비단 이것만의 문제가 아니에요. 지금 우리 위원회에서 요청했던 상당히 많은 자료들이 그 내용에 충분히 질문에 대해서 답변된 피드백들이 거의 없습니다. 차차 제가 설명을 드릴 텐데요. 이러한 것들이 바로 베일에 싸인 기관, 도무지 그 내용 속을 들여다볼 수 없는 경기연구원이란 인식을 낳게 만드는 겁니다. 자, 이해됐죠?
</p>
<p style="padding-left:1.2em">  먼저 첫 번째로 여쭤보겠습니다. 경기연구원 총 연구실적 대비 정책반영 건수를 제가 데이터로 만들어 봤습니다. 어떤가요? 2016년 57%, 2017년 46%, 2018년 9월 말까지 44%입니다. 우리 이한주 원장님께 묻습니다. 전체 데이터 중에서 정책 반영된 건수, 적절하다고 보십니까? 원장님, 마이크 눌러주시고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 경우에 따라 좀 다른데요, 기본과제로 불리어지는 것들은 사회적 담론과 관련된 과제들이고요. 관점에 따라 다른데 전 충분히 열심히 하고 있다라고 생각했습니다.
</p>
<p><b>○ 신정현 위원 </b> 아마 저 데이터를 처음 보셨을 겁니다, 정책 반영된 퍼센티지가 얼마나 됐을까.
</p>
<p><b>○ 경기연구원장 이한주 </b> 건수로는 저희들이 알고 있습니다.
</p>
<p><b>○ 신정현 위원 </b> 처음 보셨죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 그 데이터가 없더라고요. 그래서 제가 직접 만들어 본 것이고요. 비슷한 규모의 서울시 기관은 최근 몇 년간의 데이터를 취합했을 때 70%~74%의 정책반영률을 보입니다. 그런데 경기도는 이에 한참 미치지 못하는 것이 사실이죠. 저는 매년마다 예산을 올려 달라고, 조직을 더 키워 달라고 하면서 정작 정책반영의 실적이 이토록 낮은 것에 대해서 매우 유감을 표합니다. 혹시 답변하실 게 있으실까요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 국책연구기관하고 비교했을 때 저 수치는 절대로 낮은 수치는 아닙니다.
</p>
<p><b>○ 신정현 위원 </b> 서울시랑 제가 비교했죠? 서울연구원입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 서울시하고 제가 비교는 안 했습니다마는 저희들이 기본연구과제는 담론적인 과제이기 때문에, 저건 정책과 관계없이 내부…….
</p>
<p><b>○ 신정현 위원 </b> 아니, 그 세부적인 내용을 말씀드리는 게 아니고요. 다 합쳐서 제가 정책반영 건수의 퍼센티지만 절대비교 했잖아요. 그 내용 일일이 설명하실 필요 없습니다. 충분하다고 생각하십니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 더 높이도록 노력은 하겠습니다마는 내용을 좀 들여다보고 판단을 하겠습니다.
</p>
<p><b>○ 신정현 위원 </b> 네, 내용 한번 들여다보시고요. 제가 봤을 때는 연구원 자체적으로 진작에 연구되어지고 조사되어졌어야 될 거라고 보는데 이것에 대한 데이터를 본 위원이 직접 하게끔 한 것도 저는 연구원의 역할을 충분히 못 하고 있다라는 점으로 돌려 말씀드리고 싶습니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  다음 넘어가겠습니다. 앞서서 말씀하셨던 소장 채용논란에 대해서 잠깐 언급하고 넘어가겠습니다. 지금 보시는 저 응시자격사항, 정말로 저 정도 되는 사람이 나타날 거라고 생각하십니까, 소장으로?
</p>
<p><b>○ 경기연구원장 이한주 </b> 와서 즉시 저거 교체, 소장 자격 바꾸는 중입니다, 지금.
</p>
<p><b>○ 신정현 위원 </b> 더 낮춰주려고 하시는 겁니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 저는 다른 방법을 좀 제안드리려고 이 부분을 지금 한 번 더 언급하는 겁니다. 왜 내부적으로 소장이 될 방법은 없습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그것도 새로운 안에 집어넣었습니다.
</p>
<p><b>○ 신정현 위원 </b> 저는 그게 반드시 필요하다고 봅니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다.
</p>
<p><b>○ 신정현 위원 </b> 그 이유를 말씀드릴게요. 서울시는요, 부연구위원에서 연구위원으로 가는 과정이 4년여간 걸립니다. 연구위원이 돼서 한참의 시간을 해당 연구활동을 해야지만 소장과 같은 급에 갈 수가 있어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다.
</p>
<p><b>○ 신정현 위원 </b> 그런데 지금 우리가 그렇게 했던 사례가 이전에 있나요? 현직에 있던 위원이 연구위원급으로 올라가서 소장 혹은 센터장급으로 가는 사례가 있었나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구원이 연구위원으로 올라가는 건 그동안에 연구위원은 정규직이었고 연구원은 비정규직으로 뽑았기 때문에 현재로서는…….
</p>
<p><b>○ 신정현 위원 </b> 아니요, 그건 상관없고요. 일하시던 분이 직접 올라가시는…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구원이 연구위원으로?
</p>
<p><b>○ 신정현 위원 </b> 연구위원이 센터장, 소장으로.
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구위원에서는 연구위원 나급, 가급이 있어서 올라가면서 보직이 가능하도록 되어 있습니다.
</p>
<p><b>○ 신정현 위원 </b> 이것도 고려하신단 말씀이시잖아요, 내부적으로?
</p>
<p><b>○ 경기연구원장 이한주 </b> 이미 안을 만들어서 도에 올렸습니다.
</p>
<p><b>○ 신정현 위원 </b> 내부적인 연구위원을 통해서?
</p>
<p><b>○ 경기연구원장 이한주 </b> 두 가지가 다 가능하도록 해 가지고.
</p>
<p><b>○ 신정현 위원 </b> 저는 그게 배제되지 않아야 된다고 생각을 하고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다.
</p>
<p><b>○ 신정현 위원 </b> 그렇게 해야지만 또 된다고 봅니다. 지금 시간이 너무 없어서, 영상 이거 한번 보여드리고 갈게요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  이게 바로 더불어민주당 당사에 위치한 바로 우리 공투센터입니다. 누가 봐도 공투센터가 여기에 있으면 더불어민주당의 산하기관처럼 오해되지 않을까요? 저는 이거 보면서 아니, 그 수없이 많은 공간들이 그토록 많은데 “오얏나무 아래 갓끈 고쳐 매지 말라.”는 얘기도 있는데 왜 하필이면 경기연구원, 우리 원장님 특히나 우리 도지사랑 측근이라는 오해와 불명예를 자꾸만 듣는 상황에서 왜 이런 선택을 하셨습니까? 저는 이해가 되지 않습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 장소가 저기에 있는 것도 문제고 또 한 가지는 업무를 서로 보기가 굉장히 불편해서 저희 경기연구원에 있으면 불필요한 행정직을 줄일 수가 있기 때문에 합칠 수 있도록 위원 여러분께서 도와주시죠.
</p>
<p><b>○ 신정현 위원 </b> 네, 노력해 주시고요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  다음 하나씩 하나씩 보여드리면 여기가 바로 여러분들 일하시는 곳이죠? 여기 박사님들, 그렇죠? 왜 다 처음 보시는 것처럼 놀라십니까? 여러분들 일하시는 곳 사진 찍어 가지고 왔는데. 자, 여기는 어디입니까? 공투센터입니다. 제가 사이즈 물어봤죠? 이거는 공투센터의 중요성을 그토록 강조하시는 분들이 정작 연구하는 연구원분들의 처우를 이렇게 할 수 있는가에 대한 문제제기를 해 드리는 겁니다. 제대로 된 연구활동이 가능할 수 있도록 내부적인 시설도 함께 참고하셔서 신경 쓰시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 연구원 장애인 채용공고에 대한 이야기인데요. 여러분 아시겠지만 우리 경기연구원은 현재 장애인 채용 미달이 됐죠? 알고 계신가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 1명 미달됐습니다.
</p>
<p><b>○ 신정현 위원 </b> 네, 미달된 상황이죠. 같은 사이즈의 서울연구원은 3.2% 이상으로 맞춰서 일을 하고 있습니다. 이러한 부분들에 대해서는 단순히 “열심히 하겠다.” 이렇게 해서는 안 될 것 같습니다. 충분히 최선을 다해서 이 부분 채울 수 있도록 노력해 주셨으면 좋겠습니다. 지금 이걸 보여드린 이유는 같은 채용공고인데도요, 이렇게 연구원 채용공고에 장애인을 직접 올리면서 거기에 해당되는 장애인들에게 충분히 홍보할 수 있는 최선의 노력을 다한다고 하는데 우리는 기타 다른 홍보의 노력들을 하고 있는지도 좀 여쭤보고 싶습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 채용공고 시 저희들이 가점 주는 것들을 거기 표시해서…….
</p>
<p><b>○ 신정현 위원 </b> 가점은 다 주고 있는데요, 홍보의 노력들을 말씀드리는 겁니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 정말 시간이 없네요. 계획 대비 추진실적 총괄입니다. 계획은 이렇게 해 놨는데 실제로 우리가 진행하고 완료까지 다 끝마쳐도 전체적으로 83%밖에 되지 않아요. 사업계획을 이렇게 세워놓고서 결과적으로는 정책 현안분석을 제외한 연구과제는 토털 66%밖에 되지 않습니다. 왜 이렇게 계획을 세워놓고 그 계획에 미달되는 결과물을 만드십니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 대부분의 결과가 연말에 끝나도록 작성되어 있습니다. 그래서 연말이 되면 전부 다, 대부분 다 완성됩니다.
</p>
<p><b>○ 신정현 위원 </b> 지금 그 건이 바로 진행과 완료예요, 원장님. 그래서 완료가 되면 끝나는 거고요, 진행은 연말 되면 되는 것까지 다 합친 겁니다. 더해 준 겁니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 아니, 그게 아니고요. 착수가 되어지는 것들이, 저게 9월 말 현재 착수 건이거든요. 그 뒤로도 착수되는 게 있어서 대부분 다 계획대로 완료가 됩니다, 그 부분들은.
</p>
<p><b>○ 신정현 위원 </b> 계획대로 완료가 된다고요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다. 저희들이 점검을, 이걸 보낼 때 9월 말 기준으로 작성하고 나머지 건들에 대해서는…….
</p>
<p><b>○ 신정현 위원 </b> 2016년, 17년 계획 대비 건수를 저한테 다 보고를 해 주세요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다.
</p>
<p><b>○ 신정현 위원 </b> 시간이 없어서 이따 추가질의 때 추가로 말씀을 드리도록 하겠습니다. 위원장님, 여기까지 하겠습니다.
</p>
<p><b>○ 부위원장 박관열 </b> 신정현 위원님 수고하셨습니다. 그러면 다음 질문은 임채철 위원님께서 해 주시기 바랍니다.
</p>
<p><b>○ 임채철 위원 </b> 안녕하십니까? 임채철입니다. 저는 보니까 경기연구원이요, 자료는 조금 이따가 말씀을 드릴게요. 경기연구원이 자료를 보다 보니까 다른 기관에 비해서 미집행액이 굉장히 많아요, 평상시에 결산을 할 때마다. 가장 적었을 때가 10%, 많을 때는 15%, 어쩔 때는 한, 올해 같은 경우도 보니까 지금 제 예상으로는 한 20%까지도 될 수 있겠다 싶은 예상이던데요. 그러니까 미집행이 굉장히 많은 거 보면 예산을 너무 방만하게 수립을 하고 사용했다는 건데 혹시 거기에 대해서 어떻게 의견 좀 있으신가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 미집행액에는 두 가지 정도의 이유가 있습니다. 한 가지는 그동안에 인원 충원을 안 해 왔던 경향이 좀 있었습니다. 박사급 정원이 61명인데 52명, 53명에서 충원을 해서 인건비 미집행 금액이 조금 있었고요. 또 한 가지는 말씀하신 대로 초기에 저희들이 연구실적을 매우 강한 수준에서 요구를 하니까 해 놓고 실제로 연구비 연구 집행을 조금 덜 하는 경우들이 좀 있었고요. 연구 집행이 좀 덜 된다고 하는 것들은 원래 연구비 계획에는 실제로 현장을 방문하고 조사를 좀 더 하고 해외를 나가 보고 이러고 연구를 해야 되는데 실적이 좀 바쁘다 보니까 그 부분들을 좀 생략하고 하면서 조사ㆍ연구가 조금 덜 됐던 경우들이 있었고 이런 경우들이 합쳐져서 연구비 미집행이 좀 되어 있습니다. 다만 말씀하신 대로 연구비 미집행은 그 차기연도로 이월이 되기 때문에 언젠가 한 번 정리가 좀 돼야 되는데 거의 비슷한 금액이 계속 차기연도로 이월되고 있거든요. 그 얘기는 당해연도에 해당되는 예산은 대부분 쓰는데 이월돼서 넘어오는 금액들이 계속 이월되는 경향이 있어서 이 부분들에 대해서는 한번 정리가 좀 필요하다라고 생각하고 있었습니다.
</p>
<p><b>○ 임채철 위원 </b> 만약에 미사용된 금액 같은 경우에는 원래는 이월만 시키는 게 맞는 건 아니죠? 최종 잉여금의 경우에.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희는 이월해서 사용하고 있었습니다, 그 부분들이.
</p>
<p><b>○ 임채철 위원 </b> 그러니까 원래 이월손실이 있으면 거기 보전에 먼저 쓰고, 손실이 없었을 테니까 다음연도에 이월을 하거나 아니면 기금에 전입하거나.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그런데 저희들이 예산이 좀 부족했기 때문에 인건비 중에 일부분 30% 정도는 저희 기관에서 벌어서 써야 되는 상황입니다, 지금. 전체가 다 출연되는 게 아니기 때문에. 그래서 인건비 부족분에 관해서는 저희들이 기금에서 일부를 넘겨와서, 도에서 물론 허가를 받고요, 사용을 조금 하고 있었고 또 이월을 받아서 사용하고 있었습니다.
</p>
<p><b>○ 임채철 위원 </b> 약간 좀 제가 맞는지 모르겠는데 잉여금이 있어요, 그런데 기금에서 전입할 이유는 또 뭔가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 예산을 짤 때 인건비 전액이 아니라 그 일부를 저희가 벌어서 쓰도록 예산이 짜여져 있습니다. 그렇기 때문에 저희들이 기금을 조금 가져오고 저희들이 또 조금 벌고 이렇게 하는 상황이고 그러다 보니까 이월된 금액을 자연히 또 넘겨받아서 쓰고 이렇게 돼 있었는데 해마다 거의 비슷한 금액이에요. 위원님 말씀하셨습니다만 분모가 달라짐에 따라서 10~14% 혹은 15% 이렇게 변해 왔던데요, 몇 년 사이에. 그게 이월돼 있었습니다. 특히 연구비 부분이 그래왔는데 그 부분들에 관해서는 해마다 플로는 맞춰져 있었는데 보니까 한 번 정리는 반드시 필요한 상황이라고 생각합니다.
</p>
<p><b>○ 임채철 위원 </b> 그러니까 예산액 미집행액이 한 10% 정도 미만으로 적정하게 남는다 그러면 뭐 사람이 100% 정확하게 예측할 수는 없는 거니까요, 그건 이해가 가는데요. 어쨌거나 미집행이 많다는 건 예산을 좀 방만하게 수립하고 집행한 경향이 있지 않나 이런 생각이 들고요. 저희가 지금 보시면 2010년도부터 기금에서 전용해서 사용을 하고 있어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알고 있습니다.
</p>
<p><b>○ 임채철 위원 </b> 원래 출연을 하고 나서 2004년도까지 출연기록이 있더라고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다.
</p>
<p><b>○ 임채철 위원 </b> 경기도에서 처음에 기금출연을 했어요. 기금출연을 했는데 원래 보면 저희가 가용재원이 도의 출연금, 그러니까 정관에 보니까, 저게 정관 내용입니다. 연구원의 운영에 필요한 재원은 경기도의 출연금, 기금의 수입, 수탁사업의 수익에 따른 수입, 출판물 판매대금이 그 밖의 수입으로 돼 있어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 임채철 위원 </b> 기금 원본을 사용하는 게 정관에 맞는 사항인가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 조례에는 그 상황이 정해져 있지 않은데요. 저희 정관에서는 기금의 감액사용에 관한 규정이 저희들이 있습니다.
</p>
<p><b>○ 임채철 위원 </b> 그러면 조례를 좀 보시면 도의 출연금액에서 기금의 과실수입이라고 돼 있어요. 그러면 정관이 우선이에요, 조례가 우선이에요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 조례가 우선입니다. 그러나 조례 운영규정에 보면 조례 운영규정에는 저희 정관에 의뢰하도록, 정관에 위임하도록 되어 있어서요. 조례 9조 운영규정에 보면 “연구원의 운영에 관하여 필요한 사항은 조례 및 규칙과 정관이 정하는 범위 안에서 이사회의 의결을 거쳐 정한다.” 이렇게 돼 있어서…….
</p>
<p><b>○ 임채철 위원 </b> 그러면 기금을 사용한 관련 규정이라고 주신 거 보니까 경기연구원 정관 6조 기금에 “3. 기금의 원본을 감소하고자 할 때에는 이사회의 의결을 거쳐 경기도지사의 허가를 받아야 한다.” 이렇게 되어 있죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 임채철 위원 </b> 이게 “운영 경비로 쓸 수 있다.”는 규정으로 지금 해석을 하신 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 그렇게 해석해 왔습니다.
</p>
<p><b>○ 임채철 위원 </b> “원본의 감소를 허가받아야 된다.”고 되어 있는데 지금 운영재원으로 쓸 수 있다는 규정은 아니잖아요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 조례 운영규정 중에서 정관에 위임해 놓은 사항을 준용해서 그렇게 써 왔습니다.
</p>
<p><b>○ 임채철 위원 </b> 그러니까 이건 해석상의 문제인 것 같아요. 저희가 처음에, 이거 설립 언제 했죠, 경기연구원이요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 1995년.
</p>
<p><b>○ 임채철 위원 </b> 95년도부터 2010년도까지 기금을 사용한 적이 없어요, 원본을. 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 임채철 위원 </b> 2010년도에 해석을 어떻게 하신 것 같아요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그런 것 같습니다.
</p>
<p><b>○ 임채철 위원 </b> 이 정관의 개정사항을 보니까 95년도부터 개정되지가, 이 규정에 대한 건 개정된 사항이 아니에요. 설립 때부터 이 규정은 변동이 없었죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 임채철 위원 </b> 정관의 변경이 없었어요. 그러니까 원래 불법적인 거예요. 2010년도에 아마 경기도 재정이 굉장히 열악했었나 봐요. 열악하니까 줄 돈은 없고 이걸 어떻게 좀 사용은 하고 싶은 거죠. 원래는 이자만 가지고 쓰고 나머지는 출연금으로 썼어야 맞는 겁니다. 그런데 이제 보니까 관련 정관의 규정에 이 규정이 있는 거예요. 이 규정을 가지고 “그래, 감소하고자 할 때 이사회의 의결을 거쳐서 허가만 받으면 되니까 이렇게 해서 사용을 하자.” 했던 것 같아요. 맞습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 경기도, 제가 위원장께서 말씀하신 내용을 여러 가지 하면서 점검을 해 보았더니 직원들 얘기로는 당시 경기도에서 재정이 좀 부족하니까 경기도에서 권장사항 얘기도 했다고 그럽니다. “돈을 조금밖에 못 주니까 원본 중에서 일부를 쓸 수밖에 없다.”라고 하는 얘기들이 좀 있었고 그래서 그 뒤부터는 그 규정을 준용해서 사용했다고 합니다.
</p>
<p><b>○ 임채철 위원 </b> 그런데 잘못된 해석이죠. 잘못된 해석이고 원래 조례를 개정했었어야 되죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 임채철 위원 </b> 맞죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 앞으로 그 문제에 관해서 정합되도록 정리를 하도록 하겠습니다.
</p>
<p><b>○ 임채철 위원 </b> 아니, 그것도 그렇지만 누군가는 책임을 져야 될 문제라고 저는 생각을 하는 거예요. 이게 경기도의 돈, 기금, 결과적으로 아까 전에 제가 처음에 미집행액 얘기를 했던 게 뭐냐 하면 ‘예산은 받을 수 있을 만큼 받고 모자라면 기금에서 빼서 쓰지, 그것도 이사회 결의로.’ 이렇게 된 거예요, 지금. 그러다 보니까 매년 일단 쓸 돈 채워놓고 쓰다가 남으면 내년에 넘겨버리지, 그리고 또 기금으로 다시 넣자니 문제가 나중에 다시 빼서 쓰긴 또 어려울 것 같고 하니까 계속적으로 이런 문제가 반복돼 왔던 것 같아요.
</p>
<p style="padding-left:1.2em">  그래서 이 부분에 대한 것은 단순하게 뭐 앞으로 잘 하자의 문제는 아닌 것 같고요. 의회 차원에서도 한번 이 문제의 원인을 파악할 필요가 있지 않나 이런 생각이 있습니다. 이상입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 기꺼이 응하겠습니다.
</p>
<p><b>○ 부위원장 박관열 </b> 임채철 위원님 수고하셨습니다. 다음은 민경선 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 민경선 위원 </b> 고양의 민경선 위원입니다. 원장님, 오신 지 지금 며칠 되셨습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 제가 9월 10일 날…….
</p>
<p><b>○ 민경선 위원 </b> 그럼 한 달 좀 넘으셨나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 한 달 좀 넘었습니다.
</p>
<p><b>○ 민경선 위원 </b> 저기 좀 불편하실 텐데 뒤에 제가 파워포인트로 준비했습니다. 간간이 보시면서 해야 될 것 같습니다.
</p>
<p style="padding-left:1.2em">  경기연구원에서 연구결과를 가지고 이게 도정과 관련된, 시행된 정책이나 사업을 요구해서 받은 자료에 의하면요, 2016년에는 199건이 반영됐고 2017년에는 193건, 2018년에는 9월 30일 기준으로 107건이 반영됐습니다. 엄청난 숫자이거든요. 이건 결국, 그리고 그 밑에 보시면 다른 내용과 달리 또 도 정책기조의 변화 및 개발과 도정현안 해결지원 부분은 상당히 많은 자료가 돼 있습니다. 그만큼 도지사의 정책기조나 도정에 이슈 되는 부분에 대한 해결을 지원하는 역할을 경기연구원이 하고 있는 것이죠. 맞습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇다고 생각합니다.
</p>
<p><b>○ 민경선 위원 </b> 그래서 경기연의 연구가 도정에 지대한 영향력을 발휘하고 있고 그 용역보고서가 밑바탕이 돼서 정책이 이끌어지고 있다는 것입니다. 그만큼 중요하고 그 역할이 배 되는데요. 보시는 바와 같이 단체장의 역점사업은 되도록이면 이게 졸속 추진되는 경향이 있습니다. 그러니까 민주당 단체장이라서 그런 게 아니고 또 자유한국당 단체장이라서 그런 게 아니라 단체장은 임기 내, 4년 내 뭔가 실적을 남기기 위해서 그 당위성을 확보하기 위해서, 억지 당위성을 만들기 위해서 실제 경기연구원을 활용하는 경우가 있습니다. 그리고 절차적인 민주주의를 무시하는 경향, 조급증 때문에. 그리고 핵심사업을 통해서 측근인사를 함과 함께 측근비리가 다른 광역자치단체에서도 나온 바가 있습니다. 그리고 또 하나의 문제는 전 단체장이 수행했던 성공사업에 대해서 되도록이면 기본을 유지하거나 축소하거나 일몰제로 폐지하려는 경향이 있습니다. 왜냐하면 예산이 투여되는 만큼 새로운 신임 단체장한테 공이 돌아가야 되는데 계속 그 사업을 하게 되면 전임 단체장한테 공이 돌아가기 때문에 축소하는 경향이 있는 겁니다. 그런 의미에서 경기연구원이 단체장의 입맛이 아닌 도민의 입장에서 정책과제를 수행해야 된다고 보는데 이에 대해서 입장이 어떠십니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 지당하신 말씀이라고 생각하고요. 억지로 하거나 측근인사 하거나 그다음에 절차적으로 단축을 하는 건 옳지 못하다고 당연히 생각하고요. 다만 도민과 단체장 사이의 관계에 대해서는 위원님 말씀을 인정하면서도 주권자 도민이 선택한 사람이기 때문에 직접적인 도민의 의견을 일일이 들을 수 없는 상황 속에서는 한편으로는 도의회의 의견을 듣고 다른 한편에서는 도청 도지사의 의견을 듣는 게 마땅하다고 생각합니다.
</p>
<p><b>○ 민경선 위원 </b> 알겠습니다, 원장님. 그러니까 제가 도민을 무시하고 단체장의 의견을 무시하라는 게 아니라 정확한 데이터를 가지고 정확한 분석을 내려야 된다는 입장인 것이죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 지당합니다.
</p>
<p><b>○ 민경선 위원 </b> 그래서 제가 제안드립니다. 이것은 헌법재판소 판례입니다. 판례를 보면 이게 위헌이 되든 합헌이 되든 일부합헌이 되든 보면 정책결정에 대해서 구체적으로 적극설, 적극적인 입장, 소극적인 입장 그리고 각 재판관에 대한 의견들이 다 담아져 있어요. 그래서 저는 어떤 정책결정을 할 때 그 주제에 대해서는 도민이 공감을 하지만 그것을 실천하는 데 있어서의 시기나 여러 가지 보완관계에 대해서 정말 면밀하게 따질 필요가 있는데 그렇지 못한 경우가 많습니다. 그래서 제가 요청하는 것은 뭐냐 하면 연구원 과제를 수행할 때 ‘갑.을’설을 수록하는 것을 의무화했으면 좋겠습니다. 다수의 의견과 소수의 의견을 공정하게 반영하는 그러니까 정책과제 중에서 단순한 정책과제도 있지만 중심적인 정책과제를 수행할 때는 반드시 ‘갑.을’설을 수록하게 돼서, 왜냐하면 이게 반대의견도 있고 또 보완의견도 있을 수 있습니다. 그걸 통해서 정책을 수행하고 또 의회는 견제하는 입장인데 정확하게 인지하고 그것을 정책에 반영하고 보완하는 개념으로 갈 수 있도록 하고 싶습니다. 그 이유는 보시는 것 같이 정책혼선을 방지할 수 있고 혈세의 낭비를 해소할 수 있습니다. 그다음에 시행착오를 감소시킬 수 있습니다. 원장님, 잘 아시지만 4대강 문제 얼마나 심각합니까? 막대한 30조에 이르는 예산이 투입되고 잘못됐다고 해서 되돌릴 수 없는 것이죠. 그렇기 때문에 이에 대해서는 원장님의 역할이 중요한데 이 부분을 적극 반영해 주셨으면 하는 바람입니다. 이에 대해서 말씀 좀 해 주십시오.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님들과 그다음에 도지사의 이야기를 마음에는 두겠지만 머릿속으로는 냉정하고 객관적으로 연구결과가 될 수 있도록 노력하겠습니다. 말씀하신 내용 100% 공감하고 그렇게 할 수 있도록 노력하겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 그래서 제안드리면 2018년 연구과제가 지금 현재 118개가 수행 중인데 그중에 완료된 걸 제외한 72개 과제가 있는데 여기서도 일부 단순한 과제들이 있을 겁니다. 그 외에는 이 ‘갑.을’설을 수록할 수 있는 것을 반영했으면 좋겠다는 생각입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> ‘갑.을’설 그다음에 긍정ㆍ부정, 작용ㆍ부작용 이런 형태로 다양한 스펙트럼을 가지고 연구결과를 제시해 달라는 말씀으로 알겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 네, 그렇습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇게 노력하겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 고맙습니다. 수용을 해 주시니까 감사합니다. 원장님, 대안제시 한번 해 드리겠는데요. 아까 말씀드렸듯이 예산비중이 큰 주요사업에 대해서 그동안에 반대의견을 냈던 연구위원을 연구에서 배제시키고 연구과제를 수행하지 못하게 한 경우도 있었습니다, 과거에 경기연구원이. 그래서 아까 말씀한 소수의견을 담을 수 있는 풍토를 원장님이 기틀을 마련해 주시고요. 또 그다음에 이렇게 소수의견이나 반대의견을 냈을 때 인사상 불이익을 차단해 주시고 연구원의 소신과 철학이 보장되는 연구원 시스템을 구축해 주시기 바랍니다. 그렇기 위해서는 그동안에 연구원 발전방안에 대한 주제로 다른 기관에 대한 발전방안은 수행을 많이 했는데, 수탁이나 여러 가지 정책과제를 수행 많이 했는데 연구원 자체에 대해서는 어떻게 발전시킬지 발전방안에 대해서 연구한 자료를 요구했더니 한 건이 없더라고요. 그래서 이번 기회에 새로 부임하셨기 때문에 연구원을 발전시킬 수 있는 방안에 대한 연구용역을 수행해 줬으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 이 연구원 발전방안에 대한 것은 지금도 저희들이 팀이 돼서 준비를 하고 있는데 이것들을 별도의 연구과제를 수행하지는 않고 내부 팀을 가지고 매주 이 부분들은 지금 하고 있고요. 조만간에 결과가 나올 거라고 생각합니다.
</p>
<p><b>○ 민경선 위원 </b> 그러니까 제가 요구하는 건 그렇게 내부적인 논의도 있지만 객관적인 것에 근거해서 선진사례나 기타 다른 기관에서의 수행하는 부분을 하자는 것이죠. 그리고 만약에 자체에서는 좀 어렵겠다라고 하면 외부의, 오히려 자체에서는 이것이 수용되기 어렵고 여러 가지 자체에서 자기들이 부정하는 부분이 쉽지 않으니까 외부에 연구용역을 내는 방법도 있지 않겠습니까? 그 부분을 검토해 주시라는 겁니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 당연히 검토하겠고요. 한 가지 참고로 말씀드리면 경기도청에서 이번에 조직진단을 실시한 대형 프로젝트를 준비 중에 있습니다. 곧 발주를 하게 될 텐데 그때 24개 산하기관에 대해서도 전체 다 이루어지기 때문에 저희들이 그 결과를 받아들이는 것도 하겠다 하는 말씀을 드리겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 알겠습니다. 긍정적으로 답변해 주신 우리 원장님 감사드리고요. 다음 질의 이어가겠습니다.
</p>
<p style="padding-left:1.2em">  최근 받은 자료 제가 분석해 보니까 최근 3년간 연구실적이 1,008건에 이릅니다. 좀 차이가 날 수 있는데 받은 자료에 의하면 그렇습니다. 그래서 제가 분석을 해 봤습니다. 그랬더니 직급별로 연구성과를 보니까 최근 3년간 가급 선임연구위원은 평균 15건, 선임연구원 나급은 17건, 연구위원 가급은 19건, 나급 연구위원은 22건으로 과제를 수행하는데 직급이 낮을수록 수행 수가 많습니다. 여기에는 부원장을 비롯해서 실장님이나 부장님 것은 빼고 한 겁니다. 그래서 이 부분은 좀 과제의 중요도에 따라서, 이건 양적으로 평가했기 때문에 실제 정성적 평가나 질적인 부분은 제가 알 수가 없기 때문에 그것은 나름대로 분석을 해 주셨으면 좋겠고요. 이 부분에 대한 연구과제가 특정연구위원과 직급에 몰리지 않도록 균형감 있는 연구원을 운영했으면 좋겠다는 생각입니다. 그 원인은 뭐 여러 가지가 있겠지만 실제 경영평가가 그동안에 2017년까지는 예를 들면 계량적 평가가 주를 이뤘는데 정성적 평가도 포함됐는데, 지금도 계량적 평가를 계속하고 있어서 전년 대비 15% 이상이 돼야 100점을 맞을 수 있습니다. 그래서 이러한 개량적 지표에 대한 부담감이 큰 걸로 알고 있습니다. 그래서 이 부분에 대한 원장님의 개선점을 또 경영평가에 대해서도 정성적 평가가 들어갈 수 있도록 상부에 건의를 했으면 좋겠다는 생각입니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  시간이 없는데 보시는 거와 같이 연구과제가 4차 산업혁명만 봐도 38건입니다. 남북교류협력은 33건, 노인정책 등 15건, 많이 있는데 제가 보기에는 이 과제들을 일일이 설명드릴 수 없지만 한 과제를 2개, 3개 정도로 쪼개서 연구한 과제들이 너무 많더라는 것이죠. 그러니까 양적 연구과제를 늘리기 위한 계량적 평가 때문에 이런 게 관행이 되지 않는가 하는 우려가 있습니다. 이에 대해서 원장님의 답변을 듣고 추가질의 때 질의하도록 하겠습니다. 이상입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 대체로 인정하는 사실입니다. 연구과제 쪼개기 정도는 아니지만 매년 15%를 증량해서 평가를 하기 때문에 여기에 맞추다 보니까 1인당 과제 수가 늘어났고 1인당 과제 수가 아무래도 젊은 분들한테 조금 더 부하가 많이 걸렸던 것도 사실이고요. 또 그러다 보니까 연구내용이 경량화되어지는 경향이 있는 것도 사실이었습니다. 쉽게 얘기한다면 임팩트가 적어지고 그다음에 분량도 적어지고 이런 경향이 있어서 이 문제에 대해서는 이미 지난달에 도하고 협의를 했는데 도 입장에서는 내년에는 15% 늘어야 되는 건 어쩔 도리가 없고 후년도부터 이것에 대해서 평가를 해 보겠다라고 하는 지표 재조정안을 저희들이 요청했고 3회에 걸쳐서 조정안을 얘기했습니다마는 차년도에는 다른 기관과의 형평성 때문에 어쩔 수 없다라고 얘기합니다. 참고로 말씀드리면 정부기관 같은 경우에는 사업 공공기관하고 연구 공공기관으로 구별을 합니다. 그래서 사업 공공기관은 여러 가지 사업지표를 가지고 따지지만 연구 공공기관은 경제ㆍ인문사회연구회에서 따로 평가를 하는 게 있어서 지표가 조금 다른데 저희는 아직 경영평가에서 거기까지 진도가 나가지 못했기 때문에 일단은 요청하는 대로 맞추고 그다음에 저희들이 지표개선을 강하게 요구를 해서 다른 것을 똑같이 재지 않도록 하는 요청을 하겠습니다. 도와주시기 바랍니다.
</p>
<p><b>○ 부위원장 박관열 </b> 민경선 위원님 수고하셨습니다. 그럼 다음 질의하실 위원님께서는 거수로 신청해 주시기 바랍니다. 김강식 위원님 질의하세요.
</p>
<p><b>○ 김강식 위원 </b> 안녕하세요. 수원 출신 김강식 위원입니다. 혹시 아까 조금 전에 저희 앞서 위원님께서도 말씀을 해 주신 분이 계신데, 김우석 위원님이 아까 말씀하셨을 것 같습니다. 공공기관 경영평가 관련해 가지고 다른 항목들보다도 유달리 재무예산 관리의 적절성이라는 항목이 점수가 현격히 낮거든요. 이게 1~2년 된 문제는 아닌 것 같습니다. 보니까 2015년도는 100점 만점에 50.4 그리고 2016년도에는 39.9 그리고 그 뒤로도 계속 50점대를 유지하고 있어요. 다른 것들은 70점, 80점, 90점까지도 가는 것들이 있는데 사실 이런 부분들이 개선이 안 되고 있다라는 것에 대한 부분들은 이유를 파악하고 계신가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알고 있습니다. 말씀드리겠습니다. 재무예산 평가점수가 적은 것은 주로 재무예산과 관련돼서 항목별 5개년 계획이 작성되어 있지 않았던 데 그 원인이 있습니다. 특히 두 해 연도의 작성이 빠져 있었는데 그건 아마 원장 교체기 상황 속에서 5개년 계획과 관련하여 추계가 불분명하게 되니까 불분명한 추계를 할 바에는 안 하고 나중에 원장이 부임하면 그때 꼼꼼히 하자 이런 생각이었던 것 같습니다. 물론 그 생각의 아주 일면은 맞지만 그러나 전체적으로 예산을 사용하는 공공기관으로서는 해마다 수정을 하는 한이 있더라도 5개년 재정추계를 해야 되는 게 마땅하고 또 그게 법인데 그 부분이 지켜지지 않아서 그런 측면이 있어서 지금 작성하고 있고 명년도에는 그런 일이 없을 거라고 생각합니다.
</p>
<p><b>○ 김강식 위원 </b> 어쨌든 여러 평가를 받음에 있어서 이런 한쪽 부분들에 그런 부분들이 결손이 생기지 않도록 잘 관리를 하는 부분들도 원장님의 역할이라고 생각하고요. 그 부분들 충실히 지금 말씀하신 계획들대로 이행을 해 주셨으면 좋겠습니다. 그런데 제가 어쨌든 그 내용과 더불어서 사실은 우리 연구원에서 지금 목적이나 비전이나 아니면 사업방향이나 이런 것들을 의지를 담고 표명하는 것들은 또한 예산에 그 부분들이 반영돼야 될 텐데, 연구원의 사업예산을 그래서 달라고 해서 받았어요. 받았는데 사실 저는 이 내용을 보고서 어떻게 지적을 해야 될지 모르겠어요. 내용이 전혀, 이 내용을 주신 분이 계실 텐데 사업비에 대한 부분들 자체가 맞지 않다 보니까 어떻게 보고서 평가를 해야 될지 자체를 모를 정도로 허술한 이런 내용들을 전달해 주셨어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 이거 포맷이 재작성된 것 같은데, 새로 작성된 것 같은데 대신 답변드리도록 하겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 아니, 이 내용하고 부수적으로 또 딸려온 세부내역까지도 제가 받았거든요. 이 받아온 내용을 다 제가 입력해 봤어요. 그랬더니 이게 위아래가 합계하고 밑에 있는 내용이 맞지도 않는 자료들을 이렇게 갖다 주시면서, 그러니까 결국은 이런 경영평가에 대한 부분들도 이런 식으로 하시면서 자료는 이런 식으로 엉터리 자료들을 갖다가 저희한테 제출해 주시고 뭘 보고 저희가 이 부분들을 어떤 의지를 갖고 있는지 어떤 방향으로 갈 건지에 대한 것들을 판단하라고 하시는 겁니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님, 잠깐 그 자료를 확인한 후에 자료작성 담당자에게 답변…….
</p>
<p><b>○ 김강식 위원 </b> 오늘 아침에 받았어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. (관계직원을 향하여) 지금 가서 맞는지 확인하고요, 저 자료가 맞는지 얼른 답변을 드리도록 해 주십시오.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p><b>○ 김강식 위원 </b> 지금 저기 띄워 있는 자료, 연구원에서 주신 자료고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞네요.
</p>
<p><b>○ 김강식 위원 </b> 연구원에서 주신 자료인데 지금 저 예산액에 있는 부분들이 사실은 국비, 시군비, 기타, 도비에서도 이렇게 나눠져 있지 않습니까, 출연금 빼놓고는. 사실 저렇게 뭉뚱해 놓으면 안 되시죠. 왜냐하면 이 항목들이 각각의 계정들이 있고 위탁사무로 해서 이 부분들이 진행될 텐데 그 부분들이 어떤 포션을 차지하고 있는지를 확인하고 싶었어요. 사실 왜냐하면 시군과 연계해서 협력을 강화하겠다. 그다음에 수탁과제들 활성화해 가지고 사업들 진행하겠다라는 것들이면 예산에 그런 부분들이 반영돼야 되잖아요. 그런데 저렇게 주시면 어떤 의지를 갖고 하시는지 전혀 모르겠지만, 그다음에 2015년도에 비해서 또한 도비나 국비, 시군비는 절반 이상 줄었죠. 출연금은 대신에 그 이상으로 늘어나 있습니다. 그렇죠? 그럼 시군하고 연계해 가지고 활성화하고 아니면 수탁과제들 활성화해 가지고 그 수익들을 창출하시겠다라는 부분들이신데 그 의지하고는 전혀 상관없이 예산들은 절반 이상으로 줄어들어 있고 출연금은 주어지는 사업만 해서 하시겠다는 건지 자체사업의 예산은 전혀 세우지도 않고 이걸로 봐 가지고는 도대체 어떻게 운영을 하시겠다는 건지, 지금 말씀하신 주요계획들을 실천을 어떻게 하실 건지 전혀 모르겠습니다. 그 예산만 가지고 어떻게 그 부분들의 말씀하신 계획들이나 이런 것들이 반영되겠습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 허락하시면 담당자가 일단 답변을 하고 그다음에 제가 말씀드리겠습니다.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 재정지원부장 박인숙입니다. 위원님이 요청하신 이 자료에서 출연금이라고 하면 저희 자체 출연금으로 받은 예산 중에 연구사업비에 해당하는 예산만 저희가 뽑아낸 자료고요. 그 밑에 경상적 사업비, 자본적 위탁 사업비, 기타 국비ㆍ시비 이 사업은 수탁과제에서 저희가 수탁으로 수행하는 사업비에 대해서 작성한 겁니다. 그래서 위의 이 예산하고는 맞지가 않습니다. 국비라고 해서 저희가 수탁으로 경쟁입찰을 해서 따온 사업비에 대한 예산이, 지금 이 수탁과제 총예산이 17년도에 57억 4,100 그다음에 18년도에 53억 6,200 이렇게 되는 겁니다.
</p>
<p><b>○ 김강식 위원 </b> 그러니까요. (전문위원실 직원을 향하여) 다음 페이지 좀 넘겨줘 보실래요?
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  그래서 여기에 이 뒤 자료를 주셨어요. 이 자료 보면 항목별로 국비는 어떻게 돼 있다 이런 내용들을 다 주셨어요, 일일이. 그렇죠? 이렇게 내용들을 다 주셨습니다. 제가 그걸 입력해 봤더니 지금 2015년도뿐만 아니라 전체적으로 다 주신 내용들이 여기 지금 뭘 받아서 수탁하셨다라는 결과인 거잖아요. 그런데 거기에는 차액들이 있어요. 32억 집행액도 차이가 있고 예산액도 차이가 있는 거예요. 그러니까 저는 이게 도대체 무슨 자료인지 모르겠어요.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 이 수탁과제 같은 경우는 당해연도에 끝나는 과제가 아니기 때문에 당해연도에 예산을 쓰고 나머지 잔액은 그다음 연도로 해 가지고 나머지 부분에 대한 예산을 다시 기재를 하고…….
</p>
<p><b>○ 김강식 위원 </b> 아니요, 여기 보시면 이렇게 주셨잖아요. 여기 항목들도 있고 예산도 있고.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네, 그렇습니다.
</p>
<p><b>○ 김강식 위원 </b> 그러면 여기에 합계금액이 나와 있잖아요. 그 합계금액들은, 최소한 주신 것들은 항목별로 국비, 시군비, 기타 이 사업비에 대한 내용들의 합계금액들은 추가로 되던 이거하고 상관없이 받아 가지고 이때 당시에 진행이 됐으면, 이때 당시에 받은 금액들이 있으면 전체 위의 SUM 합계는 맞아야 되는 거잖아요. 그러니까 저는 사실 이거를 지적하려고 했던 부분들은 아니에요. 사실 그런데 이 자료를 보고 도대체 어떻게 지적을 해야 되는지 잘 모르겠고요. 사실은 그 부분들은 그렇게 모르겠다라는 말씀을 드리겠고 그런데 제가 궁금한 건 그겁니다. 아까 임채철 위원님께서도 말씀을 하셨지만 연간 미집행 금액들이 있는 거잖아요. 지금 보면 예산액과 집행액의 차이가 있어서 그것들이 누계돼 가지고 가고 있는 금액이, 지금 현재 누적돼 있는 규모는 어떻게 됩니까?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 지금 저 자료는 제가 말씀드린 대로 당해연도에 쓴 예산이 못 썼으면 그다음 연도로 넘어가서 그 못 쓴 예산에 대해서 집행이 되는 겁니다.
</p>
<p><b>○ 김강식 위원 </b> 저 자료를 차치하고서라도 지금 현재 그러면 미집행돼서 연간 미집행된 금액들이 누적돼 있는 금액들은 어느 정도 됩니까?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 누적돼 있는 금액이라고 하시면 일반회계 말씀…….
</p>
<p><b>○ 김강식 위원 </b> 계속 이월되잖아요, 매년 이월될 거 아닙니까.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네, 다음연도 정기이월로 해서 그건 운영재원으로 다시 편성해서 지금 사용하고 있습니다.
</p>
<p><b>○ 김강식 위원 </b> 그러니까 그 금액이 규모가 어느 정도 되냐고요.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 지금 저희가 매년 줄어들고 있는데 작년 같은 경우는 19억 정도 됐습니다.
</p>
<p><b>○ 김강식 위원 </b> 그럼 그 사업들을 먼저 써야 되는 부분인 거잖아요, 사실은.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네.
</p>
<p><b>○ 김강식 위원 </b> 지금 자꾸 출연금만 늘려 가지고 될 부분이 아니라 제가 보기에 예산을 출연금은 줄이고 그 부분들 먼저 집행할 수 있도록 해야 되는 게 맞다라고 생각되는데요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 위원님 말씀이 맞습니다. 그래서 아까 임 위원님께서 말씀하실 때도 말씀드린 것처럼 해마다 거의 비슷한 금액이 차년도로 이월되는 경향이 지금까지 있었습니다. 그러니까 실제로 보면 당해 예산이 당해에 쓰여지는 건 맞는데 한 번 넘어온 이월됐던 금액만큼 계속 이월되는 경향이 있어서 그 부분에 대해서는 한번 정산이 좀 필요하다는 생각…….
</p>
<p><b>○ 김강식 위원 </b> 그래서 저는 여기 자체사업비나 이런 부분들은 어쨌든 자체적으로 하겠다는 사업들, 예산 자체에도 편성이 안 된다. 지금 현황에 안 들어가 있어요, 그렇죠? 그러면 출연사업이나 기타 이렇게 들어오는 사업들만 가지고 진행하겠다라는 것처럼밖에 안 보이잖아요, 이 자료만 가지고는 사실은.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그런데요, 아까 드린 자본적 지출 이런 것 등은 내부적으로 사용했던 포맷이 아니라 오늘 저도 지금 처음 보는 자료 포맷이라서 저도 좀 들여다봐야 되겠습니다. 제가 오늘 처음 봤습니다, 그 자료 포맷은 처음에.
</p>
<p><b>○ 김강식 위원 </b> 그러게요, 지금 여기 주신 내용하고도 금액이 달라서 저도 당황스럽습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 포맷이 저도 좀 놀랐는데요. 처음 보는 포맷이라서 그 원인을 좀 살펴보고 끝나더라도 추후에 위원회에 제출을 하도록 하겠습니다.
</p>
<p><b>○ 김강식 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 박관열 </b> 김강식 위원님 수고하셨습니다. 다음 질의하실, 김경호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김경호 위원 </b> 안녕하세요? 가평의 김경호 위원입니다. 장시간 동안 행정사무감사 받으시느라고 고생이 많습니다. 몇 가지 잘 몰라서 물어보는 거니까 이해를 좀 해 주시고요. 아무래도 전문가들한테 물어봐야 되는 입장이라서.
</p>
<p style="padding-left:1.2em">  제가 자료 요청한 것 중에 두 번째 1075페이지에 보면 설문조사 현황이 있습니다. 자료를 보니까 2016년도에 41건, 2017년도에 34건, 29건인데요. 연구에 있어서 설문조사는 어떤 역할이 되는 거죠, 실질적으로?
</p>
<p><b>○ 경기연구원장 이한주 </b> 우리 연구원에서 하는 연구는 담론연구는 비교적 적고 대부분이 정책연구입니다. 정책연구에서 설문조사는 연구 금액 중에서 일부분을 현실 적합성 원리에서 설문조사를 하거나 자료조사를 하는 것들이 대부분이라서 이 부분도 대개 필수적으로 들어가는 것들이 많이 있습니다.
</p>
<p><b>○ 김경호 위원 </b> 설문조사가 잘못됐거나 측정도구가 잘못되면 연구내용 자체에 어떤 영향을 받나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 결정적으로 영향을 받습니다.
</p>
<p><b>○ 김경호 위원 </b> 그렇죠. 결정적인 영향을 받죠, 측정결과 얼마큼 잘되어 있는지. 그러면 측정도구에 대한 어떤 신뢰도나 타당도가 제대로 평가가 되고 있나요, 지금 현실적으로? 내용을 보면 거의 그런 평가내용들은 없던데요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그동안에 저희가 연구를 하면서 연구책임자가 연구 설문조사를 하는 업체에 대부분 그 부분을 잘라서 위탁을 줍니다. 하라고 의뢰를 하는데 어떤 경우는 잘되고 어떤 경우는 안 되고 하니까 자기들이 조정을 하게 하지 설문조사 내용에 대해서 본부 차원에서 점검을 하거나 이런 일은 없습니다.
</p>
<p><b>○ 김경호 위원 </b> 그런데 자료에는 “실효성 있게 설계하고 있다.”라고 그렇게 저희에게 전달됐습니다, 자료에 보시면. 그리고 실질적으로 자료의 설문조사를 보면 타 유사기관과 중복되는 내용들도 있고요. 그건 나중에 만약에 필요하다고 하면 제가 알려드릴 수도 있습니다. 그래서 그런 부분들에 있어서 지금 실질적으로 신뢰도나 타당도가 제대로 나오지도 않는 그런 것들을 가지고 여태껏 연구했다고 하면 연구 자체가 다 부정될 수밖에 없는 거죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 신뢰도가 훼손됐다는 얘기는…….
</p>
<p><b>○ 김경호 위원 </b> 훼손됐다는 얘기는 아니고요. 그거야 뭐 아직 검증은 안 해 봤으니까 모르겠는데 만약에 제대로 안 되어 있었으면 지금까지 했던 모든 수많은 돈을 들여서 한 경기연구원의 어떤 보고서들이 일정부분 신뢰를 잃어버릴 수밖에 없다라고 생각이 듭니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 사실이라면 그 얘기는 심각한 얘기고요. 전 뭐 그렇지 않다고 생각합니다, 그 부분에 관해서는.
</p>
<p><b>○ 김경호 위원 </b> 저도 그렇지 않기를 바라겠습니다. 그리고 대부분 보면 보고서 형태가, 아무래도 보고서 형태로 나오는 거죠, 논문 형태보다도?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 김경호 위원 </b> 그래서 보통 빈도분석이나 교차분석 정도라고 생각을 하는데요. 보고서의 경우에 있어서는 어떤 특정한 분야에 대한 주제를 수행하는 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 김경호 위원 </b> 그리고 그 결과를 보고하기 위해서 만들어지고요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 김경호 위원 </b> 그러면 이러한 데이터를 가지고 혹시 전문성 있게 논문이나 학술지에 발표한 건수들이 있나요, 연구원들이?
</p>
<p><b>○ 경기연구원장 이한주 </b> 기본과제에 해당하는 건, 저희들이 연구과제 중에는 기본과제, 정책과제 이렇게 크게 갈라지는데 기본과제에 관련돼서는 등재지에 싣는 것을 기본으로 해서 점수를 부여하고 있습니다.
</p>
<p><b>○ 김경호 위원 </b> 그것 좀 활성화시켜 주길 바라는데요. 그게 왜 그러냐면 도정의 핵심사업이나 주어진 시책 연구를 제안하는 것도 필요하지만 그러니까 연구원들이 그 전문성을 가지고, 자기의 어떤 의견을 가지고 정책제안하는 게 필요하다라고 생각을 하기 때문에 그런 부분들이 좀 활성화될 수 있도록 지원을 해 주셨으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 참고로 말씀드리면 연구원 중에서는 담론연구인 기본연구를 좋아하시는 분들이 있고 또 때로는 즉각적인 정책연구를 좋아하시는 분들이 있는데 연구원은 후자가 중심입니다. 그럼에도 불구하고 전자를 위해서 지금 연구원 구조개혁작업 중에 연구원의 트랙을 투트랙으로 나눠서 연구중심과 정책중심으로 나누어서 평가를 하는 작업들을 준비 중에 있다고 말씀드리겠습니다.
</p>
<p><b>○ 김경호 위원 </b> 그리고 우리가 설문조사한 자료들이 있지 않습니까? 그런 공공데이터들을 타 기관에 제공하는 경우가 있나요, 사례가?
</p>
<p><b>○ 경기연구원장 이한주 </b> 대체로 저도 지금 그 부분이, 연구자였을 때 그 부분에 관심이 많아서 대부분의 연구기관에서는 원자료 공개를 의무화되지 않은 것들은 안 하고 있습니다. 그래서 저희들도 물어봤더니 대부분 원자료 공개는 안 하고 재가공된 자료를 공개한다든가 결과만 공개하고 있어서, 그렇지 않아도 제가 와서 하는 작업들 중의 하나가 가능하면 원자료 공개를 해서 남아있는 데이터의 영양가를 다른 분들이 사용할 수 있는 방법들을 찾자라고 하는 것들을 준비 중에 있습니다.
</p>
<p><b>○ 김경호 위원 </b> 네, 감사합니다. 그렇게 공개를 해 주시면 좋은데요. 먼저 지난 2017년도 공공경영평가에서 보면 “공공데이터를 단순히 개방하는 초보적 수준에 머무르고 있다.”라고 지적하고 있습니다. 그래서 그런 부분들은 좀 활성화시켜 주길 부탁드리고요. 설문조사가 지금 되는데 일정부분 그것들을 데이터나 코드북으로 가공하여 개방할 용의가 있느냐라고 아까 물어봤는데 그 부분에 있어서는 가능하신 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 지난 자료들에 대해서는, 제가 오기 전 자료들에 대해서는 그 주의가 어느 정도 되는지 모르기 때문에 그건 모르지만 앞으로 하는 자료, 특히 위원님들께서 관심을 갖고 봐주셔야 될 경기도 내에 아주 대형 자료가 있습니다. 경기도민의 삶의 질 자료라고 해서 몇 억짜리 자료들을 저희들이 패널 자료로 만들고 있는데 이건 굉장히 중요한 자료입니다. 그래서 그 부분에 관해서는 공개하지 않는다면 그게 이상한 거라서 그 자료들은 적어도 지금부터는 공개를 하도록 해서, 거기에는 연구원이 감당하기 어려울 정도로 많은 내용이 들어 있기 때문에 많은 분들이 그 자료를 이용해서 연구하실 수 있도록 하겠습니다.
</p>
<p><b>○ 김경호 위원 </b> 네, 감사합니다. 그렇게 해 주시면 고맙겠고요. 왜 그러냐면 한국아동ㆍ청소년 패널조사 같은 경우에 있어서는 실질적으로 가장 연구논문들이 많이 쏟아져 나오는 게 청소년 분야인데요. 그 부분들에 있어서 이유가 뭐냐면 한국아동ㆍ청소년 패널조사 같은 경우는 전부 자료를 다 공개해서 계속 제공을 합니다. 그리고 기본적으로 아주 여러 방향에서, 여러 각도에서 시각을 가지고 연구를 하거든요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 김경호 위원 </b> 그래서 경기도도 지금 인력도 부족하고 계속 그렇다는데 그런 것들을 활용해서 어떤 새로운 시각으로서 경기도를 바라보는 그런 것들이 됐으면 고맙겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 김 위원님 말씀 맞습니다.
</p>
<p><b>○ 김경호 위원 </b> 또한 아까 말씀하신 거와 달라서, 사회조사 자료도 있습니다, 사회조사 자료요. 그것도 좀 데이터북과 코드북을 해서 같이 공개를 해 주셨으면 고맙겠습니다. 사회조사 자료도 이게 아마 패널 자료로도 가능할 것 같습니다.
</p>
<p style="padding-left:1.2em">  그리고 또 한 가지 연구와 관련해서 조례 제정, 의회와 연계된 사업이 혹시 있었나요? 조례 제정, 뭐 어떤 사업을 하는 과정 속에 있어서 조례를 제정한다든가 이런 것들이요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 의회의 요청으로 한 사업들이 있었고 그게 대부분 아마 조례하고 관련이 있을 거라고 생각합니다.
</p>
<p><b>○ 김경호 위원 </b> 물론 몇 가지 있더라고요. 그런데 먼저 같은 경우에 참여예산의 연구된 게 있는데요. 그 연구는 제대로 진짜 기가 막히게 잘해 놨더라고요, 자세히 쭉 살펴보니까. 그런데 조례를 만들 생각을 안 하고 그냥 방치됐어요. 제가 그걸 가지고 개정조례를 내긴 했는데요, 오자마자. 그래서 이번 같은 경우에 또 보면 이수행 박사가 연구한 사회적 농업 같은 경우에 있어서는 앞으로 농업에 있어서의 대표적인 어떤 방향성이거든요. 이런 부분들에 대해서 이왕 이렇게 됐으면 조례까지 만들어갈 수 있도록 그렇게 연결 좀 부탁을 드리도록 하겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 연구원 입장에서는 저희들이 했던 연구가 위원님 손을 통해서 조례로 만들어진다면 연구원으로서는 그게 보람이고 존립 목적이기 때문에 저희들로서는 적극 환영하는 바이나 저희들이 먼저 연구를 해서 조례를 만들어 달라고 하는 건 연구원의 분에 넘치는 일이라고 저희들은 생각하고요. 도나 의회에서 요청을 하는 경우에 기초 작업으로서 이렇게 하면 조례가 되는 데 안심이다라고 하는 것들에 대해서는 저희들이 얼마든지 할 수 있도록, 그게 또 저희들 목적이라고 생각합니다.
</p>
<p><b>○ 김경호 위원 </b> 네, 감사합니다. 의회에서도 적극적으로 그런 부분들에 있어서 부탁을 좀 드리도록 하겠습니다. 왜 그러냐면 아무래도 우리 입장에서는 전문성이 결여된 건 사실이거든요. 그래서 전문가들의 어떤 지원을 좀 필요로 하고요. 그런 부분들에 있어서 좀 부탁을 드리고요. 아까 앞서 말씀드렸던 데이터 공개를 적극적으로 좀 추진해 주시면 감사하겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다.
</p>
<p><b>○ 김경호 위원 </b> 이상 질문을 마치겠습니다.
</p>
<p><b>○ 부위원장 박관열 </b> 김경호 위원님 수고하셨습니다. 다음은 정승현 위원께서 질의하시겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 정승현입니다. 두 가지만 좀 말씀을 드리겠습니다. 하나는 어쨌든 원장님이 오셔서 지난 업무보고 때 언급이 있었습니다마는 실행된 부분에 대한 격려말씀을 드리고 싶고 하나는 제도적 보완문제를 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  지난 8월 달인가요? 아, 10월 달이구나. 10월 달에 각 시군 정책연구 지원 일환으로 과제신청 받으신 것 있죠? 그중에 7개 과제는 선정하고 나머지는, 그때 몇 개 과제가 신청이 됐었죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 24개가 신청이 됐습니다.
</p>
<p><b>○ 정승현 위원 </b> 그래서 지금 7개 과제는 올해 하반기 사업으로 수행하기로 결정을 한 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그리고 나머지는 내년에 하는 건가요, 아니면 별도로 또 선정과정을 거치는 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 올해 7개 내고요. 그다음에 2019년 추진 연구목록으로 11개 시군에서 17개 과제가 이월됐습니다. 내년도 과제입니다.
</p>
<p><b>○ 정승현 위원 </b> 이게 지금 몇 개 시군에서 신청한 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 11개입니다.
</p>
<p><b>○ 정승현 위원 </b> 아니, 전체 이번에 10월 달에…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 17개하고 11개하고 해서 18개입니다. 18개 시군에서…….
</p>
<p><b>○ 정승현 위원 </b> 18개 시군에서 지금 이 과제신청을 하셨네요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그럼 나머지 13개 시군에서는 신청을 안 하신 거네요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그래서 이 부분은 어쨌든 시군 각 관련 연구정책을 지원하기 위한, 또 시군에서 필요한 사업들에 대해서 어쨌든 연구용역을 하시는 거잖아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그래서 이 부분에 대해서는, 그러니까 여기에 응답한 시군 같은 경우는 적극적으로 역할들을 거의 응답하시는 부분이고 그렇지 않는 데는 좀 소극적이거나 아니면 미처 놓쳤을 수도 있는데…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 신청하지 않은 시군에 대해서도 다시 한 번, 연구원에서 이런 일련의 과제수행을 하고 있기 때문에 적극 동참할 수 있도록 한 번 더 고지를 한다든지 공문 발송을 한다든지 그렇게 하셨으면 좋겠어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 2차 수요조사를 한 번 다시 실시해서 위원님 말씀…….
</p>
<p><b>○ 정승현 위원 </b> 그래서 이런 부분들이 지난 업무보고 시간에 잠깐 언급이 됐는데 바로 이렇게 시행이 돼서 어쨌든 시군별로는 올 하반기에 7개 과제가 수행이 되겠습니다마는 저는 굉장히 큰, 또 시에서 직접 우리 시에 또 우리 군에 필요한 사업들을 올렸기 때문에 아까 이게 정책에 반영되냐 안 되냐라는 부분들에 대한 얘기들이 또 있었습니다마는 이 연구과제 같은 경우는 굉장히 효율적인 측면에서 크게 저는 작용할 거라고 보여지기 때문에 이런 부분들은 좀 더 확대ㆍ발전시켰으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다. 2차 수요조사를 연초에 바로 실시해서 더 추가하도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 네. 제가 지금 하나는 정관 그리고 우리 경기연구원 설립 조례 그리고 또 경기도 출자ㆍ출연 조례 그리고 지방자치단체 출자ㆍ출연 연구원의 운영에 관한 법률 이 네 가지를 보고 있는데, 제가 드리고 싶은 말은 원장 선임과 관련된 문제예요. 사실 우리 도의 싱크탱크 역할을 하고 있는 경기연구원이 원장을 선임하지 못하고 공석으로 1년이 넘게 있었다가 우여곡절 끝에 지금 원장님께서 취임하셨잖아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그래서 현재 지금 우리 경기연구원 같은 경우는 정관에 의해서 원장을 선임하고 있죠? 이사회 추천을 통해서 의결을 거쳐서 이사장이 임명을 하게 되어 있죠. 그렇죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 지난 2017년 7월 달에 경기도 출자ㆍ출연 조례가 개정이 됐어요. 이 개정 주 내용은 뭐냐 하면 우리 경기도 출자ㆍ출연기관에 대한 임원 선출, 임원 임용문제인데 사실 그 전에 많은 공공기관에서 자체 정관에 따라서 임원들을 선출하고 임명하고 했었던 부분들인데 그러다 보니까 여러 가지 이사회 의결과정에서의 어떤 모호성 또 이로 인한 혼란, 이로 인한 불공정성 이런 여러 가지 문제들이 대두됐기 때문에 이런 잡음들을 좀 줄여보자 그래서 합리적으로 또 효율적으로 원장이 됐든 기관장을 임명해 보자라는 측면에서 조례 개정을 통해서 임원추천위원회를 설치ㆍ운영할 수 있도록 그렇게 뒀어요. 물론 전제조건이 있어요. “법령이나 조례 또는 정관이 정하는 바에 따라서 당연히 임명되는 임원은 제외한다.”라고 조건은 되어 있어요. 이것은 법령에 의해서 선출되는 부분들이 있기 때문에 존중해 준 거죠. 그러나 어쨌든 제 판단으로는 경기연구원에서 임원추천위원회를 설치해서 임원추천위원을 통해서 추천을 받고 이사회에서 추천받은 사람들에 대해서 의결을 거쳐 이사장이 임명하는 그런 과정을 거치는 것도 나쁘지 않을 거라고 보고 있는데 원장님, 임원추천위원제를 둘 필요성은 없다고 보시나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 제가 들어오기 전에 있었던 일이라서 임원추천위원회는 없고 이사회 의결로 얘기가 됐던 걸로 보고받고, 듣고 보았습니다. 그런데 임추위가 되었든 아니면 지금 방법이 되었든 이것들은 규정과 법이 정하는 바에 의해서 할 생각이고요. 도에서 이 부분은 아직 제가 질의를 해 보지는 않았습니다. 그러나 임추위 방법이 나쁜 방법이라고 생각하진 않습니다.
</p>
<p><b>○ 정승현 위원 </b> 지금 전에 행감 결과자료를 보니까 임원추천위원회 방식을 준용하는 평가위원을 구성해서 원장을 추천하고 있다고 그랬는데 평가위원이란 것이 조례에도 없고, 경기연구원 조례에도 없고 정관에도 없어요. 그런데 이 평가위원은 도대체 어디서 나왔는지 이걸 제가 구태여 묻지는 않겠습니다마는 어쨌든 이런 평가위원을 통해서 할 거라면, 정관에도 없는 이런 비공식적인 위원들을 통해서 할 거라면 임원추천위원회를 공식적으로 만들어서 거기에서 저는 추천을 하는 게 바람직하다. 서울시 같은 경우도 마찬가지예요. 서울시도 당초에는 이 법령에 의해서…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하십시오. 듣고 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 서울시도 당초에는 법령에 의해서 그리고 내부 정관에 의해서 그렇게 이사회 의결을 거쳐서 이사장이 추천을 했거든요. 그런데 이후에 서울시도 임원추천위원회를 구성했어요. 임원추천위원회를 구성한 이유는 앞서 말씀드린 것처럼 우리 경기도가 조례 개정한 이유와 똑같습니다. 그래서 우리 경기도도 마찬가지, 경기연구원도 어쨌든 원장님 계실 때 내부 정관을 좀 개정해서라도 임원추천위원회를 두는 게 저는 바람직하고, 사실 또 우리 경기도 산하 모든 기관들이 다 임원추천위원회를 두고 있어요. 구성을 해요. 원장의 임기가 끝날 무렵에 도가 도의회로부터 임원추천위원회 추천을 받아서 거기에서 임명절차를 진행하는 거거든요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 유독 경기연구원 하나만 지금 소위 말하는 법령에 의해서 원장 임명을 하고 있는데 경기연구원 역시 이런 임원추천위원회 제도를 저는 도입할 필요가 있다. 또 그렇게 해야만이 여타 불합리한 그런 잡음들이 없고 또 합리적인 선택을 했다라는 그런 평을 저는 받을 수 있다고 보여지거든요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 정부의 위원회들은 경제ㆍ인문사회연구회에서 일괄적으로 이 부분을 하기 때문에 별도이지만 저희 경기도 경기연구원에서는 말씀하신 대로 경기도지사 추천 3명, 도의회 추천 2명, 경기연구원 비상임이사 2명 이래서 여기서 서류심사하고 면접심사를 진행하는 것으로 돼 있습니다. 말씀하신 내용들은 도 정부하고 협의를 해서 규정을 살펴보고 임추위 방법의 장단점을 비교하여 점검하도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 저는 장단점이 굳이 없다고 봐요. 어차피 평가위원이 어떻게 해서 구성됐는지 모르겠지만 평가위원회에서 하면 공식적으로 임추위를 만들어서 그걸 소집해서 그렇게 가는 게 저는 바람직하다고 보여요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 저도 지금은 위원님과 동일하게 생각하는데 혹시 법령이라든가 하는 부분을 더 점검을 해 봐야 되겠어서 적극적으로 검토를 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 서울시도 지금 그렇게 하고 있기 때문에 서울시도 당초에는 이사회 의결을 통해서만 추천했는데 그렇게 하고 있기 때문에 그런 것들을 거쳐서 제도적 보완이 이루어졌으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 이상 마치겠습니다.
</p>
<p><b>○ 부위원장 박관열 </b> 정승현 위원님 수고하셨습니다. 다음 질의는 제가 해야 되는데, 이혜원 위원님 다음 질의하세요. 안 하시겠습니까?
</p>
<p><b>○ 이혜원 위원 </b> 간단한 거 하겠습니다. 정규직전환심의위원회 구성이 됐죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 지금 어디까지 진행됐습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 지금 규칙제정 완료했고요. 그다음에 직무검사도 했고 대상자도 확정을 했고요. 도의회에 통보를 해서 실시하기 위해 도에 통보를 하고 실시 들어가기 직전입니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러면 전환대상자 직무조사를…….
</p>
<p><b>○ 경기연구원장 이한주 </b> 완료했습니다.
</p>
<p><b>○ 이혜원 위원 </b> 완료했고 전환여부 최종판단이 남았다는 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 그렇습니다.
</p>
<p><b>○ 이혜원 위원 </b> 여기 보면 정규직전환심의위원회 회의결과를 보시면 전환방법에서 면접평가 실시를 하게 돼 있어요. 이 면접평가는 어떤 방법으로 실시를 합니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 1차 면접평가는 71점을 만점으로 해서 전체 직군에 대해서 다 실시를 하는데 내부자에서 3명과 공정성을 위해서 외부에서 두 분을 모시고 해서 심사를 하도록 되어 있습니다. 표도 만들어져 있고요.
</p>
<p><b>○ 이혜원 위원 </b> 혹시 그걸 받아볼 수가 있을까요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 표?
</p>
<p><b>○ 이혜원 위원 </b> 네, 표.
</p>
<p><b>○ 경기연구원장 이한주 </b> 지금 보여드릴 수 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그것 준비 좀 해 주시고요. 여기 탈락자가 있네요. 탈락자가 있을 수 있는 건가요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다. 71점을, 절대평가를 기준으로 하기 때문에 탈락자가 있을 수 있습니다, 1차에서.
</p>
<p><b>○ 이혜원 위원 </b> 탈락자의 기준이 좀 궁금하긴 한데요. 아무튼 표 좀 줘 보시고요. 지금 제가 받은 자료 보면 80%가 진행이 됐어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 전체 공정에.
</p>
<p><b>○ 이혜원 위원 </b> 내년 1월 1일 날 최종완료를 하기로 한 거죠?
</p>
<p><b>○ 경기연구원장 이한주 </b> 목표로 하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그때까지 100% 될 것 같습니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 조금 어려울 수 있습니다. 조금 어려울 수 있고 절차는 저희 혼자 하는 게 아니라 도하고 협의를 해 가면서 하는 과정이기 때문에 조금 어려울 수 있습니다. 그러나 기본적으로 가장 힘든 과제인 노동조합하고의 관계는 이미 정리가 됐기 때문에 나머지는 행정절차상의 어려움만 좀 남아있다 이렇게 얘기할 수 있습니다만 이번 연도에 마무리 지을 수 있도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 알겠습니다. 이것 제가 조금 더 보고요. 하여튼 가장 지사님의 주요 공약이기도 하고 또 필요한 부분이기 때문에 저는 빠른 시일 내에 이게 완료될 수 있도록 최선의 노력을 다해 줬으면 고맙겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 이상입니다.
</p>
<p style="padding-left:2.4em">    (박관열 부위원장, 정승현 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 정승현 </b> 이혜원 위원님 수고하셨습니다. 다음 박관열 위원님 질의해 주십시오.
</p>
<p><b>○ 박관열 위원 </b> 원장님, 저 좀 보십시오. 고생이 많습니다, 장시간. 하여튼 경기연구원에 대한 기대가 크기 때문에 잘못된 부분에 대해서 질책도 있고 그런데 그 받아들이는 것들을 갖다가 하여튼 잘 받아들였으면 좋겠고 실제 16년 동안에 쌓인 적폐들이 분명히 있을 거예요, 경기연구원 내에도. 지난 한 달 반 되셨잖아요, 원장님. 와서 보니까 어떻습니까? 경기연구원 내부. 솔직하게 말씀해 주세요, 그냥. 본 그대로.
</p>
<p><b>○ 경기연구원장 이한주 </b> 본 그대로 말씀드리면 제가 사실은 외부에 있을 때는 조금 위원님들 아시다시피 인수위원을 하면서 경기연구원을 봤을 때는 조금 혐의와 의심점을 많이 가지고 봤었습니다, 사실은. 그런데 들어와서 보니까 나름대로 자원도 생각한 것보다는 잘 뽑아놓으셨고요. 그다음에 나름대로 열심히 하고 있었던 것도 또 사실입니다. 다만 기관이 1995년에 만들어져서 지금까지 오다 보니까 처음에 들어오셨던 분들은 굉장히 오래됐고요. 이런 분들은 나이가 오래되다 보니까 자연히 타성적인 요소도 좀 생겨있고 그다음에 요즘 기준에 덜 맞는 부분들이 있어서 적폐라고까지는 생각하지 않지만…….
</p>
<p><b>○ 박관열 위원 </b> 적폐인데 적폐라고 생각을 않고 계시겠죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 아닙니다. 적폐라고까지 생각하지는 않지만 개선여지가 굉장히 많다…….
</p>
<p><b>○ 박관열 위원 </b> 그런데 중요한 것은 이게 실제 우리 경기도 매우 중요한 위치에 있잖아요, 경기연구원이.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 맞습니다.
</p>
<p><b>○ 박관열 위원 </b> 경기연구원이 왜 중요하냐면 나는 실제 경기연구원이 경기도 심장이어야 된다고 저는 보고 있어요. 경기연구원에서 만드는 정책들을 경기도가 다 받아들여서 경기도 미래를 이렇게 만들어가야 된다고 보거든요. 사실 그렇지 않습니까?
</p>
<p style="padding-left:1.2em">  제가 시간 많지 않은데 질문을 드리겠는데 수도권 규제에 대해서 묻겠습니다. 원장님, 올해 경기도지사 선거과정에서 도지사께서 “특별한 희생에 대한 특별한 보상이 있어야 한다.” 이거 알고 계시잖아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 박관열 위원 </b> 이게 2018년 6월 20일 중부일보 “특별한 희생엔 특별한 보상, 이재명호 경기북동부 규제고리 끊어낼까?” 그랬거든요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 맞습니다.
</p>
<p><b>○ 박관열 위원 </b> 이러한 표현에 대해 본 위원은 역차별 문제에 대한 해결의지로 이해하는데 원장님, 어떻게 생각하십니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 공약 용어 자체도 제가 만드는 데 관여한 사람으로서 북부지역과 동부지역이 겪고 있는 규제에 대한 고통문제에 대해서 저희들이 자료도 많이 수집을 했고 충분히 이해하고 있습니다. 그러나 이 부분들이 꼼꼼히 차질 없이 진행되기 위해서는 정부 측과의 협의가 대단히 중요한 상황이 되어 있기 때문에 저희들이 섣부르게 주장을 할 수 없고 하게 된다면 완벽한 논리를 가지고 또 더군다나 국회에 나가 있는 저희 주권자들의 대표들, 국회의원들하고도 열심히 협의를 해야 되고 무엇보다도 여러분들의 의지를 충실히 담아내야 되기 때문에 아마도 도에서도 선거 때 나온 것들을 한 치도 잊고 있지는 않고 있고 저희 연구원도 뒷받침하려고 노력하겠습니다마는 그러나 너무 서두르면 또 부작용도 생길 수 있다 이렇게 생각합니다. 그러나 어쨌든 그 문제에 대해서는 한 치도 잊고 있지 않습니다.
</p>
<p><b>○ 박관열 위원 </b> 꼭 그렇게 해 주시고요. 이게 실제 1984년 수도권에 인구와 산업이 집중되는 현상을 막기 위해서 수도권정비계획법이 제정돼 있잖아요. 30년이 넘게 시행돼 왔지만 결국 수도권으로 집중을 막지 못하고 있잖아요, 지금?
</p>
<p><b>○ 경기연구원장 이한주 </b> 그렇습니다.
</p>
<p><b>○ 박관열 위원 </b> 오히려 수도권 내의 불균형이라는 부작용만 낳고 있단 말이에요. 경기도 내 일부 지역은 다양한 규제가 과도하게 중복 적용되고 있어서 개발과 재산권 행사에 제약을 받고 있는 상황인 것도 알고 계시잖아요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 박관열 위원 </b> 특히 경기도 광주 잘 아시잖아요, 제가 광주 출신인데.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 알고 있습니다.
</p>
<p><b>○ 박관열 위원 </b> 광주는 경기도에서 가장 많은 6개의 규제를 받고 있어요. 경기도에서 가장 많은 6개의 규제를 받고 있는 광주시는 시 전체가, 유례가 없어요. 다른 31개 시군이 시 전체가 팔당특별대책 1권역으로 갖고 있는 곳은 광주밖에 없어요. 그리고 자연보전권역으로 지정돼 있고 개발제한구역, 상수원보호구역, 수변구역, 군사시설보호구역에도 해당되는 지역을 갖고 있단 말이에요. 수도권 규제에 대한 원장님 입장은 무엇입니까?
</p>
<p><b>○ 경기연구원장 이한주 </b> 저희들 할 수 있는 건 연구이기 때문에 규제에 의해서 어느 정도 주민의 삶의 질이 위축되고 개발이 지연되는 거에 대한 연구들을 수행해서 이런 것들을 널리 알리고 입법에 반영될 수 있도록 하는 게 저희들의 임무라서 그런 임무들을 저희들이 충실히 수행을 하겠습니다.
</p>
<p><b>○ 박관열 위원 </b> 원장님, 경기도 인구정책과 관련해서 연구원의 연구는 않나요?
</p>
<p><b>○ 경기연구원장 이한주 </b> 하고 있습니다.
</p>
<p><b>○ 박관열 위원 </b> 통계청 발표에 따르면 2016년 신생아 수는 40만 6,000명에서 2017년에는 35만 7,000명으로 떨어졌어요. 2017년 합계 출산율을 보면 전국 1.05명, 경기도는 1.07명으로 역대 최저치를 경신하고 있단 말이에요. 이런 인구학자들이 지적하는 한 해 출생아 수의 심리적 저지선이 30만 명대 진입을 나타내는 수치잖아요. 이제 우리나라 본격적으로 인구절벽 시대에 들어선 것을 의미하고 있는 것이잖아요. 어떻게 대책이 있습니까, 경기도가?
</p>
<p><b>○ 경기연구원장 이한주 </b> 경기도 총량적으로 보면 경기도는 인구가 조금씩 늘고 있는 추세입니다. 총량적으로 보면 늘고 있는데…….
</p>
<p><b>○ 박관열 위원 </b> 인구는 늘고 있는데 신생아, 아이들, 우리 출산율을 말씀드리는 거예요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 말씀하신 대로 이제 고령화가 진행되는데 그나마 다행인 건 서울보다는 고령화 속도가 저희 경기도가 조금 더딥니다. 그래서 총량적으로는 다소 형편이 나아 보이지만 그러나 경기도 내에서도 격차가 아주 심해서 여주나 이런 데에서는 급속히, 연천 이런 데는 고령화가 진행되고 있고 반대로 수원이라든가 하는 데는 형편이 나은 상황입니다. 그래서 경기도 내에서도 향후 20년 동안 인구가 없어질 그런 시군들이 있는 걸로 평가가 되고 있어서 이런 부분들에 대한 배려라든가 연구 그다음에 그것들이 정책에 반영될 수 있도록 하는 점은 저희들도 열심히 노력하겠습니다.
</p>
<p><b>○ 박관열 위원 </b> 실제로 지금까지 저출산 고령화 문제를 다루는 정부정책은 많은 예산과 인력이 투입됐잖아요. 그 효과가 크지도 않고 획일적이고 백화점식 나열의 매칭사업이 주를 이루고 있었는데 현장과 지역의 현안이 실질적으로 반영되는 섬세한 정책의 부재가 아쉬운 대목이다 이렇게 보고 있거든요. 경기도는 전국에서 가장 많은 인구가 모여 사는, 아까 전에 말씀하셨지만 광역자치단체입니다. 그만큼 책임감과 역할이 중요할 텐데 대한민국의 미래 인구를 선도해 나가야 하는 경기도의 중점적 인구정책에 대해서 설명 좀 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 경기도 인구정책은 도에서 여러 가지를 준비하고 또 신정부에서도 하고 있습니다마는 우선 아동들에 대한 복지정책을 실시하고 그다음에 또 안심하고 아이를 기를 수 있는 여건 또 요즘 얘기되고 있는 보육시설에 대한 국공립 보육시설의 확대 이런 것들을 하고 있습니다마는 그러나 저출산 고령화를 막는다는 것은 단지 어떤 한두 가지 정책으로 되어질 일은 아니고 정부가 정말 혁신적인 변화를 하지 않으면 안 될 거라고 생각합니다. 정부도 저출산고령화대책위원회를 대통령 직속으로 만들어서 하고 있음에도 불구하고 그리고 또 정부에서 가장 많은 돈을 들인 게 물관리 사업하고 저출산 대책인데 여전히 이 부분에 대해서 효과를 못 보고 있어서 위원님 말씀대로 현장 적합성이 높은 정책을 이제 위에서부터가 아니라 아래에서부터 해야 되는 상황은 아닌가라는 생각들을 저희들이 해 보고 있습니다. 저희들 연구에서도 저출산 고령화 대책이 적실성 있는 연구가 될 수 있도록 저희들도 안을 조금 더 도출해 보도록 하겠습니다.
</p>
<p><b>○ 박관열 위원 </b> 수고하셨습니다. 이상입니다.
</p>
<p><b>○ 부위원장 정승현 </b> 박관열 위원님 수고하셨습니다. 박관열 위원님을 끝으로 일단 위원님들의 본질문이 끝났습니다. 혹시 추가질문하실 위원님 계신가요? 신정현 위원님 또 민경선 위원님 두 분인가요? 그럼 두 분 추가질문하고 오늘 회의를 마치도록 하겠습니다. 그러면 먼저 누가 하시겠어요? 민경선 위원님 하시겠습니까?
</p>
<p><b>○ 민경선 위원 </b> 네.
</p>
<p><b>○ 부위원장 정승현 </b> 민경선 위원님 질의해 주십시오. 시간은 얼마 정도, 한 5분 정도 하면 될까요?
</p>
<p><b>○ 민경선 위원 </b> 네. 원장님, 빔프로젝트가 아직 켜지지 않아서 그런데요. 아까 질의과정에서 말씀드렸지만 연구위원별 과제 수가 다양합니다. 분석해 보니까 최소 3년간 7건 하신 분이 계시고 최대 36건 하신 분이 계시더라고요. 그래서 균형감 있게 운영했으면 좋겠다는 말씀을 다시 한 번 드리겠습니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  실제 보면 비전공 분야의 연구를 하시는, 연구과제를 수행하시는 분이 많이 있습니다. 지금 보시는 바와 같이, 이게 잘못 나왔는데 미학 전공자가 4차 산업 기반 융복합 콘텐츠 육성 지원하고 장애인 차별, 복지 관련된 거를 하고요. 공유시장경제를 또 이야기하고 있습니다. 그래서 너무나 업무의 중복이 있으니까 이렇게 나열식으로 전혀 비전공인 부분에 떠맡기식 과제가 수행되고 있는 게 아닌가 하는 의구심이 들고 또 정책학을 전공하신 분이 4차 산업혁명 관련된 로드맵도 하시고 또 사회적경제 촉진을 위한 3건을 하시는 것 같습니다. 블록체인 관련해서도 어떻게 이걸 할 수 있죠? 그래서 여러 또 다른 분야들이 있는데요. 아까 우리 원장님께서 수용적인 말씀을 많이 해 주셨습니다. 그래서 아까 중복되지만 양질의 과제수행을 위해서 복합적 과제를, 그러니까 그 복합적인 과제들이 많더라고요. 그런데 한 전공분야에 있는 연구원이 담기에는 어려운 경우가 있습니다. 그래서 복합적인 경우는 2~4인 정도가 공통으로 과제를 수행해서 정말 좋은, 아까 말씀한 임팩트 있는 연구과제가 나왔으면 좋겠다.
</p>
<p style="padding-left:1.2em">  어제도 균형발전기획실 행정감사하면서 제가 연구과제 중에 지역개발 지원사업 관련된 강식 연구위원이 한 자료를 갖고 충분한 대안을 제시하면서 양질의 행정감사를 할 수 있는 기회를 주셨습니다. 그래서 열심히 하시고 계신 분들을 부정하는 건 아닙니다. 다만 이런 업무에 쫓겨서 정말 경기연구원의 위상이 추락하지 않도록 우리 연구원장님께서 각별히 신경 써 주시고 더 여러 가지 연구위원들에 대한 복지나 기타 여러 가지를 외부에서의 외압이나 이런 부분을 막아내는 든든한 버팀목이 되셨으면 하는 바람을 드립니다. 한 말씀 해 주시죠.
</p>
<p><b>○ 경기연구원장 이한주 </b> 너무 지당한 말씀만 하시니까 어깨만 무거워지는 감이 있는데요. 맞습니다. 위원님 지적 아주 날카롭게 잘 찾아주셨고요. 저희들이 아까 말씀드렸지만 군대 없는 국가 수준인 경기도인데 연구원 하나 가지고 다 커버를 하다 보니까 비슷한 전공자들에게 다소 부담스럽게 맡기는 그런 경향이 있었던 것 같고요. 이것을 극복할 수 있는 방안이 뭘까 이렇게 다각도로 찾고는 있습니다. 아까 말씀하신 대로 몇 명이서 합쳐서 하는 연구, 공동연구가 그 대안이 될 수 있고요. 현재로서도 그렇게 많이 하고 있습니다, 사실은. 그래서 한 과제에 대해서 서너 명이 이렇게 하는 것은 서로 점수를 나눠 갖기 위해서 그런 게 아니라 서로 부족한 부분을 보완하는 그런 점에서 많은 연구를 하고 있습니다마는 과제가 워낙 다양하니까, 도 과제가, 이것들을 감당하기가 조금 어려워서 때로는 다소 무리하게 연구를 수행하는 경우도 없지 않았음을 말씀드리고요.
</p>
<p style="padding-left:1.2em">  또 말씀하신 대로 외압이라고 얘기하는 것은 적어도 연구결과에 대한 외압은 없도록 제가 철저히 지키겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 네, 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 그 부분은 연구기관도 학자적인 양심을 지켜야 되는 것임에는 틀림이 없기 때문에 그 부분에 대해서는 결과가 왜곡되거나 주문대로 되거나 이런 일은 없이 있는 그대로 연구하는 풍토를 조성하도록 열심히 노력하겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 알겠습니다. 인사청문회 하면서 상당히 우려했던 부분이 있었는데 오늘 행정감사를 하면서 많이 불식됐습니다. 앞으로 1년 이후에 있을 행정감사 때는 칭찬을 더 받으시는 원장님이 되셨으면 좋겠다는 생각입니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네, 열심히 하겠습니다.
</p>
<p><b>○ 민경선 위원 </b> 하여간 잘 부탁드리겠습니다. 이상입니다.
</p>
<p><b>○ 부위원장 정승현 </b> 민경선 위원님 수고하셨습니다. 다음 신정현 위원님 질의해 주십시오.
</p>
<p><b>○ 신정현 위원 </b> 신정현 위원입니다. 아까 앞서서 보여드렸던 총 연구실적 대비 정책반영 건수를 다시 한 번 열었습니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  그 이유는 우리는 서울시 서울연구원과 비교했을 때 정책반영이 왜 잘 이루어지지 않을까라는 궁금증 때문인데요. 아까 보여드리려고 했다가 보여드리지 못했던 것이 바로 이겁니다. 연구 활용도를 추적조사할 수 있는 방안을 마련해 주셨으면 좋겠습니다. 무슨 말이냐면, 제가 솔직히 아까 전에 좀 화가 정말 많이 났던 것 중의 하나는 부실한 요구자료의 답변입니다. 제가 정책에 어떻게 반영되었는지를 물어봤는데 이거 내용에서 너무나 뻔하고 뻔한 이야기들, 그게 이 책에 나중에 또 똑같이 나와 있던데요. 가령 이런 겁니다. “신기술 규제개선 추진이 어떻게 반영되었나?” “규제개혁을 통한 기업경쟁력 강화로 정립되었다.” 이게 다입니다. 이거 그냥 연구목적과 연구개요에 있는 걸 그대로 복붙 하면 다 넣을 수 있는 거예요. 이런 자료를 제가 요청한 게 아닙니다.
</p>
<p style="padding-left:1.2em">  그러면 제가 요청드리고 싶었던 것은 무엇이냐면, 앞에서 보시는 바와 같이 연구과제별로 이것을 활용하는 부서들에게 실제로 활용했는지에 대한 인터뷰를 하든지 이메일 주소를 찾아서 조사를 하든지 진행을 하라는 겁니다. 또한 여기에서는 지금 3개년 간의 정책내용들을 담았습니다. 3년 전에 했던 내용들이 여기에 어떻게 반영되었다라는 것으로 한 번 기재되고 나서는 그 이후에 어떻게 활용되는지 모르시죠? 서울시에 제가 인터뷰를 했었습니다. 1년에 1~2회 정도의 조사가 시행되고 있습니다. 이미 2018년 1회 시행이 됐고요. 또 한 차례 조사가 진행되고 있다고 하는데요. 이렇게 정책을 실제로 집행하고 또 운영하게 될 당사자들에게 이 연구가 얼마나 활용성 있게 잘 진행되었는가에 대해서 계속해서 추적조사를 하는 것, 저는 그런 것들이 우리 경기연구원이 우리가 늘 얘기했던 연구를 위한 연구에서 벗어나서 정말 현장중심의 연구로 돌아갈 수 있는 방법이라고 생각합니다. 연구원님들 이런 조사하는 거 어렵지 않으시잖아요, 이걸 업으로 살아가시는 분인데. 그럼 경기연구원을 연구대상으로 만들어 보자고요. 그래서 여기서 나오는 이 자료들이 실제로 위원들에게, 담당부서ㆍ기관 공무원들에게 어떻게 활용되는지에 대해서 이것을 추적조사하면 그 자체만으로도 너무 훌륭한 결과물이 나올 거라는 생각이고요. 그렇게 해야만 또 우리가 제대로 된 연구를 하고 있는가를 파악할 수 있겠죠.
</p>
<p style="padding-left:1.2em">  아까 전의 쓴소리를 한 번 더 해야 될 것 같은데요. 예산은 늘어나는데 집행과정이 불투명하다라는 말씀을 한 번 더 드리고 싶어요. 이미 앞서서 했던 말이지만 다시 한 번 말씀드립니다. 아니, 정말 상식적으로 이해가 안 되는 이런 사업비의 집행내역들을, 저는 회사에서 경영기획실에서 일을 하면서 회계자료를 수년간 것을 연결재무제표까지 만들어 봤던 사람인데요. 이렇게 나오는 재무제표나 이렇게 나오는 예결산 자료를 저는 처음 봤어요. 이걸 들이밀고서 이런 예산을 이렇게 쓰겠다, 이렇게 집행했다고 하면서 정작 올해 여러분들께서 우리에게 요구한 예산 증감 39억을 더 달라고 하십니다. 최초로 총액이 200억이 넘어가요, 내년부터. 이토록 지금 예산이 어떻게 쓰여지는지 제대로 된 분석을 할 수 없는 내용들을 내놓으시면서 어떻게 돈을 더 달라고만 하십니까.
</p>
<p style="padding-left:1.2em">  뿐만 아닙니다. 이거 말씀드리고 싶은 건데요. 서울연구원 전체 직원 중에 관리직 비율 11%입니다. 경기연구원 관리직 비율 16%입니다. 제가 이걸 보면서 우리가 정말 관리직을 많이 늘리면서 관리를 하고, 부장급 이상을 말하는 겁니다, 관리직은요, 직책적으로. 점차 비대해져 가는 조직으로, 사실상 그럼에도 제대로 된 연구와 연구 이후의 추적을 제대로 할 수 있는 조직으로 가지 못하는 이 현실들을 지금 경기연구원은 뼈를 깎는 반성을 해야 되는 겁니다. 우리 이한주 원장님께서 이제 새로 오셨잖아요? 이전에 남경필 지사, 그전에 김문수, 그 당시는 경기개발연구원이었지만 이제는 뼈를 깎는 노력으로 새로운 모습으로 돌아서야 됩니다. 그 역할을 하시라고 이 자리에 저는 서신 거라고 믿어요.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p><b>○ 신정현 위원 </b> 자, 그래서 제가 부탁드리고 싶은 것은 이런 겁니다. 이 비대한 조직, 예산 먹는 하마로 보여지는 이 조직이 이제는 연구중심의 조직으로 가야 된다. 연구가 실제로 정책으로 반영될 수 있어야 된다. 또 하나, 예산이 합리적이고 투명하게 집행될 수 있어야 한다. 제가 이걸 위해서 산하기관들의 예결산 결과자료를 같이 비교분석을 해 봤어요. 유일하게 서로 상호 동일한 잣대로 보지 못하게 되어 있는 유일한 기관이 우리 연구원입니다. 원장님, 이거 잘 살펴봐 주셔야 됩니다. 그렇지 않으면 39억을 더 늘려드리지 못할 수도 있고요. 위원님들이 이것에 대해서 문제를 제기하기 시작하면 내년도에는 오히려 예산을 삭감하게 될 수도 있다라는 절체절명의 위기의식을 가지고 이것에 대해서 깊이 들여다보시고요. 결국은 연구의 실용적인 활용이 가능해야 되고요. 실효적 연구를 추진해서 이것이 경기도민의 삶을 낫게 만들 수 있도록 만들어져야 된다라는 생각을 저는 하고요.
</p>
<p style="padding-left:1.2em">  다시 한 번 말씀드립니다. 예산 삭감까지도 고민하는 위원들이 계셔요. 그만큼 경기연구원, 많은 문제들이 노출되어 있으니 이 부분에 대해서 뼈를 깎는 노력으로 바꿔내 주시기를 부탁드립니다. 감사합니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네.
</p>
<p style="padding-left:2.4em">    (정승현 부위원장, 정대운 위원장과 사회교대)
</p>
<p><b>○ 위원장 정대운 </b> 신정현 위원님 수고하셨습니다.
</p>
<p><b>○ 신정현 위원 </b> 말씀하세요.
</p>
<p><b>○ 위원장 정대운 </b> 김경호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 신정현 위원 </b> 아, 답변을 못 들어 가지고.
</p>
<p><b>○ 경기연구원장 이한주 </b> 신 위원님, 여러 가지 제안적 판단에 대해서 아주 감사하게 생각합니다. 연구결과 활용도 조사는 제가 말씀 들으면서 조금 더 체계를 내부화시켜야 되겠다라는 생각을 해서 이 부분은 저희 제도에 반영을 하겠고요. 집행과정, 아까 보여드린 그 집계표는 저도 사실 오늘 처음 봤습니다, 저 집계표가 있는지. 저희 회계 자료인가 싶을 정도로 제가 깜짝 놀랐는데요. 저건 아마 수탁과제에 대해서 별도로 새로 집계된 표가 아닌가 생각해요. 저도 저 표 못 봤습니다.
</p>
<p style="padding-left:1.2em">  뿐만 아니라 한 가지 말씀드리면 e-banking 시스템을 저희들이 이번에 전산을 하면서 준비 중에 있어서, 아마 회계가 그동안 저희 경기도 산하기관 24개 중에서 6개를 제외한 나머지 기관들에서 e-banking이 안 됐던 것 같아요. 그래서 저희도 그중에 하나에 들어갔던 것 같은데 이번에 정보고도화사업을 하면서 e-banking을 써서 저희들이 입력하는 대로 그것들이 다시 중앙서버에 모여서 분개될 수 있도록 해서 조금 더 작위적인 요소가 없도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  말씀하신 연구형 조직으로 가야 되는 것, 저의 방침이기도 하고요. 합리적이고 투명한 집행이라고 하는 건 안 되면 안 되는 얘기입니다. 그다음에 실효적 연구는 아까 얘기한 대로 연구결과의 활용도 조사를 조금 더 활용할 수 있도록 그렇게 하도록 하겠습니다. 좋은 제안 감사드립니다.
</p>
<p><b>○ 위원장 정대운 </b> 김경호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김경호 위원 </b> 가평의 김경호 위원입니다. 조금 아까 미진한 게 하나 있어서. 이번에 경기연구원 발전방안 연구목록하고 31개 시군 정책연구목록을 살펴봤습니다. 2018년도 하반기 추진 연구목록하고요, 2019년도 추진 연구목록 이건 아마 일반 시군하고 네트워크를 형성해서 하실 계획인 것 같습니다. 그런데 저번에 북부 10개년 계획을 한번 봤어요, 거기서 만들어 낸. 그런데 지역 현황하고는 전혀 동떨어진 내용들을 갖다가 사례로 해 놓은 케이스들이 있습니다, 사실. 그런 일들이 왜 발생됐나 했더니 현장답사를 하지 않고 앉은 자리에서 자료를 보니까 아마 그런 오류들이 계속 발생하는 것 같습니다. 그래서 추후에 필요하시면 제가 그 대목을 제출, 보여드릴 수도 있습니다.
</p>
<p style="padding-left:1.2em">  그래서 제가 부탁드리고 싶은 말은 이렇게 지역과 하는 네트워크들은 일단은 지역에서 착수보고회나 아니면 기타 토론회 이런 것들을 통해서 지역현장에서 실질적인 연구자가 갖고 있는 생각하고 그쪽에서 갖고 있는 생각들을 아마 의견교환이 필요할 거라고 생각합니다. 그래서 그런 토론회나 이런 것들을 끊임없이 해 가면서, 그 시군하고 그다음에 그 지역 사람들하고 시군 정책담당자들하고 끊임없이 연계해서 그것들이 계속 활성화가 될 수 있도록 이번만큼은 그렇게 연구를 좀 부탁드리도록 하겠습니다.
</p>
<p><b>○ 경기연구원장 이한주 </b> 네. 늘 그렇게 하려고 하는데 또 잘 안 된 점들이 있었던가 봅니다. 앞으로는 틀림없이 그렇게 할 수 있도록 하겠습니다.
</p>
<p><b>○ 김경호 위원 </b> 수고하셨습니다. 이상 질문을 마치도록 하겠습니다.
</p>
<p><b>○ 위원장 정대운 </b> 김경호 위원님 수고하셨습니다. 더 질의하실 위원님 계십니까?
</p>
<p style="padding-left:1.2em">  원장님! 발언대로 좀 나오시기 바랍니다. 오늘 또 위원님들이 한 분 한 분 소중한 말씀을 했습니다. 도민들을 위해서 우리 경기연구원이 가야 할 길을 얘기한 것 같습니다. 연구를 위한 연구가 아니라 정말 도민에게 그 정책이 하나하나 반영될 수 있는 그런 부분들을 요구한 것 같습니다. 원장님, 한 분 한 분 지적한 그 부분들 잘 정책에 담으시고 또 그런 예산 관련해서 좋은 제안하신 그런 사업에 대해서는 반영해 주시기 바랍니다. 더 이상 질의하실 위원님이 안 계십니까?
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시므로 오늘 경기연구원 소관 업무에 대한 질의와 답변을 마치겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 이한주 경기연구원 원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님의 질의에 성의껏 답해 주신 경기연구원 원장과 부원장을 비롯한 임직원 여러분께 감사드립니다.
</p>
<p style="padding-left:1.2em">  그러면 이상으로 경기연구원 소관 사항에 대한 2018년도 행정사무감사를 모두 마치겠습니다.
</p>
<p class=''ar''>(15시46분 감사종료)
</p>
<p><hr /></p>
